def _session_secret():
    global _session_secret_value
    if _session_secret_value is None:
        with _session_secret_lock:
            if _session_secret_value is None:
                _session_secret_value = load_or_create_session_secret(
                    os.path.join(os.getcwd(), ".maestro-session-secret")
                )
    return _session_secret_value


