def _queue_recovery_with_bounded_compaction(operation):
    try:
        return operation()
    except QueueRecoveryValidationError as error:
        if "must be compacted before another event" not in str(error):
            raise
        _queue_recovery_coordinator.compact()
        return operation()


def _queue_recovery_durable_transition(proposal) -> None:
    _queue_recovery_with_bounded_compaction(
        lambda: _queue_recovery_coordinator.prospective_transition(proposal),
    )


