def _stamp_job_origin(job: dict) -> dict:
    """Capture local-vs-Cloudflare origin before a worker thread is spawned."""
    job.setdefault("source_remote", bool(_request_remote.get()))
    return job


_CREDIT_ACCOUNT_PARAM = "_maestro_credit_account_id"
_CREDIT_REALM_PARAM = "_maestro_credit_execution_realm"
_CREDIT_OWNER_LINEAGE_PARAM = "_maestro_credit_owner_lineage"
_CREDIT_BASELINE_PARAM = "_maestro_credit_accounting_baseline"
_CREDIT_CLEANUP_PARAM = "_maestro_credit_accounting_cleanup"
_CREDIT_INTERNAL_PARAMS = frozenset({
    _CREDIT_ACCOUNT_PARAM,
    _CREDIT_REALM_PARAM,
    _CREDIT_OWNER_LINEAGE_PARAM,
    _CREDIT_BASELINE_PARAM,
    _CREDIT_CLEANUP_PARAM,
})
_CREDIT_EXEMPT_JOB_KINDS = frozenset({"tool_upscale", "tool_revoice"})
_CREDIT_LINEAGE_JOB_KINDS = frozenset({
    "director_pipeline",
    "director_preparation",
    "studio_generation_preparation",
    "studio_project_asset_preparation",
})
# Runtime credit enforcement has a durable account/source debit ledger and a
# validated nonzero policy, but remains operator opt-in.  The environment flag
# is deliberately absent/off by default.
_CREDIT_RUNTIME_ACCOUNTING_DURABLE = True
_CREDIT_RUNTIME_VALIDATED_POLICY_UNITS = 400
_credit_admission_evaluations: dict[str, tuple] = {}
_credit_accounting_lock = threading.RLock()
_credit_accounting_value: CreditAccountingJournal | None = None
_credit_accounting_healthy = False
_credit_accounting_reservation_accounts: dict[str, str] = {}


def _credit_runtime_policy() -> CreditRuntimePolicy:
    """Require compiled readiness plus explicit hosted operator opt-in."""
    policy_ready = bool(
        _CREDIT_RUNTIME_ACCOUNTING_DURABLE is True
        and type(_CREDIT_RUNTIME_VALIDATED_POLICY_UNITS) is int
        and _CREDIT_RUNTIME_VALIDATED_POLICY_UNITS > 0
    )
    return CreditRuntimePolicy(enforcement_enabled=bool(
        policy_ready
        and _accounts_enabled()
        and _env_flag_enabled("MAESTRO_HOSTED_CREDIT_ENFORCEMENT_ENABLED")
    ))


def _credit_server_execution_realm() -> str:
    """Resolve compute locality from host configuration, never request origin."""
    realm = str(
        os.environ.get("MAESTRO_COMPUTE_EXECUTION_REALM") or "local"
    ).strip().lower()
    return realm if realm in {"local", "lan", "hosted"} else "local"


def _credit_accounting_enabled() -> bool:
    """Require the complete hosted opt-in before touching durable state."""
    return bool(
        _credit_runtime_policy().enforcement_enabled
        and _credit_server_execution_realm() == "hosted"
    )


def _credit_accounting_journal() -> CreditAccountingJournal | None:
    """Lazily bind the journal and lifecycle seam only behind the hard gate."""
    global _credit_accounting_value
    if not _credit_accounting_enabled():
        existing_opener = globals().get("_credit_accounting_existing_journal")
        existing = existing_opener() if callable(existing_opener) else None
        callback = (
            _credit_accounting_lifecycle_callback
            if existing is not None else None
        )
        configure_credit_lifecycle_callback(callback)
        settlement_configurer = globals().get(
            "configure_credit_settlement_callback",
        )
        if callable(settlement_configurer):
            settlement_configurer(callback)
        return None
    with _credit_accounting_lock:
        if _credit_accounting_value is None:
            try:
                journal = CreditAccountingJournal(
                    os.path.join(
                        _app_dir, "storage", "credit-accounting.json",
                    ),
                    integrity_key=_support_domain_key("credit-accounting"),
                    policy=CreditAccountingPolicy(enforcement_enabled=True),
                )
                journal.probe_readiness()
            except (CreditAccountingError, OSError):
                _credit_mark_accounting_health(False)
                configure_credit_lifecycle_callback(None)
                settlement_configurer = globals().get(
                    "configure_credit_settlement_callback",
                )
                if callable(settlement_configurer):
                    settlement_configurer(None)
                return None
            _credit_accounting_value = journal
            _credit_mark_accounting_health(True)
        configure_credit_lifecycle_callback(
            _credit_accounting_lifecycle_callback,
        )
        settlement_configurer = globals().get(
            "configure_credit_settlement_callback",
        )
        if callable(settlement_configurer):
            settlement_configurer(_credit_accounting_lifecycle_callback)
        return _credit_accounting_value


def _credit_support_scheduler_enforcement_enabled() -> bool:
    """Project active priority only after the hosted journal opens cleanly."""
    if not _credit_accounting_enabled():
        return False
    if _credit_accounting_value is None:
        _credit_accounting_journal()
    return bool(_credit_accounting_value is not None and _credit_accounting_healthy)


def _credit_mark_accounting_health(healthy: bool) -> None:
    global _credit_accounting_healthy
    with _credit_accounting_lock:
        _credit_accounting_healthy = bool(healthy)


def _credit_accounting_existing_journal() -> CreditAccountingJournal | None:
    """Open prior accounting state only to settle an existing v2 hold."""
    global _credit_accounting_value
    with _credit_accounting_lock:
        if _credit_accounting_value is not None:
            return _credit_accounting_value
        path = os.path.join(_app_dir, "storage", "credit-accounting.json")
        if not os.path.isfile(path) or os.path.islink(path):
            return None
        try:
            journal = CreditAccountingJournal(
                path,
                integrity_key=_support_domain_key("credit-accounting"),
                policy=CreditAccountingPolicy(enforcement_enabled=True),
            )
            journal.probe_readiness()
        except (CreditAccountingError, OSError):
            _credit_mark_accounting_health(False)
            return None
        _credit_accounting_value = journal
        _credit_mark_accounting_health(True)
        return _credit_accounting_value


def _credit_accounting_operation_id(kind: str, *parts) -> str:
    encoded = json.dumps(
        [kind, *(str(part or "") for part in parts)],
        separators=(",", ":"),
    ).encode("utf-8")
    return "operation_" + hashlib.sha256(encoded).hexdigest()


def _credit_accounting_reservation_id(job: dict) -> str:
    payload = ":".join((
        str(job.get("id") or ""),
        str(job.get("workspace") or "default"),
        str(job.get("created_at") or ""),
        str(job.get("_credit_accounting_attempt") or 0),
    ))
    return "reservation_" + hashlib.sha256(
        payload.encode("utf-8"),
    ).hexdigest()


def _credit_account_id(job: dict, *, persisted: bool = True) -> str:
    """Resolve only a server-carried account lineage for allowance lookup."""
    candidates = [job.get("_credit_account_id")]
    parent_id = str(job.get("parent_job_id") or "")
    if parent_id:
        parent = _jobs.get(parent_id)
        if isinstance(parent, dict):
            candidates.append(parent.get("_credit_account_id"))
            parent_params = parent.get("params")
            if isinstance(parent_params, dict):
                candidates.append(parent_params.get(_CREDIT_ACCOUNT_PARAM))
    if persisted:
        params = job.get("params")
        if isinstance(params, dict):
            candidates.append(params.get(_CREDIT_ACCOUNT_PARAM))
    candidates.append(_request_account_id.get())
    for candidate in candidates:
        value = str(candidate or "")
        if re.fullmatch(r"[0-9a-f]{32}", value):
            return value
    return ""


def _credit_owner_exempt(job: dict, *, persisted: bool = True) -> bool:
    """Resolve owner exemption from the sealed account store each time."""
    account_id = _credit_account_id(job, persisted=persisted)
    if not account_id or not _accounts_enabled():
        return False
    try:
        store = _account_auth_store()
        account = None if store is None else store.resolve_account(account_id)
    except (AccountAuthError, OSError, ValueError):
        return False
    return bool(
        isinstance(account, dict)
        and account.get("id") == account_id
        and account.get("role") == "owner"
        and account.get("disabled") is False
    )


def _credit_clear_owner_artifacts(job: dict) -> None:
    """Remove credit artifacts while retaining server-carried lineage."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    for key in (_CREDIT_BASELINE_PARAM, _CREDIT_CLEANUP_PARAM):
        params.pop(key, None)
    params[_CREDIT_OWNER_LINEAGE_PARAM] = True
    job.pop("_credit_submission_preflight", None)
    current = job.get("credit_queue")
    if not (
        isinstance(current, dict)
        and current.get("schema_version") == 2
        and current.get("reservation_state") == "released"
        and current.get("revalidation_state") == "released"
    ):
        job.pop("credit_queue", None)
    _credit_admission_evaluations.pop(str(job.get("id") or ""), None)


def _credit_require_linked_reclassified_lineage(job: dict) -> None:
    """Block former-owner work until a fresh submission can reserve it."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    current = job.get("credit_queue")
    released_owner_tombstone = bool(
        isinstance(current, dict)
        and current.get("schema_version") == 2
        and current.get("reservation_state") == "released"
        and current.get("revalidation_state") == "released"
    )
    if (
        params.get(_CREDIT_OWNER_LINEAGE_PARAM) is not True
        and not released_owner_tombstone
    ):
        return
    cleanup = params.get(_CREDIT_CLEANUP_PARAM)
    if (
        isinstance(current, dict)
        and current.get("schema_version") == 2
        and current.get("reservation_state") == "reserved"
        and isinstance(cleanup, dict)
        and current.get("accounting_reservation_id") == cleanup.get("reservation_id")
        and current.get("accounting_reservation_revision")
        == cleanup.get("reservation_revision")
    ):
        return
    raise CreditRuntimeError(
        "account credit eligibility changed; submit the work again"
    )


def _credit_owner_release_tombstone(current: dict, revision: int) -> dict:
    """Build durable released-v2 provenance from an exact prior hold."""
    target = dict(current)
    target["decision"] = "owner_exempt_release"
    target["reservation_state"] = "released"
    target["accounting_reservation_revision"] = revision
    target["queue_band"] = 0
    target["revalidation_state"] = "released"
    transition_id = _credit_accounting_operation_id(
        "owner-release-tombstone",
        target["accounting_reservation_id"],
        revision,
    )
    target["transition_id"] = transition_id
    target["transition_history"] = [[transition_id, _credit_queue_fingerprint(target)]]
    return target


def _credit_retire_owner_state(job: dict) -> bool:
    """Release an old hold before removing obsolete owner credit state."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    current = job.get("credit_queue")
    linked_hold = bool(
        isinstance(current, dict)
        and current.get("schema_version") == 2
        and current.get("reservation_state") == "reserved"
    )
    cleanup = params.get(_CREDIT_CLEANUP_PARAM)
    if cleanup is not None and not isinstance(cleanup, dict):
        return False
    if linked_hold or isinstance(cleanup, dict):
        credit_release = globals().get("_credit_release_accounting")
        try:
            released = bool(
                callable(credit_release)
                and credit_release(
                    job,
                    persist_baseline=False,
                    preserve_owner_lineage=True,
                )
            )
        except (
            CreditAccountingError,
            CreditRuntimeError,
            EntitlementError,
            OSError,
            RuntimeError,
            ValueError,
        ):
            released = False
        if not released:
            # Exemption callers still let owner work advance; retaining both
            # links makes terminalization and startup recovery retryable.
            return False
    _credit_clear_owner_artifacts(job)
    return True


def _credit_recorded_allowance(job: dict) -> dict:
    """Read one current privacy-safe projection; no contribution data escapes."""
    account_id = _credit_account_id(job)
    if account_id and _accounts_enabled():
        subject = opaque_key(
            "maestro_account_support",
            account_id,
            _support_domain_key("account-identity"),
        )
        return ContributionLedger(
            integrity_key=_support_domain_key("ledger"),
        ).privacy_safe_user_projection(
            subject,
            policy=_load_server_support_catalog().benefit_policy,
        )["recorded_allowance"]
    return {
        "state": "recorded_not_enforced",
        "enforcement_enabled": False,
        "unit": "maestro_credits",
        "as_of": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "effective_allowance": 0,
        "sources": [{
            "source": "free",
            "source_event_id": None,
            "granted_allowance": 0,
            "effective_allowance": 0,
            "expires_at": None,
            "status": "inactive",
            "refund_state": "not_applicable",
        }],
    }


def _credit_accounting_account_key(job: dict) -> str:
    account_id = _credit_account_id(job)
    if not account_id:
        return ""
    return opaque_key(
        "maestro_credit_account",
        account_id,
        _support_domain_key("credit-account-identity"),
    )


def _credit_accounting_sources(recorded_allowance: dict) -> tuple:
    """Convert private allowance lots to journal-safe opaque balances."""
    balances = []
    raw_sources = recorded_allowance.get("sources")
    sources = raw_sources if isinstance(raw_sources, list) else []
    for index, source in enumerate(sources):
        if not isinstance(source, dict):
            continue
        try:
            units = max(0, int(source.get("effective_allowance") or 0))
        except (TypeError, ValueError):
            units = 0
        source_identity = str(source.get("source_event_id") or "")
        if not source_identity:
            source_identity = ":".join((
                str(source.get("source") or "unknown"),
                str(source.get("expires_at") or "never"),
                str(index),
            ))
        balances.append(CreditSourceBalance(
            source_key=opaque_key(
                "maestro_credit_source",
                source_identity,
                _support_domain_key("credit-source-identity"),
            ),
            effective_units=units,
            expires_at=source.get("expires_at"),
        ))
    return tuple(balances)


def _credit_accounting_context(job: dict) -> tuple:
    recorded_allowance = _credit_recorded_allowance(job)
    return (
        _credit_accounting_account_key(job),
        recorded_allowance,
        _credit_accounting_sources(recorded_allowance),
        str(recorded_allowance.get("as_of") or ""),
    )


def _credit_accounting_receipt_projection(receipt) -> dict:
    return {
        "reservation_status": receipt.reservation_status,
        "reservation_revision": receipt.reservation_revision,
        "fully_funded": bool(receipt.fully_funded),
        "allocation_satisfied": bool(receipt.allocation_satisfied),
        "terminal_satisfied": bool(receipt.terminal_satisfied),
    }


def _credit_restore_recovery_lineage(job: dict) -> bool:
    """Restore opaque lineage only from a verified recovery manifest."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    account_id = str(params.get(_CREDIT_ACCOUNT_PARAM) or "")
    if (
        str(params.get(_CREDIT_REALM_PARAM) or "") != "hosted"
        or re.fullmatch(r"[0-9a-f]{32}", account_id) is None
    ):
        return False
    job["_credit_account_id"] = account_id
    return True


def _credit_accounting_hydrate_job(job: dict) -> bool:
    """Recover the private reservation/account association server-side."""
    _credit_restore_recovery_lineage(job)
    credit_queue = job.get("credit_queue")
    if not isinstance(credit_queue, dict) or credit_queue.get(
        "schema_version"
    ) != 2:
        return False
    # Current owner exemption disables new reservations and releases holds
    # that have not run. It must not erase settlement authority for work that
    # was already consumed under its original non-owner lineage.
    if (
        credit_queue.get("reservation_state") != "consumed"
        and _credit_owner_exempt(job)
    ):
        _credit_retire_owner_state(job)
        return False
    reservation_id = str(
        credit_queue.get("accounting_reservation_id") or ""
    )
    account_key = _credit_accounting_account_key(job)
    if not reservation_id or not account_key:
        return False
    with _credit_accounting_lock:
        _credit_accounting_reservation_accounts[reservation_id] = account_key
    return True


def _credit_accounting_lifecycle_callback(event: dict) -> dict:
    """Bridge the opaque lifecycle event to the private durable journal."""
    action = str(event.get("action") or "")
    if action not in {"consume", "release", "settle"}:
        raise CreditAccountingError("credit lifecycle action is invalid")
    journal = (
        _credit_accounting_journal()
        if action == "consume" else (
            globals().get("_credit_accounting_existing_journal") or (
                lambda: None
            )
        )()
    )
    if journal is None:
        raise CreditAccountingError("credit accounting is unavailable")
    reservation_id = str(event.get("accounting_reservation_id") or "")
    with _credit_accounting_lock:
        account_key = _credit_accounting_reservation_accounts.get(
            reservation_id, "",
        )
    if not account_key:
        job = _jobs.get(str(event.get("job_id") or ""))
        if isinstance(job, dict) and _credit_accounting_hydrate_job(job):
            with _credit_accounting_lock:
                account_key = _credit_accounting_reservation_accounts.get(
                    reservation_id, "",
                )
    if not account_key:
        raise CreditAccountingError("credit account association is unavailable")
    try:
        arguments = {
            "account_key": account_key,
            "reservation_id": reservation_id,
            "operation_id": str(event.get("operation_id") or ""),
            "expected_revision": event.get("expected_revision"),
            "as_of": str(event.get("as_of") or ""),
        }
        if action == "settle":
            arguments.update({
                "terminal_status": str(event.get("terminal_status") or ""),
                "server_billable_units": event.get("server_billable_units"),
            })
        receipt = getattr(journal, action)(**arguments)
    except (CreditAccountingError, OSError) as error:
        _credit_mark_accounting_health(False)
        raise CreditAccountingError(
            "credit accounting is unavailable"
        ) from error
    _credit_mark_accounting_health(True)
    if (
        action == "consume" and receipt.allocation_satisfied is True
    ) or (
        action == "release" and receipt.terminal_satisfied is True
    ) or (
        action == "settle" and receipt.terminal_satisfied is True
    ):
        with _credit_accounting_lock:
            _credit_accounting_reservation_accounts.pop(
                reservation_id, None,
            )
    return _credit_accounting_receipt_projection(receipt)


def _credit_allowance_revision(recorded_allowance: dict) -> str:
    """Hash content-free allowance state without account/provider identities."""
    raw_sources = recorded_allowance.get("sources")
    sources = raw_sources if isinstance(raw_sources, list) else []
    canonical_sources = sorted(
        (
            str(source.get("source") or ""),
            source.get("granted_allowance"),
            source.get("effective_allowance"),
            source.get("expires_at"),
            source.get("status"),
            source.get("refund_state"),
        )
        for source in sources
        if isinstance(source, dict)
    )
    payload = {
        "unit": recorded_allowance.get("unit"),
        "as_of": recorded_allowance.get("as_of"),
        "effective_allowance": recorded_allowance.get("effective_allowance"),
        "sources": canonical_sources,
    }
    return hashlib.sha256(json.dumps(
        payload, sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")).hexdigest()


def _credit_requested_units(job: dict) -> int:
    """Seal a conservative compute-seconds quote from server-planned geometry."""
    estimate = job.get("h3_estimate")
    if isinstance(estimate, dict):
        try:
            seconds = float(estimate.get("seconds") or 0)
            load = float(estimate.get("model_load_seconds") or 0)
            if math.isfinite(seconds) and math.isfinite(load) and seconds > 0:
                return max(1, math.ceil(max(0.0, seconds - load)))
        except (TypeError, ValueError, OverflowError):
            pass
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    for key in ("_duration_seconds", "duration_seconds"):
        try:
            seconds = float(params.get(key) or 0)
        except (TypeError, ValueError):
            continue
        if math.isfinite(seconds) and seconds > 0:
            return max(1, math.ceil(seconds))
    try:
        frames = int(params.get("video_length") or 0)
    except (TypeError, ValueError):
        frames = 0
    return max(1, math.ceil(frames / 24)) if frames > 0 else 1


def _credit_capability_priority(job: dict) -> dict:
    """Reduce exact registered model relations to one support-priority marker."""
    from services.model_terms import required_model_terms

    model_ids = sorted(set(_job_model_term_ids(job)))
    excluded = []
    for model_id in model_ids:
        terms = set(required_model_terms(model_id, wgp.models_def))
        for capability_id, contract in SUPPORT_PRIORITY_IDENTITY_CONTRACTS.items():
            if model_id == capability_id or contract.creator_term in terms:
                excluded.append(capability_id)
    if excluded:
        return support_priority_capability_marker(min(set(excluded)))
    encoded = json.dumps(model_ids, separators=(",", ":")).encode("utf-8")
    return support_priority_capability_marker(
        "generation." + hashlib.sha256(encoded).hexdigest(),
    )


def _credit_evaluation(job: dict):
    # Current host configuration is authoritative on every recovery. A
    # persisted hosted stamp must be neutralized when work resumes locally.
    realm = _credit_server_execution_realm()
    recorded_allowance = _credit_recorded_allowance(job)
    quote = quote_reservation(
        realm=realm,
        requested_units=_credit_requested_units(job),
        recorded_allowance=recorded_allowance,
        capability_priority=_credit_capability_priority(job),
        policy=_credit_runtime_policy(),
    )
    return quote, _credit_allowance_revision(recorded_allowance)


def _credit_accounting_reserve(job: dict, quote, allowance_revision: str):
    """Reconcile and reserve before the recovery journal sees the job."""
    if not quote.reservation_required:
        return None
    journal = _credit_accounting_journal()
    if journal is None:
        return None
    account_key, recorded, sources, as_of = _credit_accounting_context(job)
    if not account_key:
        return None
    unit = str(recorded.get("unit") or "")
    journal.reconcile(
        account_key=account_key,
        operation_id=_credit_accounting_operation_id(
            "reconcile", account_key, allowance_revision, as_of,
        ),
        unit=unit,
        sources=sources,
        as_of=as_of,
    )
    reservation_id = _credit_accounting_reservation_id(job)
    receipt = journal.reserve(
        account_key=account_key,
        reservation_id=reservation_id,
        operation_id=_credit_accounting_operation_id(
            "reserve", reservation_id, allowance_revision,
        ),
        requested_units=quote.requested_units,
        as_of=as_of,
    )
    if (
        receipt.reservation_status != "pending"
        or receipt.fully_funded is not True
        or receipt.affected_units != quote.requested_units
        or type(receipt.reservation_revision) is not int
    ):
        if receipt.reservation_status == "pending":
            journal.release(
                account_key=account_key,
                reservation_id=reservation_id,
                operation_id=_credit_accounting_operation_id(
                    "partial-release", reservation_id,
                    receipt.reservation_revision,
                ),
                expected_revision=receipt.reservation_revision,
                as_of=as_of,
            )
        _credit_mark_accounting_health(True)
        return None
    with _credit_accounting_lock:
        _credit_accounting_reservation_accounts[reservation_id] = account_key
    _credit_mark_accounting_health(True)
    return reservation_id, receipt.reservation_revision


def _credit_accounting_revalidate(job: dict, allowance_revision: str):
    """Reconcile one queued v2 reservation against current source truth."""
    current = job.get("credit_queue")
    if not isinstance(current, dict) or current.get("schema_version") != 2:
        return None
    journal = _credit_accounting_journal()
    if journal is None:
        return None
    account_key, recorded, sources, as_of = _credit_accounting_context(job)
    reservation_id = str(current.get("accounting_reservation_id") or "")
    if not account_key or not reservation_id:
        return None
    with _credit_accounting_lock:
        _credit_accounting_reservation_accounts[reservation_id] = account_key
    receipt = journal.revalidate_reservation(
        account_key=account_key,
        reservation_id=reservation_id,
        operation_id=_credit_accounting_operation_id(
            "revalidate", reservation_id, allowance_revision, as_of,
        ),
        unit=str(recorded.get("unit") or ""),
        sources=sources,
        as_of=as_of,
    )
    _credit_mark_accounting_health(True)
    return receipt


def _credit_baseline_quote(job: dict, recorded_allowance: dict):
    return quote_reservation(
        realm=_credit_server_execution_realm(),
        requested_units=_credit_requested_units(job),
        recorded_allowance=recorded_allowance,
        capability_priority=_credit_capability_priority(job),
        policy=CreditRuntimePolicy(),
    )


def _credit_unfunded_hosted_quote(quote):
    """Keep an otherwise-valid hosted submission in the lowest FIFO band."""
    if (
        quote.realm != "hosted"
        or quote.policy_enforcement_enabled is not True
        or quote.metering_applied is not True
        or quote.decision == "capability_excluded"
        or quote.requested_units <= 0
    ):
        return quote
    return type(quote)(
        schema_version=quote.schema_version,
        realm=quote.realm,
        unit=quote.unit,
        snapshot_as_of=quote.snapshot_as_of,
        submission_allowed=True,
        decision="hosted_baseline",
        policy_enforcement_enabled=True,
        metering_applied=True,
        capability_priority_eligible=quote.capability_priority_eligible,
        priority_boost=False,
        reservation_required=False,
        requested_units=quote.requested_units,
        reserved_units=0,
        allocations=(),
    )


def _credit_release_accounting(
    job: dict,
    *,
    persist_baseline: bool,
    defer_cleanup_baseline: bool = False,
    preserve_owner_lineage: bool = False,
    fallback_quote=None,
    fallback_allowance_revision: str | None = None,
) -> bool:
    """Best-effort release, then preserve the applicable runnable band."""
    current = job.get("credit_queue")
    linked_v2 = bool(
        isinstance(current, dict)
        and current.get("schema_version") == 2
        and current.get("reservation_state") == "reserved"
    )
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    cleanup = params.get(_CREDIT_CLEANUP_PARAM)
    if linked_v2:
        reservation_id = str(current.get("accounting_reservation_id") or "")
        expected_revision = current.get("accounting_reservation_revision")
        observed_at = str(current.get("allowance_observed_at") or "")
    elif (
        isinstance(cleanup, dict)
        and set(cleanup) == {"reservation_id", "reservation_revision", "as_of"}
        and isinstance(cleanup.get("reservation_id"), str)
        and type(cleanup.get("reservation_revision")) is int
        and isinstance(cleanup.get("as_of"), str)
    ):
        reservation_id = cleanup["reservation_id"]
        expected_revision = cleanup["reservation_revision"]
        observed_at = cleanup["as_of"]
    else:
        return False
    released = False
    released_revision = None
    try:
        journal = _credit_accounting_existing_journal()
        account_key = _credit_accounting_account_key(job)
        if journal is not None and account_key and reservation_id:
            receipt = journal.release(
                account_key=account_key,
                reservation_id=reservation_id,
                operation_id=_credit_accounting_operation_id(
                    "rollback-release",
                    reservation_id,
                    expected_revision,
                ),
                expected_revision=expected_revision,
                as_of=observed_at,
            )
            released = receipt.terminal_satisfied is True
            released_revision = receipt.reservation_revision
    except (CreditAccountingError, EntitlementError, OSError):
        _credit_mark_accounting_health(False)
        released = False
    if not released and not (linked_v2 and persist_baseline and defer_cleanup_baseline):
        return False
    if released:
        _credit_mark_accounting_health(True)
        if preserve_owner_lineage and linked_v2:
            tombstone = _credit_owner_release_tombstone(
                current,
                released_revision,
            )
            checkpoint = globals().get("_queue_recovery_checkpoint")
            if not callable(checkpoint):
                checkpoint = globals().get("checkpoint_recovery_job")
            if callable(checkpoint):
                if not checkpoint(job, credit_queue=tombstone):
                    return False
            else:
                job["credit_queue"] = tombstone
        with _credit_accounting_lock:
            _credit_accounting_reservation_accounts.pop(reservation_id, None)
        params.pop(_CREDIT_CLEANUP_PARAM, None)
        job["_credit_accounting_attempt"] = (
            max(
                0,
                int(job.get("_credit_accounting_attempt") or 0),
            )
            + 1
        )
    if not persist_baseline:
        if linked_v2 and not preserve_owner_lineage:
            job.pop("credit_queue", None)
        return released
    if not linked_v2:
        return released
    marker_missing = object()
    previous_baseline_marker = params.get(
        _CREDIT_BASELINE_PARAM, marker_missing,
    )
    baseline_transition_persisted = False
    try:
        if fallback_quote is not None:
            baseline = _credit_unfunded_hosted_quote(fallback_quote)
            allowance_revision = str(fallback_allowance_revision or "")
            if not allowance_revision:
                raise CreditRuntimeError(
                    "credit fallback allowance revision is unavailable"
                )
        else:
            recorded = _credit_recorded_allowance(job)
            baseline = _credit_baseline_quote(job, recorded)
            allowance_revision = _credit_allowance_revision(recorded)
        if (
            baseline.realm == "hosted"
            and baseline.policy_enforcement_enabled is True
            and baseline.metering_applied is True
            and baseline.decision == "hosted_baseline"
            and baseline.requested_units > 0
        ):
            params[_CREDIT_BASELINE_PARAM] = True
        else:
            params.pop(_CREDIT_BASELINE_PARAM, None)
        transition_id = _credit_transition_id(
            job,
            "baseline",
            baseline,
            "none",
            allowance_revision,
        )
        baseline_metadata = _credit_queue_metadata_from_quote(
            baseline,
            transition_id=transition_id,
            allowance_revision=allowance_revision,
            reservation=None,
            revalidation=None,
        )
        if str(job.get("status") or "") == "running":
            update_job(job, credit_queue=baseline_metadata)
        else:
            apply_credit_queue_decision(
                job,
                baseline,
                transition_id=transition_id,
                allowance_revision=allowance_revision,
                reservation=None,
            )
        persisted = job.get("credit_queue")
        baseline_transition_persisted = not (
            isinstance(persisted, dict)
            and persisted.get("schema_version") == 2
            and persisted.get("reservation_state") == "reserved"
        )
    except (
        CreditAccountingError, CreditRuntimeError, EntitlementError,
        OSError, ValueError,
    ):
        pass
    finally:
        if not baseline_transition_persisted:
            if previous_baseline_marker is marker_missing:
                params.pop(_CREDIT_BASELINE_PARAM, None)
            else:
                params[_CREDIT_BASELINE_PARAM] = previous_baseline_marker
    return released


def _credit_reconcile_unregistered_cleanup_manifests(
    projects: dict[str, tuple[str, str]],
    snapshots,
) -> tuple[dict[str, list[str]], set[str]]:
    """Settle private credit holds left before queue registration committed."""
    referenced = {
        path
        for snapshot in snapshots
        if isinstance(snapshot, dict)
        for pointer in (snapshot.get("request_manifest"),)
        if isinstance(pointer, dict)
        for path in (pointer.get("path"),)
        if isinstance(path, str)
    }
    retained: dict[str, list[str]] = {}
    cleanup_blocked: set[str] = set()
    for workspace, (project_dir, _project_digest) in projects.items():
        try:
            entries = discover_request_manifest_pointers(project_dir)
        except (QueueRecoveryRuntimeError, OSError):
            cleanup_blocked.add(workspace)
            continue
        for entry in entries:
            job_id = str(entry.get("job_id") or "")
            pointer = entry.get("pointer")
            path = pointer.get("path") if isinstance(pointer, dict) else None
            if not isinstance(path, str) or path in referenced:
                continue
            try:
                manifest = load_request_manifest(
                    project_dir, pointer, expected_job_id=job_id,
                )
            except (QueueRecoveryRuntimeError, OSError):
                cleanup_blocked.add(workspace)
                continue
            params = manifest.get("params")
            if (
                not isinstance(params, dict)
                or not isinstance(params.get(_CREDIT_CLEANUP_PARAM), dict)
            ):
                continue
            cleanup_job = {
                "id": job_id,
                "status": "failed",
                "workspace": workspace,
                "params": dict(params),
            }
            credit_release = globals().get("_credit_release_accounting")
            try:
                released = bool(
                    callable(credit_release)
                    and credit_release(cleanup_job, persist_baseline=False)
                )
            except (
                CreditAccountingError,
                CreditRuntimeError,
                EntitlementError,
                OSError,
                ValueError,
            ):
                released = False
            if released:
                remove_request_manifest(project_dir, pointer)
            else:
                retained.setdefault(workspace, []).append(path)
    return retained, cleanup_blocked


def _credit_quote(job: dict):
    """Compatibility projection for tests and diagnostics."""
    return _credit_evaluation(job)[0]


def _credit_transition_id(
    job: dict,
    stage: str,
    quote,
    state: str,
    allowance_revision: str,
) -> str:
    payload = {
        "job": str(job.get("id") or ""),
        "stage": stage,
        "realm": quote.realm,
        "decision": quote.decision,
        "metering": quote.metering_applied,
        "requested": quote.requested_units,
        "reserved": quote.reserved_units,
        "state": state,
        "allowance_revision": allowance_revision,
        "models": sorted(set(_job_model_term_ids(job))),
    }
    digest = hashlib.sha256(json.dumps(
        payload, sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")).hexdigest()
    return f"credit:v1:{stage}:{digest[:40]}"


def _credit_reservation(job: dict, quote, *, consumed: bool):
    if not quote.reservation_required:
        return None
    reservation_id = "credit-reservation:" + hashlib.sha256(
        (str(job.get("id") or "") + ":" + quote.unit).encode("utf-8")
    ).hexdigest()[:40]
    state = reserve_quote(quote, reservation_id=reservation_id)
    return transition_reservation(state, "consume") if consumed else state


def _credit_job_exempt(job: dict) -> bool:
    """Keep standalone GPU tools outside the unavailable billing surface."""
    return str(job.get("kind") or "") in _CREDIT_EXEMPT_JOB_KINDS


def _credit_job_lineage_only(job: dict) -> bool:
    return str(job.get("kind") or "") in _CREDIT_LINEAGE_JOB_KINDS


def _credit_job_is_remote_origin(job: dict) -> bool:
    """Meter only Cloudflare-origin work; direct and LAN work stay exempt."""
    return bool(job.get("source_remote"))


def _credit_prepare_submission_manifest(job: dict) -> bool:
    """Seal exact private cleanup identity before any journal reservation."""
    if _credit_job_exempt(job):
        return False
    params = job.get("params") if isinstance(job.get("params"), dict) else None
    if params is None:
        return False
    # Fresh clients cannot nominate account or execution authority. Only the
    # server-side top-level lineage and host realm are copied into the private
    # request manifest when hosted enforcement is explicitly active.
    params.pop(_CREDIT_ACCOUNT_PARAM, None)
    params.pop(_CREDIT_REALM_PARAM, None)
    params.pop(_CREDIT_OWNER_LINEAGE_PARAM, None)
    params.pop(_CREDIT_BASELINE_PARAM, None)
    params.pop(_CREDIT_CLEANUP_PARAM, None)
    policy = _credit_runtime_policy()
    realm = _credit_server_execution_realm()
    if not policy.enforcement_enabled or realm != "hosted":
        return False
    if not _credit_job_is_remote_origin(job):
        return False
    account_id = _credit_account_id(job, persisted=False)
    owner_exempt = _credit_owner_exempt(job, persisted=False)
    if account_id:
        job["_credit_account_id"] = account_id
        params[_CREDIT_ACCOUNT_PARAM] = account_id
    params[_CREDIT_REALM_PARAM] = realm
    if not account_id:
        return False
    lineage_only = globals().get("_credit_job_lineage_only")
    if callable(lineage_only) and lineage_only(job):
        return True
    if owner_exempt:
        params[_CREDIT_OWNER_LINEAGE_PARAM] = True
        return False
    quote, allowance_revision = _credit_evaluation(job)
    job["_credit_submission_preflight"] = (quote, allowance_revision)
    if quote.reservation_required:
        params[_CREDIT_CLEANUP_PARAM] = {
            "reservation_id": _credit_accounting_reservation_id(job),
            "reservation_revision": 1,
            "as_of": str(quote.snapshot_as_of or ""),
        }
    return True


def _credit_prepare_submission(job: dict) -> bool:
    """Atomically add the first hosted envelope before queue registration."""
    preflight = job.pop("_credit_submission_preflight", None)
    if not (
        isinstance(preflight, tuple)
        and len(preflight) == 2
        and isinstance(job.get("params"), dict)
    ):
        if not _credit_prepare_submission_manifest(job):
            return False
        preflight = job.pop("_credit_submission_preflight", None)
    elif _credit_owner_exempt(job):
        # Preflight never reserves: an account promoted to owner between the
        # manifest and registration stages has no durable hold to settle.
        _credit_clear_owner_artifacts(job)
        return False
    if not isinstance(preflight, tuple) or len(preflight) != 2:
        # Lineage-only orchestration parents never reserve.
        return True
    quote, allowance_revision = preflight
    params = job["params"]
    reservation = _credit_reservation(job, quote, consumed=False)
    accounting_reserve = globals().get("_credit_accounting_reserve")
    accounting = None
    try:
        if callable(accounting_reserve):
            accounting = accounting_reserve(
                job, quote, allowance_revision,
            )
    except (CreditAccountingError, EntitlementError, OSError):
        _credit_mark_accounting_health(False)
        accounting = None
    if (
        quote.reservation_required
        and callable(accounting_reserve)
        and accounting is None
    ):
        params.pop(_CREDIT_CLEANUP_PARAM, None)
        params[_CREDIT_BASELINE_PARAM] = True
        baseline = _credit_unfunded_hosted_quote(quote)
        job["credit_queue"] = _credit_queue_metadata_from_quote(
            baseline,
            transition_id=_credit_transition_id(
                job, "submit-baseline", baseline, "none",
                allowance_revision,
            ),
            allowance_revision=allowance_revision,
            reservation=None,
            revalidation=None,
        )
        return True
    if accounting is not None:
        actual_cleanup = {
            "reservation_id": accounting[0],
            "reservation_revision": accounting[1],
            "as_of": str(quote.snapshot_as_of or ""),
        }
        if params.get(_CREDIT_CLEANUP_PARAM) != actual_cleanup:
            raise CreditRuntimeError(
                "credit cleanup identity changed after manifest preflight"
            )
    transition_id = _credit_transition_id(
        job, "submit", quote,
        "reserved" if reservation is not None else "none",
        allowance_revision,
    )
    job["credit_queue"] = _credit_queue_metadata_from_quote(
        quote,
        transition_id=transition_id,
        allowance_revision=allowance_revision,
        reservation=reservation,
        revalidation=None,
        accounting_reservation_id=(
            None if accounting is None else accounting[0]
        ),
        accounting_reservation_revision=(
            None if accounting is None else accounting[1]
        ),
    )
    return True


def _credit_prepare_admission(job: dict) -> bool:
    """Re-evaluate and notify queue ordering before waiting for the slot."""
    job_id = str(job.get("id") or "")
    _credit_admission_evaluations.pop(job_id, None)
    if _credit_job_exempt(job):
        return False
    if _credit_owner_exempt(job):
        _credit_retire_owner_state(job)
        return False
    reclassified_guard = globals().get(
        "_credit_require_linked_reclassified_lineage"
    )
    if callable(reclassified_guard):
        reclassified_guard(job)
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    if "credit_queue" not in job and not (
        _credit_runtime_policy().enforcement_enabled
        and str(params.get(_CREDIT_REALM_PARAM) or "") == "hosted"
    ):
        return False
    quote, allowance_revision = _credit_evaluation(job)
    current = job.get("credit_queue")
    if params.get(_CREDIT_BASELINE_PARAM) is True:
        baseline = _credit_unfunded_hosted_quote(quote)
        changed = apply_credit_queue_decision(
            job,
            baseline,
            transition_id=_credit_transition_id(
                job, "admission-baseline", baseline, "none",
                allowance_revision,
            ),
            allowance_revision=allowance_revision,
            reservation=None,
        )
        _credit_admission_evaluations[job_id] = (
            baseline, allowance_revision, None,
        )
        return changed
    if isinstance(current, dict) and current.get("schema_version") == 2:
        if (
            not _credit_accounting_enabled()
            or quote.realm != "hosted"
            or not quote.reservation_required
        ):
            _credit_release_accounting(
                job,
                persist_baseline=True,
                defer_cleanup_baseline=True,
                fallback_quote=quote,
                fallback_allowance_revision=allowance_revision,
            )
            downgraded = job.get("credit_queue")
            if (
                isinstance(downgraded, dict)
                and downgraded.get("schema_version") == 2
                and downgraded.get("reservation_state") == "reserved"
            ):
                raise CreditRuntimeError(
                    "credit baseline transition could not be persisted"
                )
            return True
        try:
            receipt = _credit_accounting_revalidate(
                job, allowance_revision,
            )
        except (CreditAccountingError, EntitlementError, OSError):
            _credit_mark_accounting_health(False)
            receipt = None
        if (
            receipt is None
            or receipt.reservation_status != "pending"
            or receipt.fully_funded is not True
            or receipt.affected_units != quote.requested_units
            or type(receipt.reservation_revision) is not int
        ):
            _credit_release_accounting(
                job,
                persist_baseline=True,
                defer_cleanup_baseline=True,
                fallback_quote=quote,
                fallback_allowance_revision=allowance_revision,
            )
            downgraded = job.get("credit_queue")
            if (
                isinstance(downgraded, dict)
                and downgraded.get("schema_version") == 2
                and downgraded.get("reservation_state") == "reserved"
            ):
                raise CreditRuntimeError(
                    "credit baseline transition could not be persisted"
                )
            return True
        reservation = _credit_reservation(job, quote, consumed=False)
        transition_id = _credit_transition_id(
            job, "admission", quote, "reserved", allowance_revision,
        )
        changed = apply_credit_queue_decision(
            job,
            quote,
            transition_id=transition_id,
            allowance_revision=allowance_revision,
            reservation=reservation,
            accounting_reservation_id=str(
                current.get("accounting_reservation_id") or ""
            ),
            accounting_reservation_revision=receipt.reservation_revision,
        )
        _credit_admission_evaluations[job_id] = (
            quote,
            allowance_revision,
            reservation,
            str(current.get("accounting_reservation_id") or ""),
            receipt.reservation_revision,
        )
        return changed
    was_consumed = (
        isinstance(current, dict)
        and current.get("reservation_state") == "consumed"
    )
    reservation = _credit_reservation(job, quote, consumed=was_consumed)
    transition_id = _credit_transition_id(
        job, "admission", quote,
        (
            "consumed" if reservation is not None and was_consumed
            else "reserved" if reservation is not None else "none"
        ),
        allowance_revision,
    )
    changed = apply_credit_queue_decision(
        job,
        quote,
        transition_id=transition_id,
        allowance_revision=allowance_revision,
        reservation=reservation,
    )
    _credit_admission_evaluations[job_id] = (
        quote, allowance_revision, reservation,
    )
    return changed


def _credit_prepare_dispatch(job: dict) -> bool:
    """Consume only after running admission grants model-work authority."""
    job_id = str(job.get("id") or "")
    evaluation = _credit_admission_evaluations.pop(job_id, None)
    if _credit_job_exempt(job):
        return False
    if _credit_owner_exempt(job):
        _credit_retire_owner_state(job)
        account_id = _credit_account_id(job)
        if account_id:
            try:
                receipt = _owner_test_credit_ledger().record_dispatch(
                    account_key=_owner_test_credit_account_key(account_id),
                    source_key=_owner_test_credit_source_key(account_id),
                    job_key=str(job.get("id") or ""),
                    requested_units=_credit_requested_units(job),
                )
                job["_owner_test_credit"] = receipt.private_mapping()
            except OwnerTestCreditError:
                job["_owner_test_credit_unavailable"] = True
        return False
    reclassified_guard = globals().get(
        "_credit_require_linked_reclassified_lineage"
    )
    if callable(reclassified_guard):
        reclassified_guard(job)
    current = job.get("credit_queue")
    if not isinstance(current, dict) or current.get("reservation_state") != (
        "reserved"
    ):
        return False
    if not isinstance(evaluation, tuple) or len(evaluation) not in {3, 5}:
        raise CreditRuntimeError(
            "credit admission evaluation is unavailable after admission"
        )
    quote, allowance_revision, reserved = evaluation[:3]
    if reserved is None:
        raise CreditRuntimeError(
            "credit admission reservation is unavailable after admission"
        )
    reservation = transition_reservation(reserved, "consume")
    transition_id = _credit_transition_id(
        job, "dispatch", quote, "consumed", allowance_revision,
    )
    try:
        consumed = consume_credit_queue_reservation(
            job,
            quote,
            transition_id=transition_id,
            allowance_revision=allowance_revision,
            reservation=reservation,
            accounting_reservation_id=(
                None if len(evaluation) == 3 else evaluation[3]
            ),
            accounting_reservation_revision=(
                None if len(evaluation) == 3 else evaluation[4] + 1
            ),
        )
    except (
        CreditAccountingError,
        CreditLifecycleCallbackError,
        OSError,
    ):
        # A valid admitted generation must not be denied because the optional
        # accounting store became unavailable after queue revalidation.
        if not _credit_release_accounting(
            job,
            persist_baseline=True,
            fallback_quote=quote,
            fallback_allowance_revision=allowance_revision,
        ):
            # Retain the durable v2 cleanup obligation on the job, but prevent
            # the same unavailable callback from poisoning terminalization.
            configure_credit_lifecycle_callback(None)
            settlement_configurer = globals().get(
                "configure_credit_settlement_callback",
            )
            if callable(settlement_configurer):
                settlement_configurer(None)
        return False
    if not consumed and not is_cancel_requested(job):
        raise CreditRuntimeError(
            "credit reservation could not be consumed after admission"
        )
    return consumed


def _credit_block_runtime_error(job: dict) -> None:
    """Durably remove an invalid credit waiter and wake queue followers."""
    _credit_admission_evaluations.pop(str(job.get("id") or ""), None)
    if str(job.get("status") or "") == "queued":
        block_resource_admission_failure(job)
        return
    if str(job.get("status") or "") == "running":
        finish_job(
            job,
            "failed",
            error="Queue admission validation failed",
            message="Queue admission validation failed",
            recovery_state="terminal",
            reruns_denoise=False,
        )


def _credit_prepare_director_pipeline(params: dict) -> bool:
    """Carry private lineage only for the same explicit hosted policy."""
    for key in _CREDIT_INTERNAL_PARAMS:
        params.pop(key, None)
    if (
        not _credit_runtime_policy().enforcement_enabled
        or _credit_server_execution_realm() != "hosted"
    ):
        return False
    params[_CREDIT_REALM_PARAM] = "hosted"
    account_id = str(_request_account_id.get() or "")
    if re.fullmatch(r"[0-9a-f]{32}", account_id):
        params[_CREDIT_ACCOUNT_PARAM] = account_id
    return True


_gen_lock = threading.Lock()
_active_gen_states: dict = {}  # job_id -> wgp gen state dict (for abort signaling)
_wgp_native_gpu_slot_state = threading.local()


class _WgpNativeGpuWaitCancelled(InterruptedError):
    """A queued API generation was cancelled before native GPU admission."""


def _generation_native_gpu_cancel_checkpoint(job: Mapping[str, Any]) -> None:
    if is_cancel_requested(job):
        raise _WgpNativeGpuWaitCancelled(
            "generation cancelled while waiting for native GPU admission"
        )


class _WgpNativeGpuExecutionSlot:
    """Compose FastAPI GPU/model work with Classic's process-global lane."""

    def __init__(
        self, enabled=True, *, blocking=True, cancel_checkpoint=None,
    ):
        self._enabled = bool(enabled)
        self._blocking = bool(blocking)
        self._cancel_checkpoint = cancel_checkpoint
        self._acquired = False
        self._prior_slot = None

    def acquire(self):
        if self._acquired:
            return True
        if not self._enabled:
            return False
        if self._blocking:
            try:
                if callable(self._cancel_checkpoint):
                    wgp.acquire_native_gpu_execution_lock(
                        self._cancel_checkpoint,
                    )
                else:
                    wgp.acquire_native_gpu_execution_lock()
            except _WgpNativeGpuWaitCancelled:
                return False
            self._acquired = True
        else:
            self._acquired = wgp.native_gpu_execution_lock.acquire(
                blocking=False,
            )
        if self._acquired:
            _wgp_native_gpu_slot_state.depth = (
                int(getattr(_wgp_native_gpu_slot_state, "depth", 0)) + 1
            )
        return self._acquired

    def release(self):
        if self._acquired:
            self._acquired = False
            depth = max(
                0,
                int(getattr(_wgp_native_gpu_slot_state, "depth", 0)) - 1,
            )
            _wgp_native_gpu_slot_state.depth = depth
            wgp.native_gpu_execution_lock.release()
            return True
        return False

    def __enter__(self):
        acquired = self.acquire()
        if acquired:
            self._prior_slot = getattr(
                _wgp_native_gpu_slot_state, "current_slot", None,
            )
            _wgp_native_gpu_slot_state.current_slot = self
        return acquired

    def __exit__(self, _exc_type, _exc_value, _traceback):
        self.release()
        if getattr(
            _wgp_native_gpu_slot_state, "current_slot", None,
        ) is self:
            _wgp_native_gpu_slot_state.current_slot = self._prior_slot
        return False


def _yield_current_native_gpu_slot() -> _WgpNativeGpuExecutionSlot:
    """Release the paired native lane before scheduler releases ``_gen``."""
    slot = getattr(_wgp_native_gpu_slot_state, "current_slot", None)
    if not isinstance(slot, _WgpNativeGpuExecutionSlot) or not slot.release():
        raise RuntimeError("generation native GPU slot is not owned")
    return slot


def _release_wgp_model_with_native_gpu_exclusion():
    """Release WGP residency only while owning its native GPU/model lane."""
    if int(getattr(_wgp_native_gpu_slot_state, "depth", 0)) > 0:
        return wgp.release_model()
    with _WgpNativeGpuExecutionSlot() as acquired:
        if not acquired:
            raise RuntimeError("native GPU/model lane is unavailable")
        return wgp.release_model()


def _local_llm_uses_native_gpu(selection: Mapping[str, Any]) -> bool:
    """Classify only local accelerator-backed LLM runtime selections."""
    return bool(
        str(selection.get("provider") or "local").casefold() == "local"
        and str(selection.get("device") or "cuda").casefold() != "cpu"
    )


_cpu_text_lane = CPUTextLane()
_cpu_text_preemption_gate = PreemptionGate(
    maximum_restarts=1,
    cooldown_seconds=60.0,
)
_CPU_TEXT_OPERATIONS = frozenset({
    "prompt_enhancement",
    "generation_preparation",
    "reference_planning",
})

# Opt-in model repositories can publish newer compatible checkpoints. The
# updater writes only to Maestro's primary checkpoint root, preserves linked
# read-only stores, and keeps the last-known-good file until a replacement has
# passed size/header/SHA validation.
from services.model_updates import VersionedModelUpdater
from services.h3_upstream_skills import H3SkillCatalogUpdater

_versioned_model_updater = VersionedModelUpdater(
    wgp.fl.get_download_location(),
    locate_file=lambda filename: wgp.fl.locate_file(
        filename, error_if_none=False,
    ),
    protected_path=lambda path: bool(wgp.fl.is_protected_path(path)),
)
_versioned_model_update_status: dict[str, dict] = {}
_h3_skill_catalog_updater = H3SkillCatalogUpdater(
    os.path.join(_app_dir, "storage", "h3_skill_catalog.json"),
)


def _ensure_versioned_model_current(model_type: str, *, force: bool = False) -> dict:
    model_def = wgp.get_model_def(model_type) or {}
    result = _versioned_model_updater.ensure_latest(
        model_type, model_def, force=force,
    )
    component_results = _versioned_model_updater.ensure_components_latest(
        model_type, model_def, force=force,
    )
    if component_results:
        result = dict(result)
        result["components"] = component_results
    _versioned_model_update_status[model_type] = result
    return result


_model_update_stop = threading.Event()


def _versioned_model_update_loop() -> None:
    # Never let metadata work contend with or overtake durable restoration.
    while not _startup_recovery_finished.wait(0.1):
        if _model_update_stop.is_set():
            return
    if _startup_recovery_state_value() != "ready":
        return
    # Let the restored queue settle before probing metadata.
    if _model_update_stop.wait(30):
        return
    while not _model_update_stop.is_set():
        # Declarative official H3 workflow metadata follows the same daily,
        # last-known-good update policy as model manifests. It is parsed as
        # bounded data only; downloaded SKILL.md instructions are never run.
        _h3_skill_catalog_updater.refresh()
        if _gen_lock.acquire(blocking=False):
            try:
                for model_type in list(wgp.displayed_model_types):
                    if model_type == "minimax_music3":
                        continue
                    model_def = wgp.get_model_def(model_type) or {}
                    if not (
                        isinstance(model_def.get("model_update"), dict)
                        or isinstance(model_def.get("component_updates"), list)
                    ):
                        continue
                    _versioned_model_updater.apply_recorded(model_type, model_def)
                    _versioned_model_updater.apply_recorded_components(model_type, model_def)
                    if not _check_model_downloaded(model_type):
                        continue  # never turn an optional model into a surprise 30+ GiB download
                    try:
                        _ensure_versioned_model_current(model_type)
                    except Exception as error:
                        _versioned_model_update_status[model_type] = {
                            "status": "failed", "error": str(error),
                        }
            finally:
                _gen_lock.release()
        # Due checks are per-policy (normally 24h); waking hourly also lets a
        # busy generation slot defer without waiting an entire day.
        _model_update_stop.wait(3600)


@api.on_event("startup")
def _start_queue_recovery_before_background_workers(
    *, _preserve_listener_generation: bool = False,
    _restart_generation: int | None = None,
) -> None:
    """Start durable restoration without holding FastAPI's startup loop."""
    global _startup_recovery_cancelled_restart_generation
    global _startup_recovery_restart_generation
    global _startup_recovery_restart_requested
    global _startup_recovery_thread
    with _startup_recovery_thread_lock:
        if _restart_generation is not None:
            if (
                not _startup_recovery_restart_requested
                or _restart_generation != _startup_recovery_restart_generation
                or _restart_generation
                    <= _startup_recovery_cancelled_restart_generation
            ):
                return
            _startup_recovery_restart_requested = False
        if _startup_recovery_thread is not None:
            if _startup_recovery_stop.is_set():
                if not _startup_recovery_restart_requested:
                    # Begin a fresh listener generation exactly once. A request
                    # may arrive before the retiring runner releases ownership.
                    _startup_recovery_listener_ready.clear()
                    _startup_recovery_finished.clear()
                    _startup_recovery_restart_generation += 1
                _startup_recovery_restart_requested = True
            return
        if _startup_recovery_state_value() != "pending":
            return
        if _restart_generation is None:
            _startup_recovery_restart_requested = False
        if not _preserve_listener_generation:
            _startup_recovery_listener_ready.clear()
        _startup_recovery_finished.clear()
        _startup_recovery_stop.clear()
        _set_startup_recovery_state("restoring")
        thread = threading.Thread(
            target=_run_startup_recovery_background,
            daemon=True,
            name="startup-recovery",
        )
        _startup_recovery_thread = thread
        try:
            thread.start()
        except BaseException:
            _startup_recovery_thread = None
            _set_startup_recovery_state("failed")


def _start_sample_campaign_preemption_after_recovery() -> None:
    """Start the low-frequency watcher only after durable jobs are restored."""
    starter = globals().get("_start_sample_campaign_preemption_watcher")
    if callable(starter):
        starter()


def _finish_startup_recovery_index_and_wait_for_listener() -> None:
    """Finish offline indexing, then hold all recovered execution for HTTP."""
    if _startup_recovery_stop.is_set():
        raise RuntimeError("Startup recovery stopped")
    _reindex_h3_delivery_recoveries()
    _wait_for_listener_before_recovered_execution()


def _wait_for_listener_before_recovered_execution() -> None:
    """Release recovered execution only after the listener serves requests."""
    while not _startup_recovery_listener_ready.wait(0.1):
        if _startup_recovery_stop.is_set():
            raise RuntimeError("Startup recovery stopped")
    if _startup_recovery_stop.is_set():
        raise RuntimeError("Startup recovery stopped")


def _run_startup_recovery_background() -> None:
    """Isolate every restore failure, including process-style termination."""
    global _startup_recovery_once_complete
    try:
        if _startup_recovery_once_complete:
            _wait_for_listener_before_recovered_execution()
        else:
            restored = _restore_queue_recovery_on_startup(
                before_recovered_workers=(
                    _finish_startup_recovery_index_and_wait_for_listener
                ),
                run_recovered_operation=(
                    _startup_recovery_launch_operation
                ),
                begin_recovered_execution=(
                    _startup_recovery_begin_launch_sequence
                ),
                end_recovered_execution=(
                    _startup_recovery_end_launch_sequence
                ),
                recovered_execution_started=(
                    _startup_recovery_launch_sequence_started
                ),
            )
            if restored is False:
                _reset_startup_recovery_lifecycle_after_stop()
                return
            _startup_recovery_once_complete = True
    except BaseException:
        if _startup_recovery_launch_sequence_started():
            _startup_recovery_once_complete = True
        _startup_recovery_end_launch_sequence()
        if _startup_recovery_stop.is_set():
            _reset_startup_recovery_lifecycle_after_stop()
            return
        _set_startup_recovery_state("failed")
        print(
            "[Maestro] Startup recovery failed; queue controls remain unavailable.",
            flush=True,
        )
        return
    try:
        watcher_started = _startup_recovery_launch_operation(
            _start_sample_campaign_preemption_after_recovery,
        )
    except BaseException:
        if _startup_recovery_stop.is_set():
            _reset_startup_recovery_lifecycle_after_stop()
            return
        watcher_started = True
        # Recovery and H3 indexing are complete. Keep the server ready while
        # leaving held sample jobs inert instead of letting watcher startup
        # terminate this background boundary.
        print(
            "[Maestro] Sample-campaign watcher did not start; held samples "
            "remain paused.",
            flush=True,
        )
    if not watcher_started:
        _reset_startup_recovery_lifecycle_after_stop()
        return
    ready_published = _startup_recovery_launch_operation(
        lambda: _set_startup_recovery_state("ready"),
    )
    if not ready_published:
        _reset_startup_recovery_lifecycle_after_stop()


def _reset_startup_recovery_lifecycle_after_stop() -> bool:
    """Reset restartable lifespan state only after the old runner is gone."""
    global _startup_recovery_restart_requested
    global _startup_recovery_state
    global _startup_recovery_thread
    current = threading.current_thread()
    restart_generation = None
    with _startup_recovery_thread_lock:
        thread = _startup_recovery_thread
        if (
            thread is not None
            and thread is not current
            and thread.is_alive()
        ):
            return False
        _startup_recovery_thread = None
        if _startup_recovery_restart_requested:
            restart_generation = _startup_recovery_restart_generation
        # Startup reads thread ownership before state under this same lock
        # order. Publish release + pending as one observable transition.
        with _startup_recovery_state_lock:
            _startup_recovery_state = "pending"
        _startup_recovery_finished.clear()
    if restart_generation is not None:
        _start_queue_recovery_before_background_workers(
            _preserve_listener_generation=True,
            _restart_generation=restart_generation,
        )
    return True


@api.on_event("startup")
def _start_versioned_model_updates() -> None:
    _model_update_stop.clear()
    threading.Thread(
        target=_versioned_model_update_loop,
        daemon=True,
        name="versioned-model-updates",
    ).start()


@api.on_event("shutdown")
def _stop_versioned_model_updates() -> None:
    global _startup_recovery_cancelled_restart_generation
    global _startup_recovery_restart_requested
    _model_update_stop.set()
    _startup_recovery_stop.set()
    _startup_recovery_listener_ready.set()
    # The stop signal is visible immediately. Synchronize only after
    # publishing it so a long recovered launch set cannot starve shutdown;
    # the runner observes the event before each subsequent start.
    with _startup_recovery_launch_lock:
        pass
    with _startup_recovery_thread_lock:
        # A later shutdown cancels any deferred startup generation that did
        # not yet acquire its successor thread.
        if _startup_recovery_restart_requested:
            _startup_recovery_cancelled_restart_generation = max(
                _startup_recovery_cancelled_restart_generation,
                _startup_recovery_restart_generation,
            )
        _startup_recovery_restart_requested = False
        # Reassert stop after serializing with any startup that could have
        # cleared the first signal while claiming lifecycle ownership.
        _startup_recovery_stop.set()
        _startup_recovery_listener_ready.set()
        recovery_thread = _startup_recovery_thread
    if (
        recovery_thread is not None
        and recovery_thread is not threading.current_thread()
    ):
        recovery_thread.join(timeout=2.0)
    _reset_startup_recovery_lifecycle_after_stop()


@api.on_event("shutdown")
def _stop_sample_campaign_preemption_on_shutdown() -> None:
    stopper = globals().get("_stop_sample_campaign_preemption_watcher")
    if callable(stopper):
        stopper()


_research_runtime_lock = threading.Lock()
_research_runtime_value = None


def _research_preparation_busy() -> bool:
    """Cover journal-owned preparation work that is not always in _jobs."""
    with _audio_analysis_state_lock:
        if _audio_analysis_active is not None:
            return True
    with _director_preparation_lock:
        return any(
            not isinstance(state, dict) or state.get("status") != "completed"
            for state in _director_preparation_states.values()
        )


def _research_application_busy() -> bool:
    """Fail closed while any app-owned work could overlap implementation."""
    if _gen_lock.locked() or _active_gen_states:
        return True
    if any(
        isinstance(job, dict) and job.get("status") in {"queued", "running"}
        for job in _jobs.values()
    ):
        return True
    if _research_preparation_busy():
        return True
    try:
        from services import director_pipeline as pipeline_service
        with pipeline_service._pipeline_lock:
            if (
                any(
                    isinstance(pipeline, dict)
                    and pipeline.get("status") in {"queued", "planning", "running", "paused"}
                    for pipeline in pipeline_service._pipelines.values()
                )
                or pipeline_service._pipeline_threads
                or pipeline_service._pipeline_starting
                or pipeline_service._pipeline_operations
                or pipeline_service._pipeline_deleting
                or any(pipeline_service._pipeline_child_jobs.values())
                or any(
                    isinstance(repair, dict)
                    and repair.get("status") in {"queued", "running", "cancelling"}
                    for repair in pipeline_service._pipeline_repairs.values()
                )
            ):
                return True
    except ImportError:
        pass
    with _model_downloads_lock:
        if any(
            isinstance(download, dict) and download.get("status") == "downloading"
            for download in _model_downloads.values()
        ):
            return True
    with _civitai_download_lock:
        if any(
            isinstance(download, dict) and download.get("status") == "downloading"
            for download in _civitai_downloads.values()
        ):
            return True
    try:
        from services.safe_download import get_active_downloads
        if get_active_downloads():
            return True
    except Exception:
        # The implementation runner calls this gate again. A broken activity
        # probe must refuse admission rather than silently weaken the gate.
        return True
    return False


def _research_runtime():
    global _research_runtime_value
    if _research_runtime_value is None:
        with _research_runtime_lock:
            if _research_runtime_value is None:
                from services.research_runtime import ResearchRuntime
                _research_runtime_value = ResearchRuntime(
                    repo_root=Path(_app_dir).parent,
                    busy_predicate=_research_application_busy,
                )
    return _research_runtime_value


@api.on_event("startup")
def _start_research_runtime() -> None:
    _research_runtime().start()


@api.on_event("shutdown")
def _stop_research_runtime() -> None:
    if _research_runtime_value is not None:
        _research_runtime_value.stop()


def _raise_research_http_error(error: Exception) -> None:
    from services.research_runtime import (
        ResearchNonceError,
        ResearchRuntimeBusy,
        ResearchRuntimeNotReady,
    )
    if isinstance(error, ResearchNonceError):
        raise HTTPException(status_code=403, detail=str(error)) from None
    if isinstance(error, (ResearchRuntimeBusy, ResearchRuntimeNotReady)):
        raise HTTPException(status_code=409, detail=str(error)) from None
    raise HTTPException(
        status_code=503,
        detail="The local research control surface is temporarily unavailable",
    ) from None


@api.get("/api/v1/research/status")
def research_status():
    try:
        return _research_runtime().status()
    except Exception as error:
        _raise_research_http_error(error)


@api.post("/api/v1/research/run")
def run_research_now():
    try:
        return JSONResponse(
            _research_runtime().start_research(force=True),
            status_code=202,
        )
    except Exception as error:
        _raise_research_http_error(error)


@api.post("/api/v1/research/implementation/nonce")
def issue_research_implementation_nonce(request: Request):
    try:
        return _research_runtime().issue_implementation_nonce(
            request.state.maestro_session_id,
        )
    except Exception as error:
        _raise_research_http_error(error)


@api.post("/api/v1/research/implementation/run")
async def run_research_implementation(request: Request):
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="A JSON request is required") from None
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="A JSON object is required")
    try:
        # Ignore every other client field. Paths, prompts, packet IDs, and
        # finding selections are derived exclusively from the server store.
        result = _research_runtime().start_implementation(
            session_id=request.state.maestro_session_id,
            nonce=str(body.get("nonce") or ""),
            force=body.get("force") is True,
        )
        return JSONResponse(result, status_code=202)
    except Exception as error:
        _raise_research_http_error(error)


def _interrupt_wan_model() -> None:
    """Interrupt only the Wan run bound to the active lifecycle state."""
    model = wgp.wan_model
    if model is not None and hasattr(model, "_interrupt"):
        model._interrupt = True

# --- Workspace support ---
# Base path read from wgp.server_config["save_path"] wherever needed


def _get_active_workspace() -> str:
    """Get current workspace name from server config."""
    return wgp.server_config.get("services", {}).get("active_workspace", "default")


def _workspace_dir(workspace: str = None) -> str:
    """Get a contained output directory for a validated workspace name."""
    from services.win_safe_files import (
        is_safe_workspace_name,
        safe_join_under,
    )

    ws = workspace or _get_active_workspace()
    if not is_safe_workspace_name(ws):
        raise HTTPException(status_code=400, detail="Invalid workspace name")
    # Always read base from config, never from wgp.save_path (which may already include workspace)
    base = os.path.realpath(wgp.server_config.get("save_path", "outputs"))
    if ws == "default":
        return base
    ws_dir = safe_join_under(base, ws)
    if ws_dir is None:
        raise HTTPException(status_code=400, detail="Invalid workspace path")
    os.makedirs(ws_dir, exist_ok=True)
    return ws_dir


def _existing_workspace_dir(workspace: str) -> str:
    """Resolve an existing project without creating attacker-chosen folders."""
    from services.win_safe_files import is_safe_workspace_name, safe_join_under

    if not is_safe_workspace_name(workspace):
        raise HTTPException(status_code=400, detail="Invalid workspace name")
    base = os.path.realpath(wgp.server_config.get("save_path", "outputs"))
    candidate = base if workspace == "default" else safe_join_under(base, workspace)
    if candidate is None:
        raise HTTPException(status_code=400, detail="Invalid workspace path")
    if not os.path.isdir(candidate):
        raise HTTPException(status_code=404, detail="Project not found")
    return candidate


def _require_workspace_not_deleting(workspace: str) -> None:
    """Reject new work while one named project is being removed."""
    with _workspace_lifecycle_lock:
        if workspace in _workspaces_deleting:
            raise HTTPException(
                status_code=409,
                detail="This project is being deleted",
            )


class _WorkspaceOperationReservation:
    """Atomically reserve one or more existing projects against deletion."""

    def __init__(self, *workspaces: str) -> None:
        self.workspaces = tuple(sorted(set(workspaces)))
        self.entered = False

    def __enter__(self):
        with _workspace_lifecycle_lock:
            for workspace in self.workspaces:
                _require_workspace_not_deleting(workspace)
                _existing_workspace_dir(workspace)
            for workspace in self.workspaces:
                _workspace_operations[workspace] = (
                    _workspace_operations.get(workspace, 0) + 1
                )
            self.entered = True
        return self

    def __exit__(self, exc_type, exc_value, traceback_value):
        if self.entered:
            with _workspace_lifecycle_lock:
                for workspace in self.workspaces:
                    remaining = _workspace_operations.get(workspace, 0) - 1
                    if remaining > 0:
                        _workspace_operations[workspace] = remaining
                    else:
                        _workspace_operations.pop(workspace, None)
            self.entered = False
        return False


def _reserve_workspace_operations(*workspaces: str) -> _WorkspaceOperationReservation:
    return _WorkspaceOperationReservation(*workspaces)


def _begin_workspace_operation(workspace: str) -> None:
    """Reserve a project across a race-prone start/resume operation."""
    with _workspace_lifecycle_lock:
        _require_workspace_not_deleting(workspace)
        _existing_workspace_dir(workspace)
        _workspace_operations[workspace] = (
            _workspace_operations.get(workspace, 0) + 1
        )


def _end_workspace_operation(workspace: str) -> None:
    with _workspace_lifecycle_lock:
        remaining = _workspace_operations.get(workspace, 0) - 1
        if remaining > 0:
            _workspace_operations[workspace] = remaining
        else:
            _workspace_operations.pop(workspace, None)


def _require_job_workspace_available(job: dict) -> None:
    """Final, non-creating project check immediately before job publish."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    workspace = str(job.get("workspace") or params.get("workspace") or "")
    if not workspace or workspace == "default":
        return
    if workspace in _workspaces_deleting:
        raise HTTPException(
            status_code=409,
            detail="This project is being deleted",
        )
    try:
        existing = _existing_workspace_dir(workspace)
    except HTTPException as error:
        if error.status_code in (400, 404):
            raise HTTPException(
                status_code=409,
                detail="The target project is no longer available",
            ) from error
        raise
    captured = job.get("out_dir")
    if captured and os.path.normcase(os.path.realpath(str(captured))) != os.path.normcase(
        os.path.realpath(existing)
    ):
        raise HTTPException(
            status_code=409,
            detail="The target project changed before the job was submitted",
        )


_RECOVERABLE_INPUT_KEYS = frozenset({
    *(getattr(wgp, "ATTACHMENT_KEYS", ()) or ()),
    "edit_video_path", "retake_masks_path", "retake_user_start_anchor",
    "retake_user_end_anchor", "voice_reference", "voice_clone_refs",
    "audio_path", "reference_image_path", "character_ref_paths",
    "location_ref_paths", "image_paths",
})


def _queue_recovery_project_identity(workspace: str, project_dir: str) -> str:
    """Return the stable HMAC identity for one existing project instance."""
    marker = ensure_project_instance_marker(project_dir)
    return project_instance_digest(_session_secret(), marker)


def _queue_recovery_existing_project_identity(project_dir: str) -> str:
    """Read an existing project marker without creating recovery evidence."""
    marker_path = os.path.join(project_dir, ".maestro-project-instance")
    descriptor = -1
    try:
        descriptor = os.open(
            marker_path,
            os.O_RDONLY
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NONBLOCK", 0),
        )
        info = os.fstat(descriptor)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_nlink != 1
            or info.st_size > 64
        ):
            raise QueueRecoveryAdapterError(
                "Project instance marker is unsafe."
            )
        marker = os.read(descriptor, 65).decode("ascii").strip()
        current = os.stat(marker_path, follow_symlinks=False)
        if (
            not stat.S_ISREG(current.st_mode)
            or current.st_nlink != 1
            or (current.st_dev, current.st_ino) != (info.st_dev, info.st_ino)
            or re.fullmatch(r"[0-9a-f]{32}", marker) is None
        ):
            raise QueueRecoveryAdapterError(
                "Project instance marker is invalid."
            )
        return project_instance_digest(_session_secret(), marker)
    except (OSError, UnicodeError):
        raise QueueRecoveryAdapterError(
            "Project instance marker is missing or invalid."
        ) from None
    finally:
        if descriptor >= 0:
            os.close(descriptor)


def _raise_project_setup_unavailable(error: Exception) -> None:
    raise HTTPException(
        status_code=503,
        detail="Project account access is unavailable right now",
    ) from error


def _account_project_access_state() -> dict:
    """Return the staged membership state without touching it when disabled."""
    if not _accounts_enabled():
        return {
            "state": "disabled",
            "enforced": False,
            "project_count": 0,
            "needs_attention": 0,
        }
    ledger_store = _account_project_migration_ledger()
    membership_store = _account_project_membership_store()
    if ledger_store is None or membership_store is None:
        return {
            "state": "not_started",
            "enforced": False,
            "project_count": 0,
            "needs_attention": 0,
        }
    try:
        ledger = ledger_store.load_if_present()
        if ledger is None:
            if membership_store.load(required=False) is not None:
                raise ProjectMembershipStoreUnavailableError(
                    "project migration source is missing",
                )
            return {
                "state": "not_started",
                "enforced": False,
                "project_count": 0,
                "needs_attention": 0,
            }
        projects_root = os.path.realpath(
            wgp.server_config.get("save_path", "outputs"),
        )
        if not ledger_store.matches_root(ledger, projects_root):
            raise ProjectMigrationConflictError(
                "project migration belongs to a different output root",
            )
        membership = membership_store.initialize_from_ledger(
            ledger,
            require_existing=True,
        )
    except (
        ProjectMigrationError,
        ProjectMembershipError,
    ) as error:
        _raise_project_setup_unavailable(error)
    needs_attention = len(membership["quarantine"])
    return {
        "state": "needs_attention" if needs_attention else "active",
        # Do not cut over while any census entry still needs recovery.  The
        # legacy password view keeps every project reachable until the complete
        # inventory can be bound without hiding an unresolved directory.
        "enforced": not needs_attention,
        "project_count": len(membership["projects"]),
        "needs_attention": needs_attention,
    }


def _require_account_project_permission(
    request: Request,
    workspace_dir: str,
    permission: str,
    *,
    state: dict | None = None,
) -> dict | None:
    """Require an account role once the complete project move is active."""
    state = state or _account_project_access_state()
    if not state["enforced"]:
        return None
    _require_account_store(request)
    principal = getattr(request.state, "maestro_account_principal", None)
    if not isinstance(principal, dict):
        raise HTTPException(status_code=404, detail="Project not found")
    try:
        project_instance = _queue_recovery_existing_project_identity(workspace_dir)
        store = _account_project_membership_store()
        if store is None:
            raise ProjectMembershipStoreUnavailableError(
                "project membership is unavailable",
            )
        record = store.lookup(
            project_instance=project_instance,
            include_inactive=permission == "project.delete",
        )
    except QueueRecoveryAdapterError as error:
        raise HTTPException(status_code=404, detail="Project not found") from error
    except ProjectMembershipError as error:
        _raise_project_setup_unavailable(error)
    if record is None or (
        record["state"] != "active"
        and not (
            permission == "project.delete"
            and record["state"] in {"deleting", "deleted"}
        )
    ):
        raise HTTPException(status_code=404, detail="Project not found")
    binding = next(
        (
            item
            for item in record["bindings"]
            if item["account_id"] == principal.get("id")
        ),
        None,
    )
    if binding is None or not role_allows(binding["role"], permission):
        raise HTTPException(status_code=404, detail="Project not found")
    return record


def _account_project_list_identities(request: Request) -> dict[str, dict] | None:
    """Return visible project identities and caller permissions after cutover."""
    state = _account_project_access_state()
    if not state["enforced"]:
        return None
    _require_account_store(request)
    principal = getattr(request.state, "maestro_account_principal", None)
    if not isinstance(principal, dict):
        return {}
    try:
        store = _account_project_membership_store()
        if store is None:
            raise ProjectMembershipStoreUnavailableError(
                "project membership is unavailable",
            )
        return {
            item["project_instance"]: {
                "role": item["account_role"],
                "permissions": sorted(
                    permissions_for_role(item["account_role"]),
                ),
            }
            for item in store.list_for_account(
                principal["id"],
                permission="project.list",
            )
        }
    except ProjectMembershipError as error:
        _raise_project_setup_unavailable(error)


def _require_upload_content_access(request: Request) -> None:
    """Require a signed-in account for upload content after project cutover.

    Browser-session upload ownership remains the compatibility authority while
    account project access is disabled or still migrating. Once the complete
    account-backed project inventory is active, that long-lived browser cookie
    is no longer sufficient by itself: logout must immediately fence upload
    listing, creation, reuse, and byte serving on every transport.
    """
    state = _account_project_access_state()
    if not state["enforced"]:
        return
    _require_account_store(request)
    _require_account_principal(request)


def _queue_recovery_file_values(params: dict) -> list[tuple[str, str]]:
    """Collect only producer-declared media fields, never prompt-like strings."""
    values: list[tuple[str, str]] = []
    for key in sorted(_RECOVERABLE_INPUT_KEYS):
        raw = params.get(key)
        candidates = raw if isinstance(raw, list) else [raw]
        for index, value in enumerate(candidates):
            if isinstance(value, tuple):
                value = value[0] if value else None
            if isinstance(value, str) and value:
                values.append((f"{key}:{index}", os.path.abspath(value)))
    return values


def _queue_recovery_input_descriptors(job: dict, owner_digest: str) -> list[dict]:
    """Seal every manifest-declared file with its existing access evidence."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    out_dir = os.path.realpath(str(job.get("out_dir") or ""))
    uploads = os.path.realpath(os.path.join(_app_dir, "uploads"))
    audio_uploads = os.path.realpath(os.path.join(_app_dir, "uploads", "audio"))
    descriptors = []
    for field, path in _queue_recovery_file_values(params):
        resolved = os.path.realpath(path)
        size, digest = _recovery_sha256_file(resolved)
        descriptor = {
            "field": field,
            "path": resolved,
            "sha256": digest,
            "size": size,
        }
        parent = os.path.realpath(os.path.dirname(resolved))
        if parent in {uploads, audio_uploads}:
            access = read_upload_access_sidecar(resolved)
            if not isinstance(access, dict):
                raise QueueRecoveryRuntimeError(
                    "A recovery upload is missing owner evidence."
                )
            access_path = f"{resolved}.access.json"
            sidecar_size, sidecar_digest = _recovery_sha256_file(access_path)
            access_owner = owner_principal_digest(
                _session_secret(), str(access.get("owner_session_id") or ""),
            )
            if not hmac.compare_digest(access_owner, owner_digest):
                raise QueueRecoveryRuntimeError(
                    "A recovery upload no longer belongs to this job owner."
                )
            descriptor.update({
                "scope": "upload_audio" if parent == audio_uploads else "upload",
                "sidecar_path": access_path,
                "sidecar_sha256": sidecar_digest,
                "sidecar_size": sidecar_size,
            })
        elif out_dir and parent == out_dir:
            sidecar_path = os.path.join(
                out_dir, os.path.splitext(os.path.basename(resolved))[0] + ".meta.json",
            )
            sidecar_size, sidecar_digest = _recovery_sha256_file(sidecar_path)
            descriptor.update({
                "scope": "project",
                "sidecar_path": sidecar_path,
                "sidecar_sha256": sidecar_digest,
                "sidecar_size": sidecar_size,
            })
        else:
            # Derived masks/reference cards are still content-pinned, but they
            # cannot authorize themselves after restart.  The validator below
            # accepts them only while their containing project/input evidence
            # remains exact and blocks rather than falling back otherwise.
            descriptor["scope"] = "derived"
        descriptors.append(descriptor)
    return descriptors


def _queue_recovery_manifest_validator(
    descriptor: dict,
    *,
    owner_digest: str,
    workspace: str,
    project_dir: str,
) -> bool:
    """Revalidate one exact input without resolving a substitute pathname."""
    try:
        path = str(descriptor.get("path") or "")
        if not os.path.isabs(path) or os.path.normpath(path) != path:
            return False
        size, digest = _recovery_sha256_file(path)
        if size != descriptor.get("size") or digest != descriptor.get("sha256"):
            return False
        scope = descriptor.get("scope")
        if scope in {"upload", "upload_audio"}:
            root = os.path.realpath(
                os.path.join(_app_dir, "uploads", "audio")
                if scope == "upload_audio"
                else os.path.join(_app_dir, "uploads")
            )
            if os.path.realpath(os.path.dirname(path)) != root:
                return False
            access = read_upload_access_sidecar(path)
            if not isinstance(access, dict):
                return False
            candidate_owner = owner_principal_digest(
                _session_secret(), str(access.get("owner_session_id") or ""),
            )
            if not hmac.compare_digest(candidate_owner, owner_digest):
                return False
        elif scope == "project":
            if os.path.realpath(os.path.dirname(path)) != os.path.realpath(project_dir):
                return False
            from services.search_index import load_media_sidecars as _load_sidecars
            sidecar = _load_sidecars(project_dir, {os.path.basename(path)}).get(
                os.path.basename(path)
            )
            if not isinstance(sidecar, dict):
                return False
            if str(sidecar.get("workspace") or "") != workspace:
                return False
        elif scope == "derived":
            # Content hashes do not establish ownership. Derived inputs have
            # no existing upload/project sidecar contract, so they remain
            # visible as blocked after restart instead of being auto-trusted.
            return False
        else:
            return False
        sidecar_path = descriptor.get("sidecar_path")
        if sidecar_path:
            sidecar_size, sidecar_digest = _recovery_sha256_file(sidecar_path)
            if (
                sidecar_size != descriptor.get("sidecar_size")
                or sidecar_digest != descriptor.get("sidecar_sha256")
            ):
                return False
        return True
    except (QueueRecoveryRuntimeError, ValueError, TypeError):
        return False


def _queue_recovery_register_and_publish(
    job: dict,
    *,
    worker=None,
    recovery_kind: str = "studio_generation",
    thread_name: str | None = None,
    defer_worker: bool = False,
) -> threading.Thread | None:
    """Durably register one Studio job before publication or thread start."""
    # Internal/direct callers share this pre-publication gate with HTTP
    # submissions. It runs before registry, manifest, thread, or network work.
    _require_job_model_recipe_terms(job)
    if (
        recovery_kind != "studio_generation_preparation"
        and job.get("status") == "queued"
    ):
        _seal_h3_offload_plan_for_job(job.get("params"), job=job)
    prepared = _jobs.prepare(_stamp_job_origin(job))
    prepared["kind"] = str(recovery_kind or "studio_generation")
    prepared_params = prepared.get("params")
    if isinstance(prepared_params, dict):
        # These are worker-authored native staging controls. HTTP payloads and
        # project manifests can never select a host output directory.
        prepared_params.pop("_recovery_output_directory", None)
        prepared_params.pop("_recovery_output_prefix", None)
        _stamp_h3_lightx2v_recovery_identity(prepared_params)
    job_id = str(prepared.get("id") or "")
    workspace = str(prepared.get("workspace") or "default")
    project_dir = str(prepared.get("out_dir") or "")
    session_id = str(prepared.get("session_id") or "")
    if not session_id:
        raise QueueRecoveryRuntimeError(
            "Recoverable Studio jobs require a browser owner."
        )
    owner_digest = owner_principal_digest(_session_secret(), session_id)
    with _workspace_lifecycle_lock:
        _require_job_workspace_available(prepared)
        project_digest = _queue_recovery_project_identity(
            workspace, project_dir,
        )
        # This atomic 0600 project-local manifest is the only recovery record
        # allowed to retain raw parameters or absolute input paths. The
        # machine-owned journal and every public response receive only its
        # project-relative pointer, schema, size, and SHA-256.
        request_manifest = None
        try:
            credit_manifest_preflight = globals().get(
                "_credit_prepare_submission_manifest"
            )
            if callable(credit_manifest_preflight):
                credit_manifest_preflight(prepared)
            else:
                _credit_prepare_submission(prepared)
            request_manifest = atomic_write_request_manifest(
                project_dir,
                job_id=job_id,
                params=prepared.get("params") or {},
                inputs=_queue_recovery_input_descriptors(
                    prepared, owner_digest,
                ),
            )
            manifest_params = dict(prepared.get("params") or {})
            if callable(credit_manifest_preflight):
                _credit_prepare_submission(prepared)
            if prepared.get("params") != manifest_params:
                # A fail-open baseline has no cleanup obligation. Replace the
                # preflight manifest before the queue can publish it.
                request_manifest = atomic_write_request_manifest(
                    project_dir,
                    job_id=job_id,
                    params=prepared.get("params") or {},
                    inputs=_queue_recovery_input_descriptors(
                        prepared, owner_digest,
                    ),
                )
            if prepared.get("status") == "queued":
                _stamp_requested_generation_residency(prepared)
            _queue_recovery_with_bounded_compaction(
                lambda: _queue_recovery_coordinator.register_job(
                    prepared,
                    owner_digest=owner_digest,
                    project_digest=project_digest,
                    request_manifest=request_manifest,
                    global_state=durable_queue_state(additions=(prepared,)),
                ),
            )
            prepared["_recovery_owner_digest"] = owner_digest
            prepared["_recovery_project_digest"] = project_digest
            prepared["_recovery_manifest_pointer"] = dict(request_manifest)
            _jobs.publish_prepared(job_id, prepared)
        except Exception:
            credit_release = globals().get("_credit_release_accounting")
            cleanup_required = bool(
                isinstance(prepared.get("params"), dict)
                and isinstance(
                    prepared["params"].get(globals().get(
                        "_CREDIT_CLEANUP_PARAM",
                        "_maestro_credit_accounting_cleanup",
                    )),
                    dict,
                )
            )
            released = not cleanup_required
            if callable(credit_release):
                released = bool(credit_release(
                    prepared, persist_baseline=False,
                ))
                released = released or not cleanup_required
                job["_credit_accounting_attempt"] = prepared.get(
                    "_credit_accounting_attempt", 0,
                )
            if request_manifest is not None and released:
                remove_request_manifest(project_dir, request_manifest)
            raise
    if defer_worker:
        return None
    worker = worker or _run_generation
    thread = threading.Thread(
        target=worker,
        args=(job_id,),
        daemon=False,
        name=thread_name or f"studio-generation-{job_id}",
    )
    try:
        thread.start()
    except Exception as error:
        credit_release = globals().get("_credit_release_accounting")
        if callable(credit_release):
            credit_release(prepared, persist_baseline=True)
        restart_worker = _queue_recovery_worker(prepared)
        blocked_state = (
            "blocked_preparation" if restart_worker is None else "blocked"
        )
        prepared["_recovery_reason_code"] = (
            "preparation_must_resubmit"
            if restart_worker is None else "worker_start_failed"
        )
        _queue_recovery_checkpoint(
            prepared,
            recovery_state=blocked_state,
            queue_held=True,
            reruns_denoise=restart_worker is not None,
            message="Recovery worker could not be started",
        )
        raise QueueRecoveryRuntimeError(
            "Recovery worker could not be started."
        ) from error
    return thread


def _project_reference_publication_recovery_requested(job: dict) -> bool:
    unit = job.get("recovery_unit")
    return bool(
        job.get("kind") == "studio_project_asset_preparation"
        and isinstance(unit, dict)
        and unit.get("kind") == "project_reference_publication"
    )


def _project_reference_validate_committed_variant(
    store,
    project_id,
    workspace_id,
    variant,
    *,
    job_id,
    candidate_index,
    candidate_count,
    plan_seal,
    mandatory_review,
    explicit_output,
):
    """Validate one live/restart replay against the same sealed contract."""
    metadata = variant.get("metadata") if isinstance(variant, dict) else None
    reference = (
        metadata.get("reference_pack") if isinstance(metadata, dict) else None
    )
    job_metadata = metadata.get("job") if isinstance(metadata, dict) else None
    variant_policy = (
        metadata.get("policy") if isinstance(metadata, dict) else None
    )
    variant_outputs = variant.get("outputs") if isinstance(variant, dict) else None
    if (
        not isinstance(variant, dict)
        or variant.get("variant_type") != "reference_pack"
        or not isinstance(reference, dict)
        or reference.get("plan_seal") != plan_seal
        or reference.get("publication_eligible") is not True
        or type(explicit_output) is not bool
        or not isinstance(variant_policy, dict)
        or type(variant_policy.get("explicit")) is not bool
        or variant_policy.get("explicit") is not explicit_output
        or not isinstance(job_metadata, dict)
        or job_metadata.get("id") != job_id
        or job_metadata.get("candidate_index") != candidate_index
        or job_metadata.get("candidate_count") != candidate_count
        or not isinstance(variant_outputs, list)
        or not variant_outputs
    ):
        raise ValueError("committed publication metadata changed")
    quality = reference.get("quality")
    if not isinstance(quality, dict) or set(quality) != {
        "status", "warning", "review_deferred", "assessment",
        "recommended", "recommendation_basis",
    }:
        raise ValueError("committed publication quality metadata changed")
    quality_status = quality.get("status")
    assessment = quality.get("assessment")
    if (
        quality_status not in {"pass", "residual", "review_unavailable"}
        or type(quality.get("recommended")) is not bool
        or type(quality.get("review_deferred")) is not bool
        or (
            quality.get("recommended")
            and quality.get("recommendation_basis") not in {
                "accepted_assessment", "preliminary_ungraded",
                "residual_assessment",
            }
        )
        or (
            not quality.get("recommended")
            and quality.get("recommendation_basis") is not None
        )
    ):
        raise ValueError("committed publication quality metadata changed")
    if quality_status == "review_unavailable":
        if (
            assessment is not None
            or quality.get("review_deferred") is not True
            or not isinstance(quality.get("warning"), str)
        ):
            raise ValueError("committed publication quality metadata changed")
    elif (
        not isinstance(assessment, dict)
        or set(assessment) != {
            "version", "assessment_class", "worst_severity",
            "residual_count", "score_basis_points", "status",
            "dimension_checks", "failed_roles", "reason_codes",
        }
        or type(assessment.get("residual_count")) is not int
        or assessment["residual_count"] < 0
        or quality.get("review_deferred") is not False
        or (
            quality_status == "pass"
            and (
                assessment["residual_count"] != 0
                or quality.get("warning") is not None
            )
        )
        or (
            quality_status == "residual"
            and (
                assessment["residual_count"] == 0
                or not isinstance(quality.get("warning"), str)
            )
        )
    ):
        raise ValueError("committed publication quality metadata changed")
    try:
        private_snapshot = _project_reference_private_authored_snapshot(
            variant,
        )
    except Exception:
        raise ValueError("committed publication metadata changed") from None
    has_private_request = "private_reference_request" in metadata
    has_public_explicit = "explicit_output" in reference
    has_public_convenience = "explicit_convenience" in reference
    if has_private_request and (
        not has_public_explicit
        or not has_public_convenience
        or type(reference.get("explicit_output")) is not bool
        or reference.get("explicit_output") is not explicit_output
        or type(reference.get("explicit_convenience")) is not bool
        or reference.get("explicit_convenience")
            is not private_snapshot["explicit_convenience"]
    ):
        raise ValueError("committed publication metadata changed")
    if not has_private_request and (
        has_public_explicit or has_public_convenience
    ):
        raise ValueError("committed publication metadata changed")
    outputs = []
    for output in variant_outputs:
        relative = output.get("relative_path") if isinstance(output, dict) else None
        output_policy = (
            output.get("metadata") if isinstance(output, dict) else None
        )
        if (
            not isinstance(relative, str)
            or not isinstance(output_policy, dict)
            or type(output_policy.get("explicit")) is not bool
            or output_policy.get("explicit") is not explicit_output
        ):
            raise ValueError("committed publication output changed")
        resolved = store.resolve_output_path(
            project_id, workspace_id, relative,
        )
        if os.path.islink(resolved) or not os.path.isfile(resolved):
            raise ValueError("committed publication output changed")
        outputs.append(relative)
    return outputs


def _project_reference_variant_is_recommended(variant: dict) -> bool:
    metadata = variant.get("metadata") if isinstance(variant, dict) else None
    reference = (
        metadata.get("reference_pack") if isinstance(metadata, dict) else None
    )
    quality = reference.get("quality") if isinstance(reference, dict) else None
    return bool(isinstance(quality, dict) and quality.get("recommended") is True)


def _recover_project_reference_publication(job_id: str) -> None:
    """Finalize one manifest-committed Reference job without generation."""
    job = _jobs.get(job_id)
    if not isinstance(job, dict) or not try_start(
        job,
        message="Reconciling committed reference packs",
        phase="publication_recovery",
    ):
        return
    unit = job.get("recovery_unit")
    failed_message = "Reference-pack publication recovery failed"
    try:
        if not isinstance(unit, dict):
            raise ValueError("invalid publication recovery unit")
        asset_id = unit.get("asset_id")
        workspace_id = unit.get("workspace_id")
        variant_ids = unit.get("variant_ids")
        candidate_count = unit.get("candidate_count")
        plan_seal = unit.get("plan_seal")
        mandatory_review = unit.get("mandatory_review")
        if (
            not isinstance(asset_id, str)
            or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{0,63}", asset_id) is None
            or workspace_id != "main"
            or not isinstance(variant_ids, list)
            or isinstance(candidate_count, bool)
            or not isinstance(candidate_count, int)
            or not 1 <= candidate_count <= 8
            or len(variant_ids) != candidate_count
            or variant_ids != [
                f"{job_id}_pack_{index}" for index in range(1, candidate_count + 1)
            ]
            or not isinstance(plan_seal, str)
            or re.fullmatch(r"[0-9a-f]{64}", plan_seal) is None
            or type(mandatory_review) is not bool
        ):
            raise ValueError("invalid publication recovery unit")
        store = _project_asset_store()
        project_id = str(job.get("workspace") or "")
        explicit_output = job.get("explicit")
        if type(explicit_output) is not bool:
            raise ValueError("invalid publication recovery policy")
        asset = store.get_asset(project_id, workspace_id, asset_id)
        by_id = {
            item.get("id"): item for item in asset.get("variants") or []
            if isinstance(item, dict)
        }
        outputs = []
        recommended_count = 0
        for index, variant_id in enumerate(variant_ids, 1):
            variant = by_id.get(variant_id)
            outputs.extend(_project_reference_validate_committed_variant(
                store,
                project_id,
                workspace_id,
                variant,
                job_id=job_id,
                candidate_index=index,
                candidate_count=candidate_count,
                plan_seal=plan_seal,
                mandatory_review=mandatory_review,
                explicit_output=explicit_output,
            ))
            recommended_count += int(
                _project_reference_variant_is_recommended(variant)
            )
        if recommended_count != 1:
            raise ValueError("invalid Reference recommendation set")
        finish_job(
            job,
            "completed",
            progress=100,
            step=int(job.get("total_steps") or 0),
            total_steps=int(job.get("total_steps") or 0),
            phase="",
            message="Reference packs ready",
            output_files=outputs,
            error=None,
            recovery_state="terminal",
            reruns_denoise=False,
        )
    except Exception:
        finish_job(
            job,
            "failed",
            progress=0,
            phase="",
            message=failed_message,
            error=failed_message,
            recovery_state="terminal",
            reruns_denoise=False,
        )


def _queue_recovery_worker(job: dict):
    """Resolve only restart-safe top-level workers; never guess a prep path."""
    kind = str(job.get("kind") or "studio_generation")
    if kind == "sample_campaign_generation":
        # Only a future dedicated pair-release path may attach a worker.
        return None
    if kind == "studio_generation_preparation":
        return None
    if kind == "prompt_enhancement":
        # Private prompt execution is never reconstructed from durable bytes.
        # A fresh explicit route submission creates a new canonical job.
        return None
    if kind == "studio_blend":
        return globals().get("_run_blend_generation")
    if kind == "studio_outpaint_preparation":
        return globals().get("_prepare_and_run_outpaint")
    if kind == "studio_project_asset_preparation":
        publication_recovery = globals().get(
            "_project_reference_publication_recovery_requested"
        )
        if callable(publication_recovery) and publication_recovery(job):
            return globals().get("_recover_project_reference_publication")
        return None
    if kind in {"studio_repaint_preparation", "studio_recast_preparation"}:
        return None
    return _run_generation


def _queue_recovery_checkpoint(job: dict, **updates) -> bool:
    """Persist an allowlisted recovery transition before mutating the job."""
    if job.get("kind") == _SAMPLE_CAMPAIGN_JOB_KIND:
        context_attempt = _sample_campaign_execution_attempt.get()
        supplied_attempt = updates.get("expected_execution_attempt")
        if supplied_attempt is None:
            supplied_attempt = context_attempt
            updates["expected_execution_attempt"] = supplied_attempt
        if (
            type(supplied_attempt) is not int
            or supplied_attempt < 1
            or (
                context_attempt is not None
                and supplied_attempt != context_attempt
            )
        ):
            return False
        with _sample_campaign_transition_lock:
            if job.get("resource_state") == "preemption_requested":
                return False
            with _queue_recovery_checkpoint_lock:
                return checkpoint_recovery_job(job, **updates)
    with _queue_recovery_checkpoint_lock:
        return checkpoint_recovery_job(job, **updates)


def _director_recovery_parent_job_id(pid: str) -> str:
    return f"director-parent-{pid}"


_DIRECTOR_RECOVERY_STATE_MAX_BYTES = 64 * 1024 * 1024


def _load_director_recovery_state(
    project_dir: str,
    filename: str,
    descriptor,
) -> dict | None:
    """Read, seal, and parse one unchanged no-follow state file exactly once."""
    if (
        not isinstance(descriptor, dict)
        or descriptor.get("path") != filename
        or not isinstance(descriptor.get("sha256"), str)
        or type(descriptor.get("size")) is not int
        or descriptor["size"] < 1
        or descriptor["size"] > _DIRECTOR_RECOVERY_STATE_MAX_BYTES
        or os.path.basename(filename) != filename
    ):
        return None
    file_fd = -1
    try:
        root = os.path.abspath(project_dir)
        root_info = os.lstat(root)
        if not stat.S_ISDIR(root_info.st_mode) or stat.S_ISLNK(root_info.st_mode):
            return None
        path = os.path.join(root, filename)
        path_before = os.lstat(path)
        if (
            not stat.S_ISREG(path_before.st_mode)
            or stat.S_ISLNK(path_before.st_mode)
            or path_before.st_nlink != 1
            or path_before.st_size != descriptor["size"]
        ):
            return None
        file_fd = os.open(
            path,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
        )
        before = os.fstat(file_fd)
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_nlink != 1
            or before.st_size != descriptor["size"]
            or (before.st_dev, before.st_ino)
                != (path_before.st_dev, path_before.st_ino)
        ):
            return None
        chunks = []
        remaining = descriptor["size"]
        digest = hashlib.sha256()
        while remaining:
            chunk = os.read(file_fd, min(1024 * 1024, remaining))
            if not chunk:
                return None
            chunks.append(chunk)
            digest.update(chunk)
            remaining -= len(chunk)
        if os.read(file_fd, 1):
            return None
        after = os.fstat(file_fd)
        current = os.lstat(path)
        identity_before = (
            before.st_dev, before.st_ino, before.st_size,
            before.st_mtime_ns, before.st_ctime_ns,
        )
        identity_after = (
            after.st_dev, after.st_ino, after.st_size,
            after.st_mtime_ns, after.st_ctime_ns,
        )
        if (
            identity_before != identity_after
            or current.st_nlink != 1
            or not stat.S_ISREG(current.st_mode)
            or stat.S_ISLNK(current.st_mode)
            or (current.st_dev, current.st_ino)
                != (before.st_dev, before.st_ino)
            or not hmac.compare_digest(
                digest.hexdigest(), descriptor["sha256"],
            )
        ):
            return None
        parsed = json.loads(b"".join(chunks).decode("utf-8"))
        return parsed if isinstance(parsed, dict) else None
    except (OSError, UnicodeDecodeError, ValueError, TypeError):
        return None
    finally:
        if file_fd >= 0:
            os.close(file_fd)


def _load_director_recovery_cursor_state(
    project_dir: str,
    filename: str,
    cursor: dict,
) -> tuple[dict | None, dict | None, bool]:
    """Load committed or crash-pending bytes from one sealed cursor."""
    for key in ("state", "pending_state"):
        descriptor = cursor.get(key)
        state = _load_director_recovery_state(
            project_dir, filename, descriptor,
        )
        if state is not None:
            return state, dict(descriptor), key == "pending_state"
    return None, None, False


def _director_runtime_parent_from_snapshot(
    snapshot: dict,
    *,
    identity_key: str,
    identity_value: str,
    state_descriptor: dict,
    unit_kind: str,
) -> dict | None:
    """Strip legacy artifact names/content before any new parent checkpoint."""
    return {
        "id": str(snapshot.get("id") or ""),
        "kind": str(snapshot.get("kind") or ""),
        "status": str(snapshot.get("status") or "queued"),
        "workspace": str(snapshot.get("workspace") or "default"),
        "source_remote": bool(snapshot.get("source_remote", False)),
        "private": bool(snapshot.get("private", True)),
        "explicit": bool(snapshot.get("explicit", False)),
        "created_at": snapshot.get("created_at"),
        "phase": str(snapshot.get("phase") or "restored"),
        "message": "Director recovery state restored",
        "recovery_state": str(
            snapshot.get("recovery_state") or "restored"
        ),
        "queue_held": bool(snapshot.get("queue_held", False)),
        "recovery_unit": {
            "kind": unit_kind,
            "state": "committed",
            **dict(state_descriptor),
        },
        "recovery_cursor": {
            identity_key: identity_value,
            "state": dict(state_descriptor),
        },
        "_recovery_owner_digest": str(
            snapshot.get("owner_principal") or ""
        ),
        "_recovery_project_digest": str(
            snapshot.get("project_instance") or ""
        ),
        "_recovery_manifest_pointer": dict(
            snapshot.get("request_manifest") or {}
        ),
    }


def _director_snapshot_has_legacy_artifacts(snapshot) -> bool:
    """Detect old parent snapshots that copied child/output filenames."""
    artifact_keys = {
        "output_files", "artifact_files", "clip_output_files",
        "join_output_file", "artifacts",
    }
    pending = [snapshot]
    while pending:
        value = pending.pop()
        if isinstance(value, dict):
            if artifact_keys.intersection(value):
                return True
            pending.extend(value.values())
        elif isinstance(value, list):
            pending.extend(value)
    return False


def _director_recovery_register_parent(
    pid: str,
    pipeline: dict,
    state: dict,
    state_descriptor: dict,
) -> dict:
    """Commit one Director identity without publishing it as a Studio job."""
    params = pipeline.get("params") if isinstance(pipeline.get("params"), dict) else {}
    workspace = str(pipeline.get("workspace") or "default")
    project_dir = str(pipeline.get("out_dir") or "")
    session_id = str(params.get("_maestro_session_id") or "")
    if not session_id:
        raise QueueRecoveryRuntimeError(
            "Recoverable Director pipelines require a browser owner."
        )
    owner_digest = owner_principal_digest(_session_secret(), session_id)
    project_digest = _queue_recovery_project_identity(workspace, project_dir)
    parent_id = _director_recovery_parent_job_id(pid)
    input_descriptors = _queue_recovery_input_descriptors({
        "params": params,
        "out_dir": project_dir,
    }, owner_digest)
    manifest = atomic_write_request_manifest(
        project_dir,
        job_id=parent_id,
        params={
            "pipeline_id": pid,
            "state_filename": str(state_descriptor.get("path") or ""),
        },
        inputs=input_descriptors,
    )
    policy = params.get("_maestro_access_policy")
    policy = policy if isinstance(policy, dict) else {}
    parent = {
        "id": parent_id,
        "kind": "director_pipeline",
        "status": "queued",
        "workspace": workspace,
        "source_remote": bool(pipeline.get("source_remote", False)),
        "private": bool(policy.get("private", False)),
        "explicit": bool(policy.get("explicit", False)),
        "created_at": pipeline.get("created_at"),
        "phase": "registered",
        "message": "Director pipeline registered",
        "recovery_state": "restored",
        "recovery_unit": {
            "kind": "director_parent_state",
            "state": "committed",
            **dict(state_descriptor),
        },
        "recovery_cursor": {
            "pipeline_id": pid,
            "state": dict(state_descriptor),
        },
        "_recovery_owner_digest": owner_digest,
        "_recovery_project_digest": project_digest,
        "_recovery_manifest_pointer": dict(manifest),
    }
    try:
        _queue_recovery_with_bounded_compaction(
            lambda: _queue_recovery_coordinator.register_job(
                parent,
                owner_digest=owner_digest,
                project_digest=project_digest,
                request_manifest=manifest,
            ),
        )
    except Exception:
        remove_request_manifest(project_dir, manifest)
        raise
    _director_recovery_parents[pid] = parent
    consumed_request_id = str(params.get("director_request_id") or "")
    if consumed_request_id:
        try:
            _director_recovery_retire_preparation(
                consumed_request_id,
                project_dir,
                expected_workspace=workspace,
                expected_owner_digest=owner_digest,
                expected_project_digest=project_digest,
            )
        except Exception:
            # The Director parent is already durable. Leave the completed
            # preparation for bounded startup retirement rather than failing
            # or unpublishing the newly registered pipeline.
            pass
    return {"id": parent_id, "inputs": input_descriptors}


def _director_recovery_checkpoint_parent(
    pid: str,
    state: dict,
    state_descriptor: dict,
) -> None:
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        raise QueueRecoveryRuntimeError("Director recovery parent is unavailable.")
    status = str(state.get("status") or "running")
    recovery_state = (
        "terminal" if status in {"completed", "failed", "cancelled"}
        else "paused" if status == "paused"
        else "restored"
    )
    cursor = dict(parent.get("recovery_cursor") or {})
    cursor.update({
        "pipeline_id": pid,
        "state": dict(state_descriptor),
        "pause_reason": str(state.get("pause_reason") or ""),
    })
    cursor.pop("pending_state", None)
    _queue_recovery_checkpoint(
        parent,
        # The generic journal drops terminal statuses during compaction.
        # Director's semantic terminal state remains repairable until its
        # explicit delete tombstone, so keep this identity non-schedulably
        # registered and carry terminality in recovery_state instead.
        status=(
            "queued"
            if status in {"completed", "failed", "cancelled"}
            else status
        ),
        phase=str(state.get("phase") or status),
        message=(
            "Director pipeline complete"
            if status == "completed"
            else "Director pipeline cancelled"
            if status == "cancelled"
            else "Director pipeline checkpoint committed"
        ),
        recovery_state=recovery_state,
        recovery_unit={
            "kind": "director_parent_state",
            "state": "committed",
            **dict(state_descriptor),
        },
        recovery_cursor=cursor,
    )


def _director_recovery_prepare_parent_state(
    pid: str,
    state: dict,
    state_descriptor: dict,
) -> bool:
    """Seal an upcoming JSON replacement before its canonical rename."""
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        return False
    from services.director_pipeline import pipeline_state_filename
    if (
        state.get("pipeline_id") != pid
        or state_descriptor.get("path") != pipeline_state_filename(pid)
    ):
        raise QueueRecoveryRuntimeError(
            "Director recovery mutation identity is invalid."
        )
    cursor = dict(parent.get("recovery_cursor") or {})
    cursor.update({
        "pipeline_id": pid,
        "pending_state": dict(state_descriptor),
    })
    _queue_recovery_checkpoint(
        parent,
        message="Director state replacement prepared",
        recovery_cursor=cursor,
    )
    return True


def _director_recovery_prepare_parent_delete(pid: str) -> bool:
    """Commit delete intent before any owned media or state is removed."""
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        return False
    cursor = dict(parent.get("recovery_cursor") or {})
    cursor["delete_pending"] = True
    _queue_recovery_checkpoint(
        parent,
        queue_held=True,
        message="Director deletion prepared",
        recovery_cursor=cursor,
    )
    return True


def _director_recovery_remove_parent(pid: str, project_dir: str) -> bool:
    """Tombstone one deleted semantic parent and retire its manifest."""
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        return False
    parent_id = str(parent.get("id") or "")
    _queue_recovery_durable_transition(DurableTransition(
        name="director-parent-deleted",
        tombstones=(parent_id,),
    ))
    _director_recovery_parents.pop(pid, None)
    _director_recovery_rejected_parents.pop(pid, None)
    remove_request_manifest(
        project_dir,
        parent.get("_recovery_manifest_pointer") or {},
    )
    return True


def _director_recovery_submit_child(
    job: dict,
    pid: str,
    unit: dict,
    attempt: int,
) -> dict:
    """Attach to one deterministic child, or durably register it once."""
    try:
        from services import director_pipeline as _director_service

        pipeline = _director_service._pipelines.get(pid) or {}
        pipeline_params = (
            pipeline.get("params")
            if isinstance(pipeline.get("params"), dict) else {}
        )
        account_id = str(pipeline_params.get(_CREDIT_ACCOUNT_PARAM) or "")
        realm = str(pipeline_params.get(_CREDIT_REALM_PARAM) or "")
        if (
            _credit_runtime_policy().enforcement_enabled
            and _credit_server_execution_realm() == "hosted"
            and realm == "hosted"
            and re.fullmatch(r"[0-9a-f]{32}", account_id)
        ):
            job["_credit_account_id"] = account_id
    except (AttributeError, TypeError):
        pass
    job_id = str(job.get("id") or "")
    existing = _jobs.get(job_id)
    if existing is not None:
        existing_parent = str(
            (existing.get("params") or {}).get("_director_pipeline_id")
            or (existing.get("params") or {}).get("_director_request_id")
            or ""
        )
        if (
            existing.get("kind") != "director_child"
            or existing_parent != pid
            or str(existing.get("workspace") or "default")
                != str(job.get("workspace") or "default")
            or os.path.normcase(os.path.realpath(str(existing.get("out_dir") or "")))
                != os.path.normcase(os.path.realpath(str(job.get("out_dir") or "")))
        ):
            raise QueueRecoveryRuntimeError(
                "Director child identity conflicts with recovered queue state."
            )
        if str(existing.get("recovery_state") or "") in {
            "blocked", "blocked_remote_reauth",
        }:
            session_id = str(job.get("session_id") or "")
            expected_owner = str(existing.get("_recovery_owner_digest") or "")
            if (
                not session_id
                or not hmac.compare_digest(
                    owner_principal_digest(_session_secret(), session_id),
                    expected_owner,
                )
                or not _queue_recovery_revalidate_job(existing)
            ):
                raise QueueRecoveryRuntimeError(
                    "Director child recovery authorization failed."
                )
            if _queue_recovery_delivery_pending(existing) is None:
                try:
                    _require_job_model_recipe_terms(existing)
                except HTTPException as error:
                    raise QueueRecoveryRuntimeError(
                        "Director child model terms acceptance is required."
                    ) from error
            existing["session_id"] = session_id
            existing["access_policy"] = dict(job.get("access_policy") or {})
            _queue_recovery_checkpoint(
                existing,
                status="queued",
                queue_held=False,
                recovery_state="retrying",
                message="Queued for Director recovery",
            )
            if not update_queue_job(existing, held=False):
                raise QueueRecoveryRuntimeError(
                    "Director child recovery could not be queued."
                )
            try:
                threading.Thread(
                    target=_run_generation,
                    args=(job_id,),
                    daemon=False,
                    name=f"director-child-recovery-{job_id}",
                ).start()
            except Exception as error:
                _queue_recovery_checkpoint(
                    existing,
                    queue_held=True,
                    recovery_state="blocked",
                    message="Director child recovery worker could not start",
                )
                raise QueueRecoveryRuntimeError(
                    "Director child recovery worker could not start."
                ) from error
        return existing
    job["kind"] = "director_child"
    job["recovery_unit"] = {
        "kind": "director_child_intent",
        "state": "submitted",
        "variant": int(unit.get("variant", 0) or 0),
        "index": int(unit.get("index", 0) or 0),
        "director_kind": str(unit.get("kind") or ""),
        "attempt": max(0, int(attempt)),
    }
    _queue_recovery_register_and_publish(
        job,
        recovery_kind="director_child",
        thread_name=f"director-child-{job_id}",
    )
    return _jobs[job_id]


def _director_recovery_verified_child(job: dict, project_dir: str) -> dict | None:
    """Return only terminal outputs backed by completed queue safe units."""
    if str(job.get("status") or "") != "completed":
        return None
    clip_outputs = {}
    for index, filename in dict(job.get("clip_output_files") or {}).items():
        try:
            clip_outputs[str(int(index))] = str(filename)
        except (TypeError, ValueError):
            continue
    ordered = [
        filename for _index, filename in sorted(
            clip_outputs.items(), key=lambda item: int(item[0]),
        ) if filename
    ]
    join_output = str(job.get("join_output_file") or "")
    if join_output and join_output not in ordered:
        ordered.append(join_output)
    if not ordered:
        ordered = [
            str(filename) for filename in (job.get("output_files") or [])
            if isinstance(filename, str) and filename
        ]
    units = _queue_recovery_units(job)
    evidence = []
    for filename in ordered:
        matched = None
        for unit in units:
            unit_id = str(unit.get("unit_id") or "")
            for descriptor in unit.get("artifacts") or []:
                if (
                    isinstance(descriptor, dict)
                    and descriptor.get("basename") == filename
                    and validate_artifact_descriptor(
                        project_dir, descriptor, producer_unit_id=unit_id,
                    )
                ):
                    matched = dict(descriptor)
                    break
            if matched is not None:
                break
        if matched is None:
            return None
        evidence.append(matched)
    if not evidence:
        return None
    return {
        "outputs": ordered,
        "clip_output_files": clip_outputs,
        "artifacts": evidence,
    }


def _director_recovery_validate_child(
    project_dir: str,
    evidence,
) -> dict | None:
    if not isinstance(evidence, dict):
        return None
    outputs = evidence.get("outputs")
    artifacts = evidence.get("artifacts")
    if (
        not isinstance(outputs, list)
        or not outputs
        or not isinstance(artifacts, list)
        or len(outputs) != len(artifacts)
    ):
        return None
    for filename, descriptor in zip(outputs, artifacts):
        if (
            not isinstance(filename, str)
            or not isinstance(descriptor, dict)
            or descriptor.get("basename") != filename
            or not validate_artifact_descriptor(project_dir, descriptor)
        ):
            return None
    return {
        "outputs": list(outputs),
        "clip_output_files": dict(evidence.get("clip_output_files") or {}),
        "artifacts": [dict(item) for item in artifacts],
    }


_DIRECTOR_REQUEST_ID_RE = re.compile(r"^[0-9a-f]{32}$")
_DIRECTOR_PREPARATION_RETENTION_S = 7 * 24 * 60 * 60
_DIRECTOR_PREPARATION_MAX_RETAINED = 256


def _director_preparation_filename(request_id: str) -> str:
    if _DIRECTOR_REQUEST_ID_RE.fullmatch(str(request_id or "")) is None:
        raise ValueError("Invalid Director request id")
    return f"_director_request_{request_id}.json"


def _director_preparation_payload(state: dict) -> tuple[bytes, dict]:
    request_id = str(state.get("request_id") or "")
    filename = _director_preparation_filename(request_id)
    encoded = json.dumps(
        state, ensure_ascii=False, indent=2, default=str,
    ).encode("utf-8")
    return encoded, {
        "path": filename,
        "sha256": hashlib.sha256(encoded).hexdigest(),
        "size": len(encoded),
    }


def _write_director_preparation_state(
    project_dir: str,
    state: dict,
) -> dict:
    request_id = str(state.get("request_id") or "")
    filename = _director_preparation_filename(request_id)
    path = os.path.join(project_dir, filename)
    temporary = f"{path}.{uuid.uuid4().hex[:8]}.tmp"
    encoded, descriptor = _director_preparation_payload(state)
    try:
        with open(temporary, "wb") as handle:
            handle.write(encoded)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        if os.name != "nt":
            directory = os.open(
                project_dir,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        return descriptor
    finally:
        try:
            os.remove(temporary)
        except FileNotFoundError:
            pass


def _remove_director_preparation_state(
    project_dir: str,
    request_id: str,
) -> None:
    path = os.path.join(
        project_dir, _director_preparation_filename(request_id),
    )
    try:
        os.remove(path)
    except FileNotFoundError:
        return
    if os.name != "nt":
        directory = os.open(
            project_dir,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            os.fsync(directory)
        finally:
            os.close(directory)


def _director_recovery_retire_preparation(
    request_id: str,
    project_dir: str,
    *,
    expected_workspace: str = "",
    expected_owner_digest: str = "",
    expected_project_digest: str = "",
) -> bool:
    """Retire one completed preparation after durable intent and state erase."""
    with _director_preparation_lock:
        parent = _director_preparation_parents.get(request_id)
        state = _director_preparation_states.get(request_id)
    if (
        not isinstance(parent, dict)
        or not isinstance(state, dict)
        or state.get("status") != "completed"
        or state.get("request_id") != request_id
    ):
        return False
    workspace = str(state.get("workspace") or "")
    owner_session_id = str(state.get("owner_session_id") or "")
    parent_owner_digest = str(parent.get("_recovery_owner_digest") or "")
    parent_project_digest = str(parent.get("_recovery_project_digest") or "")
    cursor = dict(parent.get("recovery_cursor") or {})
    if (
        not workspace
        or not owner_session_id
        or cursor.get("request_id") != request_id
        or (expected_workspace and workspace != expected_workspace)
    ):
        return False
    try:
        state_owner_digest = owner_principal_digest(
            _session_secret(), owner_session_id,
        )
        current_project_digest = _queue_recovery_project_identity(
            workspace, project_dir,
        )
    except (ValueError, QueueRecoveryAdapterError):
        return False
    if (
        not parent_owner_digest
        or not parent_project_digest
        or not hmac.compare_digest(parent_owner_digest, state_owner_digest)
        or not hmac.compare_digest(
            parent_project_digest, current_project_digest,
        )
        or (
            expected_owner_digest
            and not hmac.compare_digest(
                parent_owner_digest, expected_owner_digest,
            )
        )
        or (
            expected_project_digest
            and not hmac.compare_digest(
                parent_project_digest, expected_project_digest,
            )
        )
    ):
        return False
    cursor["retire_pending"] = True
    _queue_recovery_checkpoint(
        parent,
        queue_held=True,
        message="Director preparation retirement prepared",
        recovery_cursor=cursor,
    )
    _remove_director_preparation_state(project_dir, request_id)
    with _director_preparation_lock:
        _director_preparation_states.pop(request_id, None)
    _queue_recovery_durable_transition(DurableTransition(
        name="director-preparation-retired",
        tombstones=(str(parent.get("id") or ""),),
    ))
    with _director_preparation_lock:
        _director_preparation_parents.pop(request_id, None)
        _director_preparation_rejected_parents.pop(request_id, None)
    remove_request_manifest(
        project_dir,
        parent.get("_recovery_manifest_pointer") or {},
    )
    return True


def _director_recovery_retire_old_preparations(
    projects: dict[str, tuple[str, str]],
    *,
    now: float | None = None,
    retention_s: float = _DIRECTOR_PREPARATION_RETENTION_S,
    max_retained: int = _DIRECTOR_PREPARATION_MAX_RETAINED,
) -> int:
    """Bound completed request identities without touching active chains."""
    current_time = time.time() if now is None else float(now)
    completed = []
    with _director_preparation_lock:
        for request_id, state in _director_preparation_states.items():
            if not isinstance(state, dict) or state.get("status") != "completed":
                continue
            try:
                updated_at = float(
                    state.get("updated_at") or state.get("created_at") or 0
                )
            except (TypeError, ValueError):
                updated_at = 0.0
            completed.append((
                updated_at,
                request_id,
                str(state.get("workspace") or "default"),
            ))
    completed.sort(reverse=True)
    retired = 0
    keep_limit = max(0, int(max_retained))
    for index, (updated_at, request_id, workspace) in enumerate(completed):
        expired = updated_at <= current_time - max(0.0, float(retention_s))
        over_capacity = index >= keep_limit
        current = projects.get(workspace)
        if not (expired or over_capacity) or current is None:
            continue
        try:
            retired += int(_director_recovery_retire_preparation(
                request_id, current[0],
            ))
        except Exception:
            # Intent is durable; startup reconciliation can finish a state
            # erase whose tombstone was interrupted.
            continue
    return retired


def _register_director_preparation(
    request: Request,
    body: dict,
    workspace: str,
    project_dir: str,
) -> tuple[str, dict]:
    """Create the durable music/analyze parent before recoverable work."""
    requested_id = str(body.get("director_request_id") or "")
    if requested_id:
        state = _require_director_preparation(
            request, requested_id, workspace,
        )
        return requested_id, state
    request_id = uuid.uuid4().hex
    owner = request.state.maestro_session_id
    state = {
        "version": 1,
        "request_id": request_id,
        "workspace": workspace,
        "owner_session_id": owner,
        "source_remote": bool(getattr(request.state, "maestro_remote", False)),
        "status": "running",
        "phase": "registered",
        "created_at": time.time(),
        "updated_at": time.time(),
        "request": dict(body),
        "music": None,
        "analysis": None,
        "classification": None,
        "structure": None,
    }
    state["request"].pop("director_request_id", None)
    descriptor = _write_director_preparation_state(project_dir, state)
    parent_id = f"director-request-{request_id}"
    owner_digest = owner_principal_digest(_session_secret(), owner)
    project_digest = _queue_recovery_project_identity(workspace, project_dir)
    try:
        manifest = atomic_write_request_manifest(
            project_dir,
            job_id=parent_id,
            params={
                "request_id": request_id,
                "state_filename": descriptor["path"],
            },
            inputs=_queue_recovery_input_descriptors({
                "params": body,
                "out_dir": project_dir,
            }, owner_digest),
        )
    except Exception:
        _remove_director_preparation_state(project_dir, request_id)
        raise
    parent = {
        "id": parent_id,
        "kind": "director_preparation",
        "status": "queued",
        "workspace": workspace,
        "source_remote": state["source_remote"],
        "private": True,
        "explicit": False,
        "created_at": state["created_at"],
        "phase": "registered",
        "message": "Director preparation registered",
        "recovery_state": "restored",
        "recovery_unit": {
            "kind": "director_preparation_state",
            "state": "committed",
            **descriptor,
        },
        "recovery_cursor": {
            "request_id": request_id,
            "state": descriptor,
        },
        "_recovery_owner_digest": owner_digest,
        "_recovery_project_digest": project_digest,
        "_recovery_manifest_pointer": dict(manifest),
    }
    try:
        _queue_recovery_with_bounded_compaction(
            lambda: _queue_recovery_coordinator.register_job(
                parent,
                owner_digest=owner_digest,
                project_digest=project_digest,
                request_manifest=manifest,
            ),
        )
    except Exception:
        remove_request_manifest(project_dir, manifest)
        _remove_director_preparation_state(project_dir, request_id)
        raise
    with _director_preparation_lock:
        _director_preparation_parents[request_id] = parent
        _director_preparation_states[request_id] = state
    return request_id, dict(state)


def _checkpoint_director_preparation(
    request_id: str,
    project_dir: str,
    **updates,
) -> dict:
    with _director_preparation_lock:
        state = dict(_director_preparation_states.get(request_id) or {})
        parent = _director_preparation_parents.get(request_id)
        if not state or not isinstance(parent, dict):
            raise QueueRecoveryRuntimeError(
                "Director preparation recovery state is unavailable."
            )
        state.update(updates)
        state["updated_at"] = time.time()
        _encoded, descriptor = _director_preparation_payload(state)
        cursor = dict(parent.get("recovery_cursor") or {})
        cursor.update({
            "request_id": request_id,
            "pending_state": descriptor,
        })
        _queue_recovery_checkpoint(
            parent,
            message="Director preparation state replacement prepared",
            recovery_cursor=cursor,
        )
        descriptor = _write_director_preparation_state(project_dir, state)
        cursor["state"] = descriptor
        cursor.pop("pending_state", None)
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            phase=str(state.get("phase") or "preparing"),
            message="Director preparation checkpoint committed",
            recovery_state=(
                "terminal" if state.get("status") == "completed" else "restored"
            ),
            recovery_unit={
                "kind": "director_preparation_state",
                "state": "committed",
                **descriptor,
            },
            recovery_cursor={
                **cursor,
                "request_id": request_id,
                "state": descriptor,
            },
        )
        _director_preparation_states[request_id] = state
        result = dict(state)
    if result.get("status") == "completed":
        existing_projects = globals().get("_queue_recovery_existing_projects")
        retire_old_preparations = globals().get(
            "_director_recovery_retire_old_preparations"
        )
        if (
            existing_projects is not None
            and retire_old_preparations is not None
        ):
            try:
                retire_old_preparations(existing_projects())
            except Exception:
                # Completion is already durable. A later completion or
                # startup maintenance pass can retry bounded retirement.
                pass
    return result


def _require_director_preparation(
    request: Request,
    request_id: str,
    workspace: str = "",
    *,
    allow_blocked: bool = False,
) -> dict:
    try:
        filename = _director_preparation_filename(request_id)
    except ValueError:
        raise HTTPException(status_code=404, detail="Director request not found")
    selected = workspace or _get_active_workspace()
    project_dir = _require_project_access(request, selected)
    with _director_preparation_lock:
        state = dict(_director_preparation_states.get(request_id) or {})
    if not state:
        path = os.path.join(project_dir, filename)
        try:
            with open(path, "r", encoding="utf-8") as handle:
                state = json.load(handle)
        except (OSError, ValueError, TypeError):
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
    if (
        not isinstance(state, dict)
        or state.get("request_id") != request_id
        or state.get("workspace") != selected
        or state.get("owner_session_id") != request.state.maestro_session_id
    ):
        raise HTTPException(status_code=404, detail="Director request not found")
    parent = _director_preparation_parents.get(request_id)
    rejected = _director_preparation_rejected_parents.get(request_id)
    if not isinstance(parent, dict):
        if isinstance(rejected, dict):
            expected_owner = str(rejected.get("owner_principal") or "")
            expected_project = str(rejected.get("project_instance") or "")
            try:
                request_owner = owner_principal_digest(
                    _session_secret(), request.state.maestro_session_id,
                )
                current_project = _queue_recovery_project_identity(
                    selected, project_dir,
                )
            except (ValueError, QueueRecoveryAdapterError):
                raise HTTPException(
                    status_code=404, detail="Director request not found",
                )
            if (
                not expected_owner
                or not expected_project
                or not hmac.compare_digest(expected_owner, request_owner)
                or not hmac.compare_digest(expected_project, current_project)
            ):
                raise HTTPException(
                    status_code=404, detail="Director request not found",
                )
        if allow_blocked:
            state.update({
                "status": "blocked",
                "phase": "blocked_recovery_unavailable",
                "recovery_blocked": True,
            })
            return state
        raise HTTPException(
            status_code=409,
            detail="Director preparation recovery is blocked.",
        )
    if isinstance(parent, dict):
        expected_owner = str(parent.get("_recovery_owner_digest") or "")
        try:
            request_owner = owner_principal_digest(
                _session_secret(), request.state.maestro_session_id,
            )
        except ValueError:
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
        if expected_owner and not hmac.compare_digest(
            expected_owner, request_owner,
        ):
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
        expected_project = str(parent.get("_recovery_project_digest") or "")
        try:
            current_project = _queue_recovery_project_identity(
                selected, project_dir,
            )
        except (ValueError, QueueRecoveryAdapterError):
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
        if expected_project and not hmac.compare_digest(
            expected_project, current_project,
        ):
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
        if state.get("recovery_blocked"):
            if allow_blocked:
                return state
            raise HTTPException(
                status_code=409,
                detail="Director preparation inputs changed.",
            )
        pointer = parent.get("_recovery_manifest_pointer")
        try:
            cursor = parent.get("recovery_cursor")
            cursor = cursor if isinstance(cursor, dict) else {}
            sealed_state, sealed_descriptor, used_pending = (
                _load_director_recovery_cursor_state(
                    project_dir, filename, cursor,
                )
            )
            if (
                sealed_state is None
                or sealed_state.get("request_id") != request_id
                or sealed_state.get("workspace") != selected
                or sealed_state.get("owner_session_id")
                    != request.state.maestro_session_id
            ):
                raise QueueRecoveryRuntimeError(
                    "Director preparation state identity changed."
                )
            state = sealed_state
            manifest = load_request_manifest(
                project_dir,
                pointer if isinstance(pointer, dict) else {},
                expected_job_id=str(parent.get("id") or ""),
            )
            manifest_params = manifest.get("params") or {}
            if (
                manifest_params.get("request_id") != request_id
                or manifest_params.get("state_filename") != filename
            ):
                raise QueueRecoveryRuntimeError(
                    "Director preparation pointer is invalid."
                )
            validate_manifest_inputs(
                manifest,
                lambda descriptor: _queue_recovery_manifest_validator(
                    dict(descriptor),
                    owner_digest=expected_owner,
                    workspace=selected,
                    project_dir=project_dir,
                ),
            )
            if used_pending:
                promoted_cursor = dict(cursor)
                promoted_cursor["state"] = dict(sealed_descriptor or {})
                promoted_cursor.pop("pending_state", None)
                _queue_recovery_checkpoint(
                    parent,
                    recovery_unit={
                        "kind": "director_preparation_state",
                        "state": "committed",
                        **dict(sealed_descriptor or {}),
                    },
                    recovery_cursor=promoted_cursor,
                    message="Director preparation state committed",
                )
        except QueueRecoveryRuntimeError:
            if allow_blocked:
                state.update({
                    "status": "blocked",
                    "phase": "blocked_input_changed",
                    "recovery_blocked": True,
                })
                return state
            raise HTTPException(
                status_code=409,
                detail="Director preparation inputs changed.",
            )
    return state


def _queue_recovery_existing_projects() -> dict[str, tuple[str, str]]:
    """Ensure a marker for every existing project without creating projects."""
    from services.win_safe_files import is_safe_workspace_name

    base = os.path.realpath(wgp.server_config.get("save_path", "outputs"))
    projects: dict[str, tuple[str, str]] = {}
    if os.path.isdir(base):
        try:
            projects["default"] = (
                base,
                _queue_recovery_project_identity("default", base),
            )
        except (ValueError, QueueRecoveryAdapterError):
            pass
        try:
            names = sorted(os.listdir(base))
        except OSError:
            names = []
        for name in names:
            if name == "default" or not is_safe_workspace_name(name):
                continue
            candidate = os.path.join(base, name)
            if not os.path.isdir(candidate) or os.path.islink(candidate):
                continue
            try:
                projects[name] = (
                    candidate,
                    _queue_recovery_project_identity(name, candidate),
                )
            except (ValueError, QueueRecoveryAdapterError):
                continue
    return projects


_queue_recovery_final_adoption_jobs: dict[tuple[str, str], dict] = {}
_queue_recovery_final_adoption_startup_summary = {
    "adopted_groups": 0,
    "missing_groups": 0,
    "quarantined_groups": 0,
    "failed_projects": 0,
}


def _queue_recovery_adopt_quarantined_finals(
    projects: Mapping[str, tuple[str, str]],
) -> dict:
    """Adopt complete attested finals before cleanup/indexing, never jobs."""
    global _queue_recovery_final_adoption_jobs
    global _queue_recovery_final_adoption_startup_summary
    jobs: dict[tuple[str, str], dict] = {}
    aggregate = {
        "adopted_groups": 0,
        "missing_groups": 0,
        "quarantined_groups": 0,
        "failed_projects": 0,
    }
    for workspace, project in sorted(projects.items()):
        try:
            summary = _adopt_quarantined_final_groups(
                project[0],
                workspace=workspace,
            )
        except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
            aggregate["failed_projects"] += 1
            continue
        for key in ("adopted_groups", "missing_groups", "quarantined_groups"):
            value = summary.get(key)
            if type(value) is int and value >= 0:
                aggregate[key] += value
        for item in summary.get("jobs") or []:
            if not isinstance(item, dict):
                continue
            job_id = str(item.get("job_id") or "")
            state = str(item.get("state") or "")
            counts = {
                key: item.get(key)
                for key in ("declared", "adopted", "missing", "quarantined")
            }
            output_files = item.get("output_files")
            if (
                not job_id
                or state not in {"adopted", "missing", "quarantined"}
                or any(type(value) is not int or value < 0 for value in counts.values())
                or not isinstance(output_files, list)
                or any(
                    not isinstance(name, str)
                    or not name
                    or os.path.basename(name) != name
                    or name.startswith(".")
                    for name in output_files
                )
                or (state == "adopted" and len(output_files) != counts["adopted"])
                or (state != "adopted" and output_files)
            ):
                continue
            jobs[(workspace, job_id)] = {
                "state": state,
                **counts,
                "output_files": list(output_files),
            }
    _queue_recovery_final_adoption_jobs = jobs
    _queue_recovery_final_adoption_startup_summary = aggregate
    if any(aggregate.values()):
        print(
            "[Maestro] Final recovery: "
            f"{aggregate['adopted_groups']} adopted, "
            f"{aggregate['missing_groups']} missing, "
            f"{aggregate['quarantined_groups']} retained, "
            f"{aggregate['failed_projects']} project scans deferred.",
            flush=True,
        )
    return dict(aggregate)


def _valid_sample_campaign_recovery_groups(
    snapshots: Sequence[Mapping[str, Any]],
) -> tuple[tuple[dict, dict], ...]:
    """Return only exact reciprocal held pairs; never infer a missing peer."""
    grouped: dict[tuple[str, str], list[dict]] = {}
    for raw in snapshots:
        if not isinstance(raw, dict) or raw.get("kind") != "sample_campaign_generation":
            continue
        cursor = raw.get("recovery_cursor")
        linkage = cursor.get("sample_campaign") if isinstance(cursor, dict) else None
        if not isinstance(linkage, dict):
            continue
        key = (
            str(linkage.get("pair_id") or ""),
            str(linkage.get("pair_manifest_digest") or ""),
        )
        grouped.setdefault(key, []).append(raw)

    valid = []
    for (pair_id, digest), candidates in grouped.items():
        if not pair_id or len(digest) != 64 or len(candidates) != 2:
            continue
        by_arm = {}
        for candidate in candidates:
            cursor = candidate.get("recovery_cursor")
            linkage = cursor.get("sample_campaign") if isinstance(cursor, dict) else None
            arm = linkage.get("arm") if isinstance(linkage, dict) else None
            if arm in by_arm:
                by_arm = {}
                break
            by_arm[arm] = candidate
        if set(by_arm) != {"maestro", "control"}:
            continue
        maestro = by_arm["maestro"]
        control = by_arm["control"]
        shared = (
            "owner_principal", "project_instance", "workspace",
        )
        if any(maestro.get(field) != control.get(field) for field in shared):
            continue
        maestro_link = maestro["recovery_cursor"]["sample_campaign"]
        control_link = control["recovery_cursor"]["sample_campaign"]
        if (
            maestro.get("id") == control.get("id")
            or maestro_link.get("peer_job_id") != control.get("id")
            or control_link.get("peer_job_id") != maestro.get("id")
            or any(
                candidate.get("queue_class") != _SAMPLE_CAMPAIGN_QUEUE_CLASS
                or candidate.get("queue_priority")
                    != _SAMPLE_CAMPAIGN_QUEUE_PRIORITY
                for candidate in candidates
            )
            or not valid_sample_pair_lifecycle(maestro, control)
        ):
            continue
        valid.append((maestro, control))
    return tuple(valid)


def _validate_sample_campaign_recovery_linkage(
    snapshot: dict,
    params: dict,
    inputs: Sequence[Mapping[str, Any]] = (),
) -> dict:
    """Validate private pair evidence and return engine-safe request params."""
    cursor = snapshot.get("recovery_cursor")
    durable = cursor.get("sample_campaign") if isinstance(cursor, dict) else None
    private = params.get("_sample_campaign_private")
    if durable is None and private is None:
        return dict(params)
    keys = {
        "schema", "pair_id", "pair_manifest_digest", "arm", "peer_job_id",
    }
    if (
        not isinstance(durable, dict)
        or not isinstance(private, dict)
        or set(durable) != keys
        or set(private) != {
            "pair_manifest", "pair_manifest_digest", "linkage",
        }
        or private.get("linkage") != durable
        or private.get("pair_manifest_digest")
            != durable.get("pair_manifest_digest")
        or durable.get("schema") != _SAMPLE_CAMPAIGN_LINKAGE_SCHEMA
        or durable.get("arm") not in {"maestro", "control"}
        or not isinstance(durable.get("pair_id"), str)
        or not durable["pair_id"]
        or not isinstance(durable.get("peer_job_id"), str)
        or not durable["peer_job_id"]
        or durable["peer_job_id"] == snapshot.get("id")
        or snapshot.get("kind") != "sample_campaign_generation"
        or snapshot.get("queue_class") != _SAMPLE_CAMPAIGN_QUEUE_CLASS
        or snapshot.get("queue_priority") != _SAMPLE_CAMPAIGN_QUEUE_PRIORITY
        or (
            str(snapshot.get("status") or "").casefold()
                not in {"queued", "running", "completed"}
            or type(snapshot.get("queue_held")) is not bool
            or (
                str(snapshot.get("status") or "").casefold()
                in {"running", "completed"}
                and snapshot.get("queue_held") is not False
            )
        )
    ):
        raise QueueRecoveryRuntimeError(
            "Sample campaign recovery linkage is invalid."
        )
    try:
        pair = parse_private_pair_manifest(private.get("pair_manifest"))
        digest = pair_manifest_digest(pair)
        arm = pair.maestro if durable["arm"] == "maestro" else pair.control
        descriptor_paths = tuple(
            str(item.get("path") or "") for item in inputs
            if isinstance(item, Mapping)
        )
        descriptor_digests = tuple(
            str(item.get("sha256") or "").lower() for item in inputs
            if isinstance(item, Mapping)
        )
        if (
            digest != durable["pair_manifest_digest"]
            or pair.pair_id != durable["pair_id"]
            or arm.private_input_paths != descriptor_paths
            or arm.input_fingerprints != descriptor_digests
        ):
            raise SampleCampaignSubmissionError(
                "Campaign private recovery evidence is inconsistent."
            )
    except (SampleCampaignSubmissionError, ValueError, TypeError) as error:
        raise QueueRecoveryRuntimeError(
            "Sample campaign recovery linkage is invalid."
        ) from error
    clean = dict(params)
    clean.pop("_sample_campaign_private", None)
    return clean


def _queue_recovery_materialize_job(
    snapshot: dict,
    projects: dict[str, tuple[str, str]],
) -> tuple[dict, bool]:
    """Rebuild one safe runtime job and report whether it may auto-resume."""
    job_id = str(snapshot.get("id") or "")
    workspace = str(snapshot.get("workspace") or "default")
    owner_digest = str(snapshot.get("owner_principal") or "")
    expected_project = str(snapshot.get("project_instance") or "")
    runtime = {
        key: value
        for key, value in snapshot.items()
        if key not in {"owner_principal", "project_instance", "request_manifest"}
    }
    runtime.update({
        "id": job_id,
        "workspace": workspace,
        "session_id": None,
        "access_policy": {
            "private": bool(snapshot.get("private", False)),
            "explicit": bool(snapshot.get("explicit", False)),
        },
        "error": None,
        "_recovery_owner_digest": owner_digest,
        "_recovery_project_digest": expected_project,
        "_recovery_manifest_pointer": dict(snapshot.get("request_manifest") or {}),
    })
    final_adoption = globals().get(
        "_queue_recovery_final_adoption_jobs", {}
    ).get((workspace, job_id))
    if isinstance(final_adoption, dict):
        runtime["_recovery_final_adoption"] = dict(final_adoption)
    snapshot_cursor = snapshot.get("recovery_cursor")
    snapshot_units = (
        snapshot_cursor.get("completed_units")
        if isinstance(snapshot_cursor, dict) else None
    )
    had_h3_unit_evidence = any(
        isinstance(unit, dict)
        and str(unit.get("kind") or "").startswith("h3_")
        for unit in (snapshot_units if isinstance(snapshot_units, list) else [])
    )
    had_h3_segment_evidence = any(
        isinstance(unit, dict) and unit.get("kind") == "h3_segment"
        for unit in (snapshot_units if isinstance(snapshot_units, list) else [])
    )
    publication_recovery = globals().get(
        "_project_reference_publication_recovery_requested"
    )
    project_reference_finalization = bool(
        callable(publication_recovery) and publication_recovery(snapshot)
    )
    completed_final_adoption = bool(
        isinstance(final_adoption, dict)
        and final_adoption.get("state") == "adopted"
        and str(snapshot.get("status") or "").casefold() == "completed"
    )
    current = projects.get(workspace)
    blocked_reason = "Recovery project is missing or was recreated"
    blocked_code = "project_missing_or_recreated"
    manifest = None
    if current is not None and hmac.compare_digest(current[1], expected_project):
        runtime["out_dir"] = current[0]
        if project_reference_finalization or completed_final_adoption:
            # Completion-only recovery is authorized entirely by the sealed,
            # content-free recovery unit/receipt and committed asset evidence.
            # It must never reload private request inputs or rerun generation.
            blocked_reason = ""
            blocked_code = ""
        else:
            try:
                manifest = load_request_manifest(
                    current[0],
                    snapshot.get("request_manifest") or {},
                    expected_job_id=job_id,
                )
                validate_manifest_inputs(
                    manifest,
                    lambda descriptor: _queue_recovery_manifest_validator(
                        dict(descriptor),
                        owner_digest=owner_digest,
                        workspace=workspace,
                        project_dir=current[0],
                    ),
                )
                manifest_params = dict(manifest["params"])
                sample_linkage_validator = globals().get(
                    "_validate_sample_campaign_recovery_linkage",
                )
                if callable(sample_linkage_validator):
                    manifest_params = sample_linkage_validator(
                        snapshot, manifest_params, manifest.get("inputs") or (),
                    )
                runtime["params"] = manifest_params
                if (
                    str(runtime["params"].get("model_type") or "").startswith(
                        "minimax_h3"
                    )
                    and runtime["params"].get(H3_OFFLOAD_PLAN_PARAM_KEY) is None
                    and runtime.get("h3_offload_plan") is None
                ):
                    # Only startup materialization can attest that an otherwise
                    # valid durable record predates the v1 plan contract. Fresh
                    # and direct jobs never receive this process-local marker.
                    runtime["_h3_offload_legacy_recovery"] = True
                _require_h3_offload_plan_parity(runtime)
                _queue_recovery_reconcile_cursor(runtime, current[0])
                blocked_reason = ""
                blocked_code = ""
            except QueueRecoveryRuntimeError:
                blocked_reason = "Recovery request or input validation failed"
                blocked_code = "input_missing_or_changed"

    if not blocked_reason and isinstance(final_adoption, dict):
        adopted_outputs = final_adoption.get("output_files")
        if (
            final_adoption.get("state") == "adopted"
            and isinstance(adopted_outputs, list)
            and len(adopted_outputs) == final_adoption.get("adopted")
        ):
            runtime["output_files"] = list(adopted_outputs)
            artifacts = [
                name for name in runtime.get("artifact_files") or []
                if isinstance(name, str) and name
            ]
            for name in adopted_outputs:
                if name not in artifacts:
                    artifacts.append(name)
            runtime["artifact_files"] = artifacts

    status = str(snapshot.get("status") or "queued").casefold()
    if (
        snapshot.get("kind") == "prompt_enhancement"
        and status not in {"completed", "failed", "cancelled", "canceled"}
    ):
        # The queue owns restart visibility and credit finality, but never
        # guesses or auto-runs private content after process interruption.
        runtime.update({
            "status": "failed",
            "finished_at": time.time(),
            "queue_held": False,
            "recovery_state": "terminal",
            "reruns_denoise": False,
            "phase": "failed",
            "message": "Prompt enhancement was interrupted",
            "error": "Prompt enhancement was interrupted",
            "resource_execution": "standard",
            "preemption_mode": "none",
            "resource_state": "released",
        })
        return runtime, False
    if snapshot.get("kind") == "sample_campaign_generation":
        if status == "completed" and not blocked_reason:
            runtime.update({
                "status": "completed",
                "queue_held": False,
                "recovery_state": "terminal",
                "message": str(
                    snapshot.get("message") or "Sample arm completed"
                ),
                "error": None,
            })
            return runtime, False
        runtime.update({
            "status": "queued",
            "queue_held": True,
            "resource_state": "queued",
            "recovery_state": (
                "sample_campaign_held" if not blocked_reason else "blocked"
            ),
            "message": (
                "Held for dedicated sample release"
                if not blocked_reason else "Sample recovery evidence is invalid"
            ),
            "error": None,
        })
        return runtime, False
    if snapshot.get("resource_intent") in {"text", "generation"}:
        # A process-local CPU lease and runtime tokens never survive restart.
        # Preserve the attempt counter for stale-result fences, but reacquire
        # every resource from a conservative standard/released-or-queued state.
        runtime.update({
            "resource_execution": "standard",
            "preemption_mode": "none",
            "resource_state": (
                "released"
                if status in {"completed", "failed", "cancelled", "canceled"}
                or bool(snapshot.get("cancel_requested"))
                else "queued"
            ),
        })
    remote = bool(snapshot.get("source_remote", False))
    if status in {"cancelled", "canceled"} or snapshot.get("cancel_requested"):
        runtime.update({
            "status": "cancelled",
            "cancel_requested": True,
            "recovery_state": "cancelled",
            "message": "Cancelled",
        })
        return runtime, False
    if status == "failed" and not blocked_reason:
        # Older journals did not persist safe OOM details.  A fully verified
        # contiguous H3 prefix plus exactly one missing final segment may be
        # exposed for explicit owner recovery, but is never auto-started.
        if _h3_incomplete_recovery_prefix(runtime) is not None:
            if remote:
                runtime.update({
                    "status": "queued",
                    "queue_held": True,
                    "recovery_state": "blocked_remote_reauth",
                    "reruns_denoise": False,
                    "_recovery_reason_code": (
                        "owner_reauthentication_required"
                    ),
                    "message": (
                        "Owner reauthentication is required to resume"
                    ),
                    "error": None,
                })
                return runtime, False
            runtime.update({
                "status": "queued",
                "queue_held": True,
                "recovery_state": "blocked",
                "reruns_denoise": False,
                "_recovery_reason_code": (
                    "h3_generation_recovery_authorization_required"
                ),
                "message": "Calibrated H3 recovery authorization is required",
                "error": None,
            })
            return runtime, False
    runtime_params = runtime.get("params")
    h3_finality_required = bool(
        had_h3_unit_evidence
        or isinstance(final_adoption, dict)
        or (
            isinstance(runtime_params, dict)
            and str(runtime_params.get("model_type") or "").startswith(
                "minimax_h3"
            )
        )
    )
    if status == "completed" and h3_finality_required:
        adopted_state = (
            str(final_adoption.get("state") or "")
            if isinstance(final_adoption, dict) else ""
        )
        verified_outputs = [
            name for name in runtime.get("output_files") or []
            if isinstance(name, str) and name
        ]
        if (
            blocked_reason
            or not verified_outputs
            or adopted_state in {"missing", "quarantined"}
        ):
            runtime.update({
                "status": "queued",
                "queue_held": True,
                "recovery_state": "blocked",
                "reruns_denoise": False,
                "_recovery_reason_code": "final_output_recovery_incomplete",
                "message": "Final output recovery is incomplete",
                "error": None,
            })
            return runtime, False
    if status in {"completed", "failed"}:
        runtime["status"] = status
        runtime["recovery_state"] = "terminal"
        return runtime, False

    # Executable H3 recovery remains visible but held.  Preserve its prior
    # attempt counter and never start a model worker.  Verified delivery-only
    # recovery is handled from retained native bytes on terminal source jobs.
    if _job_uses_registered_h3(runtime):
        try:
            legal_attempt = max(
                0, int(snapshot.get("recovery_attempt", 0) or 0),
            )
        except (TypeError, ValueError):
            legal_attempt = 0
        runtime.update({
            "status": "queued",
            "queue_held": True,
            "recovery_state": "blocked",
            "recovery_attempt": legal_attempt,
            "reruns_denoise": False,
            "_recovery_reason_code": "h3_legal_access_required",
            "message": "MiniMax H3 needs a separate written license",
            "error": None,
        })
        return runtime, False

    try:
        prior_attempt = max(
            0, int(snapshot.get("recovery_attempt", 0) or 0),
        )
    except (TypeError, ValueError):
        prior_attempt = 0
    if status == "waiting_for_plan_approval":
        runtime["recovery_attempt"] = prior_attempt
        if blocked_reason:
            runtime.update({
                "status": "failed",
                "plan_review_required": False,
                "plan_review_deadline": None,
                "recovery_state": "terminal",
                "message": "Prepared generation state could not be restored",
                "error": "Prepared generation state could not be restored",
            })
        else:
            deadline = runtime.get("plan_review_deadline")
            terms_required = bool(
                runtime.get("plan_review_terms_required", False)
            )
            if terms_required:
                deadline = None
            elif (
                type(deadline) not in {int, float}
                or not math.isfinite(deadline)
                or deadline <= 0
            ):
                deadline = time.time() + _PLAN_REVIEW_TIMEOUT_SECONDS
            runtime.update({
                "status": "waiting_for_plan_approval",
                "plan_review_required": True,
                "plan_review_terms_required": terms_required,
                "plan_review_deadline": (
                    None if terms_required else float(deadline)
                ),
                "queue_held": False,
                "recovery_state": "restored",
                "reruns_denoise": False,
                "message": (
                    "Approval required to accept Ref2VA terms"
                    if terms_required else "Review the generation plan"
                ),
                "phase": (
                    "awaiting_plan_terms"
                    if terms_required else "awaiting_plan_approval"
                ),
            })
        return runtime, False

    if status == "preparing":
        # Content-authoring inference cannot be guessed or bypassed after a
        # process interruption. Terminalize rather than generate the original
        # request or increment a denoise recovery attempt.
        runtime.update({
            "status": "failed",
            "plan_review_required": False,
            "recovery_attempt": prior_attempt,
            "recovery_state": "terminal",
            "reruns_denoise": False,
            "message": "Prompt enhancement was interrupted",
            "error": "Prompt enhancement was interrupted",
            "resource_execution": "standard",
            "preemption_mode": "none",
            "resource_state": "released",
        })
        return runtime, False

    runtime["recovery_attempt"] = prior_attempt
    runtime["status"] = "queued"
    runtime["_recovery_original_held"] = bool(snapshot.get("queue_held", False))
    if _queue_recovery_worker(runtime) is None:
        runtime.update({
            "_recovery_reason_code": "preparation_must_resubmit",
            "queue_held": True,
            "recovery_state": "blocked_preparation",
            "reruns_denoise": False,
            "message": "This interrupted preparation must be resubmitted",
        })
        return runtime, False
    if blocked_reason:
        runtime.update({
            "_recovery_reason_code": blocked_code,
            "queue_held": True,
            "recovery_state": "blocked",
            "message": blocked_reason,
        })
        return runtime, False
    if remote and not project_reference_finalization:
        runtime.update({
            "_recovery_reason_code": "owner_reauthentication_required",
            "queue_held": True,
            "recovery_state": "blocked_remote_reauth",
            "message": "Owner reauthentication is required to resume",
        })
        return runtime, False
    if project_reference_finalization:
        runtime.update({
            "_recovery_reason_code": "",
            "queue_held": False,
            "recovery_state": "publication_prepared",
            "reruns_denoise": False,
            "message": "Reconciling committed reference packs",
        })
        return runtime, True
    held_h3_prefix = (
        _h3_incomplete_recovery_prefix(runtime)
        if snapshot.get("queue_held", False) else None
    )
    durable_h3_resource_retry = (
        runtime.get("resource_retry_phase") == "generation"
        and runtime.get("resource_retry_reason") == "generation_oom"
        and type(runtime.get("resource_retry_attempt")) is int
        and type(runtime.get("resource_retry_limit")) is int
        and 1 <= runtime["resource_retry_attempt"]
        <= runtime["resource_retry_limit"] <= _MAX_AUTOMATIC_RESOURCE_RETRIES
    )
    durable_h3_prefix = (
        _h3_dependency_closed_recovery_prefix(runtime)
        if snapshot.get("queue_held", False)
        and durable_h3_resource_retry else None
    )
    h3_reason = str(runtime.get("_recovery_reason_code") or "")
    if durable_h3_prefix is not None and h3_reason in {
        "h3_resource_retry_pending_replan",
        "h3_generation_oom_replanned",
    }:
        pending_replan = h3_reason == "h3_resource_retry_pending_replan"
        runtime.update({
            "queue_held": pending_replan,
            "recovery_state": "retrying",
            "reruns_denoise": True,
            "message": (
                "Preparing a safer final H3 segment retry"
                if pending_replan else "Queued for calibrated H3 recovery"
            ),
        })
        # Pending work is prepared before worker start. A fully resealed plan
        # can restart immediately. Neither path consumes another retry.
        return runtime, True
    if held_h3_prefix is not None:
        # A held, dependency-closed H3 prefix is a recovery authorization
        # state, not an ordinary manual queue hold. Generic restoration used
        # to erase this reason, leaving exact local prepare permanently
        # unreachable after restart. Preserve only reviewed H3 reasons; an
        # empty/legacy reason regains explicit owner authorization and never
        # consumes an automatic attempt or calibration decision.
        if h3_reason not in {
            "h3_generation_recovery_authorization_required",
            "h3_peak_calibration_required",
            "h3_generation_oom_replanned",
        }:
            h3_reason = "h3_generation_recovery_authorization_required"
        runtime.update({
            "_recovery_reason_code": h3_reason,
            "queue_held": True,
            "recovery_state": "blocked",
            "reruns_denoise": h3_reason == "h3_generation_oom_replanned",
            "message": {
                "h3_generation_recovery_authorization_required": (
                    "Calibrated H3 recovery authorization is required"
                ),
                "h3_peak_calibration_required": (
                    "Calibrated H3 recovery capacity is required"
                ),
                "h3_generation_oom_replanned": (
                    "Calibrated H3 replacement plan is ready"
                ),
            }[h3_reason],
        })
        return runtime, False
    recovery_cursor = runtime.get("recovery_cursor")
    completed_units = (
        recovery_cursor.get("completed_units")
        if isinstance(recovery_cursor, dict) else None
    )
    if snapshot.get("queue_held", False) and (
        had_h3_segment_evidence or any(
            isinstance(unit, dict) and unit.get("kind") == "h3_segment"
            for unit in (
                completed_units if isinstance(completed_units, list) else []
            )
        )
    ):
        # Segment evidence that is not the exact dependency-closed prefix is
        # neither an ordinary manual hold nor safe automatic work.
        runtime.update({
            "_recovery_reason_code": "input_missing_or_changed",
            "queue_held": True,
            "recovery_state": "blocked",
            "reruns_denoise": False,
            "message": "H3 recovery prefix validation failed",
        })
        return runtime, False
    if snapshot.get("queue_held", False):
        runtime.update({
            "_recovery_reason_code": "",
            "queue_held": True,
            "recovery_state": "restored",
            "reruns_denoise": status == "running",
            "message": str(snapshot.get("message") or "Queued"),
        })
        return runtime, False
    attempt, may_retry = next_recovery_attempt(snapshot)
    if not may_retry:
        runtime.update({
            "_recovery_reason_code": "attempt_limit_reached",
            "queue_held": True,
            "recovery_state": "blocked",
            "recovery_attempt": prior_attempt,
            "message": "Automatic recovery attempt limit reached",
        })
        return runtime, False
    runtime["recovery_attempt"] = attempt
    runtime.update({
        "_recovery_reason_code": "",
        "queue_held": False,
        "recovery_state": "interrupted" if status == "running" else "restored",
        "reruns_denoise": status == "running",
        "message": (
            "Recovered after an interrupted safe unit"
            if status == "running" else str(snapshot.get("message") or "Queued")
        ),
    })
    return runtime, True


def _director_recovery_restore_parent(
    snapshot: dict,
    projects: dict[str, tuple[str, str]],
) -> str | None:
    """Restore one exact Director parent after all child jobs are visible."""
    cursor = snapshot.get("recovery_cursor")
    cursor = cursor if isinstance(cursor, dict) else {}
    pid = str(cursor.get("pipeline_id") or "")
    if not pid:
        return None
    # A journal-known id may never fall back to the legacy raw-JSON resume
    # route when its exact recovery authority cannot be reconstructed.
    _director_recovery_rejected_parents[pid] = dict(snapshot)
    workspace = str(snapshot.get("workspace") or "default")
    current = projects.get(workspace)
    if current is None:
        return None
    expected_project = str(snapshot.get("project_instance") or "")
    if not hmac.compare_digest(current[1], expected_project):
        return None
    owner_digest = str(snapshot.get("owner_principal") or "")
    try:
        from services.director_pipeline import pipeline_state_filename
        from services.win_safe_files import safe_direct_file_under
        state_filename = pipeline_state_filename(pid)
        state_path = safe_direct_file_under(current[0], state_filename)
        if cursor.get("delete_pending") and (
            not state_path or not os.path.isfile(state_path)
        ):
            _queue_recovery_durable_transition(DurableTransition(
                name="director-parent-delete-reconciled",
                tombstones=(str(snapshot.get("id") or ""),),
            ))
            remove_request_manifest(
                current[0], snapshot.get("request_manifest") or {},
            )
            _director_recovery_rejected_parents.pop(pid, None)
            return None
        state, sealed_state, _used_pending = (
            _load_director_recovery_cursor_state(
                current[0], state_filename, cursor,
            )
        )
        if state is None:
            raise QueueRecoveryRuntimeError(
                "Director recovery state hash changed."
            )
        if not state_path or not os.path.isfile(state_path):
            raise QueueRecoveryRuntimeError(
                "Director recovery state is unavailable."
            )
        if not isinstance(state, dict) or state.get("pipeline_id") != pid:
            raise QueueRecoveryRuntimeError(
                "Director recovery state is invalid."
            )
        state_owner = _pipeline_owner(state.get("_params_snapshot"))
        if not state_owner or not hmac.compare_digest(
            owner_principal_digest(_session_secret(), state_owner),
            owner_digest,
        ):
            raise QueueRecoveryRuntimeError(
                "Director recovery owner evidence changed."
            )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        return None

    blocked_reason = ""
    manifest = None
    try:
        manifest = load_request_manifest(
            current[0],
            snapshot.get("request_manifest") or {},
            expected_job_id=str(snapshot.get("id") or ""),
        )
        manifest_params = manifest.get("params") or {}
        if (
            manifest_params.get("pipeline_id") != pid
            or manifest_params.get("state_filename") != state_filename
        ):
            raise QueueRecoveryRuntimeError(
                "Director recovery state pointer is invalid."
            )
        validate_manifest_inputs(
            manifest,
            lambda descriptor: _queue_recovery_manifest_validator(
                dict(descriptor),
                owner_digest=owner_digest,
                workspace=workspace,
                project_dir=current[0],
            ),
        )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        blocked_reason = (
            "Recovery is blocked because its saved request or inputs "
            "could not be validated."
        )

    parent = _director_runtime_parent_from_snapshot(
        snapshot,
        identity_key="pipeline_id",
        identity_value=pid,
        state_descriptor=dict(sealed_state or {}),
        unit_kind="director_parent_state",
    )
    _director_recovery_parents[pid] = parent
    _director_recovery_rejected_parents.pop(pid, None)
    _init_pipeline()
    from services.director_pipeline import restore_registered_pipeline
    active = str(state.get("status") or "") not in {
        "completed", "failed", "cancelled",
    }
    blocked_remote = (
        not blocked_reason
        and bool(snapshot.get("source_remote", False))
        and active
    )
    _queue_recovery_checkpoint(
        parent,
        status=(
            "queued"
            if str(state.get("status") or "")
                in {"completed", "failed", "cancelled"}
            else str(state.get("status") or "queued")
        ),
        queue_held=bool(blocked_reason or blocked_remote),
        recovery_state=(
            "terminal" if not active
            else "blocked" if blocked_reason
            else "blocked_remote_reauth" if blocked_remote
            else "restored"
        ),
        phase=str(state.get("phase") or state.get("status") or "restored"),
        message="Director recovery state restored",
        recovery_unit=dict(parent["recovery_unit"]),
        recovery_cursor=dict(parent["recovery_cursor"]),
    )
    if blocked_reason and active:
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            queue_held=True,
            recovery_state="blocked",
            message=blocked_reason,
        )
    elif blocked_remote:
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            queue_held=True,
            recovery_state="blocked_remote_reauth",
            message="Owner reauthentication is required to resume",
        )
    restore_registered_pipeline(
        state,
        state_path,
        {
            "id": str(snapshot.get("id") or ""),
            "owner_digest": owner_digest,
            "project_digest": expected_project,
            "inputs": list((manifest or {}).get("inputs") or []),
        },
        blocked_remote=blocked_remote,
        blocked_reason=blocked_reason if active else "",
        defer_worker=True,
    )
    return pid if active and not blocked_remote and not blocked_reason else None


def _director_recovery_restore_preparation(
    snapshot: dict,
    projects: dict[str, tuple[str, str]],
) -> bool:
    cursor = snapshot.get("recovery_cursor")
    cursor = cursor if isinstance(cursor, dict) else {}
    request_id = str(cursor.get("request_id") or "")
    if not request_id:
        return False
    _director_preparation_rejected_parents[request_id] = dict(snapshot)
    terminal_snapshot = (
        str(snapshot.get("recovery_state") or "") == "terminal"
        or str(snapshot.get("status") or "") == "completed"
    )
    workspace = str(snapshot.get("workspace") or "default")
    current = projects.get(workspace)
    if current is None:
        if terminal_snapshot:
            _queue_recovery_durable_transition(DurableTransition(
                name="director-preparation-missing-project-retired",
                tombstones=(str(snapshot.get("id") or ""),),
            ))
            _director_preparation_rejected_parents.pop(request_id, None)
        return False
    expected_project = str(snapshot.get("project_instance") or "")
    owner_digest = str(snapshot.get("owner_principal") or "")
    if not hmac.compare_digest(current[1], expected_project):
        if terminal_snapshot:
            _queue_recovery_durable_transition(DurableTransition(
                name="director-preparation-recreated-project-retired",
                tombstones=(str(snapshot.get("id") or ""),),
            ))
            _director_preparation_rejected_parents.pop(request_id, None)
        return False
    try:
        filename = _director_preparation_filename(request_id)
        if cursor.get("retire_pending"):
            _remove_director_preparation_state(current[0], request_id)
            _queue_recovery_durable_transition(DurableTransition(
                name="director-preparation-retirement-reconciled",
                tombstones=(str(snapshot.get("id") or ""),),
            ))
            remove_request_manifest(
                current[0], snapshot.get("request_manifest") or {},
            )
            _director_preparation_rejected_parents.pop(request_id, None)
            return False
        state, sealed_state, _used_pending = (
            _load_director_recovery_cursor_state(
                current[0], filename, cursor,
            )
        )
        if state is None:
            raise QueueRecoveryRuntimeError(
                "Director preparation state hash changed."
            )
        owner = str(state.get("owner_session_id") or "")
        if (
            not isinstance(state, dict)
            or state.get("request_id") != request_id
            or state.get("workspace") != workspace
            or not owner
            or not hmac.compare_digest(
                owner_principal_digest(_session_secret(), owner),
                owner_digest,
            )
        ):
            raise QueueRecoveryRuntimeError(
                "Director preparation owner evidence changed."
            )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        return False
    blocked_inputs = False
    try:
        manifest = load_request_manifest(
            current[0],
            snapshot.get("request_manifest") or {},
            expected_job_id=str(snapshot.get("id") or ""),
        )
        manifest_params = manifest.get("params") or {}
        if (
            manifest_params.get("request_id") != request_id
            or manifest_params.get("state_filename") != filename
        ):
            raise QueueRecoveryRuntimeError(
                "Director preparation pointer is invalid."
            )
        validate_manifest_inputs(
            manifest,
            lambda descriptor: _queue_recovery_manifest_validator(
                dict(descriptor),
                owner_digest=owner_digest,
                workspace=workspace,
                project_dir=current[0],
            ),
        )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        blocked_inputs = state.get("status") != "completed"
    parent = _director_runtime_parent_from_snapshot(
        snapshot,
        identity_key="request_id",
        identity_value=request_id,
        state_descriptor=dict(sealed_state or {}),
        unit_kind="director_preparation_state",
    )
    with _director_preparation_lock:
        _director_preparation_parents[request_id] = parent
        runtime_state = dict(state)
        if blocked_inputs:
            runtime_state.update({
                "status": "blocked",
                "phase": "blocked_input_changed",
                "recovery_blocked": True,
            })
        _director_preparation_states[request_id] = runtime_state
    _director_preparation_rejected_parents.pop(request_id, None)
    _queue_recovery_checkpoint(
        parent,
        status="queued",
        queue_held=bool(
            blocked_inputs
            or (
                snapshot.get("source_remote", False)
                and state.get("status") != "completed"
            )
        ),
        recovery_state=(
            "terminal" if state.get("status") == "completed"
            else "blocked" if blocked_inputs
            else "blocked_remote_reauth"
            if snapshot.get("source_remote", False)
            else "restored"
        ),
        phase=str(state.get("phase") or "restored"),
        message="Director preparation state restored",
        recovery_unit=dict(parent["recovery_unit"]),
        recovery_cursor=dict(parent["recovery_cursor"]),
    )
    if blocked_inputs:
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            queue_held=True,
            recovery_state="blocked",
            message=(
                "Director preparation inputs changed; manual restart is "
                "required"
            ),
        )
    elif (
        bool(snapshot.get("source_remote", False))
        and state.get("status") != "completed"
    ):
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            queue_held=True,
            recovery_state="blocked_remote_reauth",
            message="Owner reauthentication is required to resume",
        )
    return True


def _safe_sample_campaign_restart_snapshot(snapshot: Mapping[str, Any]) -> bool:
    """Accept only exact durable sample states before materialization."""
    status = str(snapshot.get("status") or "").casefold()
    recovery_state = str(snapshot.get("recovery_state") or "")
    if status == "completed":
        return recovery_state == "terminal"
    retry = snapshot.get("sample_retry")
    retry_is_valid = bool(
        isinstance(retry, Mapping)
        and set(retry) == {"attempt", "not_before"}
        and type(retry.get("attempt")) is int
        and 1 <= retry["attempt"] <= SAMPLE_RETRY_MAX_ATTEMPT
        and type(retry.get("not_before")) in {int, float}
        and math.isfinite(float(retry["not_before"]))
        and float(retry["not_before"]) >= 0.0
    )
    if status == "queued" and snapshot.get("queue_held") is True:
        return bool(
            recovery_state == "sample_campaign_held"
            or (
                recovery_state == "sample_campaign_released"
                and retry_is_valid
            )
        )
    # A crash can split the durable request from settlement.  Only this exact
    # preemption-requested state is normalized into the same held retry that
    # settlement would have committed; arbitrary running samples stay inert.
    return bool(
        status == "running"
        and snapshot.get("queue_held") is False
        and snapshot.get("resource_state") == "preemption_requested"
        and recovery_state == "sample_campaign_released"
        and retry_is_valid
    )


def _restore_queue_recovery_on_startup(
    *, before_recovered_workers=None,
    run_recovered_operation=None,
    begin_recovered_execution=None,
    end_recovered_execution=None,
    recovered_execution_started=None,
) -> bool:
    """Restore scheduler membership before starting any recovered workers."""
    global _queue_recovery_workers_started
    if _queue_recovery_workers_started:
        return True
    if callable(run_recovered_operation):
        run_startup_operation = run_recovered_operation
    else:
        def run_startup_operation(operation):
            operation()
            return True
    begin_startup_execution = (
        begin_recovered_execution
        if callable(begin_recovered_execution)
        else lambda: True
    )
    end_startup_execution = (
        end_recovered_execution
        if callable(end_recovered_execution)
        else lambda: None
    )

    def finish_interrupted_startup_execution() -> bool:
        global _queue_recovery_workers_started
        partially_started = bool(
            callable(recovered_execution_started)
            and recovered_execution_started()
        )
        if partially_started:
            # Never replay a launch set that may already own live workers.
            # Jobs not yet started remain visible and owner-controllable.
            _queue_recovery_workers_started = True
        end_startup_execution()
        return partially_started
    credit_journal = globals().get("_credit_accounting_journal")
    if callable(credit_journal):
        credit_journal()
    projects = _queue_recovery_existing_projects()
    final_adopter = globals().get("_queue_recovery_adopt_quarantined_finals")
    if callable(final_adopter):
        final_adopter(projects)
    credit_orphan_cleanup = globals().get(
        "_credit_reconcile_unregistered_cleanup_manifests"
    )
    orphan_credit_manifests, credit_cleanup_blocked = (
        credit_orphan_cleanup(
            projects, _queue_recovery_restored.jobs.values(),
        )
        if callable(credit_orphan_cleanup)
        else ({}, set())
    )
    restored_jobs: list[dict] = []
    resumable: list[dict] = []
    director_parents: list[dict] = []
    director_preparations: list[dict] = []
    director_resumable: list[str] = []
    director_legacy_payloads = False
    unsettled_terminal_credit = False
    sample_snapshots = tuple(
        snapshot for snapshot in _queue_recovery_restored.jobs.values()
        if snapshot.get("kind") == "sample_campaign_generation"
    )
    sample_group_validator = globals().get(
        "_valid_sample_campaign_recovery_groups"
    )
    sample_groups = (
        sample_group_validator(sample_snapshots)
        if callable(sample_group_validator) else ()
    )

    for sample_group in sample_groups:
        if any(
            not _safe_sample_campaign_restart_snapshot(snapshot)
            for snapshot in sample_group
        ):
            # Validate the journal bytes before the generic materializer can
            # normalize a malformed state into a conservative held runtime.
            continue
        materialized = tuple(
            _queue_recovery_materialize_job(snapshot, projects)[0]
            for snapshot in sample_group
        )
        if any(
            not job.get("out_dir")
            or (
                str(job.get("status") or "").casefold() == "completed"
                and job.get("recovery_state") != "terminal"
            )
            or (
                str(job.get("status") or "").casefold() != "completed"
                and (
                    job.get("status") != "queued"
                    or job.get("queue_held") is not True
                    or job.get("recovery_state") != "sample_campaign_held"
                )
            )
            for job in materialized
        ):
            # Durable held evidence remains available for a later repair; a
            # partial or tampered pair is never made live.
            continue
        _jobs.publish_prepared_many(tuple(
            (job["id"], _jobs.prepare(job)) for job in materialized
        ))
        restored_jobs.extend(materialized)
    for snapshot in _queue_recovery_restored.jobs.values():
        if snapshot.get("kind") == "sample_campaign_generation":
            continue
        if snapshot.get("kind") == "director_pipeline":
            director_parents.append(snapshot)
            director_legacy_payloads = (
                director_legacy_payloads
                or _director_snapshot_has_legacy_artifacts(snapshot)
            )
            continue
        if snapshot.get("kind") == "director_preparation":
            director_preparations.append(snapshot)
            director_legacy_payloads = (
                director_legacy_payloads
                or _director_snapshot_has_legacy_artifacts(snapshot)
            )
            continue
        job, auto_resume = _queue_recovery_materialize_job(snapshot, projects)
        credit_hydrate = globals().get("_credit_accounting_hydrate_job")
        if callable(credit_hydrate):
            credit_hydrate(job)
        credit_queue = job.get("credit_queue")
        cleanup = (
            job.get("params", {}).get(_CREDIT_CLEANUP_PARAM)
            if isinstance(job.get("params"), dict)
            else None
        )
        if (
            str(job.get("status") or "").casefold()
            in {"completed", "failed", "cancelled", "canceled"}
            and isinstance(credit_queue, dict)
            and credit_queue.get("schema_version") == 2
            and credit_queue.get("reservation_state") == "consumed"
        ):
            try:
                if not settle_terminal_credit(job):
                    unsettled_terminal_credit = True
            except (
                CreditAccountingError,
                CreditLifecycleCallbackError,
                OSError,
            ):
                unsettled_terminal_credit = True
            credit_queue = job.get("credit_queue")
        if (
            str(job.get("status") or "").casefold()
            in {"completed", "failed", "cancelled", "canceled"}
            and isinstance(credit_queue, dict)
            and credit_queue.get("schema_version") == 2
            and credit_queue.get("reservation_state") == "reserved"
        ):
            credit_release = globals().get("_credit_release_accounting")
            if not callable(credit_release) or not credit_release(
                job, persist_baseline=True,
            ):
                unsettled_terminal_credit = True
        elif (
            isinstance(cleanup, dict)
            and (
                not isinstance(credit_queue, dict)
                or credit_queue.get("schema_version") != 2
                or credit_queue.get("reservation_state") == "released"
            )
        ):
            credit_release = globals().get("_credit_release_accounting")
            if not callable(credit_release) or not credit_release(
                job, persist_baseline=True,
            ):
                unsettled_terminal_credit = True
        # Persist running->interrupted/blocked conversion before publication.
        if (
            job.get("status") not in {"completed", "failed", "cancelled"}
            or str(snapshot.get("status") or "").casefold() in {
                "preparing", "waiting_for_plan_approval",
            }
            or (
                job.get("kind") == "prompt_enhancement"
                and job.get("status") == "failed"
                and str(snapshot.get("status") or "").casefold()
                    in {"queued", "running"}
            )
        ):
            _queue_recovery_checkpoint(
                job,
                status=job.get("status"),
                queue_held=bool(job.get("queue_held", False)),
                recovery_attempt=int(job.get("recovery_attempt", 0) or 0),
                recovery_state=str(job.get("recovery_state") or "blocked"),
                reruns_denoise=bool(job.get("reruns_denoise", False)),
                message=str(job.get("message") or "Recovery blocked"),
            )
        if job.get("out_dir"):
            try:
                if job.get("status") == "queued":
                    _stamp_requested_generation_residency(job, replace=True)
            except Exception:
                job["queue_held"] = True
                job["recovery_state"] = "blocked"
                job["message"] = "Recovery scheduling validation failed"
                auto_resume = False
            _jobs.publish_prepared(job["id"], _jobs.prepare(job))
        else:
            # A missing/recreated project must remain visible as blocked but
            # can never trigger the registry's project-creating fallback.
            dict.__setitem__(_jobs, job["id"], _jobs.prepare(job))
        restored_jobs.append(job)
        if auto_resume:
            resumable.append(job)
    restore_scheduler_state(restored_jobs, _queue_recovery_restored.global_state)
    prompt_results = globals().get("_prompt_enhancement_result_store")
    if prompt_results is not None:
        try:
            prompt_results.cleanup_unreferenced(tuple(
                reference
                for candidate in restored_jobs
                if candidate.get("kind") == "prompt_enhancement"
                for reference in (candidate.get("prompt_result_reference"),)
                if isinstance(reference, Mapping)
            ))
        except Exception:
            # Uncertain result cleanup preserves bytes and leaves admission
            # fail-closed at the store's hard bound.
            pass
    for snapshot in director_parents:
        resumable_pid = _director_recovery_restore_parent(snapshot, projects)
        if resumable_pid:
            director_resumable.append(resumable_pid)
    for snapshot in director_preparations:
        _director_recovery_restore_preparation(snapshot, projects)
    retire_old_preparations = globals().get(
        "_director_recovery_retire_old_preparations"
    )
    if retire_old_preparations is not None:
        retire_old_preparations(projects)
    terminal_statuses = {"cancelled", "canceled", "completed", "failed"}
    if not unsettled_terminal_credit and (
        director_legacy_payloads or any(
            str(snapshot.get("status") or "").casefold() in terminal_statuses
            and snapshot.get("kind") != "director_child"
            for snapshot in _queue_recovery_restored.jobs.values()
        )
    ):
        # One bounded atomic replacement retires terminal queue snapshots and
        # their old revision fences before any recovered worker starts.
        _queue_recovery_coordinator.compact()
    live_manifests: dict[str, list[str]] = {
        workspace: list(paths)
        for workspace, paths in orphan_credit_manifests.items()
    }
    live_staging_jobs: dict[str, list[str]] = {}
    for snapshot in _queue_recovery_restored.jobs.values():
        if (
            str(snapshot.get("status") or "").casefold() in terminal_statuses
            and not unsettled_terminal_credit
        ):
            continue
        snapshot_workspace = str(snapshot.get("workspace") or "default")
        snapshot_job_id = snapshot.get("id")
        if isinstance(snapshot_job_id, str):
            live_staging_jobs.setdefault(snapshot_workspace, []).append(
                snapshot_job_id
            )
        pointer = snapshot.get("request_manifest")
        path = pointer.get("path") if isinstance(pointer, dict) else None
        if isinstance(path, str):
            live_manifests.setdefault(
                snapshot_workspace, [],
            ).append(path)
    # Runtime materialization can intentionally promote a failed incomplete
    # H3 chain into an owner-held recovery job and can swap to a sealed
    # calibrated plan. Retain the current pointer plus its bounded provenance
    # chain rather than deriving liveness solely from the stale startup map.
    for candidate in list(_jobs.values()):
        if str(candidate.get("status") or "").casefold() in terminal_statuses:
            continue
        candidate_workspace = str(candidate.get("workspace") or "default")
        candidate_id = candidate.get("id")
        if isinstance(candidate_id, str):
            live_staging_jobs.setdefault(candidate_workspace, []).append(
                candidate_id
            )
        pointers = [candidate.get("_recovery_manifest_pointer")]
        cursor = candidate.get("recovery_cursor")
        if isinstance(cursor, dict):
            history = cursor.get("request_manifest_history")
            if isinstance(history, list):
                pointers.extend(history)
        for pointer in pointers:
            path = pointer.get("path") if isinstance(pointer, dict) else None
            if isinstance(path, str):
                live_manifests.setdefault(candidate_workspace, []).append(path)
    # A host-local recovery may outlive an independently retired generic
    # journal snapshot. Preserve only cryptographically valid manifests whose
    # project sidecars reconstruct an exact incomplete H3 prefix; they remain
    # private and held until the offline helper supplies exact digests.
    preserve_local_candidates = globals().get(
        "_preserve_local_h3_recovery_evidence"
    )
    recovery_cleanup_blocked: set[str] = set(credit_cleanup_blocked)
    if callable(preserve_local_candidates):
        for workspace, (project_dir, _project_digest) in projects.items():
            if not preserve_local_candidates(
                workspace,
                project_dir,
                live_manifests,
                live_staging_jobs,
            ):
                # Discovery uncertainty must never become deletion authority.
                # Preserve every private artifact and retry on a later start.
                recovery_cleanup_blocked.add(workspace)
                continue
    for workspace, (project_dir, _project_digest) in projects.items():
        if workspace in recovery_cleanup_blocked:
            continue
        cleanup_orphan_request_manifests(
            project_dir, live_manifests.get(workspace, ()),
        )
        cleanup_orphan_staged_outputs(
            project_dir, live_staging_jobs.get(workspace, ()),
        )
    asset_store_factory = globals().get("_project_asset_store")
    if callable(asset_store_factory):
        try:
            asset_store_factory().cleanup_unreferenced_media()
        except Exception:
            # Uncertain manifests fail closed: preserve media and allow a later
            # startup to retry without exposing paths in recovery/public state.
            pass
    if before_recovered_workers is not None:
        before_recovered_workers()
    if not begin_startup_execution():
        return False
    # Host terms are global. Reconcile all restored, project-fenced frozen
    # plans before installing timers so a browser need not revisit each
    # workspace after restart. The common timer loop below installs exactly
    # one process-local timer per durable deadline.
    accepted_terms = globals().get("_ref2va_host_terms_accepted")
    if callable(accepted_terms) and accepted_terms():
        try:
            _reconcile_ref2va_waiting_plan_reviews(schedule_timers=False)
        except Exception:
            # One failed durable arm must not prevent the common timer loop
            # from restoring every already-armed plan. The failed candidate
            # remains terms-blocked and a later idempotent acceptance can heal
            # it without extending any committed deadline.
            pass
    # Arm plan timers only after orphan cleanup has consumed the startup
    # snapshot. An already-expired timer may atomically replace its manifest.
    for job in restored_jobs:
        if (
            job.get("status") == "waiting_for_plan_approval"
            and not job.get("plan_review_terms_required", False)
        ):
            try:
                if not run_startup_operation(
                    lambda: _schedule_plan_review_auto_approval(job)
                ):
                    return finish_interrupted_startup_execution()
            except Exception:
                fail_preparation(
                    job,
                    error="Automatic plan approval could not be restored",
                    message="Automatic plan approval could not be restored",
                    phase="preparation_failed",
                )
    from services.director_pipeline import start_restored_pipeline
    for pid in director_resumable:
        if not run_startup_operation(
            lambda: start_restored_pipeline(pid)
        ):
            return finish_interrupted_startup_execution()
    for job in resumable:
        if (
            job.get("_recovery_reason_code")
            == "h3_resource_retry_pending_replan"
            and not _prepare_pending_h3_resource_retry(job)
        ):
            continue
        publication_recovery = globals().get(
            "_project_reference_publication_recovery_requested"
        )
        project_reference_finalization = bool(
            callable(publication_recovery) and publication_recovery(job)
        )
        if _queue_recovery_delivery_pending(job) is None:
            if not project_reference_finalization:
                try:
                    _require_job_runtime_model_admission(job)
                except HTTPException as error:
                    role_mode = _director_image_role_wire_mode(
                        job.get("params") or {},
                    ) == "roles"
                    job["_recovery_reason_code"] = (
                        "h3_legal_access_required"
                        if error.status_code == 451 else
                        "director_role_admission_required"
                        if role_mode else "model_terms_required"
                    )
                    _queue_recovery_checkpoint(
                        job,
                        queue_held=True,
                        recovery_state="blocked",
                        reruns_denoise=error.status_code != 451,
                        message=(
                            "MiniMax H3 needs a separate written license"
                            if error.status_code == 451 else
                            "Director image role setup changed"
                            if role_mode
                            else "Model terms acceptance is required"
                        ),
                    )
                    continue
        worker = _queue_recovery_worker(job)
        if worker is None:
            job["_recovery_reason_code"] = "preparation_must_resubmit"
            _queue_recovery_checkpoint(
                job,
                queue_held=True,
                recovery_state="blocked_preparation",
                reruns_denoise=False,
                message="This interrupted preparation must be resubmitted",
            )
            continue
        thread = threading.Thread(
            target=worker,
            args=(job["id"],),
            daemon=False,
            name=f"studio-recovery-{job['id']}",
        )
        try:
            if not run_startup_operation(thread.start):
                return finish_interrupted_startup_execution()
        except BaseException:
            job["_recovery_reason_code"] = "worker_start_failed"
            _queue_recovery_checkpoint(
                job,
                queue_held=True,
                recovery_state="blocked",
                reruns_denoise=bool(job.get("reruns_denoise", True)),
                message="Recovery worker could not be started",
            )
    _queue_recovery_workers_started = True
    end_startup_execution()
    return True


def _queue_recovery_revalidate_job(job: dict) -> bool:
    """Recheck project marker, manifest, and all inputs for manual resume."""
    workspace = str(job.get("workspace") or "default")
    try:
        project_dir = _existing_workspace_dir(workspace)
        project_digest = _queue_recovery_existing_project_identity(project_dir)
        if not hmac.compare_digest(
            project_digest, str(job.get("_recovery_project_digest") or ""),
        ):
            job["_recovery_reason_code"] = "project_missing_or_recreated"
            return False
    except (HTTPException, QueueRecoveryAdapterError, ValueError):
        job["_recovery_reason_code"] = "project_missing_or_recreated"
        return False
    try:
        manifest = load_request_manifest(
            project_dir,
            job.get("_recovery_manifest_pointer") or {},
            expected_job_id=str(job.get("id") or ""),
        )
        validate_manifest_inputs(
            manifest,
            lambda descriptor: _queue_recovery_manifest_validator(
                dict(descriptor),
                owner_digest=str(job.get("_recovery_owner_digest") or ""),
                workspace=workspace,
                project_dir=project_dir,
            ),
        )
        job["params"] = dict(manifest["params"])
        job["out_dir"] = project_dir
        job["_recovery_reason_code"] = ""
        return True
    except (QueueRecoveryRuntimeError, ValueError):
        job["_recovery_reason_code"] = "input_missing_or_changed"
        return False


def _queue_recovery_units(job: dict) -> list[dict]:
    cursor = job.get("recovery_cursor")
    if not isinstance(cursor, dict):
        return []
    units = cursor.get("completed_units")
    return [dict(unit) for unit in units if isinstance(unit, dict)] \
        if isinstance(units, list) else []


def _h3_true_peak_policy_identity() -> dict:
    """Return the stable policy fields bound into an H3 concat unit ID."""
    from services.h3_audio_safety import DEFAULT_TARGET_DBTP, POLICY_VERSION

    return {
        "policy_version": POLICY_VERSION,
        "target_dbtp": DEFAULT_TARGET_DBTP,
    }


def _queue_recovery_unit_matches(
    job: dict,
    *,
    kind: str,
    variant: int,
    index: int,
    project_dir: str,
) -> dict | None:
    """Return one fully verified completed unit; invalid evidence is ignored."""
    for unit in _queue_recovery_units(job):
        if (
            unit.get("kind") != kind
            or unit.get("variant") != variant
            or unit.get("index") != index
            or unit.get("state") != "completed"
        ):
            continue
        if unit.get("kind") == "h3_concat":
            from services.h3_audio_safety import (
                DEFAULT_TARGET_DBTP,
                POLICY_VERSION,
            )

            attestation = unit.get("attestation")
            settings = unit.get("settings")
            policy = (
                settings.get("h3_audio_true_peak_policy")
                if isinstance(settings, dict) else None
            )
            true_peak = (
                attestation.get("h3_audio_true_peak")
                if isinstance(attestation, dict) else None
            )
            expected_policy = {
                "policy_version": POLICY_VERSION,
                "target_dbtp": DEFAULT_TARGET_DBTP,
            }
            if (
                policy != expected_policy
                or not isinstance(true_peak, dict)
                or true_peak.get("policy_version") != POLICY_VERSION
                or true_peak.get("target_dbtp") != DEFAULT_TARGET_DBTP
                or true_peak.get("verified") is not True
            ):
                # Preserve verified segments and replay only concat through
                # the current final-container audio policy.
                continue
        unit_id = str(unit.get("unit_id") or "")
        artifacts = unit.get("artifacts")
        if not isinstance(artifacts, list) or not artifacts:
            continue
        if kind == "h3_source_audio_premux":
            artifacts_valid = all(
                _queue_recovery_validate_staged_artifact(
                    project_dir, descriptor,
                )
                for descriptor in artifacts
                if isinstance(descriptor, dict)
            )
        else:
            artifacts_valid = all(
                validate_artifact_descriptor(
                    project_dir, descriptor, producer_unit_id=unit_id,
                )
                for descriptor in artifacts
                if isinstance(descriptor, dict)
            )
        if (
            not artifacts_valid
            or len([item for item in artifacts if isinstance(item, dict)])
            != len(artifacts)
        ):
            # Private pre-mux descriptors deliberately have no public
            # sidecars and cannot use the public artifact quarantine path.
            # Leave invalid private bytes for the bounded staging-orphan
            # cleanup rather than interpreting them as gallery artifacts.
            if kind != "h3_source_audio_premux":
                for descriptor in artifacts:
                    if isinstance(descriptor, dict):
                        _quarantine_recovery_artifact(project_dir, descriptor)
            return None
        continuation = unit.get("continuation")
        if isinstance(continuation, dict) and continuation.get("basename"):
            try:
                path = _queue_recovery_continuation_path(
                    project_dir, continuation,
                )
                size, digest = _recovery_sha256_file(path)
            except QueueRecoveryRuntimeError:
                return None
            if size != continuation.get("size") or digest != continuation.get("sha256"):
                return None
        return unit
    return None


def _queue_recovery_validate_staged_artifact(
    project_dir: str, descriptor: dict,
) -> bool:
    """Validate one private, direct-child pre-mux artifact by exact hash."""
    if not isinstance(descriptor, dict) or descriptor.get("storage") != "recovery_staging":
        return False
    name = descriptor.get("basename")
    if (
        not isinstance(name, str)
        or os.path.basename(name) != name
        or not name.startswith("unit-")
    ):
        return False
    path = os.path.realpath(os.path.join(
        ensure_recovery_staging_directory(project_dir), name,
    ))
    if (
        os.path.dirname(path) != os.path.realpath(
            ensure_recovery_staging_directory(project_dir)
        )
        or os.path.islink(path)
        or not os.path.isfile(path)
    ):
        return False
    try:
        size, digest = _recovery_sha256_file(path)
    except QueueRecoveryRuntimeError:
        return False
    return (
        size == descriptor.get("size")
        and hmac.compare_digest(digest, str(descriptor.get("sha256") or ""))
        and descriptor.get("media_kind") in {"video", "audio"}
    )


def _queue_recovery_staged_artifact_path(
    project_dir: str, descriptor: dict,
) -> str:
    if not _queue_recovery_validate_staged_artifact(project_dir, descriptor):
        raise QueueRecoveryRuntimeError("H3 pre-mux artifact is invalid.")
    return os.path.realpath(os.path.join(
        ensure_recovery_staging_directory(project_dir),
        descriptor["basename"],
    ))


def _queue_recovery_checkpoint_unit(
    job: dict,
    *,
    kind: str,
    variant: int,
    index: int,
    project_dir: str,
    artifact_names: list[str],
    dependencies: list[str] | None = None,
    continuation: dict | None = None,
    settings: dict | None = None,
    attestation: dict | None = None,
    ordinary_repeat_offset: int | None = None,
) -> dict:
    """Seal media+sidecars, then persist one completed safe-unit descriptor."""
    unit_id = recovery_unit_id(
        str(job.get("id") or ""), kind,
        variant=variant,
        index=index,
        dependencies=dependencies or (),
        settings=settings or {},
    )
    artifacts = []
    for name in artifact_names:
        sidecar_name = os.path.splitext(name)[0] + ".meta.json"
        artifacts.append(_recovery_artifact_descriptor(
            project_dir,
            basename=name,
            sidecar_basename=sidecar_name,
            producer_unit_id=unit_id,
        ))
    unit = {
        "artifacts": artifacts,
        "dependencies": list(dependencies or ()),
        "index": index,
        "kind": kind,
        "state": "completed",
        "unit_id": unit_id,
        "variant": variant,
    }
    if continuation:
        unit["continuation"] = dict(continuation)
    if settings:
        unit["settings"] = dict(settings)
    if attestation:
        unit["attestation"] = dict(attestation)
    units = [
        item for item in _queue_recovery_units(job)
        if not (
            item.get("kind") == kind
            and item.get("variant") == variant
            and item.get("index") == index
        )
    ]
    units.append(unit)
    cursor = dict(job.get("recovery_cursor") or {})
    cursor["completed_units"] = units[-2048:]
    if ordinary_repeat_offset is not None:
        cursor["ordinary_repeat_offset"] = max(0, int(ordinary_repeat_offset))
    committed = _queue_recovery_checkpoint(
        job,
        recovery_unit=unit,
        recovery_cursor=cursor,
        recovery_state="restored",
        reruns_denoise=False,
    )
    return unit if committed is True else None


def _queue_recovery_checkpoint_staged_premux(
    job: dict,
    *,
    index: int,
    project_dir: str,
    media_paths: dict[str, str],
    settings: dict,
) -> dict:
    """Persist private H3 pre-mux bytes without publishing gallery artifacts."""
    descriptors = []
    staging = os.path.realpath(ensure_recovery_staging_directory(project_dir))
    for media_kind in ("video", "audio"):
        path = media_paths.get(media_kind)
        if not path:
            continue
        resolved = os.path.realpath(os.path.abspath(path))
        if (
            os.path.dirname(resolved) != staging
            or os.path.islink(resolved)
            or not os.path.isfile(resolved)
            or not os.path.basename(resolved).startswith("unit-")
        ):
            raise QueueRecoveryRuntimeError("H3 pre-mux staging identity is invalid.")
        size, digest = _recovery_sha256_file(resolved)
        descriptors.append({
            "basename": os.path.basename(resolved),
            "media_kind": media_kind,
            "sha256": digest,
            "size": size,
            "storage": "recovery_staging",
        })
    expected_kinds = {"video"} | (
        {"audio"} if settings.get("final_audio_kind") == "generated" else set()
    )
    if {item["media_kind"] for item in descriptors} != expected_kinds:
        raise QueueRecoveryRuntimeError("H3 pre-mux artifact set is incomplete.")
    unit_id = recovery_unit_id(
        str(job.get("id") or ""), "h3_source_audio_premux",
        variant=0, index=index, settings=settings,
    )
    unit = {
        "artifacts": descriptors,
        "dependencies": [],
        "index": index,
        "kind": "h3_source_audio_premux",
        "settings": dict(settings),
        "state": "completed",
        "unit_id": unit_id,
        "variant": 0,
    }
    units = [
        item for item in _queue_recovery_units(job)
        if not (
            item.get("kind") == "h3_source_audio_premux"
            and item.get("variant") == 0
            and item.get("index") == index
        )
    ]
    units.append(unit)
    cursor = dict(job.get("recovery_cursor") or {})
    cursor["completed_units"] = units[-2048:]
    _queue_recovery_checkpoint(
        job,
        recovery_unit=unit,
        recovery_cursor=cursor,
        recovery_state="restored",
        reruns_denoise=False,
    )
    return unit


def _queue_recovery_continuation_descriptor(
    project_dir: str,
    path: str | None,
    *,
    mode: str,
    dependency: str,
    metadata: dict | None = None,
) -> dict:
    """Seal an H3 continuation file or an explicit prompt-only handoff."""
    if not path:
        return {"dependency": dependency, "mode": "prompt_only"}
    candidate = os.path.abspath(path)
    staging_root = os.path.realpath(
        ensure_recovery_staging_directory(project_dir)
    )
    if (
        os.path.dirname(candidate) != staging_root
        or os.path.realpath(candidate) != candidate
        or os.path.basename(candidate) != os.path.basename(path)
        or not os.path.basename(candidate).startswith("unit-")
    ):
        raise QueueRecoveryRuntimeError(
            "H3 continuation is not in private recovery staging."
        )
    size, digest = _recovery_sha256_file(candidate)
    descriptor = {
        "basename": os.path.basename(candidate),
        "dependency": dependency,
        "mode": mode,
        "sha256": digest,
        "size": size,
        "storage": "recovery_staging",
    }
    if metadata:
        allowed = {
            "fps", "audio_sample_rate", "audio_channels", "overlap_frames",
            "discard_frames", "boundary_type",
        }
        descriptor.update({
            key: metadata[key] for key in allowed if key in metadata
        })
    return descriptor


def _queue_recovery_continuation_path(
    project_dir: str,
    continuation: dict,
) -> str | None:
    """Resolve one journal-safe continuation pointer to an exact local root."""
    name = continuation.get("basename")
    if not name:
        return None
    if (
        not isinstance(name, str)
        or os.path.basename(name) != name
        or name in {".", ".."}
    ):
        raise QueueRecoveryRuntimeError("H3 continuation identity is invalid.")
    storage = continuation.get("storage")
    if storage == "recovery_staging" and name.startswith("unit-"):
        root = os.path.realpath(ensure_recovery_staging_directory(project_dir))
    else:
        raise QueueRecoveryRuntimeError("H3 continuation storage is invalid.")
    path = os.path.abspath(os.path.join(root, name))
    if os.path.dirname(path) != root or os.path.realpath(path) != path:
        raise QueueRecoveryRuntimeError("H3 continuation escaped its storage root.")
    return path


def _queue_recovery_staged_media_paths(
    values,
    staging_dir: str | None,
) -> dict[str, str]:
    """Return existing direct-child staged media keyed by stable basename."""
    if not staging_dir:
        return {}
    root = os.path.normcase(os.path.realpath(staging_dir))
    result: dict[str, str] = {}
    for value in values or ():
        if isinstance(value, tuple):
            value = value[0] if value else None
        if not isinstance(value, str) or not value:
            continue
        resolved = os.path.realpath(os.path.abspath(value))
        name = os.path.basename(resolved)
        if (
            os.path.normcase(os.path.dirname(resolved)) == root
            and os.path.splitext(name)[1].lower() in GENERATED_MEDIA_EXTENSIONS
            and os.path.isfile(resolved)
            and not os.path.islink(resolved)
        ):
            result[name] = resolved
    return result


def _queue_recovery_resolve_task_video_path(
    output_path: str,
    project_dir: str,
    staged_media: dict[str, str],
) -> str | None:
    """Accept only a current public child or its attested private staging path."""
    if not isinstance(output_path, str) or not output_path:
        return None
    candidate = output_path if os.path.isabs(output_path) else os.path.join(
        project_dir, output_path,
    )
    resolved = os.path.realpath(candidate)
    public_child = (
        os.path.normcase(os.path.dirname(resolved))
        == os.path.normcase(os.path.realpath(project_dir))
    )
    staged = staged_media.get(os.path.basename(resolved))
    staged_child = (
        isinstance(staged, str)
        and os.path.normcase(os.path.realpath(staged))
        == os.path.normcase(resolved)
    )
    if (
        not (public_child or staged_child)
        or not os.path.isfile(resolved)
        or os.path.islink(resolved)
    ):
        return None
    return resolved


def _queue_recovery_promote_staged_outputs(
    gen: dict,
    project_dir: str,
    media_paths: dict[str, str],
) -> None:
    """Promote sidecar-sealed media and rebind WGP's in-memory path state."""
    replacements = {}
    for basename, staged_path in media_paths.items():
        promote_recovery_staged_artifact(
            project_dir,
            staged_path=staged_path,
            output_basename=basename,
        )
        replacements[os.path.realpath(staged_path)] = os.path.join(
            project_dir, basename,
        )
    for list_name in ("artifact_list", "file_list", "audio_file_list"):
        values = gen.get(list_name)
        if not isinstance(values, list):
            continue
        for index, value in enumerate(values):
            raw = value[0] if isinstance(value, tuple) and value else value
            if not isinstance(raw, str):
                continue
            replacement = replacements.get(os.path.realpath(raw))
            if replacement is None:
                continue
            values[index] = (
                (replacement, *value[1:])
                if isinstance(value, tuple) else replacement
            )
    roles = gen.get("artifact_roles")
    if isinstance(roles, dict):
        for staged_real, replacement in replacements.items():
            role = None
            for path in list(roles):
                if isinstance(path, str) and os.path.realpath(path) == staged_real:
                    role = roles.pop(path)
                    break
            if role is not None:
                roles[replacement] = role
    groups = gen.get("multi_clip_paths")
    if isinstance(groups, dict):
        for group in groups.values():
            if not isinstance(group, dict):
                continue
            for item in group.values():
                if not isinstance(item, dict):
                    continue
                raw = item.get("path")
                if isinstance(raw, str):
                    replacement = replacements.get(os.path.realpath(raw))
                    if replacement is not None:
                            item["path"] = replacement


def _queue_recovery_expected_artifact_role(kind: str, meta: dict) -> str | None:
    """Resolve only producer-declared modern roles; never infer a final name."""
    fixed = _RECOVERY_UNIT_FIXED_ARTIFACT_ROLES.get(str(kind or ""))
    if fixed is not None:
        return fixed
    if kind == "ordinary_repeat":
        declared = meta.get("producer_artifact_class")
        return declared if declared in _RECOVERY_ARTIFACT_ROLES else None
    return None


def _queue_recovery_repair_unit_roles(
    job: dict,
    unit: dict,
    project_dir: str,
) -> dict | None:
    """Repair semantic roles and reseal descriptors after byte changes."""
    kind = str(unit.get("kind") or "")
    if kind == "h3_source_audio_premux":
        return unit
    unit_id = str(unit.get("unit_id") or "")
    try:
        variant = max(0, int(unit.get("variant", 0) or 0))
    except (TypeError, ValueError):
        return None
    repaired = dict(unit)
    repaired_artifacts = []
    for descriptor in unit.get("artifacts") or []:
        if not isinstance(descriptor, dict):
            return None
        name = descriptor.get("basename")
        sidecar_name = descriptor.get("sidecar_basename")
        if (
            not isinstance(name, str)
            or os.path.basename(name) != name
            or not isinstance(sidecar_name, str)
            or os.path.basename(sidecar_name) != sidecar_name
        ):
            return None
        sidecar_path = os.path.join(project_dir, sidecar_name)
        try:
            with open(sidecar_path, "r", encoding="utf-8") as handle:
                meta = json.load(handle)
        except (OSError, ValueError, TypeError):
            return None
        if (
            not isinstance(meta, dict)
            or meta.get("producer_unit_id") != unit_id
            or meta.get("producer_unit_kind") != kind
        ):
            return None
        expected_role = _queue_recovery_expected_artifact_role(kind, meta)
        if expected_role is None:
            return None
        changed = (
            meta.get("producer_artifact_class") != expected_role
            or meta.get("artifact_class") != expected_role
        )
        meta["producer_artifact_class"] = expected_role
        meta["artifact_class"] = expected_role
        if kind in {"h3_segment", "h3_concat"}:
            lineage = f"h3:{job.get('id', '')}:variant:{variant}"
            changed = changed or (
                meta.get("artifact_lineage") != lineage
                or meta.get("producer_variant_lineage") != lineage
            )
            meta["artifact_lineage"] = lineage
            meta["producer_variant_lineage"] = lineage
        if changed:
            try:
                _atomic_write_json(sidecar_path, meta)
            except (OSError, TypeError, ValueError):
                return None
        try:
            repaired_artifacts.append(_recovery_artifact_descriptor(
                project_dir,
                basename=name,
                sidecar_basename=sidecar_name,
                producer_unit_id=unit_id,
            ))
        except QueueRecoveryRuntimeError:
            return None
    if not repaired_artifacts:
        return None
    repaired["artifacts"] = repaired_artifacts
    return repaired


def _h3_dependency_closed_recovery_units(verified: list[dict]) -> list[dict]:
    """Remove H3 units whose exact predecessor evidence is unavailable."""
    dependency_closed = [
        unit for unit in verified
        if not str(unit.get("kind") or "").startswith("h3_")
    ]
    accepted_by_id = {
        str(unit.get("unit_id") or ""): unit
        for unit in dependency_closed
    }
    pending_h3 = [
        unit for unit in verified
        if str(unit.get("kind") or "").startswith("h3_")
    ]
    while pending_h3:
        admitted = []
        for unit in pending_h3:
            dependencies = unit.get("dependencies")
            if not isinstance(dependencies, list):
                continue
            if not all(
                isinstance(dependency, str) and dependency in accepted_by_id
                for dependency in dependencies
            ):
                continue
            kind = str(unit.get("kind") or "")
            settings = unit.get("settings")
            if not isinstance(settings, dict):
                settings = {}
            if kind == "h3_segment" and dependencies:
                predecessor = accepted_by_id[dependencies[-1]]
                actual_hashes = sorted(
                    str(artifact.get("sha256") or "")
                    for artifact in predecessor.get("artifacts") or []
                    if isinstance(artifact, dict) and artifact.get("sha256")
                )
                if settings.get("predecessor_artifact_hashes") != actual_hashes:
                    continue
                predecessor_continuation = predecessor.get("continuation")
                expected_continuation_hash = (
                    str(predecessor_continuation.get("sha256") or "")
                    if isinstance(predecessor_continuation, dict) else ""
                )
                if str(settings.get("predecessor_continuation_sha256") or "") != expected_continuation_hash:
                    continue
            elif kind == "h3_concat":
                actual_hashes = []
                actual_start_trims = []
                actual_tail_trims = []
                tail_metadata_complete = True
                for dependency in dependencies:
                    predecessor = accepted_by_id[dependency]
                    actual_hashes.extend(
                        str(artifact.get("sha256") or "")
                        for artifact in predecessor.get("artifacts") or []
                        if isinstance(artifact, dict) and artifact.get("sha256")
                    )
                    predecessor_settings = predecessor.get("settings")
                    tail_metadata_complete = (
                        tail_metadata_complete
                        and isinstance(predecessor_settings, dict)
                        and "trim_tail_frames" in predecessor_settings
                    )
                    actual_start_trims.append(int(
                        predecessor_settings.get("discard_prefix_frames", 0)
                        if isinstance(predecessor_settings, dict) else 0
                    ))
                    actual_tail_trims.append(int(
                        predecessor_settings.get("trim_tail_frames", 0)
                        if isinstance(predecessor_settings, dict) else 0
                    ))
                if (
                    settings.get("component_hashes") != actual_hashes
                    or settings.get("clip_start_frames") != actual_start_trims
                    or (
                        (tail_metadata_complete or "clip_tail_frames" in settings)
                        and settings.get("clip_tail_frames") != actual_tail_trims
                    )
                ):
                    continue
            dependency_closed.append(unit)
            accepted_by_id[str(unit.get("unit_id") or "")] = unit
            admitted.append(unit)
        if not admitted:
            break
        admitted_ids = {id(unit) for unit in admitted}
        pending_h3 = [
            unit for unit in pending_h3 if id(unit) not in admitted_ids
        ]
    return dependency_closed


def _queue_recovery_reconcile_cursor(job: dict, project_dir: str) -> None:
    """Keep verified units and recover the sidecar-before-journal crash gap."""
    verified: list[dict] = []
    seen: set[str] = set()
    original_units = _queue_recovery_units(job)
    had_h3_units = any(
        str(unit.get("kind") or "").startswith("h3_")
        for unit in original_units
    )
    for unit in original_units:
        unit_id = str(unit.get("unit_id") or "")
        matched = _queue_recovery_unit_matches(
            job,
            kind=str(unit.get("kind") or ""),
            variant=max(0, int(unit.get("variant", 0) or 0)),
            index=max(0, int(unit.get("index", 0) or 0)),
            project_dir=project_dir,
        )
        repair_roles = globals().get("_queue_recovery_repair_unit_roles")
        if matched is not None and callable(repair_roles):
            matched = repair_roles(job, matched, project_dir)
        if matched is not None and unit_id not in seen:
            verified.append(matched)
            seen.add(unit_id)

    # Sidecars are written and fsynced before the journal checkpoint. If the
    # process dies in that narrow gap, reconstruct the exact unit only from a
    # direct-child sidecar whose producer ID and media hash still match.
    try:
        from services.search_index import load_media_sidecars as _load_sidecars
        sidecars = _load_sidecars(project_dir)
    except Exception:
        sidecars = {}
    recovered_by_unit: dict[str, dict] = {}
    invalid_recovered_units: set[str] = set()
    for name, meta in sidecars.items():
        if not isinstance(meta, dict) or meta.get("job_id") != job.get("id"):
            continue
        unit_id = str(meta.get("producer_unit_id") or "")
        kind = str(meta.get("producer_unit_kind") or "")
        if not kind:
            continue
        try:
            variant = max(0, int(meta.get("producer_unit_variant", 0) or 0))
            index = max(0, int(meta.get("producer_unit_index", 0) or 0))
            dependencies = meta.get("producer_unit_dependencies")
            settings = meta.get("producer_unit_settings")
            continuation = meta.get("producer_unit_continuation")
            expected_artifacts = meta.get("producer_unit_artifact_names")
            if not isinstance(dependencies, list):
                dependencies = []
            if not isinstance(settings, dict):
                settings = {}
            if continuation is not None and not isinstance(continuation, dict):
                continue
            if (
                not isinstance(expected_artifacts, list)
                or not expected_artifacts
                or len(expected_artifacts) > 4096
                or len(set(expected_artifacts)) != len(expected_artifacts)
                or any(
                    not isinstance(value, str)
                    or os.path.basename(value) != value
                    or value.startswith(".")
                    for value in expected_artifacts
                )
            ):
                continue
            size, digest = _recovery_sha256_file(os.path.join(project_dir, name))
        except (TypeError, ValueError, QueueRecoveryRuntimeError):
            continue
        try:
            expected_id = recovery_unit_id(
                str(job.get("id") or ""), kind,
                variant=variant, index=index,
                dependencies=dependencies,
                settings=settings,
            )
        except QueueRecoveryRuntimeError:
            continue
        if (
            not hmac.compare_digest(unit_id, expected_id)
            or size != meta.get("producer_media_size")
            or digest != meta.get("producer_media_sha256")
        ):
            continue
        if continuation:
            if continuation.get("dependency") != unit_id:
                continue
            if continuation.get("basename"):
                try:
                    continuation_path = _queue_recovery_continuation_path(
                        project_dir, continuation,
                    )
                    continuation_size, continuation_sha = _recovery_sha256_file(
                        continuation_path,
                    )
                except QueueRecoveryRuntimeError:
                    continue
                if (
                    continuation_size != continuation.get("size")
                    or continuation_sha != continuation.get("sha256")
                ):
                    continue
        try:
            artifact = _recovery_artifact_descriptor(
                project_dir,
                basename=name,
                sidecar_basename=os.path.splitext(name)[0] + ".meta.json",
                producer_unit_id=unit_id,
            )
        except QueueRecoveryRuntimeError:
            continue
        recovered = recovered_by_unit.setdefault(unit_id, {
            "artifacts": [],
            "dependencies": list(dependencies),
            "index": index,
            "kind": kind,
            "state": "completed",
            "unit_id": unit_id,
            "variant": variant,
            "_expected_artifacts": tuple(sorted(expected_artifacts)),
        })
        if recovered.get("_expected_artifacts") != tuple(sorted(expected_artifacts)):
            invalid_recovered_units.add(unit_id)
            continue
        if settings:
            recovered["settings"] = dict(settings)
        if continuation:
            recovered["continuation"] = dict(continuation)
        recovered["artifacts"].append(artifact)
    for unit_id, unit in recovered_by_unit.items():
        expected_artifacts = set(unit.pop("_expected_artifacts", ()))
        actual_artifacts = {
            str(artifact.get("basename") or "")
            for artifact in unit.get("artifacts") or []
            if isinstance(artifact, dict)
        }
        if (
            unit_id not in invalid_recovered_units
            and actual_artifacts == expected_artifacts
            and unit_id not in seen
        ):
            repair_roles = globals().get("_queue_recovery_repair_unit_roles")
            repaired = (
                repair_roles(job, unit, project_dir)
                if callable(repair_roles) else unit
            )
            if repaired is not None:
                verified.append(repaired)
                seen.add(unit_id)

    # An independently valid downstream file must not survive after a
    # predecessor artifact or continuation is quarantined.
    verified = _h3_dependency_closed_recovery_units(verified)

    cursor = dict(job.get("recovery_cursor") or {})
    cursor["completed_units"] = verified[-2048:]
    verified_h3_units = [
        unit for unit in verified
        if str(unit.get("kind") or "").startswith("h3_")
    ]
    if had_h3_units or verified_h3_units:
        # Snapshot output_files came from the pre-repair schema and may name
        # segments as Finals. Rebuild public finality only from verified modern
        # producer units; retain every prior name in artifact lineage.
        prior_outputs = [
            name for name in job.get("output_files") or []
            if isinstance(name, str) and name
        ]
        artifacts = [
            name for name in job.get("artifact_files") or []
            if isinstance(name, str) and name
        ]
        for name in prior_outputs:
            if name not in artifacts:
                artifacts.append(name)
        for unit in verified_h3_units:
            if unit.get("kind") == "h3_source_audio_premux":
                continue
            for descriptor in unit.get("artifacts") or []:
                name = (
                    descriptor.get("basename")
                    if isinstance(descriptor, dict) else None
                )
                if isinstance(name, str) and name and name not in artifacts:
                    artifacts.append(name)
        job["artifact_files"] = artifacts
        delivery_units = [
            unit for unit in verified_h3_units
            if unit.get("kind") == "h3_delivery"
        ]
        final_units = delivery_units or [
            unit for unit in verified_h3_units
            if unit.get("kind") == "h3_concat"
        ]
        verified_finals = []
        for unit in final_units:
            for artifact in unit.get("artifacts") or []:
                name = (
                    artifact.get("basename")
                    if isinstance(artifact, dict) else None
                )
                if isinstance(name, str) and name and name not in verified_finals:
                    verified_finals.append(name)
        job["output_files"] = verified_finals
        if delivery_units or not verified_finals:
            job.pop("join_output_file", None)
        else:
            job["join_output_file"] = verified_finals[0]
    repeat_indices = {
        int(unit.get("index", -1))
        for unit in verified
        if unit.get("kind") == "ordinary_repeat"
        and int(unit.get("variant", 0) or 0) == 0
    }
    repeat_offset = 0
    while repeat_offset in repeat_indices:
        repeat_offset += 1
    cursor["ordinary_repeat_offset"] = repeat_offset
    if not isinstance(cursor.get("delivery_pending"), dict):
        recovered_delivery = _queue_recovery_reconcile_orphan_delivery(
            job, project_dir,
        )
        if recovered_delivery is not None:
            cursor["delivery_pending"] = recovered_delivery
            job["reruns_denoise"] = False
    job["recovery_cursor"] = cursor


def _h3_segment_recovery_settings(clip_info: dict) -> dict:
    """Bind published/trim semantics into one durable H3 segment identity."""
    if not isinstance(clip_info, dict):
        raise QueueRecoveryRuntimeError("H3 segment recovery metadata is invalid.")
    try:
        discard = max(
            0, int(clip_info.get("boundary_overlap_discard_frames", 0) or 0),
        )
        tail = max(0, int(clip_info.get("trim_tail_frames", 0) or 0))
        published = max(1, int(clip_info.get("published_frames", 0) or 0))
        generated_value = clip_info.get("generated_frames")
        generated = (
            max(1, int(generated_value))
            if generated_value not in (None, "")
            else published + tail
        )
    except (TypeError, ValueError):
        raise QueueRecoveryRuntimeError(
            "H3 segment trim metadata is invalid."
        ) from None
    native = clip_info.get("native_boundary_conditioning") is True
    if discard not in ({0, 17} if native else {0}):
        raise QueueRecoveryRuntimeError(
            "H3 segment trim does not match its boundary policy."
        )
    if tail >= generated or published != generated - tail:
        raise QueueRecoveryRuntimeError(
            "H3 segment tail trim does not match its publication geometry."
        )
    result = {
        "discard_prefix_frames": discard,
        "generated_frames": generated,
        "native_boundary_conditioning": native,
        "published_frames": published,
        "trim_tail_frames": tail,
    }
    peak_identity = clip_info.get("peak_recovery_identity")
    if isinstance(peak_identity, dict):
        # This identity is versioned and present only on newly replanned
        # units. Legacy sealed prefix units retain their original unit IDs.
        result["peak_recovery_identity"] = copy.deepcopy(peak_identity)
    raw_contract_version = clip_info.get(
        "semantic_physical_contract_version"
    )
    if raw_contract_version is not None:
        if (
            isinstance(raw_contract_version, bool)
            or not isinstance(raw_contract_version, int)
            or raw_contract_version not in {1, 2}
        ):
            raise QueueRecoveryRuntimeError(
                "H3 semantic execution recovery version is unsupported."
            )
        contract_version = raw_contract_version
        execution_slice = clip_info.get("execution_slice")
        try:
            execution = {
                "version": contract_version,
                "semantic_shot_index": int(
                    clip_info.get("semantic_shot_index")
                ),
                "physical_segment_index": int(
                    clip_info.get("physical_segment_index")
                ),
                "physical_segment_count": int(
                    clip_info.get("physical_segment_count")
                ),
                "predecessor_segment_index": (
                    int(clip_info.get("predecessor_segment_index"))
                    if clip_info.get("predecessor_segment_index") is not None
                    else None
                ),
                "execution_cursor_frame": int(
                    clip_info.get("execution_cursor_frame")
                ),
                "start_frame": int(execution_slice.get("start_frame")),
                "end_frame_exclusive": int(
                    execution_slice.get("end_frame_exclusive")
                ),
            }
        except (AttributeError, TypeError, ValueError):
            raise QueueRecoveryRuntimeError(
                "H3 semantic execution recovery metadata is invalid."
            ) from None
        if (
            execution["physical_segment_index"] < 0
            or execution["physical_segment_count"] < 1
            or execution["physical_segment_index"]
                >= execution["physical_segment_count"]
            or execution["execution_cursor_frame"] != execution["start_frame"]
            or execution["end_frame_exclusive"] - execution["start_frame"]
                != published
        ):
            raise QueueRecoveryRuntimeError(
                "H3 semantic execution recovery geometry is invalid."
            )
        result["semantic_execution"] = execution
    return result


def _h3_execution_shots_for_dispatch(
    longform: dict,
    prompt_lines: list[str],
    clip_count: int,
) -> list[dict] | None:
    """Validate and return the semantic-to-physical child contract."""
    shot_plan = longform.get("shot_plan") if isinstance(longform, dict) else None
    if not isinstance(shot_plan, dict):
        return None
    raw_contract_version = shot_plan.get(
        "semantic_physical_contract_version"
    )
    if raw_contract_version is None:
        return None
    if (
        isinstance(raw_contract_version, bool)
        or not isinstance(raw_contract_version, int)
        or raw_contract_version not in {1, 2}
    ):
        raise QueueRecoveryRuntimeError(
            "H3 semantic execution contract version is unsupported."
        )
    contract_version = raw_contract_version
    if contract_version == 2:
        from services.h3_shot_planner import validate_h3_shot_plan_seal

        try:
            validate_h3_shot_plan_seal(shot_plan)
        except ValueError as exc:
            raise QueueRecoveryRuntimeError(str(exc)) from exc
    shots = shot_plan.get("shots")
    semantic = shot_plan.get("semantic_shots")
    source_contracts = shot_plan.get("source_contracts")
    if (
        not isinstance(shots, list) or len(shots) != clip_count
        or not isinstance(semantic, list) or not semantic
        or len(prompt_lines) != clip_count
        or (
            contract_version == 2
            and (
                source_contracts != semantic
                or shot_plan.get("clip_prompts") != prompt_lines
            )
        )
    ):
        raise QueueRecoveryRuntimeError(
            "H3 semantic execution slice count is invalid."
        )
    partition = []
    nested_events = []
    mappings = {}
    for contract in semantic:
        if not isinstance(contract, dict):
            raise QueueRecoveryRuntimeError(
                "H3 semantic execution contract is invalid."
            )
        indices = contract.get("segment_indices")
        slices = contract.get("execution_slices")
        if (
            not isinstance(indices, list) or not isinstance(slices, list)
            or len(indices) != len(slices) or not indices
            or any(type(value) is not int for value in indices)
            or contract.get("prompt_rewrite_for_physical_split")
                is not (contract_version == 2)
            or (
                contract_version == 2
                and contract.get("physical_prompt_compiler_version") != 2
            )
        ):
            raise QueueRecoveryRuntimeError(
                "H3 semantic execution contract is invalid."
            )
        cursor = 0
        semantic_prompt = str(contract.get("semantic_prompt"))
        prompt_digests = contract.get("executable_prompt_sha256")
        if contract_version == 2 and (
            not isinstance(prompt_digests, list)
            or len(prompt_digests) != len(indices)
        ):
            raise QueueRecoveryRuntimeError(
                "H3 semantic execution prompt evidence is invalid."
            )
        for physical_index, (segment_index, execution_slice) in enumerate(
            zip(indices, slices)
        ):
            try:
                segment_index = int(segment_index)
                valid = (
                    isinstance(execution_slice, dict)
                    and all(
                        type(execution_slice.get(field)) is int
                        for field in (
                            "segment_index", "physical_segment_index",
                            "start_frame", "end_frame_exclusive",
                        )
                    )
                    and int(execution_slice.get("segment_index")) == segment_index
                    and int(execution_slice.get("physical_segment_index"))
                        == physical_index
                    and int(execution_slice.get("start_frame")) == cursor
                    and int(execution_slice.get("end_frame_exclusive")) > cursor
                    and (
                        prompt_lines[segment_index] == semantic_prompt
                        if contract_version == 1 else
                        prompt_digests[physical_index] == hashlib.sha256(
                            prompt_lines[segment_index].encode("utf-8")
                        ).hexdigest()
                    )
                )
                cursor = int(execution_slice.get("end_frame_exclusive"))
            except (IndexError, TypeError, ValueError):
                valid = False
            if not valid:
                raise QueueRecoveryRuntimeError(
                    "H3 semantic execution slice is invalid."
                )
            partition.append(segment_index)
            mappings[segment_index] = (
                contract, physical_index, execution_slice,
            )
        if contract_version == 2:
            events = contract.get("event_ownership")
            if not isinstance(events, list):
                raise QueueRecoveryRuntimeError(
                    "H3 semantic event ownership is invalid."
                )
            for event in events:
                try:
                    owner = event.get("owner_segment_index")
                    local_owner = event.get(
                        "owner_physical_segment_index"
                    )
                    payload = event.get("executable_payload")
                    valid = (
                        isinstance(event, dict)
                        and type(owner) is int
                        and type(local_owner) is int
                        and 0 <= local_owner < len(indices)
                        and int(indices[local_owner]) == owner
                        and isinstance(payload, str)
                        and payload.strip()
                        and payload in prompt_lines[owner]
                        and event.get("owner_physical_segment_id") == (
                            f"{contract.get('authored_shot_id')}:segment-"
                            f"{local_owner + 1}"
                        )
                        and (
                            event.get("kind") != "final_blocking"
                            or local_owner == len(indices) - 1
                        )
                    )
                    owner_slice = slices[local_owner]
                    source_start = event.get("source_start_frame")
                    source_end = event.get("source_end_frame_exclusive")
                    if source_start is None and source_end is None:
                        valid = valid and all(
                            event.get(field) is None
                            for field in (
                                "local_start_frame",
                                "local_end_frame_exclusive",
                            )
                        )
                    elif (
                        type(source_start) is int
                        and type(source_end) is int
                    ):
                        valid = valid and (
                            int(owner_slice.get("start_frame"))
                            <= source_start
                            < int(owner_slice.get("end_frame_exclusive"))
                            and source_end > source_start
                            and event.get("local_start_frame") == (
                                source_start
                                - int(owner_slice.get("start_frame"))
                            )
                            and event.get("local_end_frame_exclusive") == (
                                min(
                                    source_end,
                                    int(owner_slice.get(
                                        "end_frame_exclusive"
                                    )),
                                )
                                - int(owner_slice.get("start_frame"))
                            )
                        )
                    else:
                        valid = False
                except (AttributeError, IndexError, TypeError, ValueError):
                    valid = False
                if not valid:
                    raise QueueRecoveryRuntimeError(
                        "H3 semantic event ownership is invalid."
                    )
            nested_events.extend(events)
    if sorted(partition) != list(range(clip_count)) or len(set(partition)) != clip_count:
        raise QueueRecoveryRuntimeError(
            "H3 semantic execution slices do not partition the children."
        )
    if (
        contract_version == 2
        and shot_plan.get("event_ownership") != nested_events
    ):
        raise QueueRecoveryRuntimeError(
            "H3 semantic event ownership copies disagree."
        )
    for index, shot in enumerate(shots):
        if not isinstance(shot, dict):
            raise QueueRecoveryRuntimeError(
                "H3 physical execution child is invalid."
            )
        predecessor = shots[index - 1] if index else None
        try:
            contract, physical_index, execution_slice = mappings[index]
            valid = (
                int(shot.get("index")) == index
                and str(shot.get("prompt")) == prompt_lines[index]
                and int(shot.get("source_index"))
                    == int(contract.get("source_index"))
                and int(shot.get("physical_segment_index"))
                    == physical_index
                and shot.get("execution_slice") == execution_slice
                and int(shot.get("published_frames"))
                    == int(execution_slice.get("end_frame_exclusive"))
                    - int(execution_slice.get("start_frame"))
                and int(shot.get("execution_cursor_frame"))
                    == int((shot.get("execution_slice") or {}).get("start_frame"))
                and (
                    shot.get("predecessor_segment_index") is None
                    if index == 0 else int(shot.get("predecessor_segment_index"))
                        == index - 1
                )
                and (
                    shot.get("predecessor_physical_segment_id") is None
                    if predecessor is None else str(
                        shot.get("predecessor_physical_segment_id")
                    ) == str(predecessor.get("physical_segment_id"))
                )
            )
        except (TypeError, ValueError):
            valid = False
        if not valid:
            raise QueueRecoveryRuntimeError(
                "H3 physical execution predecessor contract is invalid."
            )
    return [copy.deepcopy(shot) for shot in shots]


def _h3_dependency_closed_recovery_prefix(job: dict) -> int | None:
    """Return a contiguous verified H3 prefix before concat/delivery."""
    params = job.get("params")
    params = params if isinstance(params, dict) else {}
    longform = params.get("_h3_longform")
    if not isinstance(longform, dict):
        return None
    try:
        clip_count = int(longform.get("clip_count") or 0)
        requested_outputs = int(job.get("requested_outputs") or 1)
    except (TypeError, ValueError):
        return None
    if clip_count < 2 or requested_outputs != 1:
        return None
    units = _queue_recovery_units(job)
    if any(unit.get("kind") in {"h3_concat", "h3_delivery"} for unit in units):
        return None
    indices = set()
    segment_units = 0
    try:
        for unit in units:
            if unit.get("kind") != "h3_segment":
                continue
            segment_units += 1
            if int(unit.get("variant", 0) or 0) != 0:
                return None
            indices.add(int(unit.get("index", -1)))
    except (TypeError, ValueError):
        return None
    prefix = 0
    while prefix in indices:
        prefix += 1
    if (
        indices != set(range(prefix))
        or segment_units != len(indices)
        or prefix >= clip_count
    ):
        return None
    return prefix


def _h3_incomplete_recovery_prefix(job: dict) -> int | None:
    """Return the exact sealed prefix when only the final segment is absent."""
    prefix = _h3_dependency_closed_recovery_prefix(job)
    if prefix is None:
        return None
    try:
        clip_count = int(
            ((job.get("params") or {}).get("_h3_longform") or {}).get(
                "clip_count"
            ) or 0
        )
    except (AttributeError, TypeError, ValueError):
        return None
    return prefix if prefix == clip_count - 1 else None


def _replan_h3_final_segment_for_peak(
    params: dict,
    *,
    completed_prefix: int,
    choice: dict,
) -> dict:
    """Replace only the missing final semantic segment using the H3 planner."""
    from services.h3_shot_planner import (
        infer_h3_profile_id,
        plan_h3_clip_frames,
        plan_h3_native_shots,
        seal_h3_shot_plan,
        validate_h3_shot_plan_seal,
    )
    from shared.utils.prompt_parser import classify_timeline_clip_boundaries

    result = copy.deepcopy(params)
    longform = result.get("_h3_longform")
    if not isinstance(longform, dict):
        raise QueueRecoveryRuntimeError("H3 recovery plan is unavailable.")
    clip_frames = list(longform.get("clip_frames") or [])
    published = list(longform.get("clip_published_frames") or [])
    trims = list(longform.get("clip_trim_tail_frames") or [])
    prompts = list(result.get("per_clip_prompts") or [])
    models = list(longform.get("segment_models") or [])
    boundaries = list(longform.get("clip_boundaries") or [])
    if not (
        len(clip_frames) == len(published) == len(trims) == len(prompts)
        == len(models) == completed_prefix + 1
    ):
        raise QueueRecoveryRuntimeError("H3 recovery plan geometry is incomplete.")
    final_model = str((models[-1] or {}).get("model_type") or "") \
        if isinstance(models[-1], dict) else ""
    if final_model != _H3_REF2VA_MODEL:
        raise QueueRecoveryRuntimeError(
            "Only a final Ref2VA segment can use calibrated peak recovery."
        )
    try:
        target_published = int(published[-1])
        ceiling = int(choice["frame_ceiling"])
        profile = int(choice["offload_profile"])
        fps = float(longform.get("fps") or 24)
    except (TypeError, ValueError, KeyError):
        raise QueueRecoveryRuntimeError("H3 peak calibration is invalid.") from None
    if ceiling < 1 or target_published < 1:
        raise QueueRecoveryRuntimeError("H3 peak calibration is invalid.")
    final_prompt = str(prompts[-1])
    model_def = wgp.get_model_def(final_model) or {}
    minimum, _step, _latent = wgp.get_model_min_frames_and_step(final_model)
    if target_published <= ceiling:
        replacement_frames = [int(clip_frames[-1])]
        replacement_published = [target_published]
        replacement_trims = [int(trims[-1])]
        replacement_prompts = [final_prompt]
        replacement_boundaries = []
        segment_policy = {"calibrated_single_segment": True}
        shot_plan = {}
    else:
        replacement_frames, segment_policy = plan_h3_clip_frames(
            target_published,
            prompt=final_prompt,
            fps=fps,
            minimum_frames=minimum,
            maximum_frames=ceiling,
            align_frame_count=lambda value: wgp.align_model_frame_count(
                value, model_def,
            ),
            profile_id=infer_h3_profile_id(result),
            manual_segment_ceiling=True,
            published_total_frames=target_published,
        )
        requested = list(
            segment_policy.get("clip_requested_frames") or replacement_frames
        )
        if "clip_requested_frames" not in segment_policy:
            requested[-1] -= sum(replacement_frames) - target_published
        replacement_boundaries = classify_timeline_clip_boundaries(
            final_prompt,
            clip_frame_counts=requested,
            fps=fps,
        )
        shot_plan = plan_h3_native_shots(
            global_prompt=final_prompt,
            clip_frame_counts=replacement_frames,
            fps=fps,
            clip_boundaries=replacement_boundaries,
            clip_requested_frames=requested,
            segment_frames_maximum=ceiling,
            segment_policy=segment_policy,
        )
        replacement_prompts = list(shot_plan["clip_prompts"])
        replacement_published = list(shot_plan["clip_published_frames"])
        replacement_trims = list(shot_plan["clip_trim_tail_frames"])
    if sum(replacement_published) != target_published:
        raise QueueRecoveryRuntimeError(
            "H3 recovery would change the published frame total."
        )
    old_boundary = boundaries[completed_prefix - 1] \
        if completed_prefix > 0 and len(boundaries) >= completed_prefix else None
    full_boundaries = boundaries[:max(0, completed_prefix - 1)]
    if old_boundary is not None:
        full_boundaries.append(old_boundary)
    full_boundaries.extend(replacement_boundaries)
    full_frames = clip_frames[:completed_prefix] + list(replacement_frames)
    full_published = published[:completed_prefix] + list(replacement_published)
    full_trims = trims[:completed_prefix] + list(replacement_trims)
    full_prompts = prompts[:completed_prefix] + replacement_prompts
    full_models = models[:completed_prefix] + [
        copy.deepcopy(models[-1]) for _ in replacement_frames
    ]
    original_shot_plan = longform.get("shot_plan")
    original_shots = (
        list(original_shot_plan.get("shots") or [])
        if isinstance(original_shot_plan, dict) else []
    )
    original_semantic = (
        list(original_shot_plan.get("semantic_shots") or [])
        if isinstance(original_shot_plan, dict) else []
    )
    raw_contract_version = (
        original_shot_plan.get("semantic_physical_contract_version")
        if isinstance(original_shot_plan, dict) else None
    )
    if raw_contract_version is not None and (
        isinstance(raw_contract_version, bool)
        or not isinstance(raw_contract_version, int)
        or raw_contract_version not in {1, 2}
    ):
        raise QueueRecoveryRuntimeError(
            "H3 recovery semantic contract version is unsupported."
        )
    contract_version = int(raw_contract_version or 0)
    original_has_semantic_contract = contract_version in {1, 2}
    if contract_version == 2:
        try:
            validate_h3_shot_plan_seal(original_shot_plan)
        except ValueError as exc:
            raise QueueRecoveryRuntimeError(str(exc)) from exc
        if (
            str(original_shot_plan.get("global_prompt") or "")
            != str(longform.get("global_prompt") or "")
            or list(original_shot_plan.get("clip_prompts") or []) != prompts
        ):
            raise QueueRecoveryRuntimeError(
                "H3 recovery global prompt provenance changed."
            )
    source_compiler_inputs = None
    if original_has_semantic_contract:
        if (
            len(original_shots) != completed_prefix + 1
            or not original_semantic
        ):
            raise QueueRecoveryRuntimeError(
                "H3 recovery semantic source contract is incomplete."
            )
        source_prompts = []
        structured_shots = []
        source_compiler_inputs = [] if contract_version == 2 else None
        for contract in original_semantic:
            if not isinstance(contract, dict):
                raise QueueRecoveryRuntimeError(
                    "H3 recovery semantic source contract is incomplete."
                )
            source_prompt_field = (
                "authored_prompt" if contract_version == 2
                else "semantic_prompt"
            )
            source_prompts.append(str(
                contract.get(source_prompt_field) or ""
            ))
            if contract_version == 2:
                source_compiler_inputs.append({
                    "version": 1,
                    "authored_shot_id": contract.get("authored_shot_id"),
                    "visual_context": contract.get("visual_context"),
                    "opening_blocking": contract.get("opening_blocking"),
                    "final_blocking": contract.get("final_blocking"),
                    "structured_dialogue_blocks": copy.deepcopy(
                        contract.get("structured_dialogue_blocks")
                    ),
                })
            else:
                # Retain the committed v1 compiler input shape byte-for-byte;
                # only v2 adopts the closed replay-input contract above.
                structured_shot = copy.deepcopy(contract)
                structured_shot["shot_id"] = str(
                    contract.get("authored_shot_id") or ""
                )
                structured_shots.append(structured_shot)
        if not all(source_prompts) or not all(
            shot.get("shot_id") for shot in structured_shots
        ):
            raise QueueRecoveryRuntimeError(
                "H3 recovery semantic source contract is incomplete."
            )
        final_source_index = int(original_shots[-1].get("source_index"))
        source_indices = [
            int(shot.get("source_index"))
            for shot in original_shots[:completed_prefix]
        ] + [final_source_index] * len(replacement_frames)
    else:
        # Legacy plans predate the semantic/physical contract but their
        # per-clip prompts are already sealed worker inputs. Treat each
        # completed child as its own immutable source and fan only the final
        # source across its replacement geometry. Falling back to the global
        # prompt here rewrites every prefix and makes valid legacy recovery
        # impossible.
        source_prompts = [str(prompt) for prompt in prompts]
        source_indices = list(range(completed_prefix)) + [
            completed_prefix
        ] * len(replacement_frames)
        structured_shots = None
    full_shot_plan = plan_h3_native_shots(
        global_prompt=str(longform.get("global_prompt") or ""),
        clip_frame_counts=full_frames,
        fps=fps,
        clip_boundaries=full_boundaries,
        clip_requested_frames=full_published,
        segment_frames_maximum=ceiling,
        segment_policy={
            "reason": "calibrated final-segment recovery",
            "clip_requested_frames": full_published,
        },
        source_prompts=source_prompts,
        source_indices=source_indices,
        structured_shots=(
            structured_shots if contract_version != 2 else None
        ),
        source_compiler_inputs=source_compiler_inputs,
    )
    if original_semantic:
        original_by_source = {
            int(contract.get("source_index")): contract
            for contract in original_semantic
            if isinstance(contract, dict)
        }
        rebuilt_contracts = []
        for rebuilt in list(full_shot_plan.get("semantic_shots") or []):
            try:
                source_index = int(rebuilt.get("source_index"))
                original_contract = original_by_source[source_index]
            except (AttributeError, KeyError, TypeError, ValueError):
                raise QueueRecoveryRuntimeError(
                    "H3 recovery semantic source association changed."
                ) from None
            if str(rebuilt.get("semantic_prompt")) != str(
                original_contract.get("semantic_prompt")
            ):
                raise QueueRecoveryRuntimeError(
                    "H3 recovery changed a sealed semantic prompt."
                )
            # Geometry-owned fields are recomputed for the unfinished suffix.
            # Semantic provenance is immutable across calibrated recovery.
            preserved = copy.deepcopy(rebuilt)
            for field in (
                "authored_prompt", "semantic_prompt", "reference_labels",
                "visual_context", "opening_blocking", "final_blocking",
                "authored_final_blocking",
            ):
                if field in original_contract:
                    preserved[field] = copy.deepcopy(
                        original_contract.get(field)
                    )
            rebuilt_contracts.append(preserved)
        if len(rebuilt_contracts) != len(original_semantic):
            raise QueueRecoveryRuntimeError(
                "H3 recovery semantic source count changed."
            )
        full_shot_plan["source_contracts"] = copy.deepcopy(rebuilt_contracts)
        full_shot_plan["semantic_shots"] = copy.deepcopy(rebuilt_contracts)

        original_dialogue = original_shot_plan.get("dialogue_manifest")
        rebuilt_dialogue = full_shot_plan.get("dialogue_manifest")
        if (
            not isinstance(original_dialogue, list)
            or not isinstance(rebuilt_dialogue, list)
            or len(original_dialogue) != len(rebuilt_dialogue)
        ):
            raise QueueRecoveryRuntimeError(
                "H3 recovery dialogue manifest is invalid."
            )
        remaining_dialogue = [
            copy.deepcopy(item) for item in original_dialogue
            if isinstance(item, dict)
        ]
        preserved_dialogue = []
        for rebuilt_item in rebuilt_dialogue:
            if not isinstance(rebuilt_item, dict):
                raise QueueRecoveryRuntimeError(
                    "H3 recovery dialogue manifest is invalid."
                )
            match_index = next((
                index for index, original_item in enumerate(
                    remaining_dialogue
                )
                if original_item.get("exact_block")
                    == rebuilt_item.get("exact_block")
                and original_item.get("authored_shot_id")
                    == rebuilt_item.get("authored_shot_id")
            ), None)
            if match_index is None:
                raise QueueRecoveryRuntimeError(
                    "H3 recovery dialogue provenance changed."
                )
            preserved_item = remaining_dialogue.pop(match_index)
            preserved_item["segment_index"] = rebuilt_item.get(
                "segment_index"
            )
            preserved_dialogue.append(preserved_item)
        if remaining_dialogue:
            raise QueueRecoveryRuntimeError(
                "H3 recovery dialogue provenance changed."
            )
        full_shot_plan["dialogue_manifest"] = preserved_dialogue
        for contract in full_shot_plan["source_contracts"]:
            contract["dialogue_manifest"] = [
                copy.deepcopy(item) for item in preserved_dialogue
                if item.get("source_index") == contract.get("source_index")
            ]
        full_shot_plan["semantic_shots"] = copy.deepcopy(
            full_shot_plan["source_contracts"]
        )
        for index, shot in enumerate(full_shot_plan.get("shots") or []):
            shot["dialogue_manifest_indices"] = [
                manifest_index
                for manifest_index, item in enumerate(preserved_dialogue)
                if item.get("segment_index") == index
            ]

    if contract_version == 2:
        full_prompts = list(full_shot_plan.get("clip_prompts") or [])
        if full_prompts[:completed_prefix] != prompts[:completed_prefix]:
            raise QueueRecoveryRuntimeError(
                "H3 recovery changed a completed segment-local prompt."
            )
        immutable_prefix_fields = (
            "index", "source_index", "authored_shot_id",
            "semantic_shot_index", "physical_segment_id",
            "physical_segment_index", "predecessor_segment_index",
            "predecessor_physical_segment_id",
            "predecessor_authored_shot_id", "execution_cursor_frame",
            "execution_slice", "frames", "start_frame", "end_frame",
            "published_frames", "published_start_frame",
            "published_end_frame", "published_end_frame_exclusive",
            "trim_tail_frames", "continuity_mode", "boundary_before",
            "prompt", "dialogue_manifest_indices",
        )
        for index in range(completed_prefix):
            original_shot = original_shots[index]
            rebuilt_shot = full_shot_plan["shots"][index]
            if any(
                rebuilt_shot.get(field) != original_shot.get(field)
                for field in immutable_prefix_fields
            ):
                raise QueueRecoveryRuntimeError(
                    "H3 recovery changed completed segment geometry."
                )
        try:
            def completed_event_projection(event: dict) -> dict:
                continuations = event.get("continuation_slices")
                if not isinstance(continuations, list):
                    raise TypeError
                projected = copy.deepcopy(event)
                projected["continuation_slices"] = []
                for item in continuations:
                    if (
                        not isinstance(item, dict)
                        or type(item.get("segment_index")) is not int
                    ):
                        raise TypeError
                    if item["segment_index"] < completed_prefix:
                        projected["continuation_slices"].append(
                            copy.deepcopy(item)
                        )
                return projected

            original_prefix_events = {
                str(event.get("event_id")): completed_event_projection(event)
                for event in original_shot_plan.get("event_ownership") or []
                if isinstance(event, dict)
                and int(event.get("owner_segment_index", -1))
                    < completed_prefix
            }
            rebuilt_prefix_events = {
                str(event.get("event_id")): completed_event_projection(event)
                for event in full_shot_plan.get("event_ownership") or []
                if isinstance(event, dict)
                and int(event.get("owner_segment_index", -1))
                    < completed_prefix
            }
        except (TypeError, ValueError):
            raise QueueRecoveryRuntimeError(
                "H3 recovery event ownership is invalid."
            ) from None
        if rebuilt_prefix_events != original_prefix_events:
            raise QueueRecoveryRuntimeError(
                "H3 recovery changed completed event ownership."
            )
        if "h3_style_workflow" in original_shot_plan:
            full_shot_plan["h3_style_workflow"] = copy.deepcopy(
                original_shot_plan.get("h3_style_workflow")
            )
    else:
        # Preserve committed v1 replay semantics. The v2 planner is used only
        # as a deterministic geometry builder; completed v1 children are never
        # migrated to segment-local prompts during a partial-chain recovery.
        v1_prompts = [""] * len(full_shot_plan.get("shots") or [])
        for contract in full_shot_plan.get("source_contracts") or []:
            semantic_prompt = str(contract.get("semantic_prompt") or "")
            for position in contract.get("segment_indices") or []:
                v1_prompts[int(position)] = semantic_prompt
            contract["prompt_rewrite_for_physical_split"] = False
            for field in (
                "physical_prompt_compiler_version", "event_ownership",
                "executable_prompt_sha256",
            ):
                contract.pop(field, None)
        if not all(v1_prompts):
            raise QueueRecoveryRuntimeError(
                "H3 recovery v1 prompt mapping is incomplete."
            )
        full_shot_plan["semantic_physical_contract_version"] = 1
        full_shot_plan["clip_prompts"] = v1_prompts
        full_shot_plan.pop("event_ownership", None)
        full_shot_plan.pop("prompt_contract_seal", None)
        for item in full_shot_plan.get("dialogue_manifest") or []:
            try:
                source = int(item.get("source_index"))
                item["segment_index"] = int(
                    full_shot_plan["source_contracts"][source][
                        "segment_indices"
                    ][0]
                )
            except (AttributeError, IndexError, TypeError, ValueError):
                raise QueueRecoveryRuntimeError(
                    "H3 recovery v1 dialogue association is invalid."
                ) from None
        for contract in full_shot_plan.get("source_contracts") or []:
            contract["dialogue_manifest"] = [
                copy.deepcopy(item)
                for item in full_shot_plan.get("dialogue_manifest") or []
                if item.get("source_index") == contract.get("source_index")
            ]
        full_shot_plan["semantic_shots"] = copy.deepcopy(
            full_shot_plan.get("source_contracts") or []
        )
        for index, shot in enumerate(full_shot_plan.get("shots") or []):
            shot["prompt"] = v1_prompts[index]
            shot["dialogue_manifest_indices"] = [
                manifest_index
                for manifest_index, item in enumerate(
                    full_shot_plan.get("dialogue_manifest") or []
                )
                if item.get("segment_index") == index
            ]
        full_prompts = v1_prompts
        if full_prompts[:completed_prefix] != prompts[:completed_prefix]:
            raise QueueRecoveryRuntimeError(
                "H3 recovery changed a completed v1 prompt."
            )
    if (
        list(full_shot_plan.get("clip_prompts") or []) != full_prompts
        or list(full_shot_plan.get("clip_published_frames") or [])
            != full_published
        or list(full_shot_plan.get("clip_trim_tail_frames") or []) != full_trims
    ):
        raise QueueRecoveryRuntimeError(
            "H3 recovery changed the sealed semantic shot contract."
        )
    if original_has_semantic_contract and original_shots and any(
        str(full_shot_plan["shots"][index].get("authored_shot_id"))
            != str(original_shots[index].get("authored_shot_id"))
        or int(full_shot_plan["shots"][index].get("source_index"))
            != int(original_shots[index].get("source_index"))
        for index in range(completed_prefix)
    ):
        raise QueueRecoveryRuntimeError(
            "H3 recovery changed a sealed authored-shot association."
        )
    existing_peak_identities = longform.get("peak_recovery_identities")
    if existing_peak_identities is None:
        peak_identities = [None] * completed_prefix
    elif (
        isinstance(existing_peak_identities, list)
        and len(existing_peak_identities) == len(clip_frames)
        and all(
            item is None or isinstance(item, dict)
            for item in existing_peak_identities
        )
    ):
        # Repeated calibrated recovery must retain the exact allocation
        # snapshot already bound into every newly completed prefix unit.
        peak_identities = copy.deepcopy(
            existing_peak_identities[:completed_prefix]
        )
    else:
        raise QueueRecoveryRuntimeError(
            "H3 recovery peak identity history is invalid."
        )
    for frames in replacement_frames:
        peak_identity = _h3_peak_recovery_identity(
            {**result, "model_type": final_model, "override_profile": profile},
            frame_count=frames,
        )
        peak_identity.update({
            "allocation_revision": int(choice["allocation_revision"]),
            "allocation_snapshot": str(choice["allocation_snapshot"]),
        })
        peak_identities.append(peak_identity)
    result.update({
        "override_profile": profile,
        "sliding_window_size": ceiling,
        "per_clip_frames": full_frames,
        "per_clip_prompts": full_prompts,
        "prompt": _MULTI_CLIP_SEPARATOR.join(full_prompts),
    })
    try:
        full_source_indices = [
            int(shot.get("source_index"))
            for shot in full_shot_plan.get("shots") or []
            if isinstance(shot, dict)
        ]
    except (TypeError, ValueError):
        raise QueueRecoveryRuntimeError(
            "H3 recovery source mapping is invalid."
        ) from None
    if (
        len(full_source_indices) != len(full_frames)
        or len(full_models) != len(full_frames)
    ):
        raise QueueRecoveryRuntimeError(
            "H3 recovery source/model mapping is incomplete."
        )
    longform.update({
        "clip_count": len(full_frames),
        "clip_frames": full_frames,
        "clip_published_frames": full_published,
        "clip_trim_tail_frames": full_trims,
        "clip_prompt_previews": [value[:240] for value in full_prompts],
        "clip_boundaries": full_boundaries,
        "segment_models": full_models,
        "segment_source_indices": full_source_indices,
        "segment_policy": copy.deepcopy(
            full_shot_plan.get("segment_policy") or {}
        ),
        "planned_frames": sum(full_frames),
        "final_trim_frames": sum(full_trims),
        "segment_frames_maximum": ceiling,
        "manual_segment_ceiling": True,
        "peak_recovery_identities": peak_identities,
        "shot_plan": full_shot_plan,
        "peak_recovery_policy": {
            "version": _H3_PEAK_RECOVERY_POLICY_VERSION,
            "frame_ceiling": ceiling,
            "offload_profile": profile,
        },
        "recovery_shot_plan": shot_plan,
        "recovery_segment_policy": segment_policy,
    })
    if contract_version == 2:
        original_runtime_contract = original_shot_plan.get(
            "director_runtime_contract"
        )
        if isinstance(original_runtime_contract, dict):
            full_shot_plan["director_runtime_contract"] = {
                field: copy.deepcopy(longform.get(field))
                for field in original_runtime_contract
            }
        seal_h3_shot_plan(full_shot_plan)
    if sum(full_published) != int(longform.get("published_frames") or 0):
        raise QueueRecoveryRuntimeError(
            "H3 recovery changed the job publication contract."
        )
    longform["_duration_completed_locks"] = list(range(completed_prefix))
    _stamp_h3_duration_contract(result, longform)
    result["_h3_longform"] = longform
    return result


def _prepare_h3_peak_recovery(job: dict) -> bool:
    """Reseal a calibrated replacement plan; never queue or start work."""
    prefix = _h3_incomplete_recovery_prefix(job)
    if prefix is None:
        raise QueueRecoveryRuntimeError("H3 recovery cursor is incomplete.")
    source_params = job.get("params") or {}
    longform = source_params.get("_h3_longform") \
        if isinstance(source_params, dict) else None
    try:
        missing_frames = int((longform.get("clip_frames") or [])[prefix])
        missing_model = str(
            ((longform.get("segment_models") or [])[prefix] or {}).get(
                "model_type"
            )
        )
    except (AttributeError, IndexError, TypeError, ValueError):
        raise QueueRecoveryRuntimeError("H3 recovery geometry is incomplete.") from None
    calibration_params = {
        **source_params,
        "model_type": missing_model,
        "video_length": missing_frames,
    }
    choice = _h3_calibrated_peak_choice(calibration_params)
    if choice is None:
        job["_recovery_reason_code"] = "h3_peak_calibration_required"
        _queue_recovery_checkpoint(
            job,
            status="queued",
            queue_held=True,
            recovery_state="blocked",
            reruns_denoise=False,
            message="Calibrated H3 recovery capacity is required",
        )
        return False
    project_dir = str(job.get("out_dir") or "")
    manifest = load_request_manifest(
        project_dir,
        job.get("_recovery_manifest_pointer") or {},
        expected_job_id=str(job.get("id") or ""),
    )
    manifest_params = dict(manifest["params"])
    prior_effective_profile = _h3_effective_offload_profile(manifest_params)
    prior_offload_plan = manifest_params.get(H3_OFFLOAD_PLAN_PARAM_KEY)
    if prior_offload_plan is not None:
        try:
            prior_offload_plan = validate_h3_offload_plan(
                prior_offload_plan
            )
        except H3OffloadPlanError as error:
            raise QueueRecoveryRuntimeError(
                "H3 recovery offload plan is invalid."
            ) from error
    replanned = _replan_h3_final_segment_for_peak(
        manifest_params, completed_prefix=prefix, choice=choice,
    )
    replanned_count = len(
        dict(replanned.get("_h3_longform") or {}).get("clip_frames") or []
    )
    recovered_profile = int(choice["offload_profile"])
    segment_profiles = []
    for index in range(replanned_count):
        if (
            index < prefix
            and isinstance(prior_offload_plan, dict)
            and index < len(prior_offload_plan.get("segments") or [])
        ):
            segment_profiles.append(int(
                prior_offload_plan["segments"][index]["profile"]
            ))
        elif index < prefix:
            # A pre-v1 journal has no per-segment plan. Preserve its exact
            # prior effective/manual profile rather than claiming completed
            # work ran under the newly selected recovery profile.
            segment_profiles.append(prior_effective_profile)
        else:
            segment_profiles.append(recovered_profile)
    offload_plan = _seal_h3_offload_plan_for_job(
        replanned,
        source="recovery_profile",
        replace=True,
        segment_profiles=segment_profiles,
    )
    pointer = write_sealed_request_manifest(
        project_dir,
        job_id=str(job.get("id") or ""),
        params=replanned,
        inputs=list(manifest.get("inputs") or []),
    )
    cursor = copy.deepcopy(job.get("recovery_cursor") or {})
    history = list(cursor.get("request_manifest_history") or [])
    prior_pointer = dict(job.get("_recovery_manifest_pointer") or {})
    if prior_pointer and prior_pointer not in history:
        history.append(prior_pointer)
    cursor["request_manifest_history"] = history[-8:]
    try:
        committed = block_generation_recovery(
            job,
            request_manifest=pointer,
            params=replanned,
            kind="studio_generation",
            recovery_cursor=cursor,
            h3_offload_plan=offload_plan,
            _recovery_manifest_pointer=dict(pointer),
            _recovery_reason_code="h3_generation_oom_replanned",
            recovery_state="blocked",
            reruns_denoise=True,
            message="Calibrated H3 replacement plan is ready",
        )
    except Exception:
        remove_request_manifest(project_dir, pointer)
        raise
    if not committed:
        remove_request_manifest(project_dir, pointer)
    return committed


def _h3_source_audio_premux_settings(params: dict) -> dict | None:
    """Return the path-free identity for one supported source-audio mux retry."""
    if not isinstance(params, dict) or str(params.get("model_type") or "") != "minimax_h3":
        return None
    custom = params.get("custom_settings")
    if not isinstance(custom, dict):
        return None
    mode = str(custom.get("h3_source_audio_mode") or "native")
    if mode not in {"lock_source", "remix_source", "reference_only"}:
        return None
    clip = params.get("multi_clip_info")
    if isinstance(clip, dict) and int(clip.get("total", 1) or 1) > 1:
        return None
    final_audio_kind = (
        "explicit" if params.get("audio_source")
        else "source" if mode == "lock_source"
        else "generated"
    )
    return {
        "algorithm_version": "maestro_h3_source_audio_v1",
        "final_audio_kind": final_audio_kind,
        "source_audio_mode": mode,
    }


def _snapshot_h3_recovery_task_params(
    task_params: dict, clip_info: dict | None,
) -> dict:
    """Freeze JSON-safe producer metadata before WGP materializes media inputs."""
    if not (
        isinstance(task_params, dict)
        and isinstance(clip_info, dict)
        and clip_info.get("automatic_h3_longform")
    ):
        return task_params
    try:
        snapshot = json.loads(json.dumps(task_params))
    except (TypeError, ValueError, OverflowError):
        raise QueueRecoveryRuntimeError(
            "H3 task metadata is not serializable before generation."
        ) from None
    if not isinstance(snapshot, dict):
        raise QueueRecoveryRuntimeError(
            "H3 task metadata snapshot is invalid."
        )
    return snapshot


def _apply_h3_offload_plan_to_manifest(
    manifest: list[dict], plan: dict | None,
) -> None:
    """Bind every H3 child dispatch to its sealed effective profile."""
    if plan is None:
        return
    try:
        sealed = validate_h3_offload_plan(plan)
    except H3OffloadPlanError as error:
        raise QueueRecoveryRuntimeError(
            "H3 child offload plan is invalid."
        ) from error
    segments = sealed["segments"]
    seen: set[int] = set()
    for task in manifest:
        task_params = task.get("params") if isinstance(task, dict) else None
        if not isinstance(task_params, dict) or not str(
            task_params.get("model_type") or ""
        ).startswith("minimax_h3"):
            continue
        clip_info = task_params.get("multi_clip_info")
        if (
            isinstance(clip_info, dict)
            and clip_info.get("automatic_h3_longform")
        ):
            raw_index = clip_info.get("index")
        elif len(manifest) == 1 and len(segments) == 1:
            raw_index = 0
        else:
            raise QueueRecoveryRuntimeError(
                "H3 child offload segment identity is incomplete."
            )
        if isinstance(raw_index, bool):
            raise QueueRecoveryRuntimeError(
                "H3 child offload segment index is invalid."
            )
        try:
            segment_index = int(raw_index)
        except (TypeError, ValueError):
            raise QueueRecoveryRuntimeError(
                "H3 child offload segment index is invalid."
            ) from None
        if not 0 <= segment_index < len(segments):
            raise QueueRecoveryRuntimeError(
                "H3 child offload segment index is invalid."
            )
        segment = segments[segment_index]
        try:
            matches = (
                str(task_params.get("model_type") or "")
                    == str(segment["model_type"])
                and int(task_params.get("video_length") or 0)
                    == int(segment["generated_frames"])
            )
        except (TypeError, ValueError):
            matches = False
        if not matches:
            raise QueueRecoveryRuntimeError(
                "H3 child dispatch changed after offload planning."
            )
        task_params["override_profile"] = int(segment["profile"])
        seen.add(segment_index)
    if seen != set(range(len(segments))):
        raise QueueRecoveryRuntimeError(
            "H3 child offload plan was not dispatched completely."
        )


def _merge_h3_ref2va_keyframes(
    semantic_refs: list | tuple | None,
    keyframes: list | tuple,
) -> list:
    """Preserve semantic refs while adding local Ref2VA keyframes."""
    combined = list(semantic_refs or ()) + list(keyframes or ())
    if len(combined) > 9:
        raise ValueError(
            "MiniMax H3 Ref2VA accepts at most 9 combined semantic references and per-clip keyframes"
        )
    return combined


def _apply_h3_recovered_continuation(
    unit: dict,
    next_task: dict,
    project_dir: str,
) -> None:
    """Restore only a hash-verified H3 continuation descriptor."""
    continuation = unit.get("continuation")
    if not isinstance(continuation, dict):
        return
    if continuation.get("dependency") != unit.get("unit_id"):
        raise QueueRecoveryRuntimeError("H3 continuation dependency is invalid.")
    mode = str(continuation.get("mode") or "prompt_only")
    path = _queue_recovery_continuation_path(project_dir, continuation)
    params = next_task.get("params")
    if not isinstance(params, dict):
        raise QueueRecoveryRuntimeError("H3 continuation target is invalid.")
    if mode == "last_frame" and path:
        from PIL import Image as PILImage
        frame = PILImage.open(path).convert("RGB")
        params["image_start"] = path
        params["image_prompt_type"] = "S" + str(params.get("image_prompt_type") or "")
        next_task["start_image_data"] = frame
        params.pop("_continuation", None)
    elif mode == "semantic_still" and path:
        refs = list(params.get("image_refs") or [])
        refs.append(path)
        params["image_refs"] = refs
        custom = dict(params.get("custom_settings") or {})
        custom["h3_ref2va_handoff"] = "semantic_still"
        params["custom_settings"] = custom
        params.pop("_ref2va_continuation", None)
    elif mode == "temporal_tail" and path:
        for slot, key in enumerate(
            ("video_guide", "video_guide2", "video_guide3"), start=1,
        ):
            if not params.get(key):
                params[key] = path
                params["video_prompt_type"] = {1: "V-", 2: "V+-", 3: "V++-"}[slot]
                custom = dict(params.get("custom_settings") or {})
                custom.update({
                    "h3_ref2va_handoff": "temporal_tail",
                    "h3_ref2va_handoff_video_slot": slot,
                    "h3_ref2va_handoff_frames": _H3_REF2VA_HANDOFF_FRAMES,
                })
                params["custom_settings"] = custom
                break
        params.pop("_ref2va_continuation", None)
    elif mode == "native_av_overlap" and path:
        from services.h3_boundary_policy import (
            H3_NATIVE_AUDIO_SAMPLE_RATE,
            H3_NATIVE_FPS,
            H3_NATIVE_HISTORY_FRAMES,
            H3_NATIVE_OVERLAP_FRAMES,
        )
        expected = {
            "fps": H3_NATIVE_FPS,
            "audio_sample_rate": H3_NATIVE_AUDIO_SAMPLE_RATE,
            "audio_channels": 2,
            "overlap_frames": H3_NATIVE_OVERLAP_FRAMES,
            "discard_frames": H3_NATIVE_HISTORY_FRAMES,
        }
        if any(int(continuation.get(key) or 0) != value for key, value in expected.items()):
            raise QueueRecoveryRuntimeError("H3 recovered native boundary metadata is invalid.")
        params["_h3_native_boundary"] = {
            **expected,
            "boundary_type": str(
                continuation.get("boundary_type") or "continuous"
            ),
            "mode": mode,
            "path": path,
            "sha256": continuation.get("sha256"),
            "size": continuation.get("size"),
        }
        params.pop("_h3_native_boundary_request", None)
    elif mode == "prompt_only":
        params.pop("_ref2va_continuation", None)
    else:
        raise QueueRecoveryRuntimeError("H3 continuation mode is invalid.")


def _queue_recovery_delivery_pending(job: dict) -> dict | None:
    cursor = job.get("recovery_cursor")
    pending = cursor.get("delivery_pending") if isinstance(cursor, dict) else None
    if not isinstance(pending, dict) or pending.get("state") not in {
        "staging_native", "protected_native",
    }:
        return None
    if pending.get("state") == "staging_native":
        return pending if isinstance(pending.get("staging"), list) else None
    if not isinstance(pending.get("artifacts"), list) or not pending["artifacts"]:
        return None
    if not isinstance(pending.get("settings"), dict):
        return None
    return pending


def _queue_recovery_reconcile_orphan_delivery(
    job: dict,
    project_dir: str,
) -> dict | None:
    """Recover the native-staged-before-journal crash window from sidecars."""
    records: dict[str, list[tuple[dict, dict]]] = {}
    try:
        entries = list(os.scandir(project_dir))
    except OSError:
        return None
    for entry in entries:
        if (
            not entry.is_file(follow_symlinks=False)
            or not entry.name.startswith(".maestro-delivery-")
            or not entry.name.endswith(".native.meta.json")
        ):
            continue
        try:
            with open(entry.path, "r", encoding="utf-8") as handle:
                meta = json.load(handle)
            durable = meta.get("delivery_recovery")
            unit_id = str((durable or {}).get("queue_recovery_unit_id") or "")
            settings = (durable or {}).get("queue_recovery_settings")
            dependencies = (durable or {}).get("queue_recovery_dependencies")
            original = str((durable or {}).get("original_filename") or "")
            if (
                not isinstance(meta, dict)
                or not isinstance(durable, dict)
                or str(durable.get("source_job_id") or "") != str(job.get("id") or "")
                or not isinstance(settings, dict)
                or not isinstance(dependencies, list)
                or os.path.basename(original) != original
                or original.startswith(".")
            ):
                continue
            expected = recovery_unit_id(
                str(job.get("id") or ""),
                "h3_delivery",
                dependencies=dependencies,
                settings=settings,
            )
            if not hmac.compare_digest(expected, unit_id):
                continue
            owner = str(durable.get("owner_session_id") or "")
            if not owner:
                continue
            candidate_owner = owner_principal_digest(_session_secret(), owner)
            if not hmac.compare_digest(
                candidate_owner, str(job.get("_recovery_owner_digest") or ""),
            ):
                continue
            extension = os.path.splitext(original)[1]
            native_path = entry.path[:-len(".meta.json")] + extension
            if not os.path.isfile(native_path) or os.path.islink(native_path):
                continue
            descriptor = _protected_recovery_artifact_descriptor(
                project_dir,
                basename=os.path.basename(native_path),
                sidecar_basename=entry.name,
                original_basename=original,
                producer_unit_id=unit_id,
            )
            if descriptor.get("sha256") not in settings.get("native_hashes", []):
                continue
            records.setdefault(unit_id, []).append((descriptor, durable))
        except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
            continue
    for unit_id, candidates in records.items():
        first = candidates[0][1]
        settings = dict(first.get("queue_recovery_settings") or {})
        native_hashes = list(settings.get("native_hashes") or [])
        by_hash = {descriptor["sha256"]: descriptor for descriptor, _ in candidates}
        if len(by_hash) != len(native_hashes) or any(value not in by_hash for value in native_hashes):
            continue
        artifacts = [by_hash[value] for value in native_hashes]
        work_basenames = []
        for descriptor in artifacts:
            native = descriptor["basename"]
            marker = ".native"
            position = native.rfind(marker)
            if position < 0:
                break
            work_basenames.append(native[:position] + ".work" + native[position + len(marker):])
        if len(work_basenames) != len(artifacts):
            continue
        return {
            "artifacts": artifacts,
            "dependencies": list(first.get("queue_recovery_dependencies") or []),
            "settings": settings,
            "state": "protected_native",
            "unit_id": unit_id,
            "work_basenames": work_basenames,
        }
    return None


def _queue_recovery_reseal_delivery_source(
    job: dict,
    project_dir: str,
    unit: dict,
    artifact: dict,
    file_name: str,
) -> dict | None:
    """Reseal one sanctioned private-native sidecar without changing media."""
    unit_id = str(unit.get("unit_id") or "")
    kind = str(unit.get("kind") or "")
    variant = unit.get("variant", 0)
    index = unit.get("index", 0)
    dependencies = unit.get("dependencies")
    raw_settings = unit.get("settings")
    settings = {} if raw_settings is None else raw_settings
    if (
        type(variant) is not int
        or variant < 0
        or type(index) is not int
        or index < 0
        or not isinstance(dependencies, list)
        or not isinstance(settings, dict)
    ):
        return None
    try:
        expected_unit_id = recovery_unit_id(
            str(job.get("id") or ""),
            kind,
            variant=variant,
            index=index,
            dependencies=dependencies,
            settings=settings,
        )
    except (TypeError, ValueError, QueueRecoveryRuntimeError):
        return None
    sidecar_name = artifact.get("sidecar_basename")
    if (
        artifact.get("producer_unit_id") != unit_id
        or not hmac.compare_digest(unit_id, expected_unit_id)
        or artifact.get("basename") != file_name
        or not isinstance(sidecar_name, str)
        or os.path.basename(sidecar_name) != sidecar_name
        or sidecar_name.startswith(".")
    ):
        return None
    try:
        refreshed = _recovery_artifact_descriptor(
            project_dir,
            basename=file_name,
            sidecar_basename=sidecar_name,
            producer_unit_id=unit_id,
        )
        if (
            refreshed.get("size") != artifact.get("size")
            or refreshed.get("sha256") != artifact.get("sha256")
        ):
            return None
        sidecar_path = os.path.join(project_dir, sidecar_name)
        with open(sidecar_path, "rb") as handle:
            sidecar_bytes = handle.read()
        if (
            len(sidecar_bytes) != refreshed.get("sidecar_size")
            or not hmac.compare_digest(
                hashlib.sha256(sidecar_bytes).hexdigest(),
                str(refreshed.get("sidecar_sha256") or ""),
            )
        ):
            return None
        meta = json.loads(sidecar_bytes.decode("utf-8"))
    except (
        OSError, UnicodeDecodeError, ValueError, TypeError,
        QueueRecoveryRuntimeError,
    ):
        return None
    if not isinstance(meta, dict):
        return None
    raw_meta_dependencies = meta.get("producer_unit_dependencies")
    meta_dependencies = (
        [] if raw_meta_dependencies is None else raw_meta_dependencies
    )
    raw_meta_settings = meta.get("producer_unit_settings")
    meta_settings = {} if raw_meta_settings is None else raw_meta_settings
    if not isinstance(meta_dependencies, list) or not isinstance(meta_settings, dict):
        return None
    expected_role = _queue_recovery_expected_artifact_role(kind, meta)
    producer_variant = meta.get("producer_unit_variant", 0)
    producer_index = meta.get("producer_unit_index", 0)
    if type(producer_variant) is not int or type(producer_index) is not int:
        return None
    if (
        expected_role is None
        or meta.get("producer_unit_id") != unit_id
        or str(meta.get("producer_unit_kind") or "") != kind
        or producer_variant != variant
        or producer_index != index
        or meta.get("producer_artifact_class") != expected_role
        or meta.get("artifact_class") != "temporary"
        or meta.get("delivery_native_source") is not True
        or meta.get("private") is not True
        or str(meta.get("owner_session_id") or "")
            != str(job.get("session_id") or "")
        or str(meta.get("workspace") or "")
            != str(job.get("workspace") or "default")
        or str(meta.get("job_id") or "") != str(job.get("id") or "")
        or str(meta.get("output_filename") or "") != file_name
        or meta.get("producer_media_size") != refreshed.get("size")
        or meta.get("producer_media_sha256") != refreshed.get("sha256")
        or meta_dependencies != dependencies
        or meta_settings != settings
    ):
        return None
    return refreshed


def _queue_recovery_delivery_plan(
    job: dict,
    project_dir: str,
    file_names: list[str],
    *,
    spatial_upsampling: str,
    delivery_resolution: str,
    delivery_fit: str,
) -> dict:
    """Bind delivery to ordered verified native hashes and producer units."""
    native_hashes = []
    dependencies = []
    sources = []
    for file_name in file_names:
        matching = None
        for unit in _queue_recovery_units(job):
            if unit.get("state") != "completed":
                continue
            for artifact in unit.get("artifacts") or []:
                if not (
                    isinstance(artifact, dict)
                    and artifact.get("basename") == file_name
                ):
                    continue
                unit_id = str(unit.get("unit_id") or "")
                source_unit = unit
                source_artifact = artifact
                if not validate_artifact_descriptor(
                    project_dir,
                    source_artifact,
                    producer_unit_id=unit_id,
                ):
                    # H3 delivery intentionally restamps the final native as an
                    # owner-private temporary before this plan is built. That
                    # sanctioned policy/role change invalidates only the safe
                    # unit's sidecar digest. Reseal only the exact recognized
                    # private-native policy evolution; never rewrite evidence or
                    # accept changed media under the producer's old unit ID.
                    reseal_source = globals().get(
                        "_queue_recovery_reseal_delivery_source"
                    )
                    refreshed = (
                        reseal_source(
                            job, project_dir, unit, artifact, file_name,
                        )
                        if callable(reseal_source) else None
                    )
                    if (
                        not isinstance(refreshed, dict)
                        or not validate_artifact_descriptor(
                            project_dir,
                            refreshed,
                            producer_unit_id=unit_id,
                        )
                    ):
                        continue
                    source_artifact = refreshed
                matching = (source_unit, source_artifact)
                break
            if matching is not None:
                break
        if matching is None:
            raise QueueRecoveryRuntimeError(
                "H3 delivery requires a verified native producer unit."
            )
        unit, artifact = matching
        native_hashes.append(str(artifact.get("sha256") or ""))
        dependencies.append(str(unit.get("unit_id") or ""))
        sources.append(dict(artifact))
    settings = {
        "delivery_fit": delivery_fit,
        "delivery_resolution": delivery_resolution,
        "native_hashes": native_hashes,
        "spatial_upsampling": spatial_upsampling,
    }
    unit_id = recovery_unit_id(
        str(job.get("id") or ""),
        "h3_delivery",
        dependencies=dependencies,
        settings=settings,
    )
    staging = []
    for item_index, file_name in enumerate(file_names):
        stem, extension = os.path.splitext(file_name)
        prefix = (
            f".maestro-delivery-{job.get('id', 'job')}-"
            f"{unit_id[-12:]}-{item_index}-{stem}"
        )
        staging.append({
            "native_basename": prefix + ".native" + extension,
            "native_sidecar_basename": prefix + ".native.meta.json",
            "original_basename": file_name,
            "source": sources[item_index],
            "work_basename": prefix + ".work" + extension,
        })
    return {
        "dependencies": dependencies,
        "staging": staging,
        "settings": settings,
        "unit_id": unit_id,
    }


def _queue_recovery_checkpoint_delivery_intent(job: dict, plan: dict) -> dict:
    """Persist planned native names and source hashes before the first rename."""
    pending = {
        "dependencies": list(plan.get("dependencies") or []),
        "settings": dict(plan.get("settings") or {}),
        "staging": [dict(item) for item in plan.get("staging") or []],
        "state": "staging_native",
        "unit_id": str(plan.get("unit_id") or ""),
    }
    cursor = dict(job.get("recovery_cursor") or {})
    cursor["delivery_pending"] = pending
    _queue_recovery_checkpoint(
        job,
        recovery_cursor=cursor,
        recovery_state="interrupted",
        reruns_denoise=False,
        message="Protecting native output for delivery",
    )
    return pending


def _queue_recovery_checkpoint_delivery_pending(
    job: dict,
    project_dir: str,
    staged: list[dict],
    plan: dict,
) -> dict:
    artifacts = []
    for item in staged:
        descriptor = _protected_recovery_artifact_descriptor(
            project_dir,
            basename=os.path.basename(item["native_path"]),
            sidecar_basename=os.path.basename(item["native_meta"]),
            original_basename=item["file_name"],
            producer_unit_id=plan["unit_id"],
        )
        item["recovery_descriptor"] = descriptor
        item["work_basename"] = os.path.basename(item["work_path"])
        artifacts.append(descriptor)
    pending = {
        "artifacts": artifacts,
        "dependencies": list(plan["dependencies"]),
        "settings": dict(plan["settings"]),
        "state": "protected_native",
        "unit_id": str(plan["unit_id"]),
        "work_basenames": [item["work_basename"] for item in staged],
    }
    cursor = dict(job.get("recovery_cursor") or {})
    cursor["delivery_pending"] = pending
    _queue_recovery_checkpoint(
        job,
        recovery_cursor=cursor,
        recovery_state="interrupted",
        reruns_denoise=False,
        message="Protected native output is ready for delivery",
    )
    return pending


def _queue_recovery_restore_delivery_staged(
    job: dict,
    project_dir: str,
    pending: dict,
) -> list[dict]:
    artifacts = pending.get("artifacts") or []
    work_names = pending.get("work_basenames") or []
    if len(artifacts) != len(work_names):
        raise QueueRecoveryRuntimeError("Protected delivery evidence is incomplete.")
    staged = []
    for descriptor, work_name in zip(artifacts, work_names):
        if not validate_protected_artifact_descriptor(
            project_dir,
            descriptor,
            producer_unit_id=str(pending.get("unit_id") or ""),
        ):
            raise QueueRecoveryRuntimeError("Protected delivery native no longer matches.")
        original = str(descriptor.get("original_basename") or "")
        if (
            os.path.basename(original) != original
            or original.startswith(".")
            or os.path.basename(str(work_name)) != work_name
            or not str(work_name).startswith(".maestro-delivery-")
        ):
            raise QueueRecoveryRuntimeError("Protected delivery identity is invalid.")
        stem = os.path.splitext(original)[0]
        staged.append({
            "file_name": original,
            "source_path": os.path.join(project_dir, original),
            "source_meta": os.path.join(project_dir, stem + ".meta.json"),
            "native_path": os.path.join(project_dir, descriptor["basename"]),
            "native_meta": os.path.join(project_dir, descriptor["sidecar_basename"]),
            "work_path": os.path.join(project_dir, work_name),
            "work_basename": work_name,
            "rollback_meta": os.path.join(project_dir, work_name + ".rollback.meta.json"),
            "recovery_descriptor": dict(descriptor),
        })
    job["_h3_delivery_native"] = staged
    return staged


def _queue_recovery_checkpoint_delivery_completed(
    job: dict,
    project_dir: str,
    file_names: list[str],
    pending: dict,
) -> dict | None:
    """Seal final delivery sidecars, then journal the completed delivery unit."""
    unit_id = str(pending.get("unit_id") or "")
    for file_name in file_names:
        media_path = os.path.join(project_dir, file_name)
        meta_path = os.path.join(
            project_dir, os.path.splitext(file_name)[0] + ".meta.json",
        )
        media_size, media_sha256 = _recovery_sha256_file(media_path)
        try:
            with open(meta_path, "r", encoding="utf-8") as handle:
                sidecar = json.load(handle)
        except (OSError, ValueError, TypeError) as error:
            raise QueueRecoveryRuntimeError(
                "Completed delivery sidecar is unavailable."
            ) from error
        if not isinstance(sidecar, dict):
            raise QueueRecoveryRuntimeError("Completed delivery sidecar is invalid.")
        sidecar.update({
            "producer_artifact_class": "final",
            "artifact_class": "final",
            "producer_unit_artifact_names": sorted(file_names),
            "producer_unit_id": unit_id,
            "producer_unit_kind": "h3_delivery",
            "producer_unit_variant": 0,
            "producer_unit_index": 0,
            "producer_unit_dependencies": list(
                pending.get("dependencies") or []
            ),
            "producer_unit_settings": dict(pending.get("settings") or {}),
            "producer_media_sha256": media_sha256,
            "producer_media_size": media_size,
        })
        _atomic_write_json(meta_path, sidecar)
    unit = _queue_recovery_checkpoint_unit(
        job,
        kind="h3_delivery",
        variant=0,
        index=0,
        project_dir=project_dir,
        artifact_names=file_names,
        dependencies=list(pending.get("dependencies") or []),
        settings=dict(pending.get("settings") or {}),
    )
    if unit is None:
        return None
    if unit.get("unit_id") != unit_id:
        raise QueueRecoveryRuntimeError("Completed delivery identity changed.")
    return unit


def _require_project_access(
    request: Request,
    workspace: str,
    *,
    existing_only: bool = False,
    permission: str | None = None,
) -> str:
    """Return the contained workspace dir or reject a locked project."""
    remote = bool(getattr(request.state, "maestro_remote", False))
    if remote and workspace == "default":
        raise HTTPException(status_code=404, detail="Project not found")
    account_project_state = _account_project_access_state()
    account_projects_enforced = account_project_state["enforced"]
    workspace_dir = (
        _existing_workspace_dir(workspace)
        if remote or existing_only or account_projects_enforced
        else _workspace_dir(workspace)
    )
    if permission is None:
        permission = (
            "project.read"
            if str(getattr(request, "method", "GET") or "GET").upper()
            in {"GET", "HEAD"}
            else "project.mutate"
        )
    membership = _require_account_project_permission(
        request,
        workspace_dir,
        permission,
        state=account_project_state,
    )
    if membership is not None:
        return workspace_dir
    access_method = (
        _project_access.authorize
        if str(getattr(request, "method", "GET") or "GET").upper()
        in _STATE_CHANGING_METHODS
        else _project_access.status
    )
    status = access_method(
        workspace, workspace_dir, request.state.maestro_session_id,
        remote,
    )
    if remote and not status.protected:
        raise HTTPException(
            status_code=423,
            detail="Remote access requires a password-protected project",
        )
    if not status.unlocked:
        raise HTTPException(status_code=423, detail="Project is password locked")
    return workspace_dir


def _request_project_workspace(request: Request, workspace: str | None) -> str:
    """Resolve a project scope without remote fallback to host-global state."""
    selected = str(workspace or "")
    if bool(getattr(request.state, "maestro_remote", False)) and not selected:
        raise HTTPException(
            status_code=400,
            detail="workspace is required for remote project access",
        )
    if bool(getattr(request.state, "maestro_remote", False)) and selected == "default":
        raise HTTPException(status_code=404, detail="Project not found")
    return selected or _get_active_workspace()


def _require_authorized_output(
    request: Request,
    workspace: str,
    name: str,
) -> tuple[str, str, dict | None]:
    """Resolve one direct-child output after project + session checks."""
    from services.win_safe_files import (
        is_safe_direct_basename,
        safe_direct_file_under,
    )
    if not is_safe_direct_basename(name) or name.startswith("."):
        raise HTTPException(status_code=400, detail="Invalid output name")
    out_dir = _require_project_access(request, workspace)
    filepath = safe_direct_file_under(out_dir, name)
    if not filepath or not os.path.isfile(filepath):
        raise HTTPException(status_code=404, detail="Output file not found")
    sidecar = load_media_sidecars(out_dir, {name}).get(name)
    expected_sidecar = safe_direct_file_under(
        out_dir, os.path.splitext(name)[0] + ".meta.json",
    )
    if expected_sidecar and os.path.isfile(expected_sidecar) and sidecar is None:
        # A present-but-malformed or ambiguous sidecar is evidence that this
        # is managed output, not a legacy sidecarless file. Fail closed.
        raise HTTPException(status_code=404, detail="Output file not found")
    return out_dir, filepath, sidecar


def _redact_local_paths(value):
    """Remove host directory disclosure from output-facing JSON shapes."""
    if isinstance(value, dict):
        return {
            key: _redact_local_paths(nested)
            for key, nested in value.items()
            if key not in {"owner_session_id", "_maestro_session_id", "_maestro_access_policy"}
        }
    if isinstance(value, list):
        return [_redact_local_paths(item) for item in value]
    if isinstance(value, tuple):
        return [_redact_local_paths(item) for item in value]
    if isinstance(value, str) and (
        os.path.isabs(value) or PureWindowsPath(value).is_absolute()
    ):
        return os.path.basename(value.replace("\\", "/"))
    return value


def _stamp_upload_derivatives(value, owner_session_id: str) -> None:
    """Stamp direct upload files returned by an internal media operation."""
    from services.win_safe_files import safe_direct_file_under

    if isinstance(value, dict):
        for nested in value.values():
            _stamp_upload_derivatives(nested, owner_session_id)
        return
    if isinstance(value, (list, tuple, set)):
        for nested in value:
            _stamp_upload_derivatives(nested, owner_session_id)
        return
    if not isinstance(value, str) or not value or "\x00" in value:
        return
    absolute = os.path.abspath(value)
    name = os.path.basename(absolute)
    if name.startswith("."):
        return
    for root in (
        os.path.join(os.getcwd(), "uploads"),
        os.path.join(os.getcwd(), "uploads", "audio"),
    ):
        candidate = safe_direct_file_under(root, name)
        if candidate == absolute and os.path.isfile(candidate):
            # Recursive operation results can also echo an original source.
            # Never change an existing upload's deliberate owner/visibility.
            try:
                if read_upload_access_sidecar(candidate) is not None:
                    return
            except ValueError:
                return
            write_upload_access_sidecar(
                candidate,
                owner_session_id,
                private=True,
            )
            return


def _stamp_job_output_access(job: dict) -> None:
    """Apply one job's access policy to every published sidecar."""
    policy = job.get("access_policy")
    if not isinstance(policy, dict):
        return
    out_dir = job.get("out_dir")
    if not isinstance(out_dir, str) or not os.path.isdir(out_dir):
        return
    job_id = str(job.get("id") or "")
    output_names = set(job.get("output_files") or [])
    try:
        candidates = [name for name in os.listdir(out_dir) if name.endswith(".meta.json")]
    except OSError:
        return
    for sidecar_name in candidates:
        path = _safe_join(out_dir, sidecar_name)
        if path is None or not os.path.isfile(path):
            continue
        media_stem = sidecar_name[:-len(".meta.json")]
        try:
            with open(path, "r", encoding="utf-8") as handle:
                meta = json.load(handle)
            output_filename = str(meta.get("output_filename") or "")
            if meta.get("job_id") != job_id and not (
                output_filename in output_names
                or any(os.path.splitext(name)[0] == media_stem for name in output_names)
            ):
                continue
            stamp_sidecar_policy(
                meta, policy,
                workspace=str(job.get("workspace") or "default"),
            )
            temp = f"{path}.{uuid.uuid4().hex[:8]}.tmp"
            with open(temp, "w", encoding="utf-8") as handle:
                json.dump(meta, handle, indent=2)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp, path)
        except (OSError, ValueError, TypeError):
            continue


_lifecycle_finish_job = finish_job


def _credit_prepare_owner_completion(job: dict) -> dict | None:
    """Keep owner completion non-blocking while preserving cleanup retry."""
    if not _credit_owner_exempt(job):
        return None
    current = job.get("credit_queue")
    linked_hold = bool(
        isinstance(current, dict)
        and current.get("schema_version") == 2
        and current.get("reservation_state") == "reserved"
    )
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    cleanup_retained = isinstance(params.get(_CREDIT_CLEANUP_PARAM), dict)
    if _credit_retire_owner_state(job):
        return None
    if linked_hold and cleanup_retained:
        # The request manifest retains the cleanup tuple and account lineage.
        # A released-v2 tombstone skips the optional lifecycle callback while
        # retaining durable former-owner provenance. The cleanup tuple remains
        # authoritative and startup recovery retries the idempotent release.
        job["credit_queue"] = _credit_owner_release_tombstone(
            current,
            current["accounting_reservation_revision"],
        )
        return current
    return None


def finish_job(job, *args, **kwargs):
    """Lifecycle finish plus producer-parity access metadata stamping."""
    deferred_credit_queue = _credit_prepare_owner_completion(job)
    try:
        result = _lifecycle_finish_job(job, *args, **kwargs)
    except Exception:
        if deferred_credit_queue is not None:
            job["credit_queue"] = deferred_credit_queue
        raise
    _stamp_job_output_access(job)
    owner_test = job.get("_owner_test_credit")
    if isinstance(owner_test, dict):
        account_id = _credit_account_id(job)
        status = str(job.get("status") or "")
        finished_at = job.get("finished_at")
        if (
            account_id
            and status in {"completed", "failed", "cancelled"}
            and isinstance(finished_at, (int, float))
        ):
            try:
                _owner_test_credit_ledger().settle(
                    account_key=_owner_test_credit_account_key(account_id),
                    job_key=str(job.get("id") or ""),
                    reservation_id=str(owner_test.get("reservation_id") or ""),
                    expected_revision=int(
                        owner_test.get("reservation_revision") or 0
                    ),
                    terminal_status=status,
                    started_at=(
                        float(job["started_at"])
                        if isinstance(job.get("started_at"), (int, float))
                        else None
                    ),
                    finished_at=float(finished_at),
                )
            except (OwnerTestCreditError, TypeError, ValueError):
                job["_owner_test_credit_unavailable"] = True
    return result


def _workspace_file_count(path: str) -> int:
    """Non-hidden files directly inside a workspace folder (for delete
    confirms). scandir answers is_file() from the enumeration data on
    Windows — no per-entry stat syscall."""
    try:
        with os.scandir(path) as entries:
            return sum(1 for e in entries if not e.name.startswith(".") and e.is_file())
    except OSError:
        return 0


def _list_workspaces() -> list[dict]:
    """List all workspaces (subdirectories of the base output path + default)."""
    base = wgp.server_config.get("save_path", "outputs")
    workspaces = [{"name": "default", "path": base, "file_count": _workspace_file_count(base)}]
    if os.path.isdir(base):
        for name in sorted(os.listdir(base)):
            full = os.path.join(base, name)
            if os.path.isdir(full) and not name.startswith(("_", ".")):
                workspaces.append({"name": name, "path": full, "file_count": _workspace_file_count(full)})
    return workspaces


def _persist_active_workspace(name: str, apply_save_paths: bool = True) -> str:
    """Write services.active_workspace to config and (optionally) point
    wgp's save paths at it. Pass apply_save_paths=False while a generation
    is running — the in-flight job has locked wgp.save_path to its target
    and the new value takes effect on the next job / restart."""
    services = wgp.server_config.setdefault("services", {})
    services["active_workspace"] = name
    wgp.server_config["services"] = services
    with open(wgp.server_config_filename, "w", encoding="utf-8") as f:
        f.write(json.dumps(wgp.server_config, indent=4))
    ws_dir = _workspace_dir(name)
    if apply_save_paths:
        wgp.save_path = ws_dir
        wgp.image_save_path = ws_dir
    return ws_dir

