_pipeline_initialized = False


def _init_pipeline():
    global _pipeline_initialized
    if not _pipeline_initialized:
        from services.director_pipeline import init as pipeline_init
        pipeline_init(
            _jobs, _run_generation, wgp, _gen_lock, _active_gen_states,
            recovery_register_parent=_director_recovery_register_parent,
            recovery_prepare_parent_state=(
                _director_recovery_prepare_parent_state
            ),
            recovery_checkpoint_parent=_director_recovery_checkpoint_parent,
            recovery_prepare_parent_delete=(
                _director_recovery_prepare_parent_delete
            ),
            recovery_remove_parent=_director_recovery_remove_parent,
            recovery_submit_child=_director_recovery_submit_child,
            recovery_verify_child=_director_recovery_verified_child,
            recovery_validate_child=_director_recovery_validate_child,
            runtime_admission=_director_recovery_runtime_admission,
        )
        _pipeline_initialized = True


# ============================================================================
# API Routes: /api/v1/*
# ============================================================================

def _variant_group_filenames(urls) -> list:
    """Flatten one weight group (list of variant URLs / dict entries) to file names."""
    names = []
    for url_entry in urls:
        url_str = url_entry
        if isinstance(url_entry, dict):
            inner = url_entry.get("URLs", url_entry.get("url", []))
            url_str = inner[0] if isinstance(inner, list) and inner else (inner if isinstance(inner, str) else "")
        if not isinstance(url_str, str) or not url_str:
            continue
        names.append(url_str.rstrip("/").split("/")[-1])
    return names


def _variant_group_downloaded(urls, *, extra_paths=None) -> bool:
    """True when ANY variant (full bf16 vs quantized int8...) of one weight
    group exists locally. Resolves through the files locator so checkpoints
    in linked model folders (Settings -> System -> Linked Model Folders)
    light up too — a hardcoded ckpts_dir check misses every secondary root."""
    for filename in _variant_group_filenames(urls):
        if wgp.get_local_model_filename(
            filename, extra_paths=extra_paths,
        ) is not None:
            return True
    return False


def _model_weight_groups(model_type: str, owned_only: bool = False) -> list:
    """All weight groups a model needs on disk: main URLs + weight modules.

    "URLs" may be a string pointer to another model type (finetunes such as
    z_image_control or scail2_14B_fast use "URLs": "<base_model>"). Resolve
    recursively like the engine does — iterating the raw value would walk
    the characters of the string and permanently report not-downloaded.

    owned_only=True returns only groups this entry itself declares (skips a
    string-pointer base). Used by delete: removing a finetune must not pull
    the shared base transformer out from under its sibling entries — the
    base is deleted from the base model's own row instead.

    String-named modules resolve through the engine's module registry and
    are intentionally left out (they were never counted here).
    """
    md = wgp.get_model_def(model_type) or {}
    groups = []
    raw_urls = md.get("URLs", None)
    if isinstance(raw_urls, str):
        if not owned_only:
            urls = wgp.get_model_recursive_prop(model_type, "URLs", return_list=True)
            if urls:
                groups.append(urls)
    elif raw_urls:
        groups.append(raw_urls)
    for module in md.get("modules", []):
        if isinstance(module, list):
            groups.append(module)
        elif isinstance(module, dict):
            group = module.get("URLs", [])
            if group:
                groups.append(group)
    return groups


def _check_model_downloaded(model_type: str) -> bool:
    """Check if a model's checkpoint files are downloaded.

    Models often list multiple URLs (e.g. full bf16 + quantized int8) per
    weight group; ONE variant per group is enough. Every group (main
    transformer + each weight module) must be present.
    """
    try:
        model_def = wgp.get_model_def(model_type)
        if model_def is None:
            return False
        manual_required = getattr(
            wgp, "manual_checkpoint_integrity_required", None,
        )
        manual_ready = getattr(
            wgp, "manual_checkpoint_integrity_ready", None,
        )
        if callable(manual_required) and manual_required(
            model_type,
            model_def,
            wgp.models_def,
        ) and (
            not callable(manual_ready)
            or not manual_ready(model_type, model_def, wgp.models_def)
        ):
            return False
        groups = _model_weight_groups(model_type)
        if not groups:
            return False
        if not all(_variant_group_downloaded(g) for g in groups):
            return False
        text_encoder_urls = wgp.get_model_recursive_prop(
            model_type, "text_encoder_URLs", return_list=True,
        )
        if text_encoder_urls and not _variant_group_downloaded(
            text_encoder_urls,
            extra_paths=model_def.get("text_encoder_folder"),
        ):
            return False
        # Some edit pipelines split required conditioning weights out of the
        # main transformer/text-encoder groups. Krea 2 Edit cannot run without
        # its Qwen3-VL vision tower, so do not report it as ready until that
        # preloaded companion file is actually discoverable (including through
        # linked checkpoint roots).
        vision_encoder_filename = model_def.get("vision_encoder_filename")
        if (
            vision_encoder_filename
            and wgp.fl.locate_file(vision_encoder_filename, error_if_none=False) is None
        ):
            return False
        # Def-bundled accelerator loras (e.g. SCAIL-2 Fast's lightx2v
        # distill) are loaded unconditionally at generation time, so they
        # count toward readiness too. resolve_lora_path searches linked
        # read-only roots like the generation path does.
        for url in wgp.get_model_recursive_prop(model_type, "loras", return_list=True):
            if not os.path.isfile(wgp.resolve_lora_path(model_type, url.split("/")[-1])):
                return False
        return True
    except Exception:
        return False


def _remote_visible_model_ids(request: Request) -> frozenset[str] | None:
    """Return the persisted remote catalog, or ``None`` for local callers.

    The browser selector is not an authorization boundary.  Cloudflare
    callers may use only the owner-persisted model whitelist; missing or
    malformed persisted state is deliberately an empty remote catalog.
    """
    if not bool(getattr(request.state, "maestro_remote", False)):
        return None
    visibility = _model_visibility_response()
    if not visibility.get("configured"):
        return frozenset()
    return frozenset(visibility.get("enabled_models") or ())


def _require_remote_visible_models(request: Request, model_types) -> None:
    requested = {
        str(model_type).strip()
        for model_type in (model_types or ())
        if str(model_type).strip()
    }
    if "minimax_music3" in requested:
        # Reserved for a non-executable virtual catalog entry.  Never let a
        # registry/plugin collision grant generic WGP authority.
        raise HTTPException(status_code=404, detail="Model not found")
    allowed = _remote_visible_model_ids(request)
    if allowed is None:
        return
    if any(model_type not in allowed for model_type in requested):
        # Hidden and unknown identifiers are intentionally indistinguishable.
        raise HTTPException(status_code=404, detail="Model not found")


def _h3_registered_architectures(model_types) -> dict[str, str]:
    """Resolve only server-registered architecture identities for policy."""
    resolved = {}
    for value in model_types or ():
        model_type = str(value or "").strip()
        if not model_type:
            continue
        try:
            architecture = str(wgp.get_base_model_type(model_type) or "")
        except Exception:
            architecture = ""
        if architecture:
            resolved[model_type] = architecture
    return resolved


def _require_h3_legal_execution(model_types) -> None:
    """Project the source-owned H3 policy through an ordinary HTTP denial."""
    requested = tuple(
        str(value or "").strip()
        for value in (model_types or ())
        if str(value or "").strip()
    )
    try:
        require_h3_execution_allowed(
            requested,
            model_defs=wgp.models_def,
            architectures=_h3_registered_architectures(requested),
            services=wgp.server_config.get("services", {}),
        )
    except H3LegalAccessError as error:
        raise HTTPException(status_code=451, detail=str(error)) from error


def _h3_job_model_types(job: dict) -> tuple[str, ...]:
    """Collect executable model identities without inspecting creative data."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    values = [
        job.get("model_type"), params.get("model_type"),
        params.get("video_model"), params.get("image_model"),
        params.get("image_creator_model"), params.get("image_editor_model"),
    ]
    long_plan = params.get("_h3_longform")
    if isinstance(long_plan, dict):
        segment_models = long_plan.get("segment_models")
        if isinstance(segment_models, list):
            values.extend(
                segment.get("model_type")
                if isinstance(segment, dict) else segment
                for segment in segment_models
            )
    return tuple(
        dict.fromkeys(
            str(value or "").strip() for value in values
            if str(value or "").strip()
        )
    )


def _hold_h3_job_for_legal_access(job: dict) -> bool:
    """Park executable H3 work without consuming an execution/retry attempt."""
    updates = {
        "status": "queued",
        "queue_held": True,
        "recovery_state": "blocked",
        "reruns_denoise": False,
        "message": "MiniMax H3 needs a separate written license",
        "error": None,
        "_recovery_reason_code": "h3_legal_access_required",
    }
    job.update(updates)
    try:
        return bool(_queue_recovery_checkpoint(job, **updates))
    except Exception:
        # The in-memory hold remains fail-closed. Startup materialization
        # repeats the same legal decision from the durable pre-transition job.
        return False


def _job_uses_registered_h3(job: dict) -> bool:
    for model_type in _h3_job_model_types(job):
        model_def = wgp.get_model_def(model_type)
        if is_registered_h3_family(
            model_type,
            model_def=model_def if isinstance(model_def, dict) else None,
            architecture=_h3_registered_architectures((model_type,)).get(
                model_type,
            ),
        ):
            return True
    return False


def _require_remote_visible_job_models(job: dict) -> None:
    """Fail closed if a remote-origin job could load a hidden checkpoint."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    requested = {
        str(value).strip()
        for value in (
            job.get("model_type"), params.get("model_type"),
            params.get("video_model"), params.get("image_model"),
            params.get("image_creator_model"),
            params.get("image_editor_model"),
        )
        if str(value or "").strip()
    }
    longform = params.get("_h3_longform")
    if isinstance(longform, dict):
        for segment in longform.get("segment_models") or ():
            value = segment.get("model_type") if isinstance(segment, dict) else segment
            if str(value or "").strip():
                requested.add(str(value).strip())
    if "minimax_music3" in requested:
        raise HTTPException(status_code=404, detail="Model not found")
    if not bool(job.get("source_remote")):
        return
    visibility = _model_visibility_response()
    allowed = (
        set(visibility.get("enabled_models") or ())
        if visibility.get("configured") else set()
    )
    if any(model_type not in allowed for model_type in requested):
        raise HTTPException(status_code=404, detail="Model not found")


def _job_model_term_ids(job: dict) -> list[str]:
    """Project registered model IDs only; never inspect request content."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    requested = []

    def add(value) -> None:
        model_type = str(value or "").strip()
        if model_type and model_type not in requested:
            requested.append(model_type)

    for value in (
        job.get("model_type"), params.get("model_type"),
        params.get("video_model"), params.get("image_model"),
        params.get("image_creator_model"), params.get("image_editor_model"),
        params.get("editor_model_type"),
    ):
        add(value)
    reference_pack = params.get("reference_pack")
    if isinstance(reference_pack, dict):
        for key in (
            "generation_model", "editor_model", "model_type",
            "editor_model_type",
        ):
            add(reference_pack.get(key))
        review = reference_pack.get("review")
        if isinstance(review, dict):
            add(review.get("resolved_model"))
        operation_routing = reference_pack.get("operation_routing")
        if isinstance(operation_routing, dict):
            operations = operation_routing.get("operations")
            if isinstance(operations, dict):
                for route in operations.values():
                    if isinstance(route, dict):
                        add(route.get("resolved_model"))
        elif isinstance(operation_routing, (list, tuple)):
            for route in operation_routing:
                if isinstance(route, dict):
                    add(route.get("resolved_model"))
    longform = params.get("_h3_longform")
    if isinstance(longform, dict):
        for segment in longform.get("segment_models") or ():
            add(segment.get("model_type") if isinstance(segment, dict) else segment)
    return requested


def _require_model_recipe_terms(model_types) -> None:
    """Fail closed on exact server recipe metadata, never generation data."""
    from services.model_terms import (
        ModelTermsContractError,
        ModelTermsRequiredError,
        require_model_terms,
    )

    services = wgp.server_config.get("services", {})
    for model_type in model_types or ():
        try:
            require_model_terms(services, model_type, wgp.models_def)
        except (ModelTermsContractError, ModelTermsRequiredError) as error:
            raise HTTPException(status_code=409, detail=str(error)) from error


def _require_job_model_recipe_terms(job: dict) -> None:
    _require_model_recipe_terms(_job_model_term_ids(job))


class ModelDownloadUnavailableError(RuntimeError):
    """Raised before generic download work for manual-only recipes."""


def _public_model_availability(
    model_type: str,
    model_def: dict | None,
    model_defs=None,
) -> dict:
    """Project explicit recursive recipe policy into the public catalog."""
    from services.model_terms import model_availability_policy

    definitions = model_defs if isinstance(model_defs, dict) else {
        model_type: model_def if isinstance(model_def, dict) else {},
    }
    return model_availability_policy(model_type, definitions)


def _public_manual_installation_manifest(model_def):
    """Project one exact, token-free manual artifact recipe to the catalog."""
    def safe_public_url(value, *, path, expected_query):
        if not isinstance(value, str) or len(value) > 2_048:
            return False
        try:
            parsed = urlsplit(value)
            query = parse_qsl(parsed.query, keep_blank_values=True)
        except (TypeError, ValueError):
            return False
        return bool(
            parsed.scheme == "https"
            and parsed.netloc == "civitai.com"
            and parsed.username is None
            and parsed.password is None
            and parsed.path == path
            and not parsed.fragment
            and len(query) == len(expected_query)
            and dict(query) == expected_query
        )

    if (
        not isinstance(model_def, dict)
        or model_def.get("manual_installation_ready") is not True
        or model_def.get("downloadable") is not False
    ):
        return None
    provenance = model_def.get("artifact_provenance")
    checkpoint = (
        provenance.get("checkpoint") if isinstance(provenance, dict) else None
    )
    if not isinstance(checkpoint, dict):
        return None
    filename = checkpoint.get("filename")
    size_bytes = checkpoint.get("size_bytes")
    sha256 = checkpoint.get("sha256")
    source_url = checkpoint.get("source_url")
    download_url = checkpoint.get("download_url")
    model_id = checkpoint.get("model_id")
    version_id = checkpoint.get("version_id")
    precision = checkpoint.get("precision")
    declared_urls = model_def.get("URLs")
    # Civitai's authoritative PornMaster V4 artifact URL is queryless. Keep
    # that exception bound to the complete registered artifact identity so a
    # lookalike recipe cannot weaken the normal exact selector requirement.
    pornmaster_queryless_download = bool(
        checkpoint.get("artifact_kind") == "exact_family_tune"
        and checkpoint.get("creator") == "iamddtla"
        and model_id == 2382648
        and version_id == 2973304
        and checkpoint.get("file_id") is None
        and filename == "pornmasterFlux2Klein_v4TurboFp8.safetensors"
        and size_bytes == 9433104872
        and isinstance(sha256, str)
        and sha256.casefold()
        == "e90eeb50140a10806341b7521c340214c6f76cec2f8f8dae7a443c5806072df7"
        and precision == "fp8"
        and download_url
        == "https://civitai.com/api/download/models/2973304"
    )
    if (
        checkpoint.get("provider") != "civitai"
        or not isinstance(filename, str)
        or not filename
        or os.path.basename(filename) != filename
        or not isinstance(size_bytes, int)
        or isinstance(size_bytes, bool)
        or size_bytes <= 0
        or not isinstance(sha256, str)
        or re.fullmatch(r"[0-9A-Fa-f]{64}", sha256) is None
        or isinstance(model_id, bool)
        or not isinstance(model_id, int)
        or model_id <= 0
        or isinstance(version_id, bool)
        or not isinstance(version_id, int)
        or version_id <= 0
        or not isinstance(precision, str)
        or re.fullmatch(r"[A-Za-z0-9._+-]{1,32}", precision) is None
        or not safe_public_url(
            source_url,
            path=f"/models/{model_id}",
            expected_query={"modelVersionId": str(version_id)},
        )
        or not safe_public_url(
            download_url,
            path=f"/api/download/models/{version_id}",
            expected_query=(
                {}
                if pornmaster_queryless_download
                else {
                    "type": "Diffusion Model",
                    "format": "SafeTensor",
                    "fp": precision,
                }
            ),
        )
        or not isinstance(declared_urls, list)
        or filename not in declared_urls
        or checkpoint.get("download_policy") != "manual_hash_verified_only"
        or checkpoint.get("loader_auto_download") is not False
    ):
        return None
    return {
        "filename": filename,
        "size_bytes": size_bytes,
        "sha256": sha256.lower(),
        "source_url": source_url,
        "download_url": download_url,
        "destination_hint": "app/ckpts",
        "local_verification_required": True,
    }


def _require_model_download_available(
    model_type: str,
    model_def: dict,
    model_defs=None,
) -> None:
    """Reject manual-only recipes without updater, network, or thread work."""
    if not isinstance(model_def, dict) or (
        _public_model_availability(
            model_type,
            model_def,
            model_defs,
        )["downloadable"] is not True
    ):
        raise ModelDownloadUnavailableError(
            f"Model recipe '{model_type}' requires manual installation."
        )


