@api.get("/api/v1/models")
def list_models(request: Request):
    """List available model families and model types."""
    from services.director_model_compat import assess_director_model
    from services.model_terms import (
        model_availability_policy,
        model_terms_manifest_valid,
        model_terms_statuses,
    )

    remote_visible = _remote_visible_model_ids(request)

    # Models
    models = []
    for mt in wgp.displayed_model_types:
        # Reserved for the local-only informational projection below.  A
        # registry/plugin collision must never turn it into a WGP checkpoint.
        if mt == "minimax_music3":
            continue
        if remote_visible is not None and mt not in remote_visible:
            continue
        md = wgp.get_model_def(mt)
        if md is None:
            continue
        # Exact creator-term recipes remain absent from every catalog until
        # their immutable public source and enforced term graph agree.
        if not model_terms_manifest_valid(mt, wgp.models_def):
            continue
        _versioned_model_updater.apply_recorded(mt, md)
        _versioned_model_updater.apply_recorded_components(mt, md)
        family = wgp.get_model_family(mt, for_ui=True)
        architecture = wgp.get_base_model_type(mt)
        try:
            director = assess_director_model(
                mt,
                md,
                family=family,
                architecture=architecture,
            )
        except Exception:
            # A malformed optional model definition must not take down the
            # catalog or expose its internal value through the response.
            director = assess_director_model(
                mt,
                None,
                family=family,
                architecture=architecture,
            )
        model_terms = model_terms_statuses({}, mt, wgp.models_def)
        legal_availability = h3_public_availability(
            mt,
            model_def=md,
            architecture=architecture,
            services=wgp.server_config.get("services", {}),
        )
        manual_verification_required = False
        manual_required = getattr(
            wgp, "manual_checkpoint_integrity_required", None,
        )
        manual_ready = getattr(
            wgp, "manual_checkpoint_integrity_ready", None,
        )
        if callable(manual_required):
            manual_verification_required = bool(
                manual_required(mt, md, wgp.models_def)
            )
        manual_installation = _public_manual_installation_manifest(md)
        models.append({
            "model_type": mt,
            "name": md.get("name", mt),
            "description": md.get("description"),
            "selector_help": md.get("selector_help"),
            "lora_compatibility_note": md.get("lora_compatibility_note"),
            "family": family,
            "architecture": architecture,
            "is_i2v": wgp.test_class_i2v(mt),
            "is_t2v": wgp.test_class_t2v(mt),
            "guidance_max_phases": md.get("guidance_max_phases", 1),
            "fps": md.get("fps", 16),
            "supports_end_frame": "E" in md.get("image_prompt_types_allowed", ""),
            "supports_audio": bool(md.get("any_audio_prompt", False) or md.get("returns_audio", False)),
            "supports_audio_input": bool(md.get("any_audio_prompt", False)),
            "generates_audio": bool(md.get("returns_audio", False)),
            "supports_ref_images": bool(md.get("image_ref_choices")),
            "image_outputs": bool(md.get("image_outputs", False)),
            "director": director,
            "is_downloaded": _check_model_downloaded(mt),
            **model_availability_policy(mt, wgp.models_def),
            **legal_availability,
            "supported_operations": [
                operation
                for operation in (
                    (md.get("capability_recipe") or {}).get("operations", [])
                    if isinstance(md.get("capability_recipe"), dict) else []
                )
                if isinstance(operation, str)
            ],
            "automatic_routing": md.get("automatic_routing") is True,
            "verified": md.get("verified") is True,
            "default_for_operations": [
                operation for operation in md.get("default_for_operations", [])
                if isinstance(operation, str)
            ] if isinstance(md.get("default_for_operations"), list) else [],
            "revenue_eligible": (
                md.get("revenue_eligible")
                if type(md.get("revenue_eligible")) is bool else None
            ),
            "fine_tuning_eligible": (
                md.get("fine_tuning_eligible")
                if type(md.get("fine_tuning_eligible")) is bool else None
            ),
            "derivative_tooling": (
                md.get("derivative_tooling")
                if type(md.get("derivative_tooling")) is bool else None
            ),
            "manual_checkpoint_verification_required": manual_verification_required,
            "manual_checkpoint_verified": (
                bool(manual_ready(mt, md, wgp.models_def))
                if manual_verification_required and callable(manual_ready)
                else False
            ),
            **(
                {"manual_installation": manual_installation}
                if manual_installation is not None else {}
            ),
            # Upstream descriptive metadata retained for catalog compatibility.
            # It does not gate visibility, execution, or publication.
            "nsfw_only": bool(md.get("nsfw_only", False)),
            "update_status": str(_versioned_model_update_status.get(mt, {}).get("status") or (
                "versioned" if isinstance(md.get("model_update"), dict) else "pinned"
            )),
            # Static server-owned recipe/license metadata. Acceptance remains
            # available only through the project-authorized host-terms route.
            "required_host_terms": [
                {
                    key: requirement[key]
                    for key in (
                        "term", "version", "title", "license_url",
                        "review_mode", "notice",
                    )
                }
                for requirement in model_terms
            ],
        })

    # Music 3 is not a WGP checkpoint and has no execution path in this slice.
    # Keep its server-owned informational projection strictly local even if a
    # stale remote whitelist happens to contain the virtual identifier.
    if remote_visible is None:
        music3_catalog_factory = globals().get(
            "_music3_virtual_catalog_model",
        )
        if callable(music3_catalog_factory):
            models.append(music3_catalog_factory())

    visible_families = {model["family"] for model in models}
    families = []
    for fid, (order, label) in wgp.families_infos.items():
        if fid == "unknown" or (
            remote_visible is not None and fid not in visible_families
        ):
            continue
        families.append({"id": fid, "label": label, "order": order})
    families.sort(key=lambda family: family["order"])
    return {"families": families, "models": models}


_MODEL_VISIBILITY_CONFIG_KEY = "maestro_model_visibility"
_MODEL_VISIBILITY_WRITE_LOCK = threading.RLock()


def _normalize_model_visibility_ids(values):
    """Return a stable, de-duplicated list of persisted model identifiers."""
    if not isinstance(values, list):
        raise ValueError("Model visibility must be a list.")
    normalized = []
    seen = set()
    for value in values:
        if not isinstance(value, str):
            raise ValueError("Model visibility entries must be strings.")
        model_type = value.strip()
        if not model_type or model_type in seen:
            continue
        # This virtual entry is informational only.  Filtering here removes
        # both new writes and legacy persisted attempts to enable it.
        if model_type == "minimax_music3":
            continue
        if len(model_type) > 200:
            raise ValueError("A model identifier is too long.")
        seen.add(model_type)
        normalized.append(model_type)
    if len(normalized) > 5000:
        raise ValueError("Too many model visibility entries.")
    return normalized


def _model_visibility_response():
    raw = wgp.server_config.get(_MODEL_VISIBILITY_CONFIG_KEY)
    configured = isinstance(raw, dict) and isinstance(
        raw.get("enabled_models"), list,
    )
    if not configured:
        return {
            "configured": False,
            "enabled_models": [],
            "defaults_version": 0,
        }
    try:
        enabled_models = _normalize_model_visibility_ids(
            raw.get("enabled_models", []),
        )
    except ValueError:
        return {
            "configured": False,
            "enabled_models": [],
            "defaults_version": 0,
        }
    try:
        defaults_version = max(0, int(raw.get("defaults_version", 0)))
    except (TypeError, ValueError):
        defaults_version = 0
    return {
        "configured": True,
        "enabled_models": enabled_models,
        "defaults_version": defaults_version,
    }


def _persist_model_visibility_config():
    """Atomically persist visibility across Pinokio's changing UI ports."""
    config_path = os.path.abspath(wgp.server_config_filename)
    temp_path = (
        f"{config_path}.{os.getpid()}.{threading.get_ident()}.tmp"
    )
    with _MODEL_VISIBILITY_WRITE_LOCK:
        try:
            with open(temp_path, "w", encoding="utf-8") as handle:
                json.dump(wgp.server_config, handle, indent=4)
            os.replace(temp_path, config_path)
        finally:
            if os.path.isfile(temp_path):
                try:
                    os.remove(temp_path)
                except OSError:
                    pass


@api.get("/api/v1/model-visibility")
def get_model_visibility(request: Request):
    """Return the server-persisted model selector whitelist."""
    response = _model_visibility_response()
    return response


@api.put("/api/v1/model-visibility")
async def update_model_visibility(request: Request):
    """Persist model visibility independently of the browser's origin."""
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(
            status_code=400,
            detail="Model visibility payload must be an object.",
        )
    try:
        enabled_models = _normalize_model_visibility_ids(
            body.get("enabled_models"),
        )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    try:
        defaults_version = max(0, int(body.get("defaults_version", 0)))
    except (TypeError, ValueError) as error:
        raise HTTPException(
            status_code=400,
            detail="defaults_version must be an integer.",
        ) from error

    # Keep legacy enabled identifiers readable, but do not let a visibility
    # write newly opt a legally blocked H3 recipe back into the selector.
    previous_enabled = set(_model_visibility_response()["enabled_models"])
    newly_enabled = [
        model_type for model_type in enabled_models
        if model_type not in previous_enabled
    ]
    _require_h3_legal_execution(newly_enabled)

    with _MODEL_VISIBILITY_WRITE_LOCK:
        wgp.server_config[_MODEL_VISIBILITY_CONFIG_KEY] = {
            "enabled_models": enabled_models,
            "defaults_version": defaults_version,
        }
        _persist_model_visibility_config()
        return _model_visibility_response()


@api.get("/api/v1/models/{model_type}/debug")
def debug_model(model_type: str):
    """Debug: show raw model definition and download check."""
    if model_type == "minimax_music3":
        return {"error": "Model not found"}
    md = wgp.get_model_def(model_type)
    if not md:
        return {"error": "Model not found"}
    # Collect keys and sample values (avoid huge nested objects)
    keys_info = {}
    for k, v in md.items():
        if isinstance(v, (str, int, float, bool)):
            keys_info[k] = v
        elif isinstance(v, list):
            keys_info[k] = f"[list len={len(v)}] {str(v[:2])[:200]}"
        elif isinstance(v, dict):
            keys_info[k] = f"[dict keys={list(v.keys())[:10]}]"
        else:
            keys_info[k] = f"[{type(v).__name__}]"
    return {
        "model_type": model_type,
        "keys": keys_info,
        "is_downloaded": _check_model_downloaded(model_type),
        "ckpts_dir": wgp.fl.get_download_location() if hasattr(wgp.fl, 'get_download_location') else "unknown",
    }


@api.delete("/api/v1/models/{model_type}")
def delete_model(model_type: str):
    """Delete a model's checkpoint files from disk."""
    if model_type == "minimax_music3":
        return JSONResponse({"error": "Model not found"}, status_code=404)
    md = wgp.get_model_def(model_type)
    if not md:
        return JSONResponse({"error": "Model not found"}, status_code=404)

    # Same group resolution as _check_model_downloaded, restricted to files
    # this entry owns — a finetune's delete removes its modules but leaves a
    # shared base transformer for the base model's own delete button.
    filenames = []
    for group in _model_weight_groups(model_type, owned_only=True):
        filenames.extend(_variant_group_filenames(group))
    deleted = []
    skipped_linked = []
    errors = []
    for filename in filenames:
        filepath = wgp.fl.locate_file(filename, error_if_none=False)
        if filepath and os.path.isfile(filepath):
            # locate_file also finds checkpoints in linked (read-only) model
            # folders — deleting those would break the OTHER install. Skip
            # them and tell the UI why the model still shows as available.
            if wgp.fl.is_protected_path(filepath):
                skipped_linked.append(filename)
                print(f"[Models] Skipped delete of linked checkpoint: {filepath}")
                continue
            try:
                os.remove(filepath)
                deleted.append(filename)
                print(f"[Models] Deleted checkpoint: {filepath}")
            except Exception as e:
                errors.append(f"{filename}: {e}")
    if errors:
        return JSONResponse({"deleted": deleted, "skipped_linked": skipped_linked, "errors": errors}, status_code=207)
    return {"deleted": deleted, "skipped_linked": skipped_linked, "model_type": model_type}


# ── Model pre-download ──────────────────────────────────────────────────
# Backs the click-to-download icon in Settings → System → Enabled Models.
# Fetches everything a generation would need (transformer + second-stage +
# modules + shared assets + text encoder) without occupying the GPU, so
# the first generation starts instantly. Progress reaches the UI through
# the existing /api/v1/downloads/active feed (safe_download's tqdm hook).
_model_downloads: dict = {}
_model_downloads_lock = threading.Lock()


@api.post("/api/v1/models/{model_type}/verify-manual-checkpoint")
def verify_manual_checkpoint(model_type: str, request: Request):
    """Explicitly hash one registered manual artifact on the local host."""
    if (
        _request_is_cloudflare_remote(request)
        or not _runtime_share_registration_is_local(request)
    ):
        raise HTTPException(
            status_code=403,
            detail="Manual checkpoint verification is available locally only",
        )
    if model_type == "minimax_music3":
        raise HTTPException(status_code=404, detail="Model not found")
    model_def = wgp.get_model_def(model_type)
    if not isinstance(model_def, dict):
        raise HTTPException(status_code=404, detail="Model not found")
    _require_h3_legal_execution([model_type])
    _require_model_recipe_terms([model_type])
    availability = _public_model_availability(
        model_type, model_def, wgp.models_def,
    )
    if (
        availability["downloadable"] is not False
        or availability["manual_installation_ready"] is not True
        or not wgp.manual_checkpoint_integrity_required(
            model_type, model_def, wgp.models_def,
        )
    ):
        raise HTTPException(
            status_code=409,
            detail="This model has no supported manual verification contract",
        )
    try:
        wgp.verify_manual_checkpoint_integrity(
            model_type, model_def, wgp.models_def,
        )
    except RuntimeError as error:
        raise HTTPException(
            status_code=409,
            detail=(
                "Manual checkpoint verification failed. Confirm the exact "
                "published filename, byte size, and SHA-256."
            ),
        ) from error
    return {
        "status": "verified",
        "model_type": model_type,
        "manual_checkpoint_verified": True,
        "is_downloaded": _check_model_downloaded(model_type),
    }


def _download_model_files(model_type: str):
    """Resolve and fetch every file load_models() would download.

    Mirrors the file-resolution block at the top of wgp.load_models()
    (wgp.py:4041-4143) — keep the two in sync.
    """
    if model_type == "minimax_music3":
        raise ModelDownloadUnavailableError(
            "Music 3 is not a WGP checkpoint."
        )
    # Recheck legal access in the worker before updater metadata, network
    # access, or any model file mutation.
    _require_h3_legal_execution([model_type])
    _require_model_recipe_terms([model_type])
    model_def = wgp.get_model_def(model_type)
    _require_model_download_available(model_type, model_def, wgp.models_def)
    update_result = _ensure_versioned_model_current(model_type, force=True)
    quantization = wgp.transformer_quantization
    dtype_policy = wgp.transformer_dtype_policy
    transformer_dtype = wgp.get_transformer_dtype(model_type, dtype_policy)

    model_file_list = [wgp.get_model_filename(model_type=model_type, quantization=quantization, dtype_policy=dtype_policy)]
    source_type_list = [0]
    submodel_no_list = [1]
    if "URLs2" in model_def:
        model_file_list.append(wgp.get_model_filename(model_type=model_type, quantization=quantization, dtype_policy=dtype_policy, submodel_no=2))
        source_type_list.append(0)
        submodel_no_list.append(2)
    modules = wgp.get_model_recursive_prop(model_type, "modules", return_list=True)
    modules = [wgp.get_model_recursive_prop(module, "modules", sub_prop_name="_list", return_list=True) if isinstance(module, str) else module for module in modules]
    for module_type in modules:
        if isinstance(module_type, dict):
            for urls_key, submodel_no in (("URLs", 1), ("URLs2", 2)):
                urls = module_type.get(urls_key, None)
                if urls is None:
                    raise Exception(f"No {urls_key} defined for Module {module_type}")
                model_file_list.append(wgp.get_model_filename(model_type, quantization, transformer_dtype, URLs=urls))
                source_type_list.append(1)
                submodel_no_list.append(submodel_no)
        else:
            model_file_list.append(wgp.get_model_filename(model_type, quantization, transformer_dtype, module_type=module_type))
            source_type_list.append(1)
            submodel_no_list.append(0)

    for filename, source_type, submodel_no in zip(model_file_list, source_type_list, submodel_no_list):
        if len(filename) == 0:
            continue
        wgp.download_models(filename, model_type, source_type, submodel_no)

    text_encoder_URLs = wgp.get_model_recursive_prop(model_type, "text_encoder_URLs", return_list=True)
    if text_encoder_URLs is not None:
        te_quant = (model_def.get("text_encoder_quantization", None) if model_def else None) or wgp.text_encoder_quantization
        text_encoder_filename = wgp.get_model_filename(model_type=model_type, quantization=te_quant, dtype_policy=dtype_policy, URLs=text_encoder_URLs)
        if text_encoder_filename is not None and len(text_encoder_filename):
            text_encoder_folder = model_def.get("text_encoder_folder", None)
            wgp.download_models(text_encoder_filename, model_type, 2, -1, force_path=text_encoder_folder)
            if wgp.get_local_model_filename(text_encoder_filename, extra_paths=text_encoder_folder) is None:
                raise Exception(f"Text encoder '{os.path.basename(text_encoder_filename)}' could not be located after download.")

    if not _check_model_downloaded(model_type):
        raise Exception("Download finished but the checkpoint could not be located — check disk space and earlier terminal output.")
    _versioned_model_updater.finalize_download(
        model_type,
        model_def,
        update_result.get("candidate") if isinstance(update_result, dict) else None,
    )
    component_candidates = {
        component_id: value.get("candidate")
        for component_id, value in (update_result.get("components") or {}).items()
        if isinstance(value, dict) and isinstance(value.get("candidate"), dict)
    }
    _versioned_model_updater.finalize_component_downloads(
        model_type, model_def, component_candidates,
    )


@api.post("/api/v1/models/{model_type}/download")
def download_model(model_type: str, request: Request, workspace: str = ""):
    """Start downloading a model's files in the background."""
    def _worker():
        try:
            _download_model_files(model_type)
            _model_downloads[model_type] = {"status": "completed", "error": None, "started": _model_downloads[model_type]["started"]}
            print(f"[Models] Pre-download complete: {model_type}")
        except Exception as e:
            traceback.print_exc()
            _model_downloads[model_type] = {"status": "failed", "error": str(e), "started": _model_downloads[model_type]["started"]}
            print(f"[Models] Pre-download FAILED for {model_type}: {e}")

    selected = _request_project_workspace(request, workspace)
    with _workspace_lifecycle_lock:
        _require_host_terms_project_access(request, selected)
        _require_remote_visible_models(request, [model_type])
        md = wgp.get_model_def(model_type)
        if not md:
            return JSONResponse({"error": "Model not found"}, status_code=404)
        # Authority and exact host acceptance precede registry mutation,
        # thread creation, updater checks, or any weight network activity.
        _require_h3_legal_execution([model_type])
        _require_model_recipe_terms([model_type])
        try:
            _require_model_download_available(model_type, md, wgp.models_def)
        except ModelDownloadUnavailableError as error:
            raise HTTPException(status_code=409, detail=str(error)) from error
        with _model_downloads_lock:
            entry = _model_downloads.get(model_type)
            if entry and entry["status"] == "downloading":
                return {"status": "downloading", "model_type": model_type}
            _model_downloads[model_type] = {"status": "downloading", "error": None, "started": time.time()}
        threading.Thread(target=_worker, daemon=True, name=f"model-dl-{model_type}").start()
    return {"status": "downloading", "model_type": model_type}


@api.get("/api/v1/models/downloads/status")
def model_downloads_status(request: Request):
    """Status of model pre-downloads started via POST .../download."""
    remote_visible = _remote_visible_model_ids(request)
    with _model_downloads_lock:
        snapshot = {
            model_type: {
                "status": entry["status"],
                "error": (
                    "Model download failed"
                    if remote_visible is not None and entry.get("error")
                    else entry.get("error")
                ),
            }
            for model_type, entry in _model_downloads.items()
            if remote_visible is None or model_type in remote_visible
        }
    return {"downloads": snapshot}


