@api.get("/api/v1/system/preflight")
def system_preflight():
    """Environment sanity checks surfaced to the UI on startup.

    Catches the three things that otherwise fail deep inside a
    generation with a cryptic traceback: ffmpeg missing (every
    video/audio mux needs it), no CUDA GPU (the pipeline is CUDA-only),
    and low free disk on the output drive (a long Director run writes
    gigabytes). Each check degrades to a warning the UI can show once,
    not a hard failure — the user might genuinely be on a CPU box just
    browsing.
    """
    import shutil as _shutil

    checks = []

    # ffmpeg — hard requirement for muxing/concat/audio.
    ffmpeg_path = _shutil.which("ffmpeg")
    if not ffmpeg_path:
        checks.append({
            "id": "ffmpeg",
            "level": "error",
            "message": "ffmpeg was not found on PATH. Video and audio "
                       "export will fail. Install ffmpeg and restart Maestro.",
        })

    # CUDA — the generation pipeline is NVIDIA-only.
    try:
        import torch as _torch
        if not _torch.cuda.is_available():
            checks.append({
                "id": "cuda",
                "level": "error",
                "message": "No CUDA GPU detected. Maestro's generation "
                           "pipeline requires an NVIDIA GPU; generation will "
                           "not work on this machine.",
            })
    except Exception:
        checks.append({
            "id": "torch",
            "level": "error",
            "message": "PyTorch failed to import — the install may be "
                       "incomplete. Try Reset then Install in Pinokio.",
        })

    # Free disk on the output drive.
    try:
        save_path = wgp.server_config.get("save_path", "outputs")
        probe_dir = save_path if os.path.isdir(save_path) else os.getcwd()
        free_gb = _shutil.disk_usage(probe_dir).free / (1024 ** 3)
        if free_gb < 5:
            checks.append({
                "id": "disk",
                "level": "error",
                "message": f"Only {free_gb:.1f} GB free on the output drive. "
                           "Generation writes large files and will fail soon. "
                           "Free up space.",
            })
        elif free_gb < 20:
            checks.append({
                "id": "disk",
                "level": "warn",
                "message": f"{free_gb:.0f} GB free on the output drive. Model "
                           "downloads and long runs can exhaust this — keep an "
                           "eye on free space.",
            })
    except Exception:
        pass

    return {"ok": not any(c["level"] == "error" for c in checks), "checks": checks}


# ============================================================================
# API Routes: Services config (API keys, LLM settings)
# ============================================================================

def _mask_key(key: str) -> str:
    """Mask an API key for safe display: show first 4 and last 4 chars."""
    if not key or len(key) < 10:
        return "***" if key else ""
    return key[:4] + "..." + key[-4:]


_PUBLIC_LLM_PROVIDERS = {"openai", "anthropic"}


def _llm_default_device() -> str:
    """Default LLM device — CUDA when the system has it, else CPU.

    This is the value returned for `services.llm_device` when the user
    has never explicitly set it in Settings → Services. Previously
    hardcoded to "cpu" which left CUDA-equipped users stuck on CPU
    inference until they noticed the dropdown and flipped it. New
    installs on a CUDA box now get GPU LLM out of the box.

    User who already explicitly set "cpu" keeps "cpu" — the value is
    persisted in wgp_config.json and overrides this default. Same for
    explicit "cuda".
    """
    try:
        if torch.cuda.is_available():
            return "cuda"
    except Exception:
        pass
    return "cpu"


# Default LLM repos — kept in sync with services/llm_service.py. Director and
# other heavy authoring use the 31B model; generic rewrite/image enhancement
# uses the faster Qwen 27B Vision model.
_DEFAULT_LLM_REPO = "MoonRide/gemma-4-31B-it-heretic-ara-GGUF"
_DEFAULT_ENHANCE_LLM_REPO = (
    "Youssofal/Qwen3.6-27B-Abliterated-Heretic-Uncensored-GGUF"
)


@api.get("/api/v1/services-config")
def get_services_config(request: Request):
    """Return services settings with API keys masked."""
    services = wgp.server_config.get("services", {})
    provider = str(services.get("llm_provider", "local") or "local").strip().lower()
    # Enforce: NSFW must be off when using a public provider
    nsfw = services.get("nsfw_mode", False) and provider not in _PUBLIC_LLM_PROVIDERS
    response = {
        "llm_model_id": services.get("llm_model_id", _DEFAULT_LLM_REPO),
        "llm_device": services.get("llm_device", _llm_default_device()),
        "llm_provider": provider,
        "llm_remote_url": services.get("llm_remote_url", ""),
        "enhance_llm_model_id": (
            services.get("enhance_llm_model_id")
            or _DEFAULT_ENHANCE_LLM_REPO
        ),
        "enhance_llm_device": services.get("enhance_llm_device", "cuda"),
        "google_api_key": _mask_key(services.get("google_api_key", "")),
        "google_api_key_set": bool(services.get("google_api_key", "")),
        "openai_api_key": _mask_key(services.get("openai_api_key", "")),
        "openai_api_key_set": bool(services.get("openai_api_key", "")),
        "anthropic_api_key": _mask_key(services.get("anthropic_api_key", "")),
        "anthropic_api_key_set": bool(services.get("anthropic_api_key", "")),
        # Director v2 (layered architecture: structured shot planning,
        # mode-specific renderers, prompt validation) is now the default
        # as of 2026-05-03 after weeks of real-world validation. v1 had
        # a known polish-pass failure mode where smaller LLMs (Gemma 4
        # 4B) would hallucinate dialogue into image_prompts. v2 doesn't
        # exhibit that. Existing users who explicitly set use_director_v2
        # to false (legacy v1) keep that choice; only fresh installs and
        # users who never touched the toggle see the new default.
        "use_director_v2": services.get("use_director_v2", True),
        "nsfw_mode": nsfw,
        # Default flipped from "off" to "third_pass" — Pass 3 polish runs
        # each generated prompt through a model-specific dialect pass after
        # planning, which produces materially better LTX-2 / Flux output
        # than relying on Pass 2 alone with a single hardcoded dialect.
        "director_prompt_polish": services.get("director_prompt_polish", "third_pass"),
        "civitai_api_key": _mask_key(services.get("civitai_api_key", "")),
        "civitai_api_key_set": bool(services.get("civitai_api_key", "")),
        # Voice Reference is a stable, user-facing capability now. Fresh
        # installs expose its controls by default, while an explicitly saved
        # False value remains respected.
        "voice_reference_enabled": services.get("voice_reference_enabled", True),
        "ltx_progressive_pipeline": services.get("ltx_progressive_pipeline", False),
        # Master gate for experimental features. When False (default for
        # fresh installs and a sane "ship-ready" baseline), the Services
        # panel hides external API keys and the Studio prompt enhancer
        # config; the Edit mode picker hides Inpaint. Voice Reference is
        # intentionally independent of this gate.
        "show_experimental": services.get("show_experimental", False),
        # Storage Manager: opt-in gate for removing duplicate files FROM
        # linked installs (the inverse of Reclaim). Default off — deleting
        # from another install is informed-consent territory.
        "storage_allow_linked_removal": services.get("storage_allow_linked_removal", False),
        # Performance auto-tune master switch. When True (default), the
        # Settings → System Performance section collapses to a single
        # "Detected: <hardware> → <profile>" card with all underlying
        # knobs hidden under "Show advanced settings". The auto-tune
        # values are applied at first launch (see wgp._init_default_config)
        # and reapplied if the user clicks "Re-detect". When False, the
        # user has manually configured something — we stop overwriting
        # their choices and show the full advanced UI by default.
        "auto_performance": services.get("auto_performance", True),
        # Multi-shot LoRA mode (Maque IC-LoRA and similar). When True,
        # Pass 2 emits storyboard-format video_prompts for medium-length
        # shots (20-30s), letting the LoRA cut between camera angles
        # inside a single generation. Short reaction shots (≤15s) and
        # long sustained shots (40s+ continuous action — sex acts,
        # climactic confrontations) keep the regular single-camera
        # video_prompt format because internal cuts would break either
        # the punchy timing or the sustained-take feel.
        #
        # Off by default — power-user feature for now. User must have
        # the matching IC-LoRA enabled in their video_loras selection
        # for the storyboard format to actually produce internal cuts;
        # without the LoRA, the storyboard text still renders but as
        # a single-take with no cuts. Future direction: a LoRA
        # capabilities catalog (see docs/project_lora_catalog.md) that
        # auto-enables this mode when a multi-shot-capable LoRA is in
        # the active set.
        "director_multishot_lora_mode": services.get("director_multishot_lora_mode", False),
        # FlashVSR (DiT super-resolution) spatial-upsampling settings.
        # variant: 1=tiny (fast/low-VRAM), 2=full (best quality, uses full VAE),
        # 3=tiny-long (tiny for long videos). topk_ratio 0..4 controls sparse-
        # attention density (higher = more motion fidelity, slower). backend:
        # auto / triton_sparse (bundled) / sparge (optional install, best motion).
        "flashvsr_mode": services.get("flashvsr_mode", 1),
        "flashvsr_topk_ratio": services.get("flashvsr_topk_ratio", 0.0),
        "flashvsr_backend": services.get("flashvsr_backend", "auto"),
    }
    if bool(getattr(request.state, "maestro_remote", False)):
        # Remote Studio needs model clarity, not machine configuration or
        # provider credentials. Keep this response deliberately small.
        return {
            "llm_model_id": response["llm_model_id"],
            "llm_provider": response["llm_provider"],
            "enhance_llm_model_id": response["enhance_llm_model_id"],
            "nsfw_mode": response["nsfw_mode"],
            "voice_reference_enabled": response["voice_reference_enabled"],
            "show_experimental": False,
            "remote_read_only": True,
        }
    return response


def _require_host_terms_project_access(request: Request, workspace: str) -> str:
    """Authorize one known project without creating arbitrary local names."""
    # Even the local default project is lookup-only here. A concurrent delete
    # must fail authorization rather than recreate a directory as a side
    # effect of reading or accepting host terms.
    with _workspace_lifecycle_lock:
        _require_workspace_not_deleting(workspace)
        return _require_project_access(
            request, workspace, existing_only=True,
        )


@api.get("/api/v1/host-terms")
def get_host_terms(request: Request, workspace: str = ""):
    """Return host-wide notice versions after project authorization."""
    selected = _request_project_workspace(request, workspace)
    from services.host_terms import host_terms_status
    with _workspace_lifecycle_lock:
        _require_host_terms_project_access(request, selected)
        with _services_config_lock:
            terms = host_terms_status(wgp.server_config.get("services", {}))
    return {"terms": terms}


@api.post("/api/v1/host-terms/accept")
async def accept_host_terms(request: Request):
    """Record one exact notice version for the host.

    This narrowly authorized mutation is available to any current project
    user, including a password-unlocked remote session.  It grants no project
    or machine-control capability and stores no accepting identity.
    """
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Expected a JSON object")
    workspace = _request_project_workspace(request, body.get("workspace"))
    from services.host_terms import (
        REF2VA_TERM,
        StaleHostTermVersionError,
        UnknownHostTermError,
        accept_host_term,
    )
    try:
        with _workspace_lifecycle_lock:
            _require_host_terms_project_access(request, workspace)
            with _services_config_lock:
                services = copy.deepcopy(wgp.server_config.get("services", {}))
                if not isinstance(services, dict):
                    services = {}
                terms = accept_host_term(
                    services,
                    body.get("term"),
                    body.get("version"),
                )
                staged_config = dict(wgp.server_config)
                staged_config["services"] = services
                _atomic_write_json(wgp.server_config_filename, staged_config)
                wgp.server_config["services"] = services
    except UnknownHostTermError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    except StaleHostTermVersionError as error:
        raise HTTPException(status_code=409, detail=str(error)) from error
    if (
        body.get("term") == REF2VA_TERM
        and bool((terms.get(REF2VA_TERM) or {}).get("accepted"))
    ):
        _reconcile_ref2va_waiting_plan_reviews(
            request=request, workspace=workspace,
        )
    return {"status": "ok", "terms": terms}


def _raise_account_http_error(error: AccountAuthError) -> None:
    statuses = {
        "account_store_unavailable": 503,
        "account_store_capacity": 507,
        "authentication_required": 401,
        "invalid_credentials": 401,
        "invalid_recovery": 401,
        "username_unavailable": 409,
        "registration_unavailable": 404,
        "owner_required": 403,
        "reauth_required": 403,
        "rate_limited": 429,
        "bootstrap_complete": 409,
        "invalid_nonce": 409,
        "account_not_found": 404,
        "session_not_found": 404,
    }
    headers = (
        {"Retry-After": str(error.retry_after)} if error.retry_after else None
    )
    raise HTTPException(
        status_code=statuses.get(error.code, 400),
        detail={"code": error.code, "message": str(error)},
        headers=headers,
    ) from error


def _require_account_store(request: Request) -> AccountAuthStore:
    if not _accounts_enabled():
        raise HTTPException(status_code=404, detail="Accounts are not enabled")
    if getattr(request.state, "maestro_account_error", ""):
        _raise_account_http_error(AccountStoreCorruptError())
    store = _account_auth_store()
    if store is None:
        raise HTTPException(status_code=404, detail="Accounts are not enabled")
    return store


def _require_account_principal(request: Request) -> dict:
    principal = getattr(request.state, "maestro_account_principal", None)
    account_session_id = getattr(request.state, "maestro_account_session_id", "")
    if not isinstance(principal, dict) or not account_session_id:
        _raise_account_http_error(AccountAuthError(
            "Authentication is required.", code="authentication_required",
        ))
    return principal


async def _account_request_body(request: Request) -> dict:
    try:
        body = await request.json()
    except (ValueError, TypeError):
        raise HTTPException(status_code=400, detail="Expected a JSON object") from None
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Expected a JSON object")
    return body


def _account_local_bootstrap_allowed(request: Request) -> bool:
    """Require direct loopback and an independently approved exact app origin."""
    if _request_is_cloudflare_remote(request) or not _is_loopback_request_client(request):
        return False
    return _account_exact_origin_allowed(request)


def _account_activation_read_allowed(request: Request) -> bool:
    """Allow a setup-readiness read from this exact direct loopback app."""
    if _request_is_cloudflare_remote(request) or not _is_loopback_request_client(request):
        return False
    approved = _configured_app_origins()
    direct = _canonical_http_origin(str(request.base_url), allow_path=True)
    if direct is None or direct not in approved:
        return False
    request_origins = _request_external_origins(request)
    if not request_origins or any(
        origin not in approved for origin in request_origins
    ):
        return False
    if "origin" in request.headers:
        return _account_exact_origin_allowed(request)
    return True


def _account_request_source(request: Request) -> str:
    """Return the socket peer only; never trust caller-controlled forwarding."""
    client = getattr(request, "client", None)
    host = str(getattr(client, "host", "") or "").strip()
    return host[:256]


def _rotate_account_session(request: Request, account_session_id: str) -> None:
    """Rotate account authority without changing the browser/project principal."""
    request.state.maestro_account_session_cookie_id = account_session_id
    request.state.maestro_clear_account_session_cookie = False
    request.state.maestro_account_session_id = account_session_id
    _attach_account_request_state(
        request, account_session_id,
        remote=bool(getattr(request.state, "maestro_remote", False)),
    )


def _clear_account_session(request: Request) -> None:
    request.state.maestro_account_session_cookie_id = ""
    request.state.maestro_clear_account_session_cookie = True
    request.state.maestro_account_session_id = ""
    _attach_account_request_state(
        request, "",
        remote=bool(getattr(request.state, "maestro_remote", False)),
    )


def _account_activation_context(request: Request) -> dict:
    """Describe account setup readiness without disclosing account existence remotely."""
    if not _accounts_enabled():
        return {
            "activation_state": "disabled",
            "bootstrap_available": False,
        }
    if not _account_bootstrap_enabled():
        return {
            "activation_state": "ready",
            "bootstrap_available": False,
        }
    if not _account_activation_read_allowed(request):
        return {
            "activation_state": "setup_requires_loopback",
            "bootstrap_available": False,
        }
    store = _require_account_store(request)
    try:
        bootstrap_available = not store.has_accounts()
    except AccountAuthError as error:
        _raise_account_http_error(error)
    return {
        "activation_state": (
            "setup_available" if bootstrap_available else "disable_bootstrap"
        ),
        "bootstrap_available": bootstrap_available,
    }


def _public_account_context(request: Request) -> dict:
    principal = getattr(request.state, "maestro_account_principal", None)
    account = None
    if isinstance(principal, dict):
        account = {
            key: principal[key]
            for key in (
                "id", "username", "role", "disabled", "created_at",
                "has_email", "passkey_credentials",
                "passkey_authentication_available",
            )
            if key in principal
        }
    capabilities = sorted(getattr(
        request.state, "maestro_account_capabilities", frozenset(),
    ))
    return {
        "enabled": _accounts_enabled(),
        "authenticated": account is not None,
        "account": account,
        "capabilities": capabilities,
        "reauthenticated": _request_has_recent_account_reauth(request),
        "passkey_authentication_available": False,
        "public_registration_available": _public_registration_available(request),
        **_account_activation_context(request),
    }


@api.get("/api/v1/account/context")
def get_account_context(request: Request):
    return _public_account_context(request)


