# API Routes: Workspaces
# ============================================================================

def _workspace_remember_policy(body: dict) -> str:
    remember = body.get("remember", "session")
    if not isinstance(remember, str) or remember not in PROJECT_UNLOCK_REMEMBER_POLICIES:
        raise HTTPException(
            status_code=400,
            detail="remember must be 'session' or 'device'",
        )
    return remember


def _workspace_access_fields(status) -> dict:
    return {
        "remember_policy": getattr(status, "remember_policy", None),
        "unlock_expires_at": getattr(status, "unlock_expires_at", None),
        "unlock_idle_expires_at": getattr(
            status, "unlock_idle_expires_at", None,
        ),
    }


@api.get("/api/v1/workspaces")
def list_workspaces_endpoint(request: Request):
    """List all workspaces and the active one."""
    remote = bool(getattr(request.state, "maestro_remote", False))
    visible_projects = _account_project_list_identities(request)
    workspaces = []
    for item in _list_workspaces():
        if remote and item["name"] == "default":
            continue
        project_membership = None
        if visible_projects is not None:
            try:
                project_instance = _queue_recovery_existing_project_identity(
                    item["path"],
                )
            except QueueRecoveryAdapterError:
                continue
            project_membership = visible_projects.get(project_instance)
            if project_membership is None:
                continue
        if project_membership is not None:
            entry = {
                "name": item["name"],
                "password_protected": False,
                "unlocked": True,
                "remember_policy": None,
                "unlock_expires_at": None,
                "unlock_idle_expires_at": None,
                "project_role": project_membership["role"],
                "project_permissions": project_membership["permissions"],
            }
        else:
            status = _project_access.status(
                item["name"], item["path"],
                request.state.maestro_session_id, remote,
            )
            entry = {
                "name": item["name"],
                "password_protected": status.protected,
                "unlocked": (
                    status.unlocked
                    and (status.protected if remote else True)
                ),
                **_workspace_access_fields(status),
            }
        # Project names form the remote sign-in directory. Counts are project
        # content and remain hidden until this browser unlocks that project.
        if not remote or entry["unlocked"]:
            entry["file_count"] = item.get("file_count", 0)
        workspaces.append(entry)
    if remote:
        with _remote_active_projects_lock:
            active = _remote_active_projects.get(
                request.state.maestro_session_id, "",
            )
        if active and not any(
            item["name"] == active and item["unlocked"] for item in workspaces
        ):
            active = ""
    else:
        active = _get_active_workspace()
        if visible_projects is not None and not any(
            item["name"] == active for item in workspaces
        ):
            active = ""
    return {
        "workspaces": workspaces,
        "active": active,
    }


@api.put("/api/v1/workspaces/active")
async def set_active_workspace(request: Request):
    """Switch to a different workspace."""
    body = await request.json()
    name = body.get("name", "default")

    # Validate name (alphanumeric, hyphens, underscores)
    import re
    if name != "default" and not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9_-]*$', name):
        raise HTTPException(status_code=400, detail="Invalid workspace name. Use letters, numbers, hyphens, underscores.")
    _require_project_access(request, name, permission="project.open")

    if bool(getattr(request.state, "maestro_remote", False)):
        with _remote_active_projects_lock:
            _remote_active_projects[request.state.maestro_session_id] = name
        return {"status": "ok", "active": name, "remote_session_only": True}

    # Persist the switch; only touch wgp.save_path when idle. If a job is
    # in progress it has locked wgp.save_path to its target workspace —
    # overwriting mid-generation scatters clips across workspaces. The
    # config is saved either way, so the next job or restart picks it up.
    idle = not _active_gen_states
    ws_dir = _persist_active_workspace(name, apply_save_paths=idle)
    if idle:
        print(f"[Workspace] Switched to: {name} ({ws_dir})")
    else:
        print(f"[Workspace] Config switched to: {name} (save_path deferred — generation in progress)")
    return {"status": "ok", "active": name, "path": ws_dir}


@api.post("/api/v1/workspaces")
async def create_workspace(request: Request):
    """Create a new workspace."""
    body = await request.json()
    name = body.get("name", "").strip()
    remote = bool(getattr(request.state, "maestro_remote", False))
    project_account_state = _account_project_access_state()
    account_projects_enforced = project_account_state["enforced"]
    if account_projects_enforced and any(
        key in body for key in ("password", "remember")
    ):
        raise HTTPException(
            status_code=400,
            detail="Project passwords are disabled after account migration",
        )
    password = str(body.get("password") or "")
    remember = (
        "session" if account_projects_enforced
        else _workspace_remember_policy(body)
    )

    if not name:
        raise HTTPException(status_code=400, detail="Workspace name is required")
    if remote and not account_projects_enforced and not password:
        raise HTTPException(
            status_code=400,
            detail="Remote projects require a password",
        )

    import re
    if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9_-]*$', name):
        raise HTTPException(status_code=400, detail="Invalid workspace name. Use letters, numbers, hyphens, underscores.")

    from services.win_safe_files import safe_join_under
    project_account_id = None
    project_membership_store = None
    if project_account_state["state"] in {"active", "needs_attention"}:
        _require_account_store(request)
        project_account_id = _require_account_principal(request)["id"]
        project_membership_store = _account_project_membership_store()
        if project_membership_store is None:
            raise HTTPException(
                status_code=503,
                detail="Project account access is unavailable right now",
            )
    with _workspace_creation_lock:
        base = os.path.realpath(wgp.server_config.get("save_path", "outputs"))
        existing = base if name == "default" else safe_join_under(base, name)
        if existing is None:
            raise HTTPException(status_code=400, detail="Invalid workspace path")
        if os.path.exists(existing):
            # Do not let create act as an alternate password-reset endpoint. A
            # locked project stays locked; an unlocked existing name is a conflict.
            _require_project_access(request, name)
            raise HTTPException(status_code=409, detail="Workspace already exists")

        ws_dir = _workspace_dir(name)
        os.makedirs(ws_dir, exist_ok=True)
        try:
            project_marker = ensure_project_instance_marker(ws_dir)
        except (ValueError, QueueRecoveryAdapterError) as error:
            try:
                os.rmdir(ws_dir)
            except OSError:
                pass
            raise HTTPException(
                status_code=500,
                detail="Project identity could not be initialized",
            ) from error
        if password and not account_projects_enforced:
            try:
                _project_access.set_password(
                    name, ws_dir, request.state.maestro_session_id, password,
                    remember, remote,
                )
            except ValueError as error:
                # Do not leave an unusable empty project behind when password
                # validation fails. The marker was created by this request and
                # is the only permitted entry at this point.
                try:
                    os.remove(os.path.join(ws_dir, ".maestro-project-instance"))
                except OSError:
                    pass
                try:
                    os.rmdir(ws_dir)
                except OSError:
                    pass
                raise HTTPException(status_code=400, detail=str(error)) from error
        if project_membership_store is not None:
            try:
                project_membership_store.bind(
                    project_account_id,
                    "owner",
                    marker=project_marker,
                )
            except ProjectMembershipError as error:
                rollback_errors = []
                try:
                    _project_access.revoke_workspace(name)
                except (OSError, ValueError) as rollback_error:
                    rollback_errors.append(rollback_error)
                from services.win_safe_files import safe_delete_dir
                rollback = safe_delete_dir(ws_dir)
                if not rollback["removed"]:
                    rollback_errors.extend(rollback.get("errors") or [])
                if rollback_errors:
                    raise HTTPException(
                        status_code=500,
                        detail=(
                            "The project could not be added or fully rolled back"
                        ),
                    ) from error
                if isinstance(error, ProjectMembershipConflictError):
                    raise HTTPException(
                        status_code=409,
                        detail="This project could not be added to your account",
                    ) from error
                _raise_project_setup_unavailable(error)

    if remote:
        with _remote_active_projects_lock:
            _remote_active_projects[request.state.maestro_session_id] = name

    return {"status": "ok", "name": name}


def _require_remote_project_mutation_access(
    request: Request,
    name: str,
    workspace_dir: str,
):
    access = _project_access.authorize(
        name, workspace_dir, request.state.maestro_session_id,
        bool(getattr(request.state, "maestro_remote", False)),
    )
    if bool(getattr(request.state, "maestro_remote", False)) and (
        not access.protected or not access.unlocked
    ):
        raise HTTPException(
            status_code=423,
            detail="Remote access requires an unlocked protected project",
        )
    return access


@api.put("/api/v1/workspaces/{name}/password")
async def set_workspace_password(name: str, request: Request):
    account_project_state = _account_project_access_state()
    if account_project_state["enforced"]:
        raise HTTPException(status_code=404, detail="Project not found")
    from services.win_safe_files import is_safe_workspace_name
    if not is_safe_workspace_name(name):
        raise HTTPException(status_code=400, detail="Invalid workspace name")
    remote = bool(getattr(request.state, "maestro_remote", False))
    # A remote password change may protect an existing project, but it must
    # never create or reserve a project name as a side effect of authorization.
    workspace_dir = (
        _existing_workspace_dir(name)
        if remote or account_project_state["enforced"]
        else _workspace_dir(name)
    )
    membership = _require_account_project_permission(
        request,
        workspace_dir,
        "project.lifecycle",
        state=account_project_state,
    )
    if membership is not None:
        return {
            "password_protected": False,
            "unlocked": True,
            "remember_policy": None,
            "unlock_expires_at": None,
            "unlock_idle_expires_at": None,
        }
    current = _require_remote_project_mutation_access(
        request, name, workspace_dir,
    )
    if current.protected and not current.unlocked:
        raise HTTPException(status_code=423, detail="Unlock the project first")
    body = await request.json()
    remember = _workspace_remember_policy(body)
    if (
        remote and not str(body.get("password") or "")
    ):
        raise HTTPException(
            status_code=400,
            detail="Remote projects must remain password protected",
        )
    try:
        status = _project_access.set_password(
            name, workspace_dir, request.state.maestro_session_id,
            body.get("password"),
            remember,
            remote,
        )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    return {
        "password_protected": status.protected,
        "unlocked": status.unlocked,
        **_workspace_access_fields(status),
    }


@api.post("/api/v1/workspaces/{name}/unlock")
async def unlock_workspace(name: str, request: Request):
    if _account_project_access_state()["enforced"]:
        raise HTTPException(status_code=404, detail="Project not found")
    remote = bool(getattr(request.state, "maestro_remote", False))
    if remote and name == "default":
        raise HTTPException(status_code=404, detail="Project not found")
    workspace_dir = _existing_workspace_dir(name)
    membership = _require_account_project_permission(
        request,
        workspace_dir,
        "project.open",
    )
    if membership is not None:
        return {
            "unlocked": True,
            "remember_policy": None,
            "unlock_expires_at": None,
            "unlock_idle_expires_at": None,
        }
    if remote and not _project_access.status(
        name, workspace_dir, request.state.maestro_session_id,
        remote,
    ).protected:
        raise HTTPException(
            status_code=423,
            detail="This project is not enabled for remote access",
        )
    body = await request.json()
    remember = _workspace_remember_policy(body)
    remote = bool(getattr(request.state, "maestro_remote", False))
    if remote:
        retry_after = _project_unlock_limiter.retry_after(
            name, request.state.maestro_session_id,
        )
        if retry_after:
            raise HTTPException(
                status_code=429,
                detail=f"Too many password attempts; try again in {retry_after}s",
                headers={"Retry-After": str(retry_after)},
            )
    if not _project_access.unlock(
        name, workspace_dir, request.state.maestro_session_id,
        str(body.get("password") or ""),
        remember,
        remote,
    ):
        if remote:
            retry_after = _project_unlock_limiter.record_failure(
                name, request.state.maestro_session_id,
            )
            headers = {"Retry-After": str(retry_after)} if retry_after else None
        else:
            headers = None
        raise HTTPException(
            status_code=401, detail="Incorrect project password", headers=headers,
        )
    if remote:
        _project_unlock_limiter.record_success(
            name, request.state.maestro_session_id,
        )
    status = _project_access.status(
        name, workspace_dir, request.state.maestro_session_id, remote,
    )
    return {"unlocked": True, **_workspace_access_fields(status)}


@api.post("/api/v1/workspaces/{name}/lock")
def lock_workspace(name: str, request: Request):
    account_project_state = _account_project_access_state()
    if account_project_state["enforced"]:
        raise HTTPException(status_code=404, detail="Project not found")
    remote = bool(getattr(request.state, "maestro_remote", False))
    locked_count = _project_access.lock(
        name, request.state.maestro_session_id, remote,
    )
    with _remote_active_projects_lock:
        if _remote_active_projects.get(request.state.maestro_session_id) == name:
            _remote_active_projects.pop(request.state.maestro_session_id, None)
    return {"unlocked": False, "locked_count": locked_count}


@api.post("/api/v1/workspaces/lock-all")
def lock_all_workspaces(request: Request):
    if _account_project_access_state()["enforced"]:
        raise HTTPException(status_code=404, detail="Project not found")
    remote = bool(getattr(request.state, "maestro_remote", False))
    locked_count = _project_access.lock_all(
        request.state.maestro_session_id, remote,
    )
    with _remote_active_projects_lock:
        _remote_active_projects.pop(request.state.maestro_session_id, None)
    return {"unlocked": False, "locked_count": locked_count}


def _path_targets_workspace(path_value, workspace_dir: str) -> bool:
    if not path_value:
        return False
    try:
        return os.path.normcase(os.path.realpath(str(path_value))) == os.path.normcase(
            os.path.realpath(workspace_dir)
        )
    except (OSError, TypeError, ValueError):
        return False


def _job_targets_workspace(job: dict, name: str, workspace_dir: str) -> bool:
    if not isinstance(job, dict):
        return False
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    workspace = str(job.get("workspace") or params.get("workspace") or "")
    return workspace == name or _path_targets_workspace(
        job.get("out_dir"), workspace_dir,
    )


def _workspace_has_busy_jobs(name: str, workspace_dir: str) -> bool:
    for job_id, job in list(_jobs.items()):
        if not _job_targets_workspace(job, name, workspace_dir):
            continue
        if job.get("status") in (
            "preparing", "waiting_for_plan_approval", "queued", "running",
        ) or job_id in _active_gen_states:
            return True
    return False


def _workspace_has_busy_director_pipeline(
    name: str,
    workspace_dir: str,
) -> bool:
    try:
        from services import director_pipeline as pipeline_service
    except ImportError:
        return False
    active_statuses = {"queued", "planning", "running", "paused"}
    with pipeline_service._pipeline_lock:
        for pid, pipeline in list(pipeline_service._pipelines.items()):
            if not isinstance(pipeline, dict):
                continue
            targets = (
                str(pipeline.get("workspace") or "default") == name
                or _path_targets_workspace(
                    pipeline.get("out_dir"), workspace_dir,
                )
            )
            if not targets:
                continue
            if (
                pipeline.get("status") in active_statuses
                or pid in pipeline_service._pipeline_threads
                or bool(pipeline_service._pipeline_child_jobs.get(pid))
                or pid in pipeline_service._pipeline_starting
                or pid in pipeline_service._pipeline_operations
                or pid in pipeline_service._pipeline_deleting
            ):
                return True
    return False


@api.delete("/api/v1/workspaces/{name}")
def delete_workspace(name: str, request: Request):
    """Delete a workspace folder and every asset inside it.

    Refused only while work targeting this project is live. Job publication,
    Director admission, and deletion share a lifecycle reservation so a stale
    request cannot resurrect the project after deletion succeeds.
    """
    import re
    if name == "default":
        raise HTTPException(status_code=400, detail="The default workspace is the outputs folder itself and cannot be deleted.")
    if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9_-]*$', name):
        raise HTTPException(status_code=400, detail="Invalid workspace name.")
    base = os.path.realpath(wgp.server_config.get("save_path", "outputs"))
    account_project_state = _account_project_access_state()
    with _workspace_creation_lock:
        lexical = os.path.abspath(os.path.join(base, name))
        # Reject final-component symlinks/junctions even when they resolve to
        # another directory still inside outputs/. Recursive deletion must
        # never follow a project-name alias into a different project.
        if os.path.normcase(os.path.realpath(lexical)) != os.path.normcase(lexical):
            if account_project_state["enforced"]:
                raise HTTPException(status_code=404, detail="Project not found")
            raise HTTPException(status_code=400, detail="Invalid workspace path.")
        ws_dir = _safe_join(base, name)
        if ws_dir is None:
            if account_project_state["enforced"]:
                raise HTTPException(status_code=404, detail="Project not found")
            raise HTTPException(status_code=400, detail="Invalid workspace path.")
        if not os.path.isdir(ws_dir):
            if account_project_state["enforced"]:
                raise HTTPException(status_code=404, detail="Project not found")
            raise HTTPException(status_code=404, detail=f"Workspace not found: {name}")
        membership = _require_account_project_permission(
            request,
            ws_dir,
            "project.delete",
            state=account_project_state,
        )
        if membership is None:
            access = _require_remote_project_mutation_access(
                request, name, ws_dir,
            )
            if not access.unlocked:
                raise HTTPException(
                    status_code=423,
                    detail="Project is password locked",
                )

        with _workspace_lifecycle_lock:
            if name in _workspaces_deleting:
                raise HTTPException(status_code=409, detail="This project is being deleted")
            _workspaces_deleting.add(name)
        deletion_operation_id = None
        membership_store = None
        deletion_finished = False
        deletion_destructive = False
        try:
            with _workspace_lifecycle_lock:
                if _workspace_operations.get(name, 0) > 0:
                    raise HTTPException(
                        status_code=409,
                        detail="This project has an operation in progress. Wait for it to finish before deleting the project.",
                    )
            if _workspace_has_busy_jobs(name, ws_dir):
                raise HTTPException(
                    status_code=409,
                    detail="A generation for this project is queued or running. Wait for it to finish before deleting the project.",
                )
            # Director pipelines can be alive between child generation jobs.
            if _workspace_has_busy_director_pipeline(name, ws_dir):
                raise HTTPException(
                    status_code=409,
                    detail="A Director pipeline for this project is running or paused. Stop it before deleting the project.",
                )

            if membership is not None:
                membership_store = _account_project_membership_store()
                if membership_store is None:
                    raise HTTPException(
                        status_code=503,
                        detail="Project account access is unavailable right now",
                    )
                try:
                    if membership["state"] in {"deleting", "deleted"}:
                        deleting = membership
                    else:
                        deleting = membership_store.begin_deletion(
                            project_instance=membership["project_instance"],
                            expected_revision=membership["revision"],
                        )
                    deletion_operation_id = deleting["deletion"]["operation_id"]
                    deletion_finished = deleting["state"] == "deleted"
                except ProjectMembershipNotFoundError as error:
                    raise HTTPException(
                        status_code=404,
                        detail="Project not found",
                    ) from error
                except ProjectMembershipConflictError as error:
                    raise HTTPException(
                        status_code=409,
                        detail="This project changed. Refresh and try again",
                    ) from error
                except ProjectMembershipError as error:
                    _raise_project_setup_unavailable(error)

            # Revoke before the first destructive project mutation.  If the
            # durable grant/capability stores cannot be updated, the project
            # and its references remain intact; a crash can never leave
            # deleted bytes paired with authority that might revive on reuse.
            deletion_destructive = True
            _project_access.revoke_workspace(name)
            _output_share_manager().revoke_workspace(name)

            # If unrelated work is running, persist the new selection without
            # repointing WGP's process-global save paths underneath that job.
            switched = False
            if _get_active_workspace() == name:
                _persist_active_workspace(
                    "default", apply_save_paths=not bool(_active_gen_states),
                )
                switched = True
                print("[Workspace] Active workspace deleted — switched to default")

            # Reference manifests live outside the output workspace. Remove
            # them before freeing the name so a later creator cannot inherit
            # the previous project's private cards or copied media.
            try:
                _project_asset_store().delete_project(name)
            except Exception as error:
                raise HTTPException(
                    status_code=500,
                    detail="Could not delete the project's protected reference data",
                ) from error

            # Fence the old identity before removing its directory. A crash
            # can then resume cleanup through the still-present marker, while
            # a completed removal can never leave an unfinished membership.
            if (
                membership_store is not None
                and deletion_operation_id is not None
                and not deletion_finished
            ):
                try:
                    membership_store.finish_deletion(
                        deletion_operation_id,
                        project_instance=membership["project_instance"],
                    )
                    deletion_finished = True
                except ProjectMembershipError as error:
                    _raise_project_setup_unavailable(error)

            from services.win_safe_files import safe_delete_dir
            result = safe_delete_dir(ws_dir)
            deletion_destructive = deletion_destructive or bool(result["removed"])
            with _remote_active_projects_lock:
                for session_id, active_name in list(_remote_active_projects.items()):
                    if active_name == name:
                        _remote_active_projects.pop(session_id, None)
            print(f"[Workspace] Deleted '{name}': {result['files_deleted']} files removed, "
                  f"{result['files_deferred']} deferred, dir_removed={result['removed']}")
            return {
                "status": "ok", "name": name,
                "files_deleted": result["files_deleted"], "files_deferred": result["files_deferred"],
                "dir_removed": result["removed"], "switched_to_default": switched, "errors": result["errors"],
            }
        finally:
            if (
                membership_store is not None
                and deletion_operation_id is not None
                and not deletion_finished
                and not deletion_destructive
            ):
                try:
                    membership_store.cancel_deletion(
                        deletion_operation_id,
                        project_instance=membership["project_instance"],
                    )
                except ProjectMembershipError:
                    pass
            with _workspace_lifecycle_lock:
                _workspaces_deleting.discard(name)


# ============================================================================
# API Routes: Project reference cards (characters / settings / items / styles)
# ============================================================================

_project_asset_store_instance = None
_project_asset_store_lock = threading.Lock()
_reference_admission_store_instance = None
_reference_admission_store_lock = threading.Lock()
_blender_candidate_status_lock = threading.RLock()


def _stage_json_replacement(path: str, payload: dict) -> str:
    """Durably stage JSON next to its destination without publishing it."""
    temp = f"{path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temp, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        return temp
    except Exception:
        try:
            os.remove(temp)
        except OSError:
            pass
        raise


def _restore_file_bytes(path: str, content: bytes) -> None:
    """Restore exact prior bytes, with a direct-write fallback for rollback."""
    temp = f"{path}.{uuid.uuid4().hex[:8]}.rollback.tmp"
    try:
        with open(temp, "wb") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        try:
            os.replace(temp, path)
            return
        except OSError:
            # A replace failure may be the reason rollback is running.  The
            # transaction lock keeps peer mutations out while exact prior
            # bytes are restored in place as the last-resort recovery path.
            with open(path, "wb") as handle:
                handle.write(content)
                handle.flush()
                os.fsync(handle.fileno())
    finally:
        try:
            os.remove(temp)
        except OSError:
            pass


def _project_asset_store():
    global _project_asset_store_instance
    if _project_asset_store_instance is None:
        with _project_asset_store_lock:
            if _project_asset_store_instance is None:
                from services.project_assets import ProjectAssetStore
                save_root = os.path.realpath(
                    wgp.server_config.get("save_path", "outputs")
                )
                uploads_root = os.path.realpath(os.path.join(os.getcwd(), "uploads"))
                os.makedirs(save_root, exist_ok=True)
                os.makedirs(uploads_root, exist_ok=True)
                _project_asset_store_instance = ProjectAssetStore(
                    os.path.join(os.getcwd(), "storage", "project-assets"),
                    allowed_source_roots=[save_root, uploads_root],
                )
    return _project_asset_store_instance


def _reference_admission_store():
    """Return the content-free durable Reference admission ledger."""
    global _reference_admission_store_instance
    if _reference_admission_store_instance is None:
        with _reference_admission_store_lock:
            if _reference_admission_store_instance is None:
                _reference_admission_store_instance = ReferenceAdmissionStore(
                    os.path.join(
                        os.getcwd(), "storage", "reference-admission",
                    ),
                    _session_secret(),
                )
    return _reference_admission_store_instance


def _project_asset_error(error):
    from services.project_assets import (
        ProjectAssetNotFoundError,
        ProjectAssetPersistenceError,
    )
    if isinstance(error, HTTPException):
        details = {
            400: "Invalid reference asset request",
            401: "Reference asset access denied",
            403: "Reference asset access denied",
            404: "Reference asset not found",
            409: "Reference asset conflict",
        }
        return HTTPException(
            status_code=error.status_code,
            detail=details.get(
                error.status_code,
                "Reference asset operation failed",
            ),
        )
    if isinstance(error, ProjectAssetNotFoundError):
        return HTTPException(status_code=404, detail="Reference asset not found")
    if isinstance(error, ValueError):
        return HTTPException(status_code=400, detail="Invalid reference asset request")
    if isinstance(error, ProjectAssetPersistenceError):
        return HTTPException(
            status_code=503,
            detail="Reference asset storage is unavailable",
        )
    return HTTPException(status_code=500, detail="Reference asset operation failed")


def _project_asset_provenance(value, *, default: str):
    """Normalize the UI's local-import alias at the HTTP compatibility edge."""
    selected = default if value is None else value
    return "imported" if selected == "local_import" else selected


def _asset_scope(request: Request, project: str):
    _require_project_access(request, project)
    return project, "main"


def _can_access_project_asset_variant(variant: dict, session_id: str) -> bool:
    """Keep unaccepted Blender review media scoped to its creating session."""
    metadata = (
        variant.get("metadata")
        if isinstance(variant.get("metadata"), dict)
        else {}
    )
    if (
        variant.get("variant_type") != "blender_video"
        or metadata.get("tool") != "blender_mcp"
        or variant.get("status") == "kept"
    ):
        return True
    expected = str(metadata.get("review_owner_session_hash") or "")
    if len(expected) != 64 or not session_id:
        return False
    actual = hashlib.sha256(session_id.encode("utf-8")).hexdigest()
    return hmac.compare_digest(expected, actual)


def _public_authorized_project_assets(assets: list[dict], session_id: str) -> list[dict]:
    """Hide owner-only asset media and redact its owner token from manifests."""
    import copy
    public_assets = []
    for source_asset in assets:
        asset = copy.deepcopy(source_asset)
        variants = []
        for variant in asset.get("variants") or []:
            if not _can_access_project_asset_variant(variant, session_id):
                continue
            variant_metadata = variant.get("metadata")
            if isinstance(variant_metadata, dict):
                variant_metadata.pop("private_authored_settings", None)
                variant_metadata.pop("private_reference_request", None)
            review_private = (
                variant.get("variant_type") == "blender_video"
                and variant.get("status") != "kept"
            )
            outputs = []
            for output in variant.get("outputs") or []:
                policy = output.get("metadata") if isinstance(output.get("metadata"), dict) else {}
                output["metadata"] = {
                    **{
                        key: value for key, value in policy.items()
                        if key not in {"owner_session_id"}
                    },
                    **public_output_policy(policy),
                }
                if review_private:
                    output["metadata"]["private"] = True
                outputs.append(output)
            if outputs:
                variant["outputs"] = outputs
                variants.append(variant)
        source_variants = source_asset.get("variants") or []
        asset["variants"] = variants
        # A metadata-only card is shared by the project. A card whose every
        # variant is an unkept, session-owned Blender review stays hidden.
        if not source_variants or variants:
            public_assets.append(asset)
    return public_assets


def _require_project_asset_media_access(
    project_id: str,
    workspace_id: str,
    asset_id: str,
    session_id: str,
    *,
    variant_id: str | None = None,
) -> dict:
    """Deny mutations that would touch another session's Blender review."""
    store = _project_asset_store()
    asset = store.get_asset(project_id, workspace_id, asset_id)
    variants = asset.get("variants") or []
    if variant_id is not None:
        variants = [item for item in variants if item.get("id") == variant_id]
        if not variants:
            raise HTTPException(status_code=404, detail="Reference variant not found")
    for variant in variants:
        if not _can_access_project_asset_variant(variant, session_id):
            raise HTTPException(status_code=404, detail="Reference asset not found")
    return asset


def _project_reference_private_authored_snapshot(variant: dict) -> dict:
    """Validate one durable private snapshot without exposing it publicly."""
    if not isinstance(variant, dict) or variant.get("variant_type") != "reference_pack":
        raise HTTPException(status_code=409, detail="Reference authoring snapshot unavailable")
    metadata = variant.get("metadata")
    reference = metadata.get("reference_pack") if isinstance(metadata, dict) else None
    private = metadata.get("private_authored_settings") if isinstance(metadata, dict) else None
    private_request = (
        metadata.get("private_reference_request")
        if isinstance(metadata, dict) else None
    )
    public_authored = (
        reference.get("authored_settings") if isinstance(reference, dict) else None
    )
    expected_seal = (
        public_authored.get("seal") if isinstance(public_authored, dict) else None
    )
    try:
        from services.reference_sheets import (
            CHARACTER_PROFILE_SCHEMA_VERSION,
            _normalize_character_managed_callout_state,
            normalize_character_profile,
            reference_pack_authored_settings_seal,
        )
        public_style_keys = {"style_present", "style_commitment"}.intersection(
            public_authored if isinstance(public_authored, dict) else {}
        )
        private_has_style = isinstance(private, dict) and "style" in private
        if public_style_keys:
            if (
                public_style_keys != {"style_present", "style_commitment"}
                or type(public_authored.get("style_present")) is not bool
                or not private_has_style
                or not isinstance(private.get("style"), str)
                or bool(private["style"]) != public_authored["style_present"]
            ):
                raise ValueError("private style contract changed")
            expected_style_commitment = _project_reference_private_commitment({
                "kind": "reference_style_v1",
                "value": private["style"],
            })
            if not hmac.compare_digest(
                expected_style_commitment,
                str(public_authored.get("style_commitment") or ""),
            ):
                raise ValueError("private style commitment changed")
        elif private_has_style:
            raise ValueError("private style contract is incomplete")
        private_profile = (
            private.get("character_profile")
            if isinstance(private, dict) else None
        )
        normalized_profile = normalize_character_profile(private_profile)
        private_managed = (
            private.get("managed_character_callouts")
            if isinstance(private, dict) else None
        )
        normalized_managed = _normalize_character_managed_callout_state(
            private_managed,
        )
        public_profile = (
            public_authored.get("character_profile")
            if isinstance(public_authored, dict) else None
        )
        public_managed = (
            public_authored.get("managed_character_callouts")
            if isinstance(public_authored, dict) else None
        )
        if normalized_profile is None:
            if (
                private_managed is not None
                or public_profile is not None
                or public_managed is not None
            ):
                raise ValueError("private character contract changed")
        elif (
            public_profile != normalized_profile.public_metadata()
            or public_managed != (
                normalized_managed.public_metadata(normalized_profile)
                if normalized_managed is not None else {
                    "schema_version": CHARACTER_PROFILE_SCHEMA_VERSION,
                    "active_count": 0,
                    "tombstone_count": 0,
                    "rename_count": 0,
                    "commitments": [],
                }
            )
        ):
            raise ValueError("private character contract changed")
        for selection in (
            private.get("additional_lora_parameters", [])
            if isinstance(private, dict) else []
        ):
            if selection.get("schema_digest") is None:
                continue
            expected_values_digest = _project_reference_snapshot_commitment(
                selection.get("commitment_context"),
                "values",
                selection.get("values"),
            )
            if not hmac.compare_digest(
                expected_values_digest,
                str(selection.get("values_digest") or ""),
            ):
                raise ValueError("private LoRA parameter commitment changed")
        actual_seal = reference_pack_authored_settings_seal(private)
    except (TypeError, ValueError):
        raise HTTPException(
            status_code=409, detail="Reference authoring snapshot unavailable",
        ) from None
    if (
        not isinstance(expected_seal, str)
        or not hmac.compare_digest(actual_seal, expected_seal)
    ):
        raise HTTPException(
            status_code=409, detail="Reference authoring snapshot unavailable",
        )
    snapshot = {
        "seal": actual_seal,
        "type_fields": copy.deepcopy(private["type_fields"]),
        "detail_callouts": copy.deepcopy(private["detail_callouts"]),
    }
    if "style" in private:
        snapshot["style"] = private["style"]
    if "additional_lora_parameters" in private:
        snapshot["additional_lora_parameters"] = copy.deepcopy(
            private["additional_lora_parameters"],
        )
    if "character_profile" in private:
        snapshot["character_profile"] = copy.deepcopy(
            private["character_profile"],
        )
    if "managed_character_callouts" in private:
        snapshot["managed_character_callouts"] = copy.deepcopy(
            private["managed_character_callouts"],
        )
    if private_request is None:
        # V2 records created before the profile feature remain retryable and
        # never acquire inferred character facts or convenience behavior.
        snapshot["explicit_convenience"] = False
    else:
        if not isinstance(private_request, dict) or set(private_request) != {
            "schema_version", "explicit_convenience", "commitment",
        }:
            raise HTTPException(
                status_code=409,
                detail="Reference authoring snapshot unavailable",
            )
        try:
            expected_private_request = _project_reference_private_character_state(
                private.get("character_profile"),
                explicit_convenience=private_request.get(
                    "explicit_convenience"
                ),
            )
        except (TypeError, ValueError):
            raise HTTPException(
                status_code=409,
                detail="Reference authoring snapshot unavailable",
            ) from None
        if (
            private_request.get("schema_version") != 1
            or not hmac.compare_digest(
                str(private_request.get("commitment") or ""),
                expected_private_request["commitment"],
            )
        ):
            raise HTTPException(
                status_code=409,
                detail="Reference authoring snapshot unavailable",
            )
        snapshot["explicit_convenience"] = private_request[
            "explicit_convenience"
        ]
    return snapshot


@api.get(
    "/api/v1/projects/{project}/assets/{asset_id}/variants/{variant_id}/"
    "reference-authoring"
)
def get_project_reference_authoring(
    project: str, asset_id: str, variant_id: str, request: Request,
):
    project_id, workspace_id = _asset_scope(request, project)
    try:
        asset = _require_project_asset_media_access(
            project_id,
            workspace_id,
            asset_id,
            request.state.maestro_session_id,
            variant_id=variant_id,
        )
        variant = next(
            item for item in asset.get("variants") or []
            if item.get("id") == variant_id
        )
        private_snapshot = _project_reference_private_authored_snapshot(
            variant,
        )
        authored_settings = {
            key: copy.deepcopy(value)
            for key, value in private_snapshot.items()
            if key not in {
                "additional_lora_parameters", "managed_character_callouts",
                "character_profile",
            }
        }
        managed_state = private_snapshot.get("managed_character_callouts")
        if isinstance(managed_state, dict):
            managed_ids = {
                item.get("managed_id")
                for item in managed_state.get("entries") or []
                if isinstance(item, dict)
            }
            authored_settings["detail_callouts"] = [
                copy.deepcopy(item)
                for item in private_snapshot["detail_callouts"]
                if not isinstance(item, dict)
                or item.get("custom_id") not in managed_ids
            ]
        character_profile = private_snapshot.get("character_profile")
        if isinstance(character_profile, dict):
            authored_settings["character_profile"] = {
                "gender": character_profile["gender"],
                "age": character_profile["age"],
                "explicit_anatomy": list(
                    character_profile["explicit_anatomy"]
                ),
            }
        response = {
            "schema_version": 2,
            "asset_id": asset_id,
            "variant_id": variant_id,
            "authored_settings": authored_settings,
        }
        if "additional_lora_parameters" in private_snapshot:
            response["additional_loras"] = []
            for item in private_snapshot["additional_lora_parameters"]:
                selection = {
                    "id": item["id"],
                    "multiplier": item["multiplier"],
                    "scope": item["scope"],
                }
                if item.get("schema_digest") is not None:
                    selection.update({
                        "parameter_schema_digest": item["schema_digest"],
                        "parameter_values": {
                            value["id"]: value["value"]
                            for value in item["values"]
                        },
                        "parameter_values_digest": item["values_digest"],
                        "parameter_expansion_digest": item[
                            "expansion_digest"
                        ],
                    })
                response["additional_loras"].append(selection)
        return response
    except Exception as error:
        raise _project_asset_error(error) from error


