def _project_reference_text(value, field, *, limit, default=""):
    if value is None:
        value = default
    if not isinstance(value, str) or len(value) > limit:
        raise HTTPException(
            status_code=400,
            detail=f"{field} must be text of at most {limit} characters",
        )
    return value.strip()


def _project_reference_dimensions(value, field, default):
    if value is None:
        value = default
    if isinstance(value, str):
        match = re.fullmatch(r"\s*(\d{2,4})[xX](\d{2,4})\s*", value)
        value = [int(match.group(1)), int(match.group(2))] if match else None
    if (
        not isinstance(value, (list, tuple))
        or len(value) != 2
        or any(isinstance(item, bool) or not isinstance(item, int) for item in value)
        or any(item < 64 or item > 4096 for item in value)
    ):
        raise HTTPException(
            status_code=400,
            detail=f"{field} must contain two dimensions from 64 through 4096",
        )
    return int(value[0]), int(value[1])


def _project_reference_seal_intelligence_selection(selection):
    """Bind one path/credential-free model-provider choice to a stable token."""
    if not isinstance(selection, dict):
        raise HTTPException(status_code=409, detail="Studio intelligence selection is invalid")
    requested = selection.get("requested_model")
    resolved = selection.get("resolved_model")
    provider = selection.get("resolved_provider")
    if (
        not isinstance(requested, str)
        or not requested
        or len(requested) > 256
        or (
            resolved is not None
            and (not isinstance(resolved, str) or not resolved or len(resolved) > 256)
        )
        or not isinstance(provider, str)
        or not provider
        or len(provider) > 64
    ):
        raise HTTPException(status_code=409, detail="Studio intelligence selection is invalid")
    identity = {
        "requested_model": requested,
        "resolved_model": resolved,
        "resolved_provider": provider,
    }
    revision = hashlib.sha256(json.dumps(
        {"schema_version": 1, **identity},
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")).hexdigest()
    supplied = selection.get("selection_revision")
    if supplied is not None and supplied != revision:
        raise HTTPException(status_code=409, detail="Studio intelligence selection changed")
    return {**identity, "selection_revision": revision}


def _project_reference_intelligence_selection(
    request, *, requested_model, requested_provider, purpose, intent,
):
    """Resolve Studio-local planning/review without inheriting global intent."""
    from services import llm_service

    catalog_builder = globals().get("_llm_model_catalog")

    if purpose == "planning" and requested_model in {"auto", "deterministic"}:
        if requested_model == "deterministic" or intent == "exact_spec":
            return {
                "requested_model": requested_model,
                "resolved_model": "deterministic",
                "resolved_provider": "local",
            }
        status = dict(llm_service.get_status())
        if (
            status.get("provider") == "local"
            and status.get("loaded")
            and isinstance(status.get("model_id"), str)
            and status.get("model_id")
        ):
            return {
                "requested_model": requested_model,
                "resolved_model": status["model_id"],
                "resolved_provider": "local",
            }
        if callable(catalog_builder):
            local_catalog = catalog_builder(request, "local")
            selected = next(
                (
                    item for item in local_catalog
                    if item.get("provider", "local") == "local"
                    and isinstance(item.get("id"), str)
                    and item.get("id")
                ),
                None,
            )
            if selected is not None:
                return {
                    "requested_model": requested_model,
                    "resolved_model": selected["id"],
                    "resolved_provider": "local",
                }
        return {
            "requested_model": requested_model,
            "resolved_model": "deterministic",
            "resolved_provider": "local",
        }
    if purpose == "review" and requested_model in {"auto_local", "off"}:
        if requested_model == "off":
            return {
                "requested_model": "off",
                "resolved_model": None,
                "resolved_provider": "off",
            }
        status = dict(llm_service.get_status())
        if (
            status.get("provider") == "local"
            and status.get("loaded")
            and status.get("vision_available")
            and llm_service.vision_available()
            and isinstance(status.get("model_id"), str)
            and status.get("model_id")
        ):
            return {
                "requested_model": "auto_local",
                "resolved_model": status["model_id"],
                "resolved_provider": "local",
            }
        if callable(catalog_builder):
            local_catalog = catalog_builder(request, "local")
            selected = next(
                (
                    item for item in local_catalog
                    if item.get("provider", "local") == "local"
                    and item.get("vision_capable") is True
                    and isinstance(item.get("id"), str)
                    and item.get("id")
                ),
                None,
            )
            if selected is not None:
                return {
                    "requested_model": "auto_local",
                    "resolved_model": selected["id"],
                    "resolved_provider": "local",
                }
        return {
            "requested_model": "auto_local",
            "resolved_model": None,
            "resolved_provider": "local",
        }

    if not callable(catalog_builder):
        raise HTTPException(status_code=409, detail="Selected Studio intelligence model is unavailable")
    catalog = catalog_builder(request, requested_provider or "")
    selected = next(
        (item for item in catalog if item.get("id") == requested_model),
        None,
    )
    if selected is None:
        raise HTTPException(status_code=409, detail="Selected Studio intelligence model is unavailable")
    provider = str(selected.get("provider") or "local")
    if requested_provider is not None and requested_provider != provider:
        raise HTTPException(status_code=400, detail="Studio intelligence provider does not match model")
    if purpose == "review" and selected.get("vision_capable") is not True:
        raise HTTPException(status_code=409, detail="Reference review requires a vision-capable model")
    # Residency is intentionally not a prequeue requirement. The exact
    # authorized selection is loaded during the durable planning/review job
    # phase and failures are reported on that job rather than freezing Queue.
    return {
        "requested_model": requested_model,
        "resolved_model": requested_model,
        "resolved_provider": provider,
    }


def _project_reference_model_schedule(body, model_type):
    """Resolve steps/guidance from the exact model unless explicitly set."""
    try:
        defaults = dict(wgp.get_default_settings(model_type) or {})
    except Exception as error:
        raise HTTPException(
            status_code=409,
            detail="Reference model defaults are unavailable",
        ) from error
    explicit_steps = body.get("num_inference_steps")
    if explicit_steps is None:
        steps = defaults.get("num_inference_steps", defaults.get("sampling_steps"))
    else:
        steps = explicit_steps
    if (
        isinstance(steps, bool)
        or not isinstance(steps, int)
        or not 1 <= steps <= 200
    ):
        raise HTTPException(status_code=400, detail="num_inference_steps must be from 1 through 200")
    guidance_key = (
        "guidance_scale"
        if "guidance_scale" in defaults
        else "embedded_guidance_scale"
        if "embedded_guidance_scale" in defaults
        else "guidance_scale"
    )
    explicit_guidance = body.get("guidance_scale")
    guidance = (
        defaults.get(guidance_key, 1.0)
        if explicit_guidance is None else explicit_guidance
    )
    if (
        isinstance(guidance, bool)
        or not isinstance(guidance, (int, float))
        or not math.isfinite(float(guidance))
        or not 0 <= float(guidance) <= 30
    ):
        raise HTTPException(status_code=400, detail="guidance_scale must be from 0 through 30")
    return {
        "model": model_type,
        "steps": int(steps),
        "guidance": float(guidance),
        "guidance_key": guidance_key,
        "source": "explicit" if (
            explicit_steps is not None or explicit_guidance is not None
        ) else "model_default",
    }


def _project_reference_operation_routing(
    request, *, content_capability, generation_model, editor_model,
    editor_reference_mode,
):
    """Resolve content-neutral image recipes from an exact verified map only."""
    requested_models = {
        "generation": generation_model,
        "edit": editor_model,
        "repair": editor_model,
        "callout": editor_model,
    }
    routes = []
    for operation in _PROJECT_REFERENCE_OPERATION_ORDER:
        requested_model = requested_models[operation]
        base = {
            "operation": operation,
            "requested_capability": content_capability,
            "requested_model": requested_model,
            "resolved_model": requested_model,
        }
        if content_capability == "standard":
            routes.append({**base, "status": "standard"})
            continue
        candidates = _PROJECT_REFERENCE_VERIFIED_OPERATION_RECIPES.get(operation)
        candidate = (
            candidates.get(requested_model)
            if isinstance(candidates, dict) and requested_model is not None
            else None
        )
        resolved_model = candidate.get("model_type") if isinstance(candidate, dict) else None
        verified = bool(
            isinstance(candidate, dict)
            and set(candidate) == {
                "operation", "base_model", "model_type", "recipe_id",
                "verification_status",
            }
            and candidate.get("operation") == operation
            and candidate.get("base_model") == requested_model
            and candidate.get("verification_status") == "verified"
            and isinstance(candidate.get("recipe_id"), str)
            and re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9._:+/-]{0,127}", candidate["recipe_id"],
            ) is not None
            and isinstance(resolved_model, str)
            and re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9._:+/-]{0,127}", resolved_model,
            ) is not None
        )
        if verified:
            try:
                _require_remote_visible_models(request, [resolved_model])
            except HTTPException:
                verified = False
        model_def = wgp.get_model_def(resolved_model) if verified else None
        if verified and (
            not isinstance(model_def, dict) or not model_def.get("image_outputs")
        ):
            verified = False
        if verified and operation != "generation":
            editor_base = str(wgp.get_base_model_type(resolved_model) or "")
            choices = model_def.get("image_ref_choices", {}).get("choices", [])
            reference_modes = [
                str(choice[1]) for choice in choices
                if isinstance(choice, (list, tuple)) and len(choice) > 1
                and "I" in str(choice[1])
            ]
            if (
                editor_base not in _PROJECT_REFERENCE_EDITOR_ARCHITECTURES
                or not reference_modes
                or editor_reference_mode not in reference_modes
            ):
                verified = False
        if verified:
            routes.append({
                **base,
                "resolved_model": resolved_model,
                "status": "applied",
                "recipe_id": candidate["recipe_id"],
                "verification_status": "verified",
            })
        else:
            routes.append({
                **base,
                "status": "skipped",
                "reason": "no_verified_compatible_recipe",
            })
    return routes


def _project_reference_sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        while True:
            block = handle.read(1024 * 1024)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


def _project_reference_resolve_additional_loras(
    value, *, generation_model, editor_model, operation_models=None,
    operation_roles=None, reference_type=None, freeze=False,
    commitment_contexts=None,
):
    """Validate compatibility cheaply, then optionally freeze file identity.

    ``freeze`` is reserved for the durable worker phase: selected weight files
    can be gigabytes, so request validation must never stream-hash them.
    """
    if value is None:
        return []
    if not isinstance(value, list) or len(value) > 64:
        raise HTTPException(status_code=400, detail="Invalid additional LoRA selection")
    if commitment_contexts is not None and (
        not isinstance(commitment_contexts, dict)
        or any(
            not isinstance(lora_id, str)
            or not isinstance(context, str)
            or re.fullmatch(r"[0-9a-f]{64}", context) is None
            for lora_id, context in commitment_contexts.items()
        )
    ):
        raise RuntimeError("reference_lora_commitment_context_invalid")
    if operation_models is None:
        operation_models = {
            "generation": (generation_model,),
            "editing": (() if editor_model is None else (editor_model,)),
        }
    if (
        not isinstance(operation_models, dict)
        or set(operation_models) != {"generation", "editing"}
        or any(
            not isinstance(models, (list, tuple))
            or any(not isinstance(model, str) or not model for model in models)
            for models in operation_models.values()
        )
    ):
        raise HTTPException(status_code=400, detail="Invalid operation model scope")
    if operation_roles is not None and (
        not isinstance(operation_roles, dict)
        or set(operation_roles) != {"generation", "editing"}
        or any(
            not isinstance(roles, (list, tuple))
            or any(not isinstance(role, str) or not role for role in roles)
            for roles in operation_roles.values()
        )
    ):
        raise HTTPException(status_code=400, detail="Invalid operation role scope")
    if reference_type is not None and (
        not isinstance(reference_type, str) or not reference_type
    ):
        raise HTTPException(status_code=400, detail="Invalid Reference type scope")
    resolved = []
    seen = set()
    for item in value:
        legacy_keys = {"id", "multiplier", "scope"}
        parameterized_keys = {
            *legacy_keys, "parameter_schema_digest", "parameter_values",
        }
        if (
            not isinstance(item, dict)
            or frozenset(item) not in {
                frozenset(legacy_keys), frozenset(parameterized_keys),
            }
        ):
            raise HTTPException(status_code=400, detail="Invalid additional LoRA selection")
        parameterized_request = set(item) == parameterized_keys
        lora_id = item.get("id")
        multiplier = item.get("multiplier")
        requested_scope = item.get("scope")
        if (
            not isinstance(lora_id, str)
            or not lora_id
            or len(lora_id) > 512
            or os.path.basename(lora_id) != lora_id
            or lora_id in seen
            or isinstance(multiplier, bool)
            or not isinstance(multiplier, (int, float))
            or not math.isfinite(float(multiplier))
            or not -10 <= float(multiplier) <= 10
            or requested_scope not in {"auto", "generation", "editing"}
        ):
            raise HTTPException(status_code=400, detail="Invalid additional LoRA selection")
        seen.add(lora_id)
        compatible = {}
        for scope, models in operation_models.items():
            if not models:
                continue
            paths = []
            for model in dict.fromkeys(models):
                try:
                    path = wgp.resolve_lora_path(model, lora_id)
                except Exception:
                    path = ""
                if (
                    not isinstance(path, str)
                    or not path
                    or not os.path.isfile(path)
                    or os.path.islink(path)
                ):
                    paths = []
                    break
                real_path = os.path.realpath(path)
                try:
                    parameter_schema = _project_reference_lora_parameter_schema(
                        model, real_path,
                    )
                except ValueError as error:
                    if parameterized_request:
                        raise HTTPException(
                            status_code=400,
                            detail="Additional LoRA parameter schema is invalid",
                        ) from error
                    parameter_schema = None
                paths.append((model, real_path, parameter_schema))
            if paths:
                compatible[scope] = tuple(paths)
        required = () if requested_scope == "auto" else (requested_scope,)
        if any(scope not in compatible for scope in required):
            raise HTTPException(
                status_code=409,
                detail="Additional LoRA is incompatible with its selected scope",
            )
        resolved_scopes = (
            tuple(scope for scope in ("generation", "editing") if scope in compatible)
            if requested_scope == "auto" else required
        )
        if not resolved_scopes:
            if parameterized_request:
                raise HTTPException(
                    status_code=409,
                    detail="Additional LoRA parameter scope is unavailable",
                )
            resolved.append({
                "id": lora_id,
                "multiplier": float(multiplier),
                "requested_scope": requested_scope,
                "resolved_scopes": (),
                "revision": "unavailable",
                "source_sha256": hashlib.sha256(lora_id.encode("utf-8")).hexdigest(),
                "parameter_schema_digest": None,
                "parameter_commitment_context": None,
                "parameter_values": (),
                "parameter_values_digest": None,
                "parameter_expansion_digest": None,
                "parameter_expansions": [],
                "skipped_reason": "incompatible",
            })
            continue
        selected_schemas = [
            schema
            for scope in resolved_scopes
            for _model, _path, schema in compatible[scope]
        ]
        if not parameterized_request:
            selected_schemas = [
                schema for schema in selected_schemas
                if (
                    schema is not None
                    and schema.get("schema_source") == "server_known_contract"
                )
            ]
        schema_digests = {
            schema["schema_digest"]
            for schema in selected_schemas
            if schema is not None
        }
        if (
            len(schema_digests) > 1
            or (schema_digests and any(schema is None for schema in selected_schemas))
        ):
            raise HTTPException(
                status_code=409,
                detail="Additional LoRA parameter schemas differ across selected scopes",
            )
        selected_schema = next(
            (schema for schema in selected_schemas if schema is not None), None,
        )
        if (
            not parameterized_request
            and selected_schema is not None
            and selected_schema.get("schema_source") == "server_known_contract"
        ):
            raise HTTPException(
                status_code=400,
                detail="Server-known LoRA requires its published parameters",
            )
        if not parameterized_request:
            selected_schema = None
        if selected_schema is None and parameterized_request:
            raise HTTPException(
                status_code=400,
                detail="Strength-only LoRA does not accept parameters",
            )
        if selected_schema is not None and parameterized_request:
            requested_schema_digest = item.get("parameter_schema_digest")
            if (
                not isinstance(requested_schema_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", requested_schema_digest) is None
                or not hmac.compare_digest(
                    requested_schema_digest, selected_schema["schema_digest"],
                )
            ):
                raise HTTPException(
                    status_code=409,
                    detail="Additional LoRA parameter schema changed; refresh and retry",
                )
        parameter_commitment_context = None
        if selected_schema is not None:
            parameter_commitment_context = (
                commitment_contexts.get(lora_id)
                if commitment_contexts is not None else os.urandom(32).hex()
            )
            if parameter_commitment_context is None:
                raise RuntimeError("reference_lora_commitment_context_missing")
        try:
            (
                parameter_values,
                parameter_values_digest,
                parameter_expansion_digest,
                parameter_expansions,
            ) = _normalize_lora_parameter_values(
                selected_schema,
                item.get("parameter_values") if parameterized_request else None,
                commitment_context=parameter_commitment_context,
            )
        except ValueError as error:
            raise HTTPException(
                status_code=400,
                detail="Invalid additional LoRA parameter values",
            ) from error
        if (
            selected_schema is not None
            and selected_schema.get("schema_source") == "server_known_contract"
        ):
            if reference_type is not None and reference_type != "character":
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Server-known character LoRA is not applicable to "
                        "the selected Reference type"
                    ),
                )
        if (
            selected_schema is not None
            and selected_schema.get("schema_source") == "server_known_contract"
            and operation_roles is not None
        ):
            activation_definition = next(
                (
                    definition for definition in selected_schema["parameters"]
                    if definition["id"]
                    == selected_schema.get("_activation_parameter_id")
                ),
                None,
            )
            for operation_scope in resolved_scopes:
                applicable_roles = operation_roles.get(operation_scope, ())
                if (
                    activation_definition is None
                    or operation_scope not in activation_definition["scopes"]
                    or (
                        activation_definition["roles"]
                        and not any(
                            role in activation_definition["roles"]
                            for role in applicable_roles
                        )
                    )
                ):
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "Server-known LoRA trigger is not applicable to "
                            "the selected Reference roles"
                        ),
                    )
        sources = {}
        revisions = {}
        for scope in resolved_scopes:
            scope_sources = {}
            scope_revisions = {}
            for model, path, _schema in compatible[scope]:
                if freeze:
                    actual_sha256 = _project_reference_sha256_file(path)
                    expected_sha256 = (
                        selected_schema.get("_expected_source_sha256")
                        if selected_schema is not None else None
                    )
                    if (
                        expected_sha256 is not None
                        and not hmac.compare_digest(actual_sha256, expected_sha256)
                    ):
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                "Additional LoRA source does not match its "
                                "server-known contract"
                            ),
                        )
                    scope_sources[model] = actual_sha256
                sidecar = os.path.splitext(path)[0] + ".civitai.json"
                revision = "pending"
                if freeze:
                    revision = "local"
                    try:
                        with open(sidecar, "r", encoding="utf-8") as handle:
                            metadata = json.load(handle)
                        revision = str(metadata.get("versionId") or metadata.get("revision") or "local")
                    except (OSError, TypeError, ValueError):
                        pass
                scope_revisions[model] = revision
            if freeze:
                sources[scope] = scope_sources
            revisions[scope] = scope_revisions
        resolved.append({
            "id": lora_id,
            "multiplier": float(multiplier),
            "requested_scope": requested_scope,
            "resolved_scopes": resolved_scopes,
            "revision": json.dumps(revisions, sort_keys=True, separators=(",", ":")),
            "source_sha256": (
                hashlib.sha256(
                    json.dumps(sources, sort_keys=True, separators=(",", ":")).encode("utf-8")
                ).hexdigest()
                if freeze else "pending"
            ),
            "parameter_schema_digest": (
                selected_schema["schema_digest"]
                if selected_schema is not None else None
            ),
            "expected_source_sha256": (
                selected_schema.get("_expected_source_sha256")
                if selected_schema is not None else None
            ),
            "parameter_commitment_context": parameter_commitment_context,
            "parameter_values": parameter_values,
            "parameter_values_digest": parameter_values_digest,
            "parameter_expansion_digest": parameter_expansion_digest,
            "parameter_expansions": parameter_expansions,
            "skipped_reason": None,
        })
    for operation_scope in ("generation", "editing"):
        expansion_characters = sum(
            len(expansion["text"])
            for selection in resolved
            if operation_scope in selection.get("resolved_scopes", ())
            for expansion in selection.get("parameter_expansions") or ()
            if operation_scope in expansion.get("scopes", ())
        )
        if expansion_characters > 32_000:
            raise HTTPException(
                status_code=400,
                detail="Additional LoRA parameter expansions exceed the operation budget",
            )
    return resolved


def _project_reference_uncensored_review_setup():
    """Return content-free setup facts for the exact local fidelity reviewer."""
    from services import llm_service

    model_id = _PROJECT_REFERENCE_ABLITERATED_RECIPE["model_id"]
    catalog_model = next((
        item for item in llm_service.get_available_models(provider="local")
        if item.get("id") == model_id
    ), {})
    status = llm_service.get_status()
    provider = str(status.get("provider") or "local")
    resident = bool(
        status.get("loaded")
        and status.get("model_id") == model_id
        and provider == "local"
    )
    download = status.get("download")
    loading_model_id = status.get("loading_model_id") or (
        download.get("model_id") if isinstance(download, dict) else None
    )
    loading = bool(status.get("loading") and loading_model_id == model_id)
    installed = catalog_model.get("downloaded") is True
    projector_available = catalog_model.get("projector_available") is True
    vision_capable = catalog_model.get("vision_capable") is True
    vision_available = (
        bool(status.get("vision_available")) if resident else None
    )
    if loading:
        setup_state = "loading"
    elif not installed:
        setup_state = "missing_model"
    elif not projector_available or not vision_capable:
        setup_state = "missing_projector"
    elif resident and vision_available is not True:
        setup_state = "loaded_without_vision"
    elif resident:
        setup_state = "ready_resident"
    else:
        setup_state = "ready_unloaded"
    queue_ready = setup_state in {"ready_unloaded", "ready_resident"}
    return {
        "requested_model": "auto_local",
        "resolved_model": model_id,
        "resolved_provider": "local",
        "vision_required": True,
        "required_projector": _PROJECT_REFERENCE_ABLITERATED_RECIPE["projector"],
        "installed": installed,
        "projector_available": projector_available,
        "vision_capable": vision_capable,
        "resident": resident,
        "vision_available": vision_available,
        "loading": loading,
        "loading_phase": (
            str(status.get("loading_phase") or "loading model")
            if loading else None
        ),
        "setup_state": setup_state,
        "queue_ready": queue_ready,
    }


def _project_reference_explicit_generation_model():
    """Resolve an explicit-only default without changing global routing policy."""
    from services.model_terms import (
        model_terms_manifest_valid,
        model_terms_statuses,
    )

    visibility_reader = globals().get("_model_visibility_response")
    visibility = (
        visibility_reader() if callable(visibility_reader) else {
            "configured": False,
            "enabled_models": [],
        }
    )
    enabled_models = set(
        visibility.get("enabled_models") or ()
        if visibility.get("configured") else ()
    )
    services = getattr(wgp, "server_config", {}).get("services", {})
    manual_ready = getattr(wgp, "manual_checkpoint_integrity_ready", None)
    candidates = []
    for model_type in _PROJECT_REFERENCE_EXPLICIT_CREATE_MODELS:
        model_def = wgp.get_model_def(model_type)
        manifest_valid = bool(
            isinstance(model_def, dict)
            and model_terms_manifest_valid(model_type, wgp.models_def)
        )
        checkpoint_verified = bool(
            manifest_valid
            and callable(manual_ready)
            and manual_ready(model_type, model_def, wgp.models_def)
        )
        term_statuses = (
            model_terms_statuses(services, model_type, wgp.models_def)
            if manifest_valid else []
        )
        terms_accepted = bool(
            manifest_valid
            and term_statuses
            and all(item.get("accepted") is True for item in term_statuses)
        )
        enabled = model_type in enabled_models
        downloaded = bool(
            checkpoint_verified and _check_model_downloaded(model_type)
        )
        ready = bool(
            enabled and checkpoint_verified and terms_accepted
        )
        candidates.append({
            "model_type": model_type,
            "enabled": enabled,
            "manual_checkpoint_verified": checkpoint_verified,
            "terms_accepted": terms_accepted,
            "downloaded": downloaded,
            "ready": ready,
        })
    preferred = next((
        candidate["model_type"] for candidate in candidates
        if candidate["ready"]
    ), _PROJECT_REFERENCE_DEFAULT_CREATE_MODEL)
    return {
        "preferred_order": list(_PROJECT_REFERENCE_EXPLICIT_CREATE_MODELS),
        "resolved_model": preferred,
        "fallback_model": _PROJECT_REFERENCE_DEFAULT_CREATE_MODEL,
        "selection_source": (
            "verified_manual_preference"
            if preferred != _PROJECT_REFERENCE_DEFAULT_CREATE_MODEL
            else "fallback"
        ),
        "candidates": candidates,
    }


def _project_reference_capabilities():
    from services.character_sheet_capabilities import (
        character_sheet_capability_projection,
    )
    from services.reference_sheets import (
        CHARACTER_EXPLICIT_ANATOMY,
        CHARACTER_GENDERS,
        CHARACTER_PROFILE_SCHEMA_VERSION,
        MAX_PACK_SHEETS,
        PACK_TYPE_PRESETS,
        reference_pack_detail_kind_capabilities,
        reference_pack_ordered_roles,
        reference_pack_type_field_capabilities,
    )

    return {
        "schema_version": 2,
        "planner_version": "reference-pack-v2",
        "intents": ["exact_spec", "generic", "brainstorming"],
        "depths": {
            "compact": {"sheet_count": 1},
            "standard": {"minimum": 2, "maximum": 3, "default": 3},
            "comprehensive": {"minimum": 3, "maximum": 5, "default": 5},
            "custom": {"minimum": 1, "maximum": MAX_PACK_SHEETS},
        },
        "reference_types": [
            {
                "id": reference_type,
                "presets": [
                    {
                        "id": preset,
                        "label": {
                        "underlayers": "Wardrobe & underlayers",
                        "anatomy": "Anatomy / nude",
                        }.get(preset, preset.replace("_", " ").title()),
                        "ordered_roles": list(reference_pack_ordered_roles(
                            reference_type, preset,
                        )),
                        "valid_source_roles": list(reference_pack_ordered_roles(
                            reference_type, preset,
                        )),
                        "detail_operations": [
                            "auto", "crop", "enhance", "reconstruct",
                        ],
                    }
                    for preset in PACK_TYPE_PRESETS[reference_type]
                ],
                "type_fields": reference_pack_type_field_capabilities(
                    reference_type,
                ),
                "detail_kinds": reference_pack_detail_kind_capabilities(
                    reference_type,
                ),
                "supports_custom_details": True,
            }
            for reference_type in (
                "character", "location", "prop", "vehicle", "creature",
                "wardrobe", "world",
            )
        ],
        "detail_operations": ["auto", "crop", "enhance", "reconstruct"],
        "character_profile": {
            "schema_version": CHARACTER_PROFILE_SCHEMA_VERSION,
            "genders": list(CHARACTER_GENDERS),
            "age": {"optional": True, "minimum": 0, "maximum": 999},
            "explicit_anatomy": list(CHARACTER_EXPLICIT_ANATOMY),
            "explicit_convenience": {
                "supported": True,
                "requires_explicit_output": True,
            },
        },
        "lora_scopes": ["auto", "generation", "editing"],
        "content_capabilities": ["standard", "unrestricted_local"],
        "intelligence_policies": ["standard_auto", "uncensored_auto"],
        "uncensored_auto_review": _project_reference_uncensored_review_setup(),
        "explicit_generation_model": _project_reference_explicit_generation_model(),
        "review_policy": {
            "mandatory_for_content_capabilities": ["unrestricted_local"],
            "mandatory_when_explicit_output": True,
            "off_allowed_for_content_capabilities": ["standard"],
            "mandatory_contract": _PROJECT_REFERENCE_UNRESTRICTED_REVIEW,
        },
        "max_candidate_count": 8,
        "max_repair_attempts": 5,
        "default_models": {
            "generation_model": _PROJECT_REFERENCE_DEFAULT_CREATE_MODEL,
            "editor_model": _PROJECT_REFERENCE_DEFAULT_EDITOR_MODEL,
        },
        "planning_models": {
            "built_in": ["auto", "deterministic"],
            "catalog_endpoint": "/api/v1/llm/models",
        },
        "review_models": {
            "built_in": ["auto_local", "off"],
            "catalog_endpoint": "/api/v1/llm/models",
            "required_capability": "vision_capable",
        },
        "managed_layout_assist": {
            "schema_version": 1,
            "mode": "off",
            "allowlisted": sorted(_PROJECT_REFERENCE_MANAGED_LAYOUT_LORAS),
            "provenance": {
                "kind": "server_allowlist",
                "version": "managed-layout-v1",
            },
        },
        "character_sheet": character_sheet_capability_projection(),
    }


@api.get("/api/v1/projects/{project}/assets/reference-capabilities")
def get_project_reference_capabilities(project: str, request: Request):
    _asset_scope(request, project)
    return _project_reference_capabilities()


def _project_reference_request_config(
    body, request, *, existing_asset_type=None, commitment_contexts=None,
    managed_character_callouts=None,
):
    """Validate one v2 pack request before any asset or job can be created."""
    from services.reference_sheets import (
        PACK_TYPE_FIELDS,
        PACK_TYPE_PRESETS,
        _normalize_pack_callouts,
        normalize_character_profile,
        normalize_reference_pack_type,
        normalize_reference_pack_type_fields,
        reference_pack_ordered_roles,
    )

    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Request body must be an object")
    unknown = set(body).difference(_PROJECT_REFERENCE_BODY_FIELDS)
    if unknown:
        raise HTTPException(status_code=400, detail="Unsupported reference request fields")

    schema_version = body.get("schema_version", 2)
    if schema_version != 2 or isinstance(schema_version, bool):
        raise HTTPException(status_code=400, detail="Reference authoring requires schema_version 2")

    mode = body.get("mode", "production")
    if mode not in {"production", "hybrid", "draft"}:
        raise HTTPException(status_code=400, detail="Unsupported reference-pack mode")
    intent = body.get("intent", "generic")
    if intent not in {"exact_spec", "generic", "brainstorming"}:
        raise HTTPException(status_code=400, detail="Unsupported reference intent")
    depth = body.get("depth", "standard")
    if depth not in {"compact", "standard", "comprehensive", "custom"}:
        raise HTTPException(status_code=400, detail="Unsupported reference depth")
    requested_asset_type = body.get("asset_type")
    if requested_asset_type is None:
        requested_asset_type = existing_asset_type or "character"
    try:
        asset_type = normalize_reference_pack_type(requested_asset_type)
    except ValueError as error:
        raise HTTPException(status_code=400, detail="Unsupported reference asset type") from error
    explicit_output_value = body.get("explicit_output")
    if explicit_output_value is not None and type(explicit_output_value) is not bool:
        raise HTTPException(status_code=400, detail="explicit_output must be a boolean")
    explicit_output = explicit_output_value is True
    explicit_convenience = body.get("explicit_convenience", False)
    if type(explicit_convenience) is not bool:
        raise HTTPException(
            status_code=400,
            detail="explicit_convenience must be a boolean",
        )
    raw_character_profile = body.get("character_profile")
    if asset_type != "character" and (
        raw_character_profile is not None
        or managed_character_callouts is not None
        or explicit_convenience
    ):
        raise HTTPException(
            status_code=400,
            detail="Character profile fields require a character reference",
        )
    if explicit_convenience and not explicit_output:
        raise HTTPException(
            status_code=400,
            detail="Explicit convenience requires explicit output authorization",
        )
    try:
        character_profile = normalize_character_profile(
            raw_character_profile,
            explicit_convenience=explicit_convenience,
        )
    except ValueError as error:
        raise HTTPException(
            status_code=400,
            detail="Invalid character profile or explicit convenience",
        ) from error
    normalized_character_profile = (
        None if character_profile is None
        else character_profile.private_metadata()
    )

    preset = body.get("preset") or {
        "character": "identity", "location": "spatial", "prop": "product",
        "vehicle": "exterior", "creature": "identity", "wardrobe": "look",
        "world": "visual_language",
    }[asset_type]
    if preset not in PACK_TYPE_PRESETS[asset_type]:
        raise HTTPException(status_code=400, detail="Reference preset does not match asset type")
    anchor_basis = body.get("anchor_basis")
    if anchor_basis is not None and not isinstance(anchor_basis, str):
        raise HTTPException(status_code=400, detail="Invalid reference anchor basis")
    if asset_type in {"character", "creature"}:
        anchor_basis = anchor_basis or ("anatomy" if preset == "anatomy" else "primary_outfit")
        if anchor_basis not in {"anatomy", "primary_outfit"}:
            raise HTTPException(status_code=400, detail="Invalid reference anchor basis")
        if preset == "anatomy" and anchor_basis != "anatomy":
            raise HTTPException(status_code=400, detail="Anatomy preset requires anatomy anchor")
    else:
        anchor_basis = anchor_basis or "least_occluded"
        if anchor_basis != "least_occluded":
            raise HTTPException(status_code=400, detail="Invalid reference anchor basis")

    type_fields = body["type_fields"] if "type_fields" in body else {}
    if not isinstance(type_fields, dict):
        raise HTTPException(status_code=400, detail="type_fields must be an object")
    if set(type_fields).difference(PACK_TYPE_FIELDS[asset_type]):
        raise HTTPException(status_code=400, detail="type_fields do not match asset type")
    try:
        sealed_type_fields = normalize_reference_pack_type_fields(
            type_fields,
            reference_type=asset_type,
        )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    normalized_type_fields = {
        field: [item.private_metadata() for item in items]
        for field, items in sealed_type_fields
    }
    if asset_type == "character" and explicit_convenience:
        nude_anatomy = {
            "id": "anatomy:nude-anatomy",
            "label": "nude anatomy",
            "custom": False,
            "group": "anatomy",
        }
        if (
            preset != "anatomy"
            or anchor_basis != "anatomy"
            or nude_anatomy not in normalized_type_fields.get("poses", [])
        ):
            raise HTTPException(
                status_code=400,
                detail=(
                    "Explicit character references require the Anatomy preset, "
                    "an anatomy anchor, and the canonical nude anatomy field"
                ),
            )
    legacy_type_fields = {
        "poses": {"character", "creature"},
        "outfits": {"character"},
        "genre": {"world"},
    }
    if any(
        body.get(field) is not None
        and body.get(field) != ""
        and asset_type not in allowed_types
        for field, allowed_types in legacy_type_fields.items()
    ):
        raise HTTPException(status_code=400, detail="Legacy type fields do not match asset type")

    raw_detail_callouts = (
        body["detail_callouts"] if "detail_callouts" in body else []
    )
    if not isinstance(raw_detail_callouts, list) or len(raw_detail_callouts) > 8:
        raise HTTPException(status_code=400, detail="Invalid detail callouts")
    if mode == "draft" and raw_detail_callouts:
        raise HTTPException(
            status_code=400,
            detail="Draft mode does not support editor-dependent detail callouts",
        )

    content_capability = body.get("content_capability")
    if content_capability is None:
        content_capability = (
            "unrestricted_local"
            if explicit_output or explicit_convenience or anchor_basis == "anatomy"
            else "standard"
        )
    if content_capability not in {"standard", "unrestricted_local"}:
        raise HTTPException(status_code=400, detail="Invalid content_capability")

    requested_model_type = body.get("model_type")
    if requested_model_type:
        model_type = requested_model_type
    elif mode != "draft" and (
        explicit_output
        or explicit_convenience
        or content_capability == "unrestricted_local"
    ):
        model_type = _project_reference_explicit_generation_model()[
            "resolved_model"
        ]
    else:
        model_type = _PROJECT_REFERENCE_DEFAULT_CREATE_MODEL
    if not isinstance(model_type, str) or not 1 <= len(model_type) <= 128:
        raise HTTPException(status_code=400, detail="Invalid reference image model")
    _require_remote_visible_models(request, [model_type])
    model_def = wgp.get_model_def(model_type)
    if not isinstance(model_def, dict) or not model_def.get("image_outputs"):
        raise HTTPException(status_code=400, detail="Reference generation requires an image model")

    editor_model_type = body.get("editor_model_type")
    if editor_model_type is None and mode != "draft":
        editor_model_type = _PROJECT_REFERENCE_DEFAULT_EDITOR_MODEL
    if mode == "draft" and editor_model_type is not None:
        raise HTTPException(status_code=400, detail="Draft mode does not use an editor model")
    if editor_model_type is not None:
        if not isinstance(editor_model_type, str) or not 1 <= len(editor_model_type) <= 128:
            raise HTTPException(status_code=400, detail="Invalid reference editor model")
        _require_remote_visible_models(request, [editor_model_type])
        editor_def = wgp.get_model_def(editor_model_type)
        editor_base = str(wgp.get_base_model_type(editor_model_type) or "")
        choices = (
            editor_def.get("image_ref_choices", {}).get("choices", [])
            if isinstance(editor_def, dict) else []
        )
        reference_modes = [
            str(choice[1]) for choice in choices
            if isinstance(choice, (list, tuple)) and len(choice) > 1
            and "I" in str(choice[1])
        ]
        if (
            not isinstance(editor_def, dict)
            or not editor_def.get("image_outputs")
            or editor_base not in _PROJECT_REFERENCE_EDITOR_ARCHITECTURES
            or not reference_modes
        ):
            raise HTTPException(
                status_code=409,
                detail="Anchored mode needs an image editor with reference-image support",
            )
        editor_reference_mode = "KI" if any("K" in item for item in reference_modes) else "I"
    else:
        editor_reference_mode = ""

    def bounded_integer(field, default, minimum, maximum):
        value = body.get(field, default)
        if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
            raise HTTPException(
                status_code=400,
                detail=f"{field} must be an integer from {minimum} through {maximum}",
            )
        return value

    candidate_count = bounded_integer("candidate_count", 1, 1, 8)
    if depth == "custom":
        sheet_count = bounded_integer("sheet_count", None, 1, 5)
    else:
        if body.get("sheet_count") is not None:
            raise HTTPException(status_code=400, detail="sheet_count is allowed only for custom depth")
        sheet_count = {"compact": 1, "standard": 3, "comprehensive": 5}[depth]
    try:
        available_roles = reference_pack_ordered_roles(
            asset_type, preset, sheet_count,
        )
        sealed_callouts = _normalize_pack_callouts(
            raw_detail_callouts,
            reference_type=asset_type,
            intent=intent,
            sheet_roles=available_roles,
        )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    normalized_callouts = [item.private_metadata() for item in sealed_callouts]
    seed = bounded_integer("seed", -1, -1, (2 ** 63) - 1)
    columns = bounded_integer("columns", 2, 1, 4)
    palette_swatches = bounded_integer("palette_swatches", 8, 3, 12)
    max_repair_attempts = bounded_integer("max_repair_attempts", 1, 0, 5)
    model_schedules = {
        model_type: _project_reference_model_schedule(body, model_type),
    }
    if editor_model_type is not None:
        model_schedules[editor_model_type] = _project_reference_model_schedule(
            body, editor_model_type,
        )
    review = body.get("review", True)
    if not isinstance(review, bool):
        raise HTTPException(status_code=400, detail="review must be a boolean")

    mandatory_review = bool(
        content_capability == "unrestricted_local"
        or explicit_output
        or explicit_convenience
    )
    review_contract = (
        _PROJECT_REFERENCE_UNRESTRICTED_REVIEW
        if mandatory_review else _PROJECT_REFERENCE_STANDARD_REVIEW
    )
    initial_blur = body.get("initial_blur")
    if initial_blur is None:
        initial_blur = (
            explicit_output or explicit_convenience or anchor_basis == "anatomy"
        )
    if type(initial_blur) is not bool:
        raise HTTPException(status_code=400, detail="initial_blur must be a boolean")
    intelligence_policy = body.get("intelligence_policy")
    if intelligence_policy is None:
        intelligence_policy = (
            "uncensored_auto"
            if explicit_output or explicit_convenience or anchor_basis == "anatomy"
            else "standard_auto"
        )
    if intelligence_policy not in {"standard_auto", "uncensored_auto"}:
        raise HTTPException(status_code=400, detail="Invalid intelligence_policy")

    planning_model = body.get("planning_model", "auto")
    review_model = body.get("review_model", "auto_local" if review else "off")
    planning_provider = body.get("planning_provider")
    review_provider = body.get("review_provider")
    for value, field in (
        (planning_model, "planning_model"), (review_model, "review_model"),
        (planning_provider, "planning_provider"), (review_provider, "review_provider"),
    ):
        if value is not None and (not isinstance(value, str) or not value or len(value) > 256):
            raise HTTPException(status_code=400, detail=f"Invalid {field}")
    planning_selection = _project_reference_intelligence_selection(
        request,
        requested_model=planning_model,
        requested_provider=planning_provider,
        purpose="planning",
        intent=intent,
    )
    review_selection = None
    if intelligence_policy != "uncensored_auto" or not review:
        review_selection = _project_reference_intelligence_selection(
            request,
            requested_model=review_model,
            requested_provider=review_provider,
            purpose="review",
            intent=intent,
        )
    intelligence_recipe = None
    if intelligence_policy == "uncensored_auto":
        intelligence_recipe = dict(_PROJECT_REFERENCE_ABLITERATED_RECIPE)
        if planning_model == "auto":
            planning_selection = {
                "requested_model": "auto",
                "resolved_model": intelligence_recipe["id"],
                "resolved_provider": "local",
            }
        if review:
            if review_provider not in {None, "local"}:
                raise HTTPException(
                    status_code=400,
                    detail="Uncensored Auto fidelity review is local-only",
                )
            if review_model not in {
                "auto_local", intelligence_recipe["model_id"],
            }:
                raise HTTPException(
                    status_code=409,
                    detail="Uncensored Auto requires its compatible local vision reviewer",
                )
            reviewer_setup = _project_reference_uncensored_review_setup()
            if reviewer_setup["queue_ready"] is not True:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "The exact local Uncensored Auto reviewer is not ready "
                        f"({reviewer_setup['setup_state']})."
                    ),
                )
            review_selection = {
                "requested_model": review_model,
                "resolved_model": intelligence_recipe["model_id"],
                "resolved_provider": "local",
            }
        intelligence_recipe["status"] = "queued"
    assert review_selection is not None
    if mandatory_review:
        review_selection = _project_reference_seal_intelligence_selection(
            review_selection,
        )
        if not review or review_selection["resolved_model"] is None:
            raise HTTPException(
                status_code=409,
                detail="Explicit/unrestricted output requires a selected vision fidelity reviewer",
            )
    if (
        review_selection["resolved_model"] is not None
        and review_selection["resolved_provider"] != "local"
        and review_provider != review_selection["resolved_provider"]
    ):
        raise HTTPException(
            status_code=400,
            detail="Remote fidelity review requires an explicit provider selection",
        )

    operation_routing = _project_reference_operation_routing(
        request,
        content_capability=content_capability,
        generation_model=model_type,
        editor_model=editor_model_type,
        editor_reference_mode=editor_reference_mode,
    )
    for route in operation_routing:
        routed_model = route["resolved_model"]
        if route["status"] == "applied" and routed_model not in model_schedules:
            model_schedules[routed_model] = _project_reference_model_schedule(
                body, routed_model,
            )
        route["schedule"] = (
            copy.deepcopy(model_schedules[routed_model])
            if routed_model is not None else None
        )
    operation_models = {
        "generation": tuple(dict.fromkeys(
            route["resolved_model"] for route in operation_routing
            if route["operation"] == "generation" and route["resolved_model"]
        )),
        "editing": tuple(dict.fromkeys(
            route["resolved_model"] for route in operation_routing
            if route["operation"] != "generation" and route["resolved_model"]
        )),
    }
    operation_roles = {
        "generation": tuple(
            available_roles if mode == "draft" else available_roles[:1]
        ),
        "editing": tuple(() if mode == "draft" else available_roles[1:]),
    }

    resolution = body.get("resolution")
    resolution_size = (
        _project_reference_dimensions(resolution, "resolution", (512, 512))
        if resolution is not None else None
    )
    panel_size = _project_reference_dimensions(
        body.get("panel_size"), "panel_size", resolution_size or (512, 512),
    )
    draft_size = _project_reference_dimensions(
        body.get("draft_size"), "draft_size", resolution_size or (1024, 1024),
    )
    tags = body.get("tags")
    if tags is not None and (
        not isinstance(tags, list)
        or len(tags) > 100
        or any(not isinstance(tag, str) or not tag.strip() or len(tag.strip()) > 64 for tag in tags)
    ):
        raise HTTPException(status_code=400, detail="Invalid reference asset tags")
    loras = body.get("activated_loras") or []
    if (
        not isinstance(loras, list)
        or len(loras) > 64
        or any(not isinstance(item, str) or not item or len(item) > 512 for item in loras)
    ):
        raise HTTPException(status_code=400, detail="Invalid reference LoRA selection")
    managed_layout_assist = body.get("managed_layout_assist", "off")
    if managed_layout_assist != "off":
        raise HTTPException(
            status_code=409,
            detail="No managed Reference layout assist is currently vetted",
        )
    additional_loras = _project_reference_resolve_additional_loras(
        body.get("additional_loras"),
        generation_model=model_type,
        editor_model=editor_model_type,
        operation_models=operation_models,
        operation_roles=operation_roles,
        reference_type=asset_type,
        commitment_contexts=commitment_contexts,
    )
    style = _project_reference_text(body.get("style"), "style", limit=10_000)
    style_commitment = _project_reference_private_commitment({
        "kind": "reference_style_v1",
        "value": style,
    })

    asset_id = body.get("asset_id")
    parent_variant_id = body.get("parent_variant_id")
    for value, field in ((asset_id, "asset_id"), (parent_variant_id, "parent_variant_id")):
        if value is not None and (not isinstance(value, str) or not value or len(value) > 128):
            raise HTTPException(status_code=400, detail=f"Invalid {field}")
    edit_instruction = _project_reference_text(
        body.get("edit_instruction"), "edit_instruction", limit=10_000,
    )
    if (parent_variant_id or edit_instruction) and not asset_id:
        raise HTTPException(
            status_code=400,
            detail="Retry and edit requests require asset_id",
        )

    default_private = True if anchor_basis == "anatomy" else body.get("private_output")
    policy_request = {
        "private_output": (
            default_private if body.get("private_output") is None
            else body.get("private_output")
        ),
        "explicit_output": body.get("explicit_output"),
    }
    policy = _http_output_policy_from_request(
        policy_request,
        owner_session_id=request.state.maestro_session_id,
    )
    name = _project_reference_text(
        body.get("name"), "name", limit=200, default="Untitled reference",
    )
    if not asset_id and not name:
        raise HTTPException(status_code=400, detail="name is required")
    return {
        "schema_version": 2,
        "mode": mode,
        "intent": intent,
        "depth": depth,
        "sheet_count": sheet_count,
        "preset": preset,
        "anchor_basis": anchor_basis,
        "asset_type": asset_type,
        "model_type": model_type,
        "editor_model_type": editor_model_type,
        "editor_reference_mode": editor_reference_mode,
        "candidate_count": candidate_count,
        "type_fields": normalized_type_fields,
        "detail_callouts": normalized_callouts,
        "character_profile": normalized_character_profile,
        "managed_character_callouts": copy.deepcopy(
            managed_character_callouts,
        ),
        "explicit_convenience": explicit_convenience,
        "managed_layout_assist": managed_layout_assist,
        "content_capability": content_capability,
        "initial_blur": initial_blur,
        "intelligence_policy": intelligence_policy,
        "review_contract": review_contract,
        "mandatory_review": mandatory_review,
        "intelligence_recipe": intelligence_recipe,
        "operation_routing": operation_routing,
        "operation_models": operation_models,
        "operation_roles": operation_roles,
        "additional_loras": additional_loras,
        "planning": planning_selection,
        "review_selection": review_selection,
        "model_schedules": model_schedules,
        "seed": seed,
        "columns": columns,
        "palette_swatches": palette_swatches,
        "max_repair_attempts": max_repair_attempts,
        "panel_size": panel_size,
        "draft_size": draft_size,
        "review": review,
        "asset_id": asset_id,
        "parent_variant_id": parent_variant_id,
        "edit_instruction": edit_instruction,
        "name": name,
        "description": _project_reference_text(
            body.get("description"), "description", limit=10_000,
        ),
        "tags": tags,
        "poses": _project_reference_text(body.get("poses"), "poses", limit=10_000),
        "outfits": _project_reference_text(body.get("outfits"), "outfits", limit=10_000),
        "style": style,
        "style_commitment": style_commitment,
        "genre": _project_reference_text(body.get("genre"), "genre", limit=10_000),
        "negative_prompt": _project_reference_text(
            body.get("negative_prompt"), "negative_prompt", limit=50_000,
        ),
        "activated_loras": list(loras),
        "loras_multipliers": _project_reference_text(
            body.get("loras_multipliers"), "loras_multipliers", limit=2_000,
        ),
        "policy": policy,
    }


def _project_reference_creative_request(asset, config):
    authored_values = []
    for items in config["type_fields"].values():
        for item in items:
            if not isinstance(item, dict):
                continue
            label = item.get("label", "")
            group = item.get("group", "")
            authored_values.append(
                label if group == "legacy" else f"{group}: {label}"
            )
    authored_values.extend(
        f"detail: {item.get('label', '')}"
        for item in config["detail_callouts"]
        if isinstance(item, dict)
    )
    parts = [
        str(asset.get("name") or "").strip(),
        str(asset.get("description") or "").strip(),
        (
            config["description"]
            if config["description"] != str(asset.get("description") or "").strip()
            else ""
        ),
        *authored_values,
        config["poses"], config["outfits"], config["style"], config["genre"],
        config["edit_instruction"],
    ]
    return "\n".join(part for part in parts if part).strip()


def _project_reference_generation_params(
    config, *, model_type, prompt, size, seed, reference_path=None,
    operation_scope="generation", operation_role=None,
):
    schedule = config["model_schedules"][model_type]
    params = {
        "model_type": model_type,
        "prompt": prompt,
        "negative_prompt": config["negative_prompt"],
        "image_mode": 1,
        "image_prompt_type": "",
        "video_prompt_type": "",
        "resolution": f"{size[0]}x{size[1]}",
        "num_inference_steps": schedule["steps"],
        "seed": seed,
        "settings_version": 2.57,
        "generation_mode": "image",
        "repeat_generation": 1,
        "batch_size": 1,
        "video_length": 1,
        "private_output": config["policy"]["private"],
        "explicit_output": config["policy"]["explicit"],
    }
    params[schedule["guidance_key"]] = schedule["guidance"]
    params["activated_loras"] = list(config["activated_loras"])
    params["loras_multipliers"] = config["loras_multipliers"]
    scoped = [
        item for item in config.get("additional_loras") or []
        if operation_scope in item.get("resolved_scopes", ())
    ]
    prompt_fragments = []
    for item in scoped:
        params["activated_loras"].append(item["id"])
        for expansion in item.get("parameter_expansions") or []:
            scopes = expansion.get("scopes")
            roles = expansion.get("roles")
            if (
                operation_scope in scopes
                and (not roles or operation_role in roles)
                and isinstance(expansion.get("text"), str)
                and expansion["text"]
            ):
                prompt_fragments.append(expansion["text"])
    if prompt_fragments:
        params["prompt"] = " ".join((params["prompt"], *prompt_fragments))
    if scoped:
        additions = " ".join(str(item["multiplier"]) for item in scoped)
        params["loras_multipliers"] = " ".join(
            part for part in (params["loras_multipliers"], additions) if part
        )
    if reference_path is not None:
        references = (
            list(reference_path)
            if isinstance(reference_path, (list, tuple))
            else [reference_path]
        )
        unique_references = []
        for item in references:
            rendered = str(item)
            if rendered not in unique_references:
                unique_references.append(rendered)
        params.update({
            "image_refs": unique_references,
            "video_prompt_type": config["editor_reference_mode"],
            "remove_background_images_ref": 0,
            "image_refs_relative_size": 100,
        })
    return params


def _write_project_reference_sidecar(
    path, *, parent_job, model_type, artifact_metadata,
):
    """Write policy-stamped role metadata plus exact private authoring state."""
    sidecar_path = os.path.splitext(path)[0] + ".meta.json"
    metadata_key = (
        "reference_pack"
        if artifact_metadata.get("schema_version") == 2
        else "reference_sheet"
    )
    sidecar_metadata = dict(artifact_metadata)
    if metadata_key == "reference_pack":
        authored = (
            ((parent_job.get("params") or {}).get("reference_pack") or {}).get(
                "private_authored_settings"
            )
        )
        if isinstance(authored, dict):
            sidecar_metadata["private_authored_settings"] = copy.deepcopy(authored)
        private_request = (
            ((parent_job.get("params") or {}).get("reference_pack") or {}).get(
                "private_reference_request"
            )
        )
        if isinstance(private_request, dict):
            sidecar_metadata["private_reference_request"] = copy.deepcopy(
                private_request,
            )
    sidecar = {
        "params": {metadata_key: sidecar_metadata},
        "generation_mode": "image",
        "model_type": model_type,
        "job_id": str(parent_job.get("id") or ""),
        "reference_parent_job_id": str(parent_job.get("id") or ""),
    }
    stamp_sidecar_policy(
        sidecar,
        parent_job.get("access_policy") or {},
        workspace=str(parent_job.get("workspace") or "default"),
    )
    temp_path = f"{sidecar_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            json.dump(sidecar, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, sidecar_path)
    finally:
        try:
            os.remove(temp_path)
        except OSError:
            pass


def _cleanup_project_reference_private_source(path, root=None):
    """Remove one owned generator source and private sidecar after copying."""
    lexical = os.path.abspath(str(path))
    if root is not None:
        expected_root = os.path.realpath(str(root))
        if os.path.dirname(lexical) != expected_root:
            return False
    removed = False
    for candidate in (lexical, os.path.splitext(lexical)[0] + ".meta.json"):
        try:
            if os.path.islink(candidate) or not os.path.isfile(candidate):
                continue
            if root is not None and os.path.dirname(os.path.realpath(candidate)) != expected_root:
                continue
            os.remove(candidate)
            removed = True
        except OSError:
            pass
    return removed


def _project_reference_wait_at_output_boundary(parent_job, boundary):
    """Honor one parent deferred hold between complete Reference outputs."""
    while (
        bool(parent_job.get("hold_after_output", False))
        and not is_cancel_requested(parent_job)
    ):
        if not update_job(
            parent_job,
            resource_intent="text",
            resource_execution="standard",
            resource_state="queued",
            phase="Reference generation held",
            message=f"Held after completed {boundary}",
        ):
            return False
        time.sleep(0.1)
    if is_cancel_requested(parent_job):
        return False
    return bool(update_job(
        parent_job,
        resource_intent="text",
        resource_execution="standard",
        resource_state="released",
    ))


def _project_reference_safe_failure_envelope(state):
    """Copy only normalized, content-free child failure diagnostics."""
    from services.oom_detect import (
        normalize_failure_details,
        oom_info_from_failure_details,
    )

    updates = {}
    raw_details = state.get("failure_details")
    if isinstance(raw_details, dict):
        details = normalize_failure_details(raw_details)
        updates.update({
            "failure_details": details,
            "error": details["detail"],
            "message": details["detail"],
        })

    raw_oom = state.get("oom_info")
    if isinstance(raw_oom, dict) and raw_oom.get("is_oom") is True:
        oom_details = normalize_failure_details({
            **raw_oom,
            "is_oom": True,
        })
        coefficient = raw_oom.get("current_coefficient")
        if (
            type(coefficient) not in {int, float}
            or not math.isfinite(coefficient)
            or not 0.0 < coefficient <= 1.0
        ):
            coefficient = 0.80
        safe_oom = oom_info_from_failure_details(
            oom_details, float(coefficient),
        )
        if safe_oom is not None:
            updates["oom_info"] = safe_oom
    return updates


def _project_reference_child_failure_updates(snapshot):
    """Build one bounded parent stamp for a terminal non-completed child."""
    child_id = _public_parent_job_id({
        "parent_job_id": snapshot.get("id"),
    })
    raw_status = str(snapshot.get("status") or "")
    blocked = bool(
        snapshot.get("resource_state") == "blocked"
        or str(snapshot.get("recovery_state") or "").startswith("blocked")
    )
    if raw_status == "cancelled":
        child_status = "cancelled"
    elif blocked or raw_status in {"queued", "running"}:
        child_status = "blocked"
    else:
        child_status = "failed"

    safe_failure = _project_reference_safe_failure_envelope(snapshot)
    details = safe_failure.get("failure_details")
    reason = (
        details.get("code")
        if isinstance(details, dict)
        else {
            "failed": "child_failed",
            "cancelled": "child_cancelled",
            "blocked": "child_blocked",
        }[child_status]
    )
    updates = {
        "failed_child_job_id": child_id,
        "failed_child_status": child_status,
        "failed_child_reason": reason,
    }
    updates.update(safe_failure)
    return updates


def _run_project_reference_image_job(
    parent_job, params, *, role, phase, step, total_steps,
    artifact_metadata=None,
):
    """Run one recoverable local image child and return only its owned output."""
    child_id = uuid.uuid4().hex[:8]
    child = {
        "id": child_id,
        "status": "queued",
        "progress": 0,
        "step": 0,
        "total_steps": 0,
        "phase": "",
        "message": phase,
        "created_at": time.time(),
        "params": dict(params),
        "output_files": [],
        "error": None,
        "workspace": parent_job["workspace"],
        "out_dir": parent_job["out_dir"],
        "session_id": parent_job["session_id"],
        "source_remote": bool(parent_job.get("source_remote")),
        "prompt_preview": "",
        "model_type": params["model_type"],
        "generation_mode": "image",
        "resource_intent": "generation",
        "resource_execution": "standard",
        "preemption_mode": "none",
        "resource_state": "queued",
        "execution_attempt": 1,
        "parent_job_id": str(parent_job.get("id") or ""),
        "logical_job_kind": "reference_pack_child",
        "requested_outputs": 1,
        "queue_priority": int(parent_job.get("queue_priority", 0) or 0),
        "queue_held": bool(parent_job.get("queue_held", False)),
        "hold_after_output": bool(
            parent_job.get("hold_after_output", False)
        ),
    }
    thread = _queue_recovery_register_and_publish(
        child,
        recovery_kind="studio_generation",
        thread_name=f"reference-panel-{child_id}",
    )
    while thread.is_alive():
        thread.join(timeout=0.1)
        snapshot = snapshot_job(child)
        parent_hold = bool(parent_job.get("hold_after_output", False))
        child_hold = bool(snapshot.get("hold_after_output", False))
        # Once registered, the child is the scheduler authority. A deferred
        # parent hold may still be forwarded, but a child-targeted UI hold or
        # resume must never be overwritten by stale parent orchestration state.
        if parent_hold and not child_hold and snapshot.get("status") in {
            "queued", "running",
        }:
            forwarded = set_job_hold(child, True)
            snapshot = snapshot_job(child)
            if forwarded is not None:
                set_job_hold(parent_job, False)
        if snapshot.get("status") == "queued" and snapshot.get("queue_held"):
            if parent_job.get("hold_after_output", False):
                set_job_hold(parent_job, False)
        child_progress = max(0.0, min(100.0, float(snapshot.get("progress") or 0)))
        overall = ((step - 1) + (child_progress / 100.0)) / max(1, total_steps) * 100.0
        child_resource_state = str(snapshot.get("resource_state") or "queued")
        if child_resource_state not in {
            "queued", "admitted", "running", "blocked", "released",
        }:
            child_resource_state = "queued"
        if not update_job(
            parent_job,
            progress=min(99.0, overall),
            step=step,
            total_steps=total_steps,
            resource_intent="text",
            resource_execution="standard",
            resource_state=child_resource_state,
            phase=phase,
            message=(
                str(snapshot.get("message") or phase)
                if child_resource_state in {"queued", "blocked"}
                else f"{phase} · {child_progress:.0f}%"
            ),
        ):
            request_cancel(child, job_id=child_id, active_states=_active_gen_states)
    snapshot = snapshot_job(child)
    if snapshot.get("status") != "completed":
        failure_updates = _project_reference_child_failure_updates(snapshot)
        update_job(
            parent_job,
            resource_intent="text",
            resource_execution="standard",
            resource_state="blocked",
            message=failure_updates.get(
                "message", "Reference image child did not complete",
            ),
            **{
                key: value for key, value in failure_updates.items()
                if key != "message"
            },
        )
        raise RuntimeError("reference_image_generation_failed")
    candidates = []
    root = os.path.realpath(str(parent_job["out_dir"]))
    for filename in snapshot.get("output_files") or []:
        if not isinstance(filename, str) or os.path.basename(filename) != filename:
            continue
        lexical_path = os.path.join(root, filename)
        path = os.path.realpath(lexical_path)
        if (
            not os.path.islink(lexical_path)
            and os.path.dirname(path) == root
            and os.path.isfile(path)
            and os.path.splitext(path)[1].lower() in _PROJECT_REFERENCE_IMAGE_EXTENSIONS
        ):
            candidates.append(path)
    if len(candidates) != 1:
        raise RuntimeError("reference_image_output_invalid")
    artifact_metadata = dict(artifact_metadata or {
        "schema_version": 2,
        "planner_version": "reference-pack-v2",
        "role": role,
        "index": 0,
        "model": params["model_type"],
        "provenance": {
            "strategy": "local_generation",
            "version": "reference-pack-v2",
            "anchor_role": None,
        },
        "reason_codes": [],
    })
    _write_project_reference_sidecar(
        candidates[0],
        parent_job=parent_job,
        model_type=params["model_type"],
        artifact_metadata=artifact_metadata,
    )
    if not _project_reference_wait_at_output_boundary(parent_job, "sheet"):
        raise RuntimeError("reference_job_cancelled")
    return candidates[0]


def _project_reference_runtime_intelligence_selection(
    request, config, selection, *, purpose,
):
    """Resolve a sealed Studio selection to private load arguments in-worker."""
    sealed = _project_reference_seal_intelligence_selection(selection)
    model_id = sealed.get("resolved_model")
    if model_id in {None, "deterministic"}:
        return None
    recipe = config.get("intelligence_recipe")
    if (
        purpose == "planning"
        and isinstance(recipe, dict)
        and model_id == recipe.get("id")
        and isinstance(recipe.get("model_id"), str)
    ):
        model_id = recipe["model_id"]
    resolver = globals().get("_resolve_llm_chat_model")
    if not callable(resolver):
        raise RuntimeError("reference_intelligence_resolver_unavailable")
    runtime = resolver(request, model_id)
    if runtime.get("provider") != sealed.get("resolved_provider"):
        raise RuntimeError("reference_intelligence_provider_changed")
    if purpose == "review":
        exact_recipe = (
            recipe
            if config.get("intelligence_policy") == "uncensored_auto"
            and isinstance(recipe, dict)
            else None
        )
        if (
            runtime.get("vision_capable") is not True
            or runtime.get("response_model_id") != sealed.get("resolved_model")
            or (
                exact_recipe is not None
                and (
                    sealed.get("resolved_model") != exact_recipe.get("model_id")
                    or runtime.get("model_id") != exact_recipe.get("model_id")
                    or runtime.get("provider") != "local"
                )
            )
        ):
            raise RuntimeError("review_unavailable")
    return runtime


def _project_reference_run_planning(request, parent_job, plan, config):
    """Run and validate the queued structured planning phase when selected."""
    from services import llm_service
    from services.director.policies import build_visual_style_default_block
    from services.reference_sheets import apply_reference_pack_role_briefs

    selection = config["planning"]
    reference_params = parent_job["params"]["reference_pack"]
    try:
        runtime = _project_reference_runtime_intelligence_selection(
            request, config, selection, purpose="planning",
        )
    except Exception:
        if selection.get("requested_model") != "auto":
            raise
        reference_params["planning_status"] = "deterministic_fallback"
        recipe = reference_params.get("intelligence_recipe")
        if isinstance(recipe, dict):
            recipe["status"] = "deterministic_fallback"
        return plan
    if runtime is None:
        reference_params["planning_status"] = "deterministic"
        return plan
    schema = {
        "type": "object",
        "additionalProperties": False,
        "required": [
            "schema_version", "reference_type", "preset",
            "anchor_basis", "ordered_roles", "role_briefs",
        ],
        "properties": {
            "schema_version": {"const": 2},
            "reference_type": {"const": plan.reference_type},
            "preset": {"const": plan.preset},
            "anchor_basis": {"const": plan.anchor_basis},
            "ordered_roles": {
                "type": "array",
                "items": {
                    "type": "string",
                    "enum": list(plan.sheet_roles),
                },
                "minItems": len(plan.sheet_roles),
                "maxItems": len(plan.sheet_roles),
            },
            "role_briefs": {
                "type": "array",
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["role", "brief"],
                    "properties": {
                        "role": {
                            "type": "string",
                            "enum": list(plan.sheet_roles),
                        },
                        "brief": {
                            "type": "string",
                            "minLength": 1,
                            "maxLength": 500,
                        },
                    },
                },
                "minItems": len(plan.sheet_roles),
                "maxItems": len(plan.sheet_roles),
            },
        },
    }

    def progress(_event):
        if not is_cancel_requested(parent_job):
            update_job(
                parent_job,
                phase="Planning reference pack",
                message="Planning sealed Reference deliverables",
            )

    runner = globals().get("_run_llm_with_selection")
    if not callable(runner):
        raise RuntimeError("reference_intelligence_runner_unavailable")
    operation = llm_service.generate
    if runtime.get("provider") == "local":
        def operation(*args, **kwargs):
            try:
                return llm_service.generate(*args, **kwargs)
            finally:
                # This runs inside loaded_model_lease's re-entrant turn lock,
                # so no new chat can begin between inference and release.
                llm_service.unload_model()
    cpu_lane_options = (
        {
            "_cpu_text_job": parent_job,
            "_cpu_text_operation": "reference_planning",
            "_cpu_text_text_only": True,
        }
        if getattr(runner, "_maestro_cpu_text_lane", False)
        else {}
    )
    try:
        raw = runner(
            runtime,
            operation,
            (
                "Produce bounded per-sheet execution briefs for this Reference "
                "Studio request. Do not add, remove, or reorder deliverables; "
                "do not contradict authored facts or invent identity-bearing "
                "facts. Generic may clarify constraints and brainstorming may "
                "suggest non-identity presentation ideas.\n"
                f"Reference request:\n{plan.creative_request}"
            ),
            system_prompt=(
                "Return only the strict server-provided Reference Pack schema. "
                "The server owns all bounds and role ordering.\n\n"
                + build_visual_style_default_block()
            ),
            max_new_tokens=384,
            temperature=0.2,
            top_p=0.9,
            enable_thinking=False,
            json_schema=schema,
            progress_callback=progress,
            **cpu_lane_options,
        )
        parsed = json.loads(raw) if isinstance(raw, str) else raw
        fixed = {
            "schema_version": 2,
            "reference_type": plan.reference_type,
            "preset": plan.preset,
            "anchor_basis": plan.anchor_basis,
            "ordered_roles": list(plan.sheet_roles),
        }
        if not isinstance(parsed, dict) or any(
            parsed.get(key) != value for key, value in fixed.items()
        ) or set(parsed) != {*fixed, "role_briefs"}:
            raise RuntimeError("reference_planner_output_invalid")
        raw_briefs = parsed.get("role_briefs")
        if (
            not isinstance(raw_briefs, list)
            or [item.get("role") for item in raw_briefs if isinstance(item, dict)]
            != list(plan.sheet_roles)
        ):
            raise RuntimeError("reference_planner_output_invalid")
        planned = apply_reference_pack_role_briefs(
            plan,
            {item["role"]: item.get("brief") for item in raw_briefs},
        )
        reference_params.update(planned.public_preview(
            candidate_count=int(reference_params.get("candidate_count") or 1),
        ))
        # The bounded briefs remain private; only their content-free immutable
        # seal enters recovery/retry provenance.
        reference_params["role_brief_seal"] = planned.role_brief_seal
        reference_params["planning_status"] = "validated"
        return planned
    except Exception:
        is_auto = selection.get("requested_model") == "auto"
        if not is_auto:
            raise
        reference_params["planning_status"] = "deterministic_fallback"
        recipe = reference_params.get("intelligence_recipe")
        if isinstance(recipe, dict):
            recipe["status"] = "deterministic_fallback"
        return plan


def _project_reference_authored_prompt_fragment(authored_contract) -> str:
    """Render only the sealed role-scoped authored facts needed by a callback."""
    parts = []
    style = getattr(authored_contract, "style", None)
    if isinstance(style, str) and style:
        parts.append(f"Authored style: {style}")
    for field, items in getattr(authored_contract, "type_fields", ()) or ():
        labels = [
            item.label for item in items
            if isinstance(getattr(item, "label", None), str) and item.label
        ]
        if labels:
            parts.append(f"Authored {field}: {'; '.join(labels)}")
    callout_labels = [
        item.label
        for item in getattr(authored_contract, "detail_callouts", ()) or ()
        if isinstance(getattr(item, "label", None), str) and item.label
    ]
    if callout_labels:
        parts.append(f"Authored detail callouts: {'; '.join(callout_labels)}")
    character_facts = getattr(authored_contract, "character_facts", None)
    gender = getattr(character_facts, "gender", None)
    if isinstance(gender, str) and gender:
        parts.append(f"Authored character gender: {gender}")
    age = getattr(character_facts, "age", None)
    if type(age) is int:
        parts.append(f"Authored character age in years: {age}")
    anatomy = tuple(
        item
        for item in (
            getattr(character_facts, "explicit_anatomy", ()) or ()
        )
        if isinstance(item, str) and item
    )
    if anatomy:
        parts.append(
            f"Authored role-local anatomy: {'; '.join(anatomy)}"
        )
    return "\n".join(parts)


def _project_reference_selected_reviewer(
    request, parent_job, review_request, config,
):
    """Load the exact review selection in its queued fidelity phase."""
    from services import llm_service

    runtime = _project_reference_runtime_intelligence_selection(
        request, config, config["review_selection"], purpose="review",
    )
    if runtime is None:
        raise RuntimeError("review_unavailable")
    runner = globals().get("_run_llm_with_selection")
    if not callable(runner):
        raise RuntimeError("review_unavailable")
    operation = llm_service.generate
    if runtime.get("provider") == "local":
        def operation(*args, **kwargs):
            try:
                if config.get("intelligence_policy") == "uncensored_auto":
                    recipe = config.get("intelligence_recipe")
                    status = llm_service.get_status()
                    if (
                        not isinstance(recipe, dict)
                        or runtime.get("model_id") != recipe.get("model_id")
                        or runtime.get("provider") != "local"
                        or status.get("loaded") is not True
                        or status.get("model_id") != recipe.get("model_id")
                        or str(status.get("provider") or "local") != "local"
                        or status.get("vision_available") is not True
                    ):
                        raise RuntimeError("review_unavailable")
                return llm_service.generate(*args, **kwargs)
            finally:
                llm_service.unload_model()
    authored_fragment = _project_reference_authored_prompt_fragment(
        review_request.authored_contract,
    )
    raw = runner(
            runtime,
            operation,
            prompt=(
                f"{review_request.instruction}\n"
                f"Authored request: {review_request.creative_request}\n"
                f"Question: {review_request.question}\n"
                f"Target role: {review_request.target_role}\n"
                "Ordered attachment roles: "
                f"{json.dumps(list(review_request.sheet_roles))}\n"
                "Sealed authored role contract:\n"
                f"{authored_fragment or '(no additional authored fields)'}"
            ),
            system_prompt=(
                "Answer only the current sealed fidelity question against the "
                "supplied outputs and role-scoped authored contract. Return one "
                "strict JSON Boolean and no other fields."
            ),
            image_paths=[str(path) for path in review_request.sheet_paths],
            max_new_tokens=512,
            temperature=0.1,
            top_p=0.9,
            enable_thinking=False,
            json_schema=dict(review_request.response_schema),
        )
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except (TypeError, ValueError) as error:
            raise RuntimeError("reference_reviewer_boolean_invalid") from error
    if type(raw) is not bool:
        raise RuntimeError("reference_reviewer_boolean_invalid")
    return raw


def _project_reference_public_quality(
    result, *, recommended: bool, recommendation_basis: str | None,
) -> dict:
    """Return a compact, closed publication assessment for one candidate."""
    review = getattr(result, "review", None)
    assessment = getattr(review, "fidelity_assessment", None)
    if assessment is None:
        return {
            "status": "review_unavailable",
            "warning": "Fidelity review was unavailable; this result is ungraded.",
            "review_deferred": True,
            "assessment": None,
            "recommended": bool(recommended),
            "recommendation_basis": recommendation_basis,
        }
    public = assessment.public_metadata()
    residual_count = public["residual_count"]
    return {
        "status": "pass" if residual_count == 0 else "residual",
        "warning": (
            None if residual_count == 0 else
            "Fidelity review found residual differences in this result."
        ),
        "review_deferred": False,
        "assessment": {
            key: public[key] for key in (
                "version", "assessment_class", "worst_severity",
                "residual_count", "score_basis_points", "status",
                "dimension_checks", "failed_roles", "reason_codes",
            )
        },
        "recommended": bool(recommended),
        "recommendation_basis": recommendation_basis,
    }


def _project_reference_source_identity(path) -> dict:
    """Seal one generated source independently of reviewer availability."""
    try:
        before = os.lstat(path)
        if (
            not stat.S_ISREG(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or before.st_nlink != 1
        ):
            raise OSError("unsafe Reference artifact")
        size, digest = _recovery_sha256_file(path)
        after = os.lstat(path)
        if (
            not stat.S_ISREG(after.st_mode)
            or stat.S_ISLNK(after.st_mode)
            or after.st_nlink != 1
            or (before.st_dev, before.st_ino, before.st_size)
                != (after.st_dev, after.st_ino, after.st_size)
            or size != after.st_size
        ):
            raise OSError("Reference artifact changed")
    except OSError as error:
        raise RuntimeError("reference_pack_artifact_integrity_failed") from error
    return {
        "device": after.st_dev,
        "inode": after.st_ino,
        "size": size,
        "sha256": digest,
    }


def _attach_project_reference_result(
    *, asset_id, result, parent_job, candidate_index, candidate_count,
    parent_variant_id, recommended=False, recommendation_basis=None,
):
    if is_cancel_requested(parent_job):
        raise RuntimeError("reference_job_cancelled")
    artifacts = list(result.artifacts)
    expected_output_roles = getattr(
        result.plan, "output_roles", result.plan.sheet_roles,
    )
    if (
        not artifacts
        or tuple(item.role for item in artifacts) != expected_output_roles
        or [item.index for item in artifacts] != list(range(len(artifacts)))
    ):
        raise RuntimeError("reference_pack_output_invalid")
    policy = public_output_policy(parent_job.get("access_policy") or {})
    lineage = {
        "parent_job_id": str(parent_job.get("id") or ""),
        "candidate_index": candidate_index + 1,
        "candidate_count": candidate_count,
        "pack_sheet_count": len(artifacts),
        "parent_asset_id": asset_id,
        "parent_variant_id": parent_variant_id or None,
    }
    reference_request = (
        (parent_job.get("params") or {}).get("reference_pack") or {}
    )
    model_metadata = {
        "generation_model": str(
            reference_request.get("generation_model")
            or result.plan.generation_model
        ),
    }
    editor_model_type = reference_request.get("editor_model")
    if isinstance(editor_model_type, str) and editor_model_type:
        model_metadata["editor_model"] = editor_model_type
    reference_metadata = {
        **result.public_metadata(),
        **model_metadata,
        "explicit_output": bool(policy.get("explicit")),
        "explicit_convenience": bool(
            getattr(result.plan, "explicit_convenience", False)
        ),
        "planning_status": str(
            reference_request.get("planning_status") or "deterministic"
        ),
        "quality": _project_reference_public_quality(
            result,
            recommended=bool(recommended),
            recommendation_basis=recommendation_basis,
        ),
    }
    review = getattr(result, "review", None)
    artifact_seals = tuple(getattr(review, "artifact_seals", ()) or ())
    seal_by_index = {
        seal.index: seal for seal in artifact_seals
        if type(getattr(seal, "index", None)) is int
    }
    if artifact_seals and (
        len(seal_by_index) != len(artifacts)
        or any(
            getattr(seal_by_index.get(artifact.index), "role", None)
            != artifact.role
            for artifact in artifacts
        )
    ):
        raise RuntimeError("reference_pack_review_seal_invalid")
    outputs = []
    for artifact in artifacts:
        artifact_metadata = artifact.public_metadata()
        # Visual concealment is deliberately orthogonal to access control.
        # Clients may blur this output initially, while only ``policy`` decides
        # whether the caller is authorized to fetch it.
        artifact_metadata["private_output"] = bool(result.plan.private_output)
        artifact_metadata["anchor_privacy"] = result.plan.anchor_privacy
        artifact_metadata["initial_blur"] = bool(result.plan.initial_blur)
        artifact_metadata["planning_status"] = reference_metadata[
            "planning_status"
        ]
        schedule = (
            reference_request.get("model_schedules") or {}
        ).get(artifact.model)
        if isinstance(schedule, dict):
            artifact_metadata["schedule"] = dict(schedule)
        output = {
            "source_path": str(artifact.path),
            "label": (
                result.plan.sheets[artifact.index].label
                if artifact.index < len(result.plan.sheets)
                else f"Detail callout {artifact.index - len(result.plan.sheets) + 1}"
            ),
            "metadata": {
                **policy,
                "initial_blur": bool(result.plan.initial_blur),
                "reference_pack": artifact_metadata,
                "lineage": dict(lineage),
            },
        }
        approved = seal_by_index.get(artifact.index)
        if approved is not None:
            output["expected_source_identity"] = {
                "device": approved.device,
                "inode": approved.inode,
                "size": approved.size,
                "sha256": approved.sha256,
            }
        else:
            output["expected_source_identity"] = (
                _project_reference_source_identity(str(artifact.path))
            )
        outputs.append(output)
        _write_project_reference_sidecar(
            str(artifact.path),
            parent_job=parent_job,
            model_type=artifact.model,
            artifact_metadata=artifact_metadata,
        )
        if is_cancel_requested(parent_job):
            raise RuntimeError("reference_job_cancelled")

    variant_id = f"{parent_job['id']}_pack_{candidate_index + 1}"
    variant_spec = {
        "id": variant_id,
        "variant_type": "reference_pack",
        "label": f"Candidate {candidate_index + 1}",
        "outputs": outputs,
        "provenance": {
            "kind": "generated",
            "details": {
                "service": "reference_sheets",
                "version": result.plan.planner_version,
                "job_id": str(parent_job.get("id") or ""),
            },
        },
        "status": "candidate",
        "metadata": {
            "reference_pack": reference_metadata,
            "private_authored_settings": copy.deepcopy(
                result.plan.private_authored_settings()
            ),
            "private_reference_request": (
                _project_reference_private_character_state(
                    getattr(result.plan, "character_profile", None),
                    explicit_convenience=bool(
                        getattr(result.plan, "explicit_convenience", False)
                    ),
                )
            ),
            "job": {
                "id": str(parent_job.get("id") or ""),
                **model_metadata,
                "candidate_index": candidate_index + 1,
                "candidate_count": candidate_count,
                "max_repair_attempts_per_candidate": (
                    result.max_repair_attempts
                ),
                "repair_attempts_used_per_candidate": (
                    result.repair_attempts_used
                ),
                "repair_attempts_requested_total": int(
                    reference_request.get("repair_attempts_requested_total", 0)
                    or 0
                ),
                "repair_attempts_used_total": int(
                    reference_request.get("repair_attempts_used_total", 0)
                    or 0
                ),
                "retry": {
                    "parent_variant_id": parent_variant_id or None,
                    "instruction_present": bool(
                        reference_request.get("retry_instruction_present")
                    ),
                    "plan_seal": result.plan.plan_seal,
                },
            },
            "policy": policy,
            "parent": {
                "asset_id": asset_id,
                "variant_id": parent_variant_id or None,
            },
        },
    }
    return variant_spec


@api.post("/api/v1/projects/{project}/assets/generate")
async def generate_project_asset_references(project: str, request: Request):
    """Queue one or more v2 ordered reference packs for a project card."""
    from services.director.policies import build_visual_style_default_block
    from services.reference_sheets import (
        PackIntelligenceSelection,
        PackLoraSelection,
        PackOperationRoute,
        ReferenceCandidateAssessment,
        build_reference_pack_plan,
        fidelity_attempt_accepted,
        fidelity_rubric_role_applicability,
        recommend_reference_candidate,
    )

    visual_style_default = build_visual_style_default_block()
    project_id, workspace_id = _asset_scope(request, project)
    body = await request.json()
    if isinstance(body, dict):
        fresh_profile = body.get("character_profile")
        if (
            not body.get("parent_variant_id")
            and isinstance(fresh_profile, dict)
            and "commitment_nonce" in fresh_profile
        ):
            raise HTTPException(
                status_code=400,
                detail="Private Reference authoring state requires Retry or Edit",
            )
    try:
        request_id = normalize_request_id(
            body.get("request_id") if isinstance(body, dict) else None
        )
    except ReferenceAdmissionValidationError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    owner_session_id = request.state.maestro_session_id
    existing_asset = None
    existing_asset_type = None
    restored_lora_commitment_contexts = None
    restored_managed_character_callouts = None
    if isinstance(body, dict):
        requested_asset_id = body.get("asset_id")
        if (
            isinstance(requested_asset_id, str)
            and requested_asset_id
            and len(requested_asset_id) <= 128
        ):
            try:
                existing_asset = _require_project_asset_media_access(
                    project_id,
                    workspace_id,
                    requested_asset_id,
                    owner_session_id,
                )
                from services.reference_sheets import normalize_reference_pack_type
                existing_asset_type = normalize_reference_pack_type(
                    existing_asset.get("asset_type")
                )
            except Exception as error:
                raise _project_asset_error(error) from error
        parent_variant_id = body.get("parent_variant_id")
        if (
            existing_asset is not None
            and isinstance(parent_variant_id, str)
            and parent_variant_id
            and len(parent_variant_id) <= 128
        ):
            try:
                _require_project_asset_media_access(
                    project_id,
                    workspace_id,
                    requested_asset_id,
                    owner_session_id,
                    variant_id=parent_variant_id,
                )
                parent_variant = next(
                    item for item in existing_asset.get("variants") or []
                    if item.get("id") == parent_variant_id
                )
                if parent_variant.get("variant_type") == "reference_pack":
                    private_snapshot = _project_reference_private_authored_snapshot(
                        parent_variant,
                    )
                    body = copy.deepcopy(body)
                    body.setdefault(
                        "type_fields", private_snapshot["type_fields"],
                    )
                    client_supplied_callouts = "detail_callouts" in body
                    if not client_supplied_callouts:
                        body["detail_callouts"] = copy.deepcopy(
                            private_snapshot["detail_callouts"],
                        )
                    if "style" in private_snapshot:
                        body.setdefault("style", private_snapshot["style"])
                    parent_profile = private_snapshot.get("character_profile")
                    parent_convenience = private_snapshot.get(
                        "explicit_convenience", False,
                    )
                    if (
                        "explicit_convenience" in body
                        and body.get("explicit_convenience")
                        != parent_convenience
                    ):
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                "Reference explicit convenience cannot change "
                                "on retry"
                            ),
                        )
                    body.setdefault(
                        "explicit_convenience", parent_convenience,
                    )
                    if "character_profile" in body:
                        supplied_profile = body.get("character_profile")
                        if supplied_profile is None:
                            supplied_semantic_profile = None
                        else:
                            from services.reference_sheets import (
                                normalize_character_profile,
                            )
                            supplied = normalize_character_profile(
                                supplied_profile,
                                explicit_convenience=parent_convenience,
                            )
                            supplied_semantic_profile = {
                                "gender": supplied.gender,
                                "age": supplied.age,
                                "explicit_anatomy": list(
                                    supplied.explicit_anatomy
                                ),
                            }
                        parent_semantic_profile = (
                            None if parent_profile is None else {
                                "gender": parent_profile["gender"],
                                "age": parent_profile["age"],
                                "explicit_anatomy": list(
                                    parent_profile["explicit_anatomy"]
                                ),
                            }
                        )
                        if supplied_semantic_profile != parent_semantic_profile:
                            raise HTTPException(
                                status_code=409,
                                detail=(
                                    "Reference character profile cannot "
                                    "change on retry"
                                ),
                            )
                    if parent_profile is not None:
                        body["character_profile"] = copy.deepcopy(
                            parent_profile,
                        )
                    else:
                        body.pop("character_profile", None)
                    restored_managed_character_callouts = copy.deepcopy(
                        private_snapshot.get("managed_character_callouts"),
                    )
                    if (
                        client_supplied_callouts
                        and isinstance(body.get("detail_callouts"), list)
                        and isinstance(
                            restored_managed_character_callouts, dict,
                        )
                    ):
                        managed_entries = (
                            restored_managed_character_callouts.get("entries")
                            or []
                        )
                        managed_ids = {
                            entry.get("managed_id")
                            for entry in managed_entries
                            if isinstance(entry, dict)
                        }
                        if any(
                            isinstance(item, dict)
                            and item.get("custom_id") in managed_ids
                            for item in body["detail_callouts"]
                        ):
                            raise HTTPException(
                                status_code=409,
                                detail="Managed character callouts are server-owned",
                            )
                        for entry in managed_entries:
                            if (
                                isinstance(entry, dict)
                                and entry.get("status") == "active"
                            ):
                                body["detail_callouts"].append({
                                    "custom_id": entry["managed_id"],
                                    "label": entry["label"],
                                    "kind": "custom",
                                    "operation": entry["operation"],
                                    "source_role": entry["source_role"],
                                })
                    if (
                        "additional_loras" not in body
                        and isinstance(
                            private_snapshot.get("additional_lora_parameters"),
                            list,
                        )
                    ):
                        restored_loras = []
                        for item in private_snapshot[
                            "additional_lora_parameters"
                        ]:
                            restored = {
                                "id": item["id"],
                                "multiplier": item["multiplier"],
                                "scope": item["scope"],
                            }
                            if item.get("schema_digest") is not None:
                                restored.update({
                                    "parameter_schema_digest": item[
                                        "schema_digest"
                                    ],
                                    "parameter_values": {
                                        value["id"]: value["value"]
                                        for value in item["values"]
                                    },
                                })
                            restored_loras.append(restored)
                        body["additional_loras"] = restored_loras
                        restored_lora_commitment_contexts = {
                            item["id"]: item["commitment_context"]
                            for item in private_snapshot[
                                "additional_lora_parameters"
                            ]
                            if item.get("commitment_context") is not None
                        }
            except Exception as error:
                raise _project_asset_error(error) from error
    config = _project_reference_request_config(
        body,
        request,
        existing_asset_type=existing_asset_type,
        commitment_contexts=restored_lora_commitment_contexts,
        managed_character_callouts=restored_managed_character_callouts,
    )
    _require_remote_visible_models(
        request,
        [config["model_type"], config.get("editor_model_type")],
    )
    _require_model_recipe_terms(
        list(dict.fromkeys(
            model for model in (
                config["model_type"],
                config.get("editor_model_type"),
                config["review_selection"].get("resolved_model"),
                *(
                    route.get("resolved_model")
                    for route in config["operation_routing"]
                ),
            ) if model
        )),
    )
    workspace = project
    job_out_dir = _require_project_access(
        request, workspace, permission="project.generate",
    )
    asset_id = config["asset_id"]
    new_asset_request = not bool(asset_id)

    try:
        if asset_id:
            asset = existing_asset or _require_project_asset_media_access(
                project_id, workspace_id, asset_id, owner_session_id,
            )
            from services.reference_sheets import normalize_reference_pack_type
            try:
                existing_type = normalize_reference_pack_type(asset.get("asset_type"))
            except ValueError as error:
                raise HTTPException(status_code=400, detail="Unsupported reference asset type")
            if body.get("asset_type") is not None and config["asset_type"] != existing_type:
                raise HTTPException(status_code=409, detail="Reference asset type cannot change on retry")
            config["asset_type"] = existing_type
            if config["parent_variant_id"]:
                _require_project_asset_media_access(
                    project_id,
                    workspace_id,
                    asset_id,
                    owner_session_id,
                    variant_id=config["parent_variant_id"],
                )
            asset_spec = {
                "name": asset["name"],
                "asset_type": existing_type,
                "description": asset.get("description") or "",
                "tags": list(asset.get("tags") or []),
            }
            authorized = _public_authorized_project_assets(
                [asset], owner_session_id,
            )
            if not authorized:
                raise HTTPException(status_code=404, detail="Reference asset not found")
            response_asset = authorized[0]
        else:
            asset_id = uuid.uuid4().hex
            asset_spec = {
                "name": config["name"],
                "asset_type": config["asset_type"],
                "description": config["description"],
                "tags": list(config["tags"] or []),
            }
            asset = {**asset_spec, "id": asset_id}
            response_asset = {
                **asset_spec,
                "id": asset_id,
                "provenance": {"kind": "generated", "details": {}},
                "metadata": {},
                "variants": [],
                "pending": True,
            }
    except Exception as error:
        raise _project_asset_error(error) from error

    creative_request = _project_reference_creative_request(asset, config)
    if not creative_request:
        raise HTTPException(status_code=400, detail="Reference request is empty")
    sealed_operation_routing = tuple(
        PackOperationRoute(**item) for item in config["operation_routing"]
    )
    plan = build_reference_pack_plan(
        reference_type=config["asset_type"],
        mode=config["mode"],
        intent=config["intent"],
        depth=config["depth"],
        creative_request=creative_request,
        style=config["style"],
        style_commitment=config["style_commitment"],
        generation_model=config["model_type"],
        editor_model=config.get("editor_model_type"),
        preset=config["preset"],
        sheet_count=(config["sheet_count"] if config["depth"] == "custom" else None),
        sheet_size=config["draft_size"],
        anchor_basis=config["anchor_basis"],
        managed_layout_assist=config["managed_layout_assist"],
        user_lora_count=len(config["activated_loras"]),
        type_fields=config["type_fields"],
        detail_callouts=config["detail_callouts"],
        character_profile=config["character_profile"],
        managed_character_callouts=config["managed_character_callouts"],
        explicit_convenience=config["explicit_convenience"],
        planning=PackIntelligenceSelection(**config["planning"]),
        review_selection=PackIntelligenceSelection(**config["review_selection"]),
        generation_schedule=config["model_schedules"][config["model_type"]],
        editor_schedule=(
            config["model_schedules"][config["editor_model_type"]]
            if config.get("editor_model_type") else None
        ),
        content_capability=config["content_capability"],
        private_output=config["policy"]["private"],
        initial_blur=config["initial_blur"],
        intelligence_policy=config["intelligence_policy"],
        review_contract=config["review_contract"],
        operation_routing=sealed_operation_routing,
    )
    sealed_loras = []
    for selection in config["additional_loras"]:
        roles = []
        if "generation" in selection["resolved_scopes"]:
            roles.extend(
                plan.sheet_roles
                if plan.mode == "draft" else plan.sheet_roles[:1]
            )
        if "editing" in selection["resolved_scopes"] and plan.mode != "draft":
            roles.extend(plan.output_roles[1:])
        sealed_loras.append(PackLoraSelection(
            lora_id=selection["id"],
            multiplier=selection["multiplier"],
            requested_scope=selection["requested_scope"],
            resolved_scopes=tuple(selection["resolved_scopes"]),
            roles=tuple(dict.fromkeys(roles)),
            revision=selection["revision"],
            source_sha256=selection["source_sha256"],
            parameter_schema_digest=selection["parameter_schema_digest"],
            parameter_commitment_context=selection[
                "parameter_commitment_context"
            ],
            parameter_values=tuple(selection["parameter_values"]),
            parameter_values_digest=selection["parameter_values_digest"],
            parameter_expansion_digest=selection["parameter_expansion_digest"],
            skipped_reason=selection["skipped_reason"],
        ))
    if sealed_loras:
        plan = build_reference_pack_plan(
            reference_type=config["asset_type"],
            mode=config["mode"],
            intent=config["intent"],
            depth=config["depth"],
            creative_request=creative_request,
            style=config["style"],
            style_commitment=config["style_commitment"],
            generation_model=config["model_type"],
            editor_model=config.get("editor_model_type"),
            preset=config["preset"],
            sheet_count=(config["sheet_count"] if config["depth"] == "custom" else None),
            sheet_size=config["draft_size"],
            anchor_basis=config["anchor_basis"],
            managed_layout_assist=config["managed_layout_assist"],
            user_lora_count=len(config["activated_loras"]),
            type_fields=config["type_fields"],
            detail_callouts=config["detail_callouts"],
            character_profile=config["character_profile"],
            managed_character_callouts=config["managed_character_callouts"],
            explicit_convenience=config["explicit_convenience"],
            planning=PackIntelligenceSelection(**config["planning"]),
            review_selection=PackIntelligenceSelection(**config["review_selection"]),
            generation_schedule=config["model_schedules"][config["model_type"]],
            editor_schedule=(
                config["model_schedules"][config["editor_model_type"]]
                if config.get("editor_model_type") else None
            ),
            content_capability=config["content_capability"],
            private_output=config["policy"]["private"],
            initial_blur=config["initial_blur"],
            intelligence_policy=config["intelligence_policy"],
            review_contract=config["review_contract"],
            operation_routing=sealed_operation_routing,
            additional_loras=tuple(sealed_loras),
        )

    admission = None
    admission_scope = None
    if request_id is not None:
        operation = (
            "reference.edit.v1"
            if config["asset_id"] and config["edit_instruction"]
            else "reference.retry.v1"
            if config["asset_id"]
            else "reference.fresh.v1"
        )
        admission_scope = {
            "owner_principal": owner_principal_digest(
                _session_secret(), owner_session_id,
            ),
            "project_instance": _queue_recovery_project_identity(
                workspace, job_out_dir,
            ),
            "operation": operation,
            "payload": {
                key: value for key, value in body.items()
                if key != "request_id"
            },
        }
        admission_store = _reference_admission_store()
        try:
            admission = admission_store.begin(
                request_id,
                **admission_scope,
                proposed_job_id=uuid.uuid4().hex,
                proposed_asset_id=asset_id or uuid.uuid4().hex,
            )
            if admission.disposition == "pending":
                deadline = time.monotonic() + min(
                    3.0, admission_store.lease_seconds,
                )
                while admission.disposition == "pending" and (
                    time.monotonic() < deadline
                ):
                    await asyncio.sleep(0.05)
                    admission = admission_store.inspect(
                        request_id, **admission_scope,
                    )
                    if admission is None:
                        raise ReferenceAdmissionPersistenceError(
                            "Reference admission reservation disappeared."
                        )
            if admission.disposition == "failed":
                raise ReferenceAdmissionPersistenceError(
                    "The prior Reference admission failed closed."
                )
            if admission.disposition == "pending":
                raise ReferenceAdmissionPersistenceError(
                    "Reference admission is still being committed."
                )
        except ReferenceAdmissionMismatchError as error:
            raise HTTPException(status_code=409, detail=str(error)) from error
        except ReferenceAdmissionValidationError as error:
            raise HTTPException(status_code=400, detail=str(error)) from error
        except (
            ReferenceAdmissionCapacityError,
            ReferenceAdmissionCorruptionError,
            ReferenceAdmissionPersistenceError,
        ) as error:
            raise HTTPException(status_code=503, detail=str(error)) from error
        asset_id = admission.asset_id
        if config["asset_id"] and asset_id != config["asset_id"]:
            raise HTTPException(
                status_code=503,
                detail="Reference admission identity is unavailable.",
            )
        asset["id"] = asset_id
        # An idempotent acceptance is intentionally a stable, minimal asset
        # envelope.  It never changes when the admitted worker later appends
        # variants, so a lost-response replay is byte-for-byte equivalent.
        response_asset = {
            "id": asset_id,
            "name": "",
            "asset_type": config["asset_type"],
            "description": "",
            "tags": [],
            "provenance": {"kind": "generated", "details": {}},
            "metadata": {},
            "variants": [],
            "pending": True,
        }
    job_id = admission.job_id if admission is not None else uuid.uuid4().hex[:8]

    def admission_response():
        response = {
            "job_id": job_id,
            "asset": copy.deepcopy(response_asset),
        }
        if request_id is None:
            response["plan"] = plan.public_preview(
                candidate_count=config["candidate_count"],
            )
        return response

    if admission is not None and admission.disposition == "replay":
        # The integrity-checked accepted ledger is the durable authority. A
        # terminal job may already have been compacted from queue recovery;
        # the canonical idempotent response contains only its reserved opaque
        # identities and therefore remains reconstructable for the ledger TTL.
        return admission_response()

    if admission is not None and admission.disposition == "resume":
        admitted_job = _jobs.get(job_id)
        admitted_params = (
            admitted_job.get("params", {}).get("reference_pack", {})
            if isinstance(admitted_job, dict) else {}
        )
        recovery_unit = (
            admitted_job.get("recovery_unit")
            if isinstance(admitted_job, dict) else None
        )
        admitted_job_matches = bool(
            _job_owned_by_request(admitted_job, request)
            and admitted_job.get("workspace") == workspace
            and admitted_job.get("logical_job_kind")
                == "reference_pack_parent"
            and (
                admitted_params.get("asset_id") == asset_id
                or isinstance(recovery_unit, dict)
                and recovery_unit.get("asset_id") == asset_id
            )
        )
        if admitted_job_matches:
            try:
                admission_store.accept(
                    request_id,
                    **admission_scope,
                    lease_token=admission.lease_token,
                )
            except (
                ReferenceAdmissionMismatchError,
                ReferenceAdmissionValidationError,
                ReferenceAdmissionCorruptionError,
                ReferenceAdmissionPersistenceError,
            ) as error:
                raise HTTPException(status_code=503, detail=str(error)) from error
            return admission_response()

    repair_budget = 0 if config["mode"] == "draft" else config["max_repair_attempts"]
    review_questions_per_attempt = sum(
        len(applicable_roles)
        for _item_id, applicable_roles in fidelity_rubric_role_applicability(
            plan.reference_type, plan.output_roles,
        )
    )
    # One failed canonical anchor regenerates every authored output in the
    # candidate, while other failed roles repair only one output. Reserve the
    # larger bounded path so step/total never moves backward when the reviewer
    # selects the anchor late in execution.
    operations_per_repair = (
        len(plan.output_roles) + review_questions_per_attempt
    )
    operations_per_candidate = (
        len(plan.output_roles) + review_questions_per_attempt + 1
        + (operations_per_repair * repair_budget)
    )
    total_steps = 1 + operations_per_candidate * config["candidate_count"]
    reference_params = {
        **plan.public_preview(candidate_count=config["candidate_count"]),
        "asset_id": asset_id,
        "review_requested": config["review_selection"]["requested_model"] != "off",
        "max_repair_attempts": repair_budget,
        "max_repair_attempts_per_candidate": repair_budget,
        "repair_attempts_requested_total": repair_budget * config["candidate_count"],
        "repair_attempts_used": 0,
        "repair_attempts_used_total": 0,
        "review_questions_per_attempt": review_questions_per_attempt,
        "review_attempts_requested_per_candidate": repair_budget + 1,
        "review_questions_requested_total": (
            review_questions_per_attempt
            * (repair_budget + 1)
            * config["candidate_count"]
        ),
        "review_questions_used_total": 0,
        "model_schedules": copy.deepcopy(config["model_schedules"]),
        "retry_instruction_present": bool(config["edit_instruction"]),
        "intelligence_recipe": copy.deepcopy(config["intelligence_recipe"]),
        "resource_seal": plan.resource_seal,
        "sealed_additional_loras": [
            {
                "id": item.lora_id,
                "weight": item.multiplier,
                "requested_scope": item.requested_scope,
                "resolved_scopes": list(item.resolved_scopes),
                "roles": list(item.roles),
                "revision": item.revision,
                "source_sha256": item.source_sha256,
                "parameter_schema_digest": item.parameter_schema_digest,
                "parameter_count": len(item.parameter_values),
                "parameter_ids": [
                    parameter_id for parameter_id, _value in item.parameter_values
                ],
                "parameter_values_digest": item.parameter_values_digest,
                "parameter_expansion_digest": item.parameter_expansion_digest,
                "skipped_reason": item.skipped_reason,
            }
            for item in sealed_loras
        ],
        "private_authored_settings": plan.private_authored_settings(),
        "private_reference_request": _project_reference_private_character_state(
            plan.character_profile,
            explicit_convenience=plan.explicit_convenience,
        ),
    }
    job = {
        "id": job_id,
        "status": "queued",
        "progress": 0,
        "step": 0,
        "total_steps": total_steps,
        "phase": "Planning",
        "message": "Queued reference-pack planning",
        "created_at": time.time(),
        "params": {"reference_pack": reference_params},
        "output_files": [],
        "error": None,
        "workspace": workspace,
        "out_dir": job_out_dir,
        "session_id": owner_session_id,
        "access_policy": dict(config["policy"]),
        "private": config["policy"]["private"],
        "explicit": config["policy"]["explicit"],
        "source_remote": bool(_request_remote.get()),
        "prompt_preview": "",
        "model_type": config["model_type"],
        "generation_mode": "image",
        "resource_intent": "text",
        "resource_execution": "standard",
        "preemption_mode": "none",
        "resource_state": "queued",
        "logical_job_kind": "reference_pack_parent",
        "execution_attempt": 1,
        "requested_outputs": len(plan.output_roles) * config["candidate_count"],
    }
    _begin_workspace_operation(project_id)

    def _run_and_attach_candidates(_job_id):
        from services.reference_sheets import (
            create_reference_pack,
        )

        nonlocal plan

        parent_job = _jobs[_job_id]
        completed_sheets = []
        published_variant_ids = []
        replayed_variants = []
        staged_results = []
        step_state = {"value": 0}

        def next_step(phase):
            step_state["value"] += 1
            if not update_job(
                parent_job,
                step=step_state["value"],
                total_steps=total_steps,
                progress=min(99.0, (step_state["value"] - 1) / max(1, total_steps) * 100.0),
                phase=phase,
                message=phase,
            ):
                raise RuntimeError("reference_job_cancelled")
            return step_state["value"]

        try:
            # Planning owns no image or GPU-generation slot. Queue pause/hold
            # remains authoritative, but admitted local text may coexist with
            # one ordinary GPU generation through the dedicated CPU lane.
            while not is_cancel_requested(parent_job):
                queue_state_reader = globals().get("queue_control_state")
                paused = bool(
                    callable(queue_state_reader)
                    and queue_state_reader().get("paused", False)
                )
                if not parent_job.get("queue_held", False) and not paused:
                    break
                time.sleep(0.1)
            if not try_start(
                parent_job,
                message="Planning sealed reference packs",
                phase="Planning",
                total_steps=total_steps,
            ):
                return
            next_step("Planning sealed reference packs")

            # Freeze potentially large user LoRAs only after durable job
            # registration. Re-resolving here also detects selection drift
            # before either an intelligence or image model is loaded.
            if config["additional_loras"]:
                update_job(
                    parent_job,
                    phase="Freezing reference resources",
                    message="Freezing selected Reference resources",
                )
                frozen_loras = _project_reference_resolve_additional_loras(
                    body.get("additional_loras"),
                    generation_model=config["model_type"],
                    editor_model=config.get("editor_model_type"),
                    operation_models=config["operation_models"],
                    operation_roles=config["operation_roles"],
                    reference_type=config["asset_type"],
                    freeze=True,
                    commitment_contexts={
                        item["id"]: item["parameter_commitment_context"]
                        for item in config["additional_loras"]
                        if item.get("parameter_commitment_context") is not None
                    },
                )
                pending_by_id = {
                    item["id"]: item for item in config["additional_loras"]
                }
                if (
                    len(pending_by_id) != len(frozen_loras)
                    or any(
                        selection["id"] not in pending_by_id
                        or any(
                            pending_by_id[selection["id"]].get(key)
                            != selection.get(key)
                            for key in (
                                "multiplier", "requested_scope",
                                "resolved_scopes", "parameter_schema_digest",
                                "expected_source_sha256",
                                "parameter_commitment_context",
                                "parameter_values", "parameter_values_digest",
                                "parameter_expansion_digest", "skipped_reason",
                            )
                        )
                        for selection in frozen_loras
                    )
                ):
                    raise RuntimeError("reference_lora_selection_changed")
                frozen_selections = []
                for selection in frozen_loras:
                    roles = []
                    if "generation" in selection["resolved_scopes"]:
                        roles.extend(
                            plan.sheet_roles
                            if plan.mode == "draft" else plan.sheet_roles[:1]
                        )
                    if (
                        "editing" in selection["resolved_scopes"]
                        and plan.mode != "draft"
                    ):
                        roles.extend(plan.output_roles[1:])
                    frozen_selections.append(PackLoraSelection(
                        lora_id=selection["id"],
                        multiplier=selection["multiplier"],
                        requested_scope=selection["requested_scope"],
                        resolved_scopes=tuple(selection["resolved_scopes"]),
                        roles=tuple(dict.fromkeys(roles)),
                        revision=selection["revision"],
                        source_sha256=selection["source_sha256"],
                        parameter_schema_digest=selection[
                            "parameter_schema_digest"
                        ],
                        parameter_commitment_context=selection[
                            "parameter_commitment_context"
                        ],
                        parameter_values=tuple(selection["parameter_values"]),
                        parameter_values_digest=selection[
                            "parameter_values_digest"
                        ],
                        parameter_expansion_digest=selection[
                            "parameter_expansion_digest"
                        ],
                        skipped_reason=selection["skipped_reason"],
                    ))
                config["additional_loras"] = frozen_loras
                plan = build_reference_pack_plan(
                    reference_type=config["asset_type"],
                    mode=config["mode"],
                    intent=config["intent"],
                    depth=config["depth"],
                    creative_request=creative_request,
                    style=config["style"],
                    style_commitment=config["style_commitment"],
                    generation_model=config["model_type"],
                    editor_model=config.get("editor_model_type"),
                    preset=config["preset"],
                    sheet_count=(
                        config["sheet_count"]
                        if config["depth"] == "custom" else None
                    ),
                    sheet_size=config["draft_size"],
                    anchor_basis=config["anchor_basis"],
                    managed_layout_assist=config["managed_layout_assist"],
                    user_lora_count=len(config["activated_loras"]),
                    type_fields=config["type_fields"],
                    detail_callouts=config["detail_callouts"],
                    character_profile=config["character_profile"],
                    managed_character_callouts=config[
                        "managed_character_callouts"
                    ],
                    explicit_convenience=config["explicit_convenience"],
                    planning=PackIntelligenceSelection(**config["planning"]),
                    review_selection=PackIntelligenceSelection(
                        **config["review_selection"]
                    ),
                    generation_schedule=config["model_schedules"][config["model_type"]],
                    editor_schedule=(
                        config["model_schedules"][config["editor_model_type"]]
                        if config.get("editor_model_type") else None
                    ),
                    content_capability=config["content_capability"],
                    private_output=config["policy"]["private"],
                    initial_blur=config["initial_blur"],
                    intelligence_policy=config["intelligence_policy"],
                    review_contract=config["review_contract"],
                    operation_routing=sealed_operation_routing,
                    additional_loras=tuple(frozen_selections),
                )
                frozen_public = plan.public_preview(
                    candidate_count=config["candidate_count"]
                )
                parent_job["params"]["reference_pack"].update(frozen_public)
                parent_job["params"]["reference_pack"]["resource_seal"] = (
                    plan.resource_seal
                )
                parent_job["params"]["reference_pack"]["sealed_additional_loras"] = [
                    {
                        "id": item.lora_id,
                        "weight": item.multiplier,
                        "requested_scope": item.requested_scope,
                        "resolved_scopes": list(item.resolved_scopes),
                        "roles": list(item.roles),
                        "revision": item.revision,
                        "source_sha256": item.source_sha256,
                        "parameter_schema_digest": item.parameter_schema_digest,
                        "parameter_count": len(item.parameter_values),
                        "parameter_ids": [
                            parameter_id
                            for parameter_id, _value in item.parameter_values
                        ],
                        "parameter_values_digest": item.parameter_values_digest,
                        "parameter_expansion_digest": item.parameter_expansion_digest,
                        "skipped_reason": item.skipped_reason,
                    }
                    for item in frozen_selections
                ]
            plan = _project_reference_run_planning(
                request, parent_job, plan, config,
            )
            current_attempt = int(
                parent_job.get("execution_attempt") or 1
            )
            transition = globals().get("transition_resource_execution")
            if callable(transition):
                if transition(
                    parent_job,
                    expected_execution_attempt=current_attempt,
                    intent="text",
                    execution="standard",
                    preemption_mode="none",
                    state="queued",
                    message="Reference planning complete; waiting for image child",
                ) is None:
                    raise RuntimeError("reference_job_cancelled")
            else:
                # Isolated legacy harnesses have no durability adapter.
                parent_job.update({
                    "resource_intent": "text",
                    "resource_execution": "standard",
                    "preemption_mode": "none",
                    "resource_state": "queued",
                })
            for candidate_index in range(config["candidate_count"]):
                candidate_review_progress = {"questions": 0}
                variant_id = f"{job_id}_pack_{candidate_index + 1}"
                try:
                    current_asset = _project_asset_store().get_asset(
                        project_id, workspace_id, asset_id,
                    )
                except Exception:
                    current_asset = None
                existing_variant = next((
                    item for item in (current_asset or {}).get("variants") or []
                    if item.get("id") == variant_id
                ), None)
                if existing_variant is not None:
                    try:
                        _project_reference_validate_committed_variant(
                            _project_asset_store(),
                            project_id,
                            workspace_id,
                            existing_variant,
                            job_id=job_id,
                            candidate_index=candidate_index + 1,
                            candidate_count=config["candidate_count"],
                            plan_seal=plan.plan_seal,
                            mandatory_review=config["mandatory_review"],
                            explicit_output=config["policy"]["explicit"],
                        )
                    except Exception:
                        raise RuntimeError("reference_pack_variant_collision")
                    replayed_variants.append(existing_variant)
                    step_state["value"] += operations_per_candidate
                    continue

                def adjusted_seed(index):
                    if config["seed"] < 0:
                        return -1
                    return min(
                        (2 ** 63) - 1,
                        config["seed"] + candidate_index * 100 + index,
                    )

                def artifact_seed_metadata(sheet_request):
                    metadata = {
                        "schema_version": 2,
                        "planner_version": "reference-pack-v2",
                        "role": sheet_request.role,
                        "index": sheet_request.index,
                        "model": sheet_request.model,
                        "provenance": {
                            "strategy": sheet_request.strategy,
                            "version": "reference-pack-v2",
                            "anchor_role": plan.anchor_role,
                        },
                        "schedule": dict(config["model_schedules"][sheet_request.model]),
                        "reason_codes": [],
                    }
                    if sheet_request.detail_custom_id is not None:
                        metadata["detail"] = {
                            "custom_id": sheet_request.detail_custom_id,
                            "kind": sheet_request.detail_kind,
                            "source_role": sheet_request.source_role,
                            "requested_operation": sheet_request.requested_operation,
                            "resolved_operation": sheet_request.operation,
                            "label_digest": sheet_request.detail_label_digest,
                            "seal": sheet_request.detail_seal,
                        }
                    return metadata

                def generate_sheet(sheet_request):
                    phase = (
                        f"Generating pack {candidate_index + 1}/{config['candidate_count']} "
                        f"sheet {sheet_request.index + 1}/{sheet_request.sheet_count}"
                    )
                    step = next_step(phase)
                    authored_fragment = _project_reference_authored_prompt_fragment(
                        sheet_request.authored_contract,
                    )
                    if sheet_request.strategy == "canonical_anchor":
                        prompt = (
                            f"Create the canonical {sheet_request.reference_type} reference sheet. "
                            f"Authored request: {sheet_request.creative_request}. "
                            f"Anchor basis: {sheet_request.anchor_basis}. Role: {sheet_request.label}. "
                            f"Objective: {sheet_request.objective}. This is the single immutable "
                            "visual source for every derivative in this candidate pack. Use a "
                            "deterministic clean reference layout and preserve exact requested "
                            f"details. {visual_style_default}"
                        )
                    else:
                        prompt = (
                            f"Create one Draft compatibility sheet for this {sheet_request.reference_type}. "
                            f"Authored request: {sheet_request.creative_request}. "
                            f"Role: {sheet_request.label}. Objective: {sheet_request.objective}. "
                            "This Draft is an independent one-shot and does not claim anchored "
                            f"cross-sheet continuity. {visual_style_default}"
                        )
                    if authored_fragment:
                        prompt = (
                            f"{prompt}\nSealed authored role contract:\n"
                            f"{authored_fragment}"
                        )
                    params = _project_reference_generation_params(
                        config,
                        model_type=sheet_request.model,
                        prompt=prompt,
                        size=sheet_request.sheet_size,
                        seed=adjusted_seed(sheet_request.index),
                        operation_scope="generation",
                        operation_role=sheet_request.role,
                    )
                    return _run_project_reference_image_job(
                        parent_job, params,
                        role=sheet_request.role,
                        phase=phase,
                        step=step,
                        total_steps=total_steps,
                        artifact_metadata=artifact_seed_metadata(sheet_request),
                    )

                def edit_sheet(primary_path, anchor_path, sheet_request):
                    phase = (
                        f"Deriving pack {candidate_index + 1}/{config['candidate_count']} "
                        f"sheet {sheet_request.index + 1}/{sheet_request.sheet_count}"
                    )
                    step = next_step(phase)
                    authored_fragment = _project_reference_authored_prompt_fragment(
                        sheet_request.authored_contract,
                    )
                    exact_guard = (
                        "Do not invent, reconstruct, or infer absent identity-bearing detail. "
                        if sheet_request.intent == "exact_spec" else ""
                    )
                    prompt = (
                        "Create a new ordered reference sheet guided by the attached primary "
                        "source and full canonical anchor. Preserve identity, geometry, design, "
                        f"materials, and palette. Authored request: {sheet_request.creative_request}. "
                        f"{exact_guard}Role: {sheet_request.label}. "
                        f"Objective: {sheet_request.objective}. Requested detail operation: "
                        f"{sheet_request.operation or 'enhance'}. {visual_style_default}"
                    )
                    if authored_fragment:
                        prompt = (
                            f"{prompt}\nSealed authored role contract:\n"
                            f"{authored_fragment}"
                        )
                    params = _project_reference_generation_params(
                        config,
                        model_type=sheet_request.model,
                        prompt=prompt,
                        size=sheet_request.sheet_size,
                        seed=adjusted_seed(sheet_request.index),
                        reference_path=[primary_path, anchor_path],
                        operation_scope="editing",
                        operation_role=sheet_request.role,
                    )
                    return _run_project_reference_image_job(
                        parent_job, params,
                        role=sheet_request.role,
                        phase=phase,
                        step=step,
                        total_steps=total_steps,
                        artifact_metadata=artifact_seed_metadata(sheet_request),
                    )

                def repair_sheet(original_path, anchor_path, repair_request):
                    repair_role_index = plan.output_roles.index(
                        repair_request.role
                    )
                    public_repair_role = plan.public_output_roles[
                        repair_role_index
                    ]
                    repair_label = (
                        "managed character detail"
                        if public_repair_role != repair_request.role
                        else repair_request.label
                    )
                    phase = (
                        f"Repairing pack {candidate_index + 1}/{config['candidate_count']} "
                        f"sheet {repair_label}"
                    )
                    step = next_step(phase)
                    authored_fragment = _project_reference_authored_prompt_fragment(
                        repair_request.authored_contract,
                    )
                    exact_guard = (
                        "Do not invent absent identity-bearing detail. "
                        if config["intent"] == "exact_spec" else ""
                    )
                    prompt = (
                        "Create one corrected reference-guided replacement sheet. "
                        f"Authored request: {repair_request.creative_request}. "
                        f"Role: {repair_request.label}. Objective: {repair_request.objective}. "
                        f"Correction reasons: {', '.join(repair_request.reason_codes)}. "
                        f"{exact_guard}Preserve the immutable canonical anchor, requested "
                        f"design, and layout. {visual_style_default}"
                    )
                    if authored_fragment:
                        prompt = (
                            f"{prompt}\nSealed authored role contract:\n"
                            f"{authored_fragment}"
                        )
                    params = _project_reference_generation_params(
                        config,
                        model_type=repair_request.model,
                        prompt=prompt,
                        size=repair_request.sheet_size,
                        seed=adjusted_seed(plan.output_roles.index(repair_request.role) + 50),
                        reference_path=[original_path, anchor_path],
                        operation_scope="editing",
                        operation_role=repair_request.role,
                    )
                    return _run_project_reference_image_job(
                        parent_job, params,
                        role=repair_request.role,
                        phase=phase,
                        step=step,
                        total_steps=total_steps,
                    )

                def reviewer(review_request):
                    candidate_review_progress["questions"] += 1
                    review_call = candidate_review_progress["questions"]
                    question_index = (
                        (review_call - 1) % review_questions_per_attempt
                    ) + 1
                    attempt_index = (
                        (review_call - 1) // review_questions_per_attempt
                    ) + 1
                    next_step(
                        f"Reviewing pack {candidate_index + 1}/"
                        f"{config['candidate_count']} fidelity question "
                        f"{question_index}/{review_questions_per_attempt}, "
                        f"attempt {attempt_index}/{repair_budget + 1}"
                    )
                    update_job(
                        parent_job,
                        phase="Reviewing fidelity",
                        message=(
                            f"Reviewing pack {candidate_index + 1}/"
                            f"{config['candidate_count']} fidelity question "
                            f"{question_index}/{review_questions_per_attempt}, "
                            f"attempt {attempt_index}/{repair_budget + 1}"
                        ),
                    )
                    if config["review_selection"]["resolved_model"] is None:
                        raise RuntimeError("review_unavailable")
                    return _project_reference_selected_reviewer(
                        request, parent_job, review_request, config,
                    )

                result = create_reference_pack(
                    plan,
                    generate_sheet=generate_sheet,
                    edit_sheet=edit_sheet if config["mode"] != "draft" else None,
                    reviewer=reviewer,
                    repair_sheet=repair_sheet if config["mode"] != "draft" else None,
                    max_repair_attempts=repair_budget,
                )
                reference_job_params = parent_job["params"]["reference_pack"]
                reference_job_params["repair_attempts_used"] += (
                    result.repair_attempts_used
                )
                reference_job_params["repair_attempts_used_total"] += (
                    result.repair_attempts_used
                )
                reference_job_params["review_questions_used_total"] += (
                    candidate_review_progress["questions"]
                )
                reference_job_params["review"] = {
                    **config["review_selection"],
                    "status": result.review.status,
                }
                # Every structurally valid candidate remains publishable. A
                # residual or unavailable review is public assessment data,
                # never a terminal generation failure.
                staged_results.append((candidate_index, result))
                next_step(
                    f"Staging pack {candidate_index + 1}/"
                    f"{config['candidate_count']}"
                )
                if not _project_reference_wait_at_output_boundary(
                    parent_job, "candidate",
                ):
                    raise RuntimeError("reference_job_cancelled")

            update_job(
                parent_job,
                phase="Publishing reference packs",
                message="Publishing prepared reference packs",
            )
            replayed_recommendations = [
                variant for variant in replayed_variants
                if _project_reference_variant_is_recommended(variant)
            ]
            if len(replayed_recommendations) > 1:
                raise RuntimeError("reference_pack_recommendation_invalid")
            recommended_candidate_index = None
            recommendation_basis = None
            if replayed_recommendations:
                replayed = replayed_recommendations[0]
                recommended_candidate_index = int(
                    replayed["metadata"]["job"]["candidate_index"]
                ) - 1
                recommendation_basis = replayed["metadata"][
                    "reference_pack"
                ]["quality"]["recommendation_basis"]

            assessed_candidates = []
            accepted_candidates = []
            ungraded_candidate_indices = []
            for candidate_index, result in staged_results:
                assessment = result.review.fidelity_assessment
                if assessment is None:
                    ungraded_candidate_indices.append(candidate_index)
                    continue
                candidate = ReferenceCandidateAssessment(
                    candidate_index=candidate_index,
                    assessment=assessment,
                    repair_count=result.review.fidelity_attempt_index,
                )
                assessed_candidates.append(candidate)
                if fidelity_attempt_accepted(
                    assessment,
                    attempt_index=result.review.fidelity_attempt_index,
                ):
                    accepted_candidates.append(candidate)
            if recommended_candidate_index is not None:
                pass
            elif accepted_candidates:
                recommended_candidate_index = (
                    recommend_reference_candidate(
                        accepted_candidates,
                    ).candidate_index
                )
                recommendation_basis = "accepted_assessment"
            elif ungraded_candidate_indices:
                recommended_candidate_index = min(ungraded_candidate_indices)
                recommendation_basis = "preliminary_ungraded"
            elif assessed_candidates:
                recommended_candidate_index = (
                    recommend_reference_candidate(
                        assessed_candidates,
                    ).candidate_index
                )
                recommendation_basis = "residual_assessment"
            elif staged_results:
                raise RuntimeError("reference_pack_candidate_set_invalid")
            prepared_variants = []
            for candidate_index, result in staged_results:
                prepared_variants.append(_attach_project_reference_result(
                    asset_id=asset_id,
                    result=result,
                    parent_job=parent_job,
                    candidate_index=candidate_index,
                    candidate_count=config["candidate_count"],
                    parent_variant_id=config["parent_variant_id"],
                    recommended=(
                        candidate_index == recommended_candidate_index
                    ),
                    recommendation_basis=(
                        recommendation_basis
                        if candidate_index == recommended_candidate_index
                        else None
                    ),
                ))

            from services import job_lifecycle as _job_lifecycle
            store = _project_asset_store()
            # Cancellation, one-manifest publication, and terminal completion
            # share the canonical lifecycle lock order. Cancellation can win
            # only before the visible manifest commit; after commit, completion
            # wins and durable recovery can repeat finalization without models.
            with (
                _job_lifecycle._queue_condition,
                _job_lifecycle._lifecycle_lock,
                store.publication_guard(),
            ):
                if is_cancel_requested(parent_job):
                    finish_job(
                        parent_job,
                        "failed",
                        progress=0,
                        phase="",
                        message="Reference-pack generation cancelled",
                        error="Reference-pack generation cancelled",
                    )
                else:
                    expected_variant_ids = [
                        f"{job_id}_pack_{index + 1}"
                        for index in range(config["candidate_count"])
                    ]
                    checkpoint = globals().get("checkpoint_recovery_job")
                    if not callable(checkpoint) or not checkpoint(
                        parent_job,
                        recovery_state="publication_prepared",
                        recovery_unit={
                            "kind": "project_reference_publication",
                            "asset_id": asset_id,
                            "workspace_id": workspace_id,
                            "variant_ids": expected_variant_ids,
                            "candidate_count": config["candidate_count"],
                            "plan_seal": plan.plan_seal,
                            "mandatory_review": config["mandatory_review"],
                        },
                        reruns_denoise=False,
                        phase="publishing_approved_reference_packs",
                        message="Approved reference packs prepared for publication",
                    ):
                        raise RuntimeError(
                            "reference_pack_publication_checkpoint_failed"
                        )
                    attached_variants = []
                    if new_asset_request:
                        published_asset = store.create_asset(
                            project_id,
                            workspace_id,
                            asset_id=asset_id,
                            name=asset_spec["name"],
                            asset_type=asset_spec["asset_type"],
                            description=asset_spec["description"],
                            tags=asset_spec["tags"],
                            provenance="generated",
                            metadata={},
                            variants=prepared_variants,
                        )
                        attached_variants = published_asset["variants"]
                    else:
                        attached_variants = store.add_variants_atomic(
                            project_id,
                            workspace_id,
                            asset_id,
                            prepared_variants,
                            expected_existing_variants=replayed_variants,
                        )
                    committed_by_id = {
                        item["id"]: item
                        for item in (*replayed_variants, *attached_variants)
                    }
                    if set(committed_by_id) != set(expected_variant_ids):
                        raise RuntimeError("reference_pack_publication_incomplete")
                    committed_recommendations = 0
                    for candidate_index, variant_id in enumerate(
                        expected_variant_ids, start=1,
                    ):
                        _project_reference_validate_committed_variant(
                            store,
                            project_id,
                            workspace_id,
                            committed_by_id[variant_id],
                            job_id=job_id,
                            candidate_index=candidate_index,
                            candidate_count=config["candidate_count"],
                            plan_seal=plan.plan_seal,
                            mandatory_review=config["mandatory_review"],
                            explicit_output=config["policy"]["explicit"],
                        )
                        committed_recommendations += int(
                            _project_reference_variant_is_recommended(
                                committed_by_id[variant_id],
                            )
                        )
                    if committed_recommendations != 1:
                        raise RuntimeError(
                            "reference_pack_recommendation_incomplete"
                        )
                    published_variant_ids.extend(expected_variant_ids)
                    for variant_id in expected_variant_ids:
                        completed_sheets.extend(
                            output.get("relative_path")
                            for output in (
                                committed_by_id[variant_id].get("outputs") or []
                            )
                            if isinstance(output.get("relative_path"), str)
                        )
                    if published_variant_ids:
                        try:
                            finalized = finish_job(
                                parent_job,
                                "completed",
                                progress=100,
                                step=total_steps,
                                total_steps=total_steps,
                                phase="",
                                message="Reference packs ready",
                                output_files=completed_sheets,
                                error=None,
                                recovery_state="terminal",
                            )
                            if finalized is False:
                                raise RuntimeError(
                                    "reference_pack_finalization_pending"
                                )
                        except Exception:
                            if parent_job.get("status") == "completed":
                                continue_finalization = False
                            else:
                                continue_finalization = True
                            pending = {
                                "recovery_state": "publication_committed_finalization_pending",
                                "reruns_denoise": False,
                                "phase": "publication_committed",
                                "message": (
                                    "Reference packs committed; finalization requires recovery"
                                ),
                                "error": (
                                    "Reference-pack finalization requires recovery"
                                ),
                                "resource_state": "blocked",
                            }
                            if continue_finalization:
                                blocker = globals().get("block_generation_recovery")
                                parked = False
                                if callable(blocker):
                                    try:
                                        parked = bool(blocker(parent_job, **pending))
                                    except Exception:
                                        parked = False
                                if not parked:
                                    parent_job.update({
                                        **pending,
                                        "status": "queued",
                                        "queue_held": True,
                                    })
                    else:
                        finish_job(
                            parent_job,
                            "completed",
                            progress=100,
                            step=total_steps,
                            total_steps=total_steps,
                            phase="",
                            message="Reference packs ready",
                            output_files=completed_sheets,
                            error=None,
                        )
        except Exception as error:
            if (
                parent_job.get("status") == "queued"
                and not is_cancel_requested(parent_job)
            ):
                block_resource_admission_failure(parent_job)
                return
            child_failure = {}
            if (
                _public_parent_job_id({
                    "parent_job_id": parent_job.get("failed_child_job_id"),
                }) is not None
            ):
                child_failure = _project_reference_safe_failure_envelope(
                    parent_job,
                )
            terminal_failure = {
                "message": "Reference-pack generation failed",
                "error": "Reference-pack generation failed",
            }
            terminal_failure.update(child_failure)
            finish_job(
                parent_job,
                "failed",
                progress=0,
                phase="",
                **terminal_failure,
            )
        finally:
            for _candidate_index, result in staged_results:
                for source_path in result.private_source_paths:
                    _cleanup_project_reference_private_source(
                        source_path, job_out_dir,
                    )
            _end_workspace_operation(project_id)

    try:
        _queue_recovery_register_and_publish(
            job,
            worker=_run_and_attach_candidates,
            recovery_kind="studio_project_asset_preparation",
            thread_name=f"studio-project-asset-{job_id}",
        )
    except Exception as error:
        _end_workspace_operation(project_id)
        if (
            admission is not None
            and admission.owns_lease
            and _jobs.get(job_id) is job
        ):
            try:
                admission_store.accept(
                    request_id,
                    **admission_scope,
                    lease_token=admission.lease_token,
                )
            except Exception as admission_error:
                raise _project_asset_error(admission_error) from admission_error
            return admission_response()
        if admission is not None and admission.owns_lease:
            try:
                admission_store.fail(
                    request_id,
                    **admission_scope,
                    lease_token=admission.lease_token,
                )
            except Exception:
                pass
        raise _project_asset_error(error) from error
    if admission is not None and admission.owns_lease:
        try:
            admission_store.accept(
                request_id,
                **admission_scope,
                lease_token=admission.lease_token,
            )
        except (
            ReferenceAdmissionMismatchError,
            ReferenceAdmissionValidationError,
            ReferenceAdmissionCorruptionError,
            ReferenceAdmissionPersistenceError,
        ) as error:
            raise HTTPException(status_code=503, detail=str(error)) from error
    return admission_response()


# ============================================================================
# API Routes: Blender MCP (pinned, structured, project-scoped)
# ============================================================================

_blender_services: dict[str, object] = {}
_blender_services_lock = threading.RLock()
_blender_scene_lock = threading.RLock()


class _BlenderGpuRenderSlot:
    """Hold shared generation/GPU exclusion only while Blender renders."""

    def __init__(self, enabled: bool = True):
        self.enabled = bool(enabled)
        self._native_slot = None

    def __enter__(self):
        if not self.enabled:
            return False
        _gen_lock.acquire()
        self._native_slot = _WgpNativeGpuExecutionSlot()
        try:
            return self._native_slot.__enter__()
        except BaseException:
            _gen_lock.release()
            raise

    def __exit__(self, exc_type, exc, traceback_value):
        if not self.enabled:
            return False
        try:
            return self._native_slot.__exit__(
                exc_type, exc, traceback_value,
            )
        finally:
            _gen_lock.release()


def _blender_checkout_root() -> str:
    return os.path.join(os.getcwd(), "services", "blender_mcp")


def _blender_runtime_info() -> dict:
    marker = os.path.join(os.getcwd(), "tools", "blender", "runtime.json")
    try:
        from services.blender_mcp_service import read_blender_runtime_info

        return read_blender_runtime_info(marker)
    except (ImportError, OSError, ValueError, TypeError):
        return {}


def _blender_bridge_ready() -> bool:
    try:
        with socket.create_connection(("127.0.0.1", 9876), timeout=0.2):
            return True
    except OSError:
        return False


def _blender_mcp_sdk_ready() -> bool:
    """Return whether this app interpreter can run the standard MCP client."""
    try:
        metadata_module = __import__("importlib.metadata", fromlist=("version",))
        if (
            metadata_module.version("mcp") != "1.12.4"
            or metadata_module.version("blender-mcp") != "1.0.0"
        ):
            return False
        mcp_module = __import__(
            "mcp",
            fromlist=("ClientSession", "StdioServerParameters"),
        )
        stdio_module = __import__(
            "mcp.client.stdio",
            fromlist=("get_default_environment", "stdio_client"),
        )
        required = (
            mcp_module.ClientSession,
            mcp_module.StdioServerParameters,
            stdio_module.get_default_environment,
            stdio_module.stdio_client,
        )
        __import__("blmcp")
        __import__("docutils")
        __import__("yaml")
    except Exception:
        # A present-but-incompatible SDK can fail while importing one of its
        # transitive modules. Status must fail closed and direct repair rather
        # than turning the Blender status endpoint into a 500 response.
        return False
    return all(callable(value) for value in required)


def _blender_readiness(runtime: dict | None = None) -> dict:
    """Return the user-safe installed/ready matrix for hosted Blender."""
    from services.blender_mcp_service import PINNED_INSTALL

    checkout = _blender_checkout_root()
    marker_path = os.path.join(checkout, ".maestro-attested")
    mcp_attested = False
    try:
        with open(marker_path, "r", encoding="utf-8") as handle:
            marker = json.load(handle)
        mcp_attested = bool(
            isinstance(marker, dict)
            and marker.get("repository") == PINNED_INSTALL.repository
            and marker.get("tag") == PINNED_INSTALL.tag
            and marker.get("revision") == PINNED_INSTALL.revision
            and marker.get("package_version") == PINNED_INSTALL.package_version
            and marker.get("transport") == PINNED_INSTALL.transport
            and os.path.isfile(os.path.join(checkout, "mcp", "blmcp", "__init__.py"))
        )
    except (OSError, TypeError, ValueError):
        mcp_attested = False

    runtime = dict(runtime) if isinstance(runtime, dict) else _blender_runtime_info()
    runtime_attested = bool(runtime)
    mcp_sdk_ready = _blender_mcp_sdk_ready()
    bridge_ready = _blender_bridge_ready()
    installed = mcp_attested and runtime_attested
    ready = installed and mcp_sdk_ready and bridge_ready
    if not mcp_attested:
        recovery = (
            "On the Maestro host, open Pinokio → Maestro and run "
            "Verify / Repair Blender MCP Support, then restart Maestro."
        )
    elif not runtime_attested:
        recovery = (
            "On the Maestro host, open Pinokio → Maestro and run "
            "Verify / Repair Blender Runtime, then restart Maestro."
        )
    elif not mcp_sdk_ready:
        recovery = (
            "On the Maestro host, open Pinokio → Maestro and run "
            "Verify / Repair Blender MCP Support, then try again."
        )
    elif not bridge_ready:
        recovery = (
            "On the Maestro host, stop and start Maestro in Pinokio so its "
            "localhost Blender bridge starts."
        )
    else:
        recovery = "Blender is ready."
    return {
        "installed": installed,
        "ready": ready,
        "mcp_attested": mcp_attested,
        "runtime_attested": runtime_attested,
        "mcp_sdk_ready": mcp_sdk_ready,
        "bridge_ready": bridge_ready,
        "recovery_action": recovery,
    }


def _require_blender_ready() -> dict:
    readiness = _blender_readiness()
    if not readiness["ready"]:
        raise HTTPException(status_code=503, detail=readiness["recovery_action"])
    return readiness


def _close_blender_services() -> None:
    with _blender_services_lock:
        services = list(_blender_services.values())
        _blender_services.clear()
    for service in services:
        try:
            service.close()
        except Exception:
            pass


atexit.register(_close_blender_services)


def _blender_service_for(workspace: str, project_root: str):
    """Return one serialized lazy MCP client per validated project."""
    _require_blender_ready()
    checkout = _blender_checkout_root()
    if not os.path.isdir(checkout):
        raise HTTPException(
            status_code=503,
            detail="Blender is not installed. Run Blender setup and try again.",
        )
    with _blender_services_lock:
        service = _blender_services.get(workspace)
        if service is not None:
            return service
        try:
            from services.blender_mcp_service import BlenderMCPService
            from services.blender_mcp_transport import StdioBlenderMCPClient
            client = StdioBlenderMCPClient(
                checkout_root=checkout,
                blender_version=str(
                    os.environ.get("BLENDER_MCP_BLENDER_VERSION")
                    or _blender_runtime_info().get("version")
                    or "5.1.0"
                ),
            )
            service = BlenderMCPService(client, project_root)
        except Exception as error:
            raise HTTPException(
                status_code=503, detail="Blender is unavailable. Restart Maestro and try again.",
            ) from error
        _blender_services[workspace] = service
        return service


def _blender_error(error: Exception) -> HTTPException:
    from services.blender_mcp_service import (
        BlenderMCPCancelled,
        BlenderMCPSecurityError,
        BlenderMCPToolError,
        BlenderMCPValidationError,
    )
    if isinstance(error, BlenderMCPValidationError):
        return HTTPException(status_code=400, detail=str(error))
    if isinstance(error, BlenderMCPCancelled):
        return HTTPException(status_code=409, detail=str(error))
    if isinstance(error, BlenderMCPSecurityError):
        return HTTPException(status_code=503, detail="Blender could not pass its safety check. Run Blender setup or restart Maestro.")
    if isinstance(error, BlenderMCPToolError):
        if "camera" in str(error).lower():
            return HTTPException(
                status_code=503,
                detail=(
                    "Blender could not prepare a camera for this scene. "
                    "Recreate the structured scene, then try rendering again."
                ),
            )
        return HTTPException(status_code=503, detail="Blender could not complete that operation. Restart Blender and try again.")
    return HTTPException(status_code=500, detail="The Blender operation failed")


def _write_blender_preview_sidecar(
    out_dir: str,
    filename: str,
    *,
    workspace: str,
    policy: dict,
    frames: list[int],
    lineage: str,
) -> None:
    sidecar = {
        "params": {
            "edit_sub_mode": "blender_review_sample",
            "sampled_frames": frames,
            "review_only": True,
        },
        "generation_mode": "image",
        "tool": "blender_mcp",
        "artifact_class": "temporary",
        "artifact_lineage": lineage,
        "review_only": True,
        "created_at": time.time(),
        "output_filename": filename,
    }
    stamp_sidecar_policy(sidecar, policy, workspace=workspace)
    meta_path = os.path.join(out_dir, os.path.splitext(filename)[0] + ".meta.json")
    temp_path = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            json.dump(sidecar, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, meta_path)
    except Exception as error:
        for path in (temp_path, os.path.join(out_dir, filename)):
            try:
                os.remove(path)
            except OSError:
                pass
        raise HTTPException(
            status_code=500,
            detail="Could not publish protected Blender preview metadata",
        ) from error


def _write_blender_video_sidecar(
    out_dir: str,
    filename: str,
    *,
    workspace: str,
    policy: dict,
    lineage: str,
    frame_start: int,
    frame_end: int,
    fps: int,
    review_attempts: int,
    director_model: str,
    control_mode: str,
    semantic_mapping: dict | None = None,
) -> None:
    frame_count = frame_end - frame_start + 1
    sidecar = {
        "params": {
            "edit_sub_mode": "blender_director_reference",
            "frame_start": frame_start,
            "frame_end": frame_end,
            "fps": fps,
            "frame_count": frame_count,
            "duration_seconds": frame_count / fps,
            "review_attempts": review_attempts,
            "video_prompt_type": control_mode,
            "control_reference_fps": "match_generation",
            "ic_lora_attention_strength": 1.0,
            "ic_lora_reference_downscale": 2,
            "semantic_mapping": dict(semantic_mapping or {}),
            "conditioned_prompt": str(
                (semantic_mapping or {}).get("conditioned_prompt") or ""
            ),
            # Official LTX IC-LoRA applies video conditioning in stage 1;
            # stage 2 is an unconditioned refinement pass.
            "ic_lora_stage2_controlled": False,
        },
        "generation_mode": "video",
        "tool": "blender_mcp",
        # Director has approved the render for human review, but only the
        # user's explicit Keep action promotes it into the default gallery.
        "artifact_class": "temporary",
        "artifact_lineage": lineage,
        "director_reviewed": True,
        "director_approved": False,
        "user_review_status": "candidate",
        "director_model": director_model,
        "semantic_mapping": dict(semantic_mapping or {}),
        "created_at": time.time(),
        "output_filename": filename,
    }
    stamp_sidecar_policy(sidecar, policy, workspace=workspace)
    meta_path = os.path.join(out_dir, os.path.splitext(filename)[0] + ".meta.json")
    temp_path = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            json.dump(sidecar, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, meta_path)
    except Exception as error:
        for path in (temp_path, os.path.join(out_dir, filename)):
            try:
                os.remove(path)
            except OSError:
                pass
        raise HTTPException(
            status_code=500,
            detail="Could not publish protected Blender reference metadata",
        ) from error


def _set_blender_candidate_status(
    project_id: str,
    workspace_id: str,
    asset_id: str,
    variant_id: str,
    status: str,
    *,
    out_dir: str,
    session_id: str,
) -> dict | None:
    """Promote or reject a Blender candidate with sidecar rollback.

    Generic reference variants retain the project-asset store's ordinary
    status behavior.  Blender full-video candidates additionally own a gallery
    sidecar, so the two durable representations must transition together.
    """
    if status not in {"candidate", "kept", "rejected"}:
        raise ValueError("status must be candidate, kept, or rejected")

    from services.win_safe_files import safe_direct_file_under

    store = _project_asset_store()
    with _blender_candidate_status_lock:
        asset = store.get_asset(project_id, workspace_id, asset_id)
        variant = next(
            (
                item for item in asset.get("variants") or []
                if isinstance(item, dict) and item.get("id") == variant_id
            ),
            None,
        )
        if variant is None:
            raise HTTPException(status_code=404, detail="Reference variant not found")
        variant_meta = (
            variant.get("metadata")
            if isinstance(variant.get("metadata"), dict)
            else {}
        )
        if (
            variant.get("variant_type") != "blender_video"
            or variant_meta.get("tool") != "blender_mcp"
        ):
            return None

        current_status = str(variant.get("status") or "candidate")
        if status == current_status:
            return variant
        if current_status != "candidate" or status == "candidate":
            raise HTTPException(
                status_code=409,
                detail="This Blender reference has already been reviewed",
            )

        variant_outputs = variant.get("outputs") or []
        legacy_filename = (
            str(variant_outputs[0].get("filename") or "")
            if len(variant_outputs) == 1 and isinstance(variant_outputs[0], dict)
            else ""
        )
        filename = str(
            variant_meta.get("gallery_output_filename") or legacy_filename
        )
        sidecar_name = os.path.splitext(filename)[0] + ".meta.json"
        sidecar_path = safe_direct_file_under(out_dir, sidecar_name)
        media_path = safe_direct_file_under(out_dir, filename)
        if (
            not filename
            or sidecar_path is None
            or media_path is None
            or not os.path.isfile(sidecar_path)
            or not os.path.isfile(media_path)
        ):
            raise HTTPException(
                status_code=409,
                detail="The Blender review candidate is no longer available",
            )

        try:
            with open(sidecar_path, "rb") as handle:
                original_bytes = handle.read()
            sidecar = json.loads(original_bytes)
        except (OSError, ValueError, TypeError) as error:
            raise HTTPException(
                status_code=409,
                detail="The Blender review candidate metadata is unavailable",
            ) from error
        if (
            not isinstance(sidecar, dict)
            or sidecar.get("tool") != "blender_mcp"
            or sidecar.get("artifact_lineage") != variant_meta.get("artifact_lineage")
        ):
            raise HTTPException(
                status_code=409,
                detail="The Blender review candidate metadata does not match",
            )

        updated_sidecar = dict(sidecar)
        updated_sidecar["artifact_class"] = "final" if status == "kept" else "temporary"
        updated_sidecar["director_reviewed"] = True
        updated_sidecar["director_approved"] = status == "kept"
        updated_sidecar["user_review_status"] = status
        updated_sidecar.pop("approved_at", None)
        updated_sidecar.pop("rejected_at", None)
        updated_sidecar[f"{'approved' if status == 'kept' else 'rejected'}_at"] = time.time()

        requested_explicit = bool(
            variant_meta.get("requested_explicit", sidecar.get("explicit", False))
        )
        requested_private = bool(
            variant_meta.get("requested_private", sidecar.get("private", False))
        )
        final_private = requested_private if status == "kept" else True
        stamp_sidecar_policy(
            updated_sidecar,
            {
                "private": final_private,
                "explicit": requested_explicit,
            },
            workspace=project_id,
        )

        staged = None
        sidecar_published = False
        try:
            staged = _stage_json_replacement(sidecar_path, updated_sidecar)
            # The staged sidecar is not visible yet. Abort with both durable
            # representations unchanged if capability revocation cannot be
            # persisted.
            _revoke_output_shares(project_id, [filename])
            os.replace(staged, sidecar_path)
            staged = None
            sidecar_published = True
            updated_variant = store.set_variant_status(
                project_id, workspace_id, asset_id, variant_id, status,
            )
        except Exception as error:
            rollback_error = None
            if sidecar_published:
                try:
                    _restore_file_bytes(sidecar_path, original_bytes)
                except Exception as restore_error:
                    rollback_error = restore_error
            try:
                persisted = store.get_variant(project_id, workspace_id, asset_id, variant_id)
                if str(persisted.get("status") or "candidate") != current_status:
                    store.set_variant_status(
                        project_id, workspace_id, asset_id, variant_id,
                        current_status,
                    )
            except Exception as restore_error:
                rollback_error = rollback_error or restore_error
            if rollback_error is not None:
                raise HTTPException(
                    status_code=500,
                    detail="Could not safely restore the Blender review candidate",
                ) from rollback_error
            raise HTTPException(
                status_code=500,
                detail="Could not update the Blender review candidate",
            ) from error
        finally:
            if staged:
                try:
                    os.remove(staged)
                except OSError:
                    pass

    return updated_variant


