def _blender_plan_json(text: str) -> dict:
    value = str(text or "").strip()
    if value.startswith("```"):
        value = value.split("\n", 1)[-1]
        value = value.rsplit("```", 1)[0].strip()
    start, end = value.find("{"), value.rfind("}")
    if start < 0 or end <= start:
        raise ValueError("Director LLM did not return a Blender plan object")
    fragment = value[start:end + 1]
    try:
        parsed = json.loads(fragment)
    except json.JSONDecodeError:
        try:
            from json_repair import repair_json
            parsed = json.loads(repair_json(fragment))
        except Exception as error:
            raise ValueError("Director LLM returned an invalid Blender plan") from error
    if not isinstance(parsed, dict):
        raise ValueError("Director Blender plan must be an object")
    return parsed


def _normalize_blender_semantic_mapping(
    raw,
    scene: dict,
    *,
    director_prompt: str,
    fallback: dict | None = None,
) -> dict:
    """Bind a data-only semantic legend to normalized Blender objects."""
    objects = list(scene.get("objects") or []) if isinstance(scene, dict) else []
    if not objects:
        raise ValueError("semantic mapping requires at least one scene object")
    by_name = {
        str(item.get("name") or ""): item
        for item in objects
        if isinstance(item, dict) and item.get("name")
    }
    if len(by_name) != len(objects):
        raise ValueError("scene object names must be unique before semantic mapping")

    source = raw if isinstance(raw, dict) else fallback
    source = source if isinstance(source, dict) else {}
    raw_legend = source.get("legend")
    raw_legend = raw_legend if isinstance(raw_legend, list) else []
    supplied = {}
    for index, item in enumerate(raw_legend):
        if not isinstance(item, dict):
            raise ValueError(f"semantic legend entry {index + 1} must be an object")
        object_name = str(item.get("object_name") or "").strip()
        if object_name not in by_name:
            label = object_name or f"entry {index + 1}"
            raise ValueError(
                f"semantic legend object {label!r} is not in the normalized scene"
            )
        if object_name in supplied:
            raise ValueError(f"semantic legend repeats scene object {object_name}")
        supplied[object_name] = item

    legend = []
    for object_name, scene_object in by_name.items():
        item = supplied.get(object_name, {})
        primitive = str(scene_object.get("primitive") or "").strip()
        requested_primitive = str(item.get("primitive") or primitive).strip()
        if requested_primitive != primitive:
            raise ValueError(
                f"semantic legend primitive for {object_name} must match the normalized scene"
            )
        material = scene_object.get("material")
        scene_color = (
            list(material.get("color") or [])
            if isinstance(material, dict)
            else [0.5, 0.5, 0.5, 1.0]
        )
        if len(scene_color) != 4:
            scene_color = [0.5, 0.5, 0.5, 1.0]
        requested_color = item.get("color", scene_color)
        if (
            not isinstance(requested_color, list)
            or len(requested_color) != 4
            or any(
                not isinstance(value, (int, float)) or isinstance(value, bool)
                for value in requested_color
            )
            or any(abs(float(left) - float(right)) > 0.001 for left, right in zip(requested_color, scene_color))
        ):
            raise ValueError(
                f"semantic legend color for {object_name} must match the normalized scene"
            )
        subject = str(item.get("subject") or object_name.replace("_", " ")).strip()
        action = str(item.get("action") or "follows the planned motion").strip()
        if not subject or len(subject) > 500:
            raise ValueError(f"semantic subject for {object_name} must be 1-500 characters")
        if not action or len(action) > 1000:
            raise ValueError(f"semantic action for {object_name} must be 1-1000 characters")
        legend.append({
            "object_name": object_name,
            "primitive": primitive,
            "color": [round(float(value), 6) for value in scene_color],
            "subject": subject,
            "action": action,
        })

    conditioned_prompt = str(source.get("conditioned_prompt") or "").strip()
    if not conditioned_prompt:
        correspondences = "; ".join(
            f"{item['object_name']} ({item['primitive']}) represents "
            f"{item['subject']} and {item['action']}"
            for item in legend
        )
        conditioned_prompt = f"{director_prompt.strip()} Semantic control: {correspondences}".strip()
    if not conditioned_prompt or len(conditioned_prompt) > 10_000:
        raise ValueError("conditioned_prompt must be 1-10000 characters")
    return {"legend": legend, "conditioned_prompt": conditioned_prompt}


@api.post("/api/v1/blender/director-plan")
async def blender_director_plan(request: Request):
    """Use the configured Director LLM to produce a bounded editable plan."""
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Request body must be an object")
    workspace = str(body.get("workspace") or _get_active_workspace())
    project_root = _require_project_access(request, workspace)
    prompt = str(body.get("prompt") or "").strip()
    if not prompt or len(prompt) > 10_000:
        raise HTTPException(status_code=400, detail="prompt must be 1-10000 characters")
    try:
        duration = float(body.get("duration_seconds") or 10)
        fps = int(body.get("fps") or 24)
    except (TypeError, ValueError) as error:
        raise HTTPException(status_code=400, detail="duration and fps must be numeric") from error
    if not 1 <= duration <= 3600 or not 1 <= fps <= 240:
        raise HTTPException(status_code=400, detail="duration or fps is outside the supported range")
    from services.blender_mcp_service import BlenderMCPLimits
    frame_count = max(1, round(duration * fps))
    frame_end = frame_count - 1
    max_total_frames = BlenderMCPLimits().max_total_frames
    if frame_count > max_total_frames:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Animation requires {frame_count} frames; hosted Blender is "
                f"limited to {max_total_frames} frames ({max_total_frames / fps:.2f}s at {fps} fps)."
            ),
        )

    # Fail before any model load or provider work when the hosted bridge is
    # not fully installed, attested, and reachable.
    _require_blender_ready()
    _ensure_llm_loaded()
    from services import llm_service
    system_prompt = (
        "You are Director's bounded Blender blocking planner. Return JSON only. "
        "Use primitives cube/sphere/cylinder/cone/torus/plane, no Python, no paths, "
        "no external assets. Schema: {objects:[{name,primitive,location:[x,y,z],"
        "rotation_degrees:[x,y,z],scale:[x,y,z],material:{name,color:[r,g,b,a]}}],"
        "animations:[{name,keyframes:[{frame,location?,rotation_degrees?,scale?,"
        "interpolation?}]}],review_frames:[integers],notes:string}. "
        "Also return semantic_mapping:{legend:[{object_name,primitive,color:[r,g,b,a],"
        "subject,action}],conditioned_prompt:string}. The legend must contain every "
        "scene object exactly once; object_name, primitive, and color must exactly match "
        "that normalized scene object. Give every object a material with the same unique, "
        "camera-readable color used by its legend entry. The conditioned prompt must explain how each "
        "colored primitive controls its named subject and action. "
        f"Frame range is 0..{frame_end}; create 1-12 objects and 2-8 unique review "
        "frames including the beginning and end. Every animated name must exist."
    )
    try:
        raw = await asyncio.to_thread(
            _run_configured_llm_operation,
            llm_service.generate,
            prompt=f"Scene request:\n{prompt}\nStyle: {str(body.get('style') or 'cinematic blocking')}",
            system_prompt=system_prompt,
            max_new_tokens=2200,
            temperature=0.25,
            top_p=0.9,
        )
        proposed = _blender_plan_json(raw)
        scene = {
            "clear_scene": True,
            "objects": proposed.get("objects") or [],
        }
        animation = {
            "frame_start": 0,
            "frame_end": frame_end,
            "objects": proposed.get("animations") or [],
        }
        service = _blender_service_for(workspace, project_root)
        # Validation is pure and does not connect to Blender. Returning the
        # normalized shapes makes the confirmation UI exact and executable.
        scene = service._normalize_scene_create(scene)
        animation = service._normalize_animation(animation)
        semantic_mapping = _normalize_blender_semantic_mapping(
            proposed.get("semantic_mapping"),
            scene,
            director_prompt=prompt,
        )
        raw_frames = proposed.get("review_frames") or [0, frame_end // 2, frame_end]
        frames = sorted({int(value) for value in raw_frames})
        if len(frames) < 2 or len(frames) > 8 or frames[0] < 0 or frames[-1] > frame_end:
            frames = sorted({0, frame_end // 2, frame_end})
    except HTTPException:
        raise
    except Exception as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    services = wgp.server_config.get("services", {})
    return {
        "workspace": workspace,
        "director_prompt": prompt,
        "scene": scene,
        "animation": animation,
        "semantic_mapping": semantic_mapping,
        "review_frames": frames,
        "notes": str(proposed.get("notes") or "")[:2000],
        "duration_seconds": duration,
        "frame_count": frame_count,
        "fps": fps,
        "llm_model": services.get("llm_model_id", _DEFAULT_LLM_REPO),
        "confirmation_required": False,
        "review_strategy": "Director analyzes 2-8 temporally separated frames together, revises if needed, then renders the full-rate reference",
    }


