@api.post("/api/v1/blender/render")
async def blender_render_preview(request: Request):
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Request body must be an object")
    workspace = str(body.pop("workspace", "") or _get_active_workspace())
    project_root = _require_project_access(
        request, workspace, permission="project.generate",
    )
    try:
        policy = output_policy_from_request(
            body,
            owner_session_id=request.state.maestro_session_id,
        )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    register_reference = body.pop("register_reference", False)
    reference_name = str(body.pop("reference_name", "Blender scene guide"))
    asset_type = str(body.pop("asset_type", "setting"))
    description = str(body.pop("description", "Sampled Blender scene previews"))
    body.pop("private_output", None)
    body.pop("explicit_output", None)
    frames_value = body.get("frames")
    frame_value = body.get("frame")
    try:
        frames = (
            [int(value) for value in frames_value]
            if isinstance(frames_value, list)
            else ([int(frame_value)] if frame_value is not None else [])
        )
    except (TypeError, ValueError) as error:
        raise HTTPException(status_code=400, detail="frames must be integers") from error
    filename = f"blender_preview_{uuid.uuid4().hex[:10]}.png"
    lineage = f"blender-review:{uuid.uuid4().hex}"
    body["output_path"] = filename
    body["overwrite"] = False
    service = _blender_service_for(workspace, project_root)
    try:
        def render_serialized():
            with _blender_scene_lock, _BlenderGpuRenderSlot():
                return service.invoke("render_preview", body)
        result = await asyncio.to_thread(render_serialized)
    except Exception as error:
        raise _blender_error(error) from error

    output_values = []
    if isinstance(result.get("outputs"), list):
        output_values = [
            item.get("output_path") for item in result["outputs"]
            if isinstance(item, dict)
        ]
    elif result.get("output_path"):
        output_values = [result.get("output_path")]
    published = []
    for value in output_values:
        path = os.path.realpath(str(value or ""))
        if os.path.dirname(path) != os.path.realpath(project_root) or not os.path.isfile(path):
            raise HTTPException(status_code=503, detail="Blender returned an invalid project preview")
        output_name = os.path.basename(path)
        _write_blender_preview_sidecar(
            project_root, output_name,
            workspace=workspace, policy=policy, frames=frames,
            lineage=lineage,
        )
        published.append({"filename": output_name, "url": f"/api/v1/file/{quote(output_name)}?workspace={quote(workspace)}"})

    if not published:
        raise HTTPException(status_code=503, detail="Blender produced no preview")

    if register_reference:
        variants = [
            {
                "variant_type": "blender_preview",
                "label": (
                    f"Frame {frames[index]}" if index < len(frames) else f"Preview {index + 1}"
                ),
                "outputs": [{
                    "source_path": os.path.join(project_root, item["filename"]),
                    "label": "Blender scene guide",
                    "metadata": dict(policy),
                }],
                "provenance": "generated",
                "status": "candidate",
            }
            for index, item in enumerate(published)
        ]
        try:
            asset = _project_asset_store().create_asset(
                workspace, "main",
                name=reference_name,
                asset_type=asset_type,
                description=description,
                provenance="generated",
                variants=variants,
                metadata={"tool": "blender_mcp", "sampled_frames": frames},
            )
        except Exception as error:
            raise _project_asset_error(error) from error
    else:
        asset = None
    return {"status": "ok", "workspace": workspace, "previews": published, "asset": asset}


def _normalize_blender_review_frames(raw, frame_start: int, frame_end: int) -> list[int]:
    if not isinstance(raw, list):
        raise ValueError("review_frames must be a list")
    try:
        frames = sorted({int(value) for value in raw})
    except (TypeError, ValueError) as error:
        raise ValueError("review_frames must contain integers") from error
    if not 2 <= len(frames) <= 8:
        raise ValueError("Director review requires 2-8 distinct frames together")
    if frames[0] < frame_start or frames[-1] > frame_end:
        raise ValueError("review_frames must stay inside the animation range")
    if frames[-1] == frames[0]:
        raise ValueError("Director review frames must be temporally separated")
    return frames


@api.post("/api/v1/blender/director-finalize")
async def blender_director_finalize(request: Request):
    """Let Director visually review sparse frames, then publish one full video.

    Each review pass sends every sampled frame in one multimodal request so the
    model can judge motion/progression. The user sees only the Director-approved
    full-rate candidate and may keep, reject, or request another edited pass.
    """
    body = await request.json()
    if not isinstance(body, dict) or not isinstance(body.get("plan"), dict):
        raise HTTPException(status_code=400, detail="A Director Blender plan is required")
    workspace = str(body.get("workspace") or _get_active_workspace())
    project_root = _require_project_access(request, workspace)
    _require_blender_ready()
    plan = dict(body["plan"])
    try:
        policy_input = {
            key: body[key] for key in ("private_output", "explicit_output")
            if key in body
        }
        policy = output_policy_from_request(
            policy_input,
            owner_session_id=request.state.maestro_session_id,
        )
        max_attempts = max(1, min(3, int(body.get("max_attempts") or 3)))
    except (TypeError, ValueError) as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    edit_prompt = str(body.get("edit_prompt") or "").strip()[:4000]
    reference_name = str(
        body.get("reference_name") or "Director Blender motion reference"
    )[:200]
    control_mode = str(body.get("recommended_video_prompt_type") or "TVG")
    if control_mode not in {"VG", "TVG", "EVG", "PTVG", "TEVG"}:
        raise HTTPException(status_code=400, detail="Unsupported Blender control mode")
    run_id = uuid.uuid4().hex
    lineage = f"blender-director:{run_id}"

    def execute_review_loop():
        service = _blender_service_for(workspace, project_root)
        try:
            scene = service._normalize_scene_create(plan.get("scene") or {})
            animation = service._normalize_animation(plan.get("animation") or {})
            semantic_mapping = _normalize_blender_semantic_mapping(
                plan.get("semantic_mapping"),
                scene,
                director_prompt=str(plan.get("director_prompt") or ""),
            )
            frame_start = int(animation["frame_start"])
            frame_end = int(animation["frame_end"])
            fps = int(plan.get("fps") or 24)
            if not 1 <= fps <= 240:
                raise ValueError("fps must be between 1 and 240")
            review_frames = _normalize_blender_review_frames(
                list(plan.get("review_frames") or []), frame_start, frame_end,
            )
        except (TypeError, ValueError) as error:
            raise HTTPException(status_code=400, detail=str(error)) from error

        _ensure_llm_loaded()
        from services import llm_service
        if not llm_service.vision_available():
            raise HTTPException(
                status_code=409,
                detail=(
                    "Director Blender review needs a vision-capable LLM. "
                    "Select a Director model marked Vision, then retry."
                ),
            )
        llm_status = llm_service.get_status()
        director_model = str(llm_status.get("model_id") or "Director vision model")

        sample_names: list[str] = []
        reviews: list[dict] = []
        try:
            with _blender_scene_lock:
                service.invoke("scene_create", scene)
                service.invoke("animate_keyframes", animation)
                approved = False
                for attempt in range(1, max_attempts + 1):
                    preview_name = f"blender_review_{run_id[:10]}_a{attempt}.png"
                    with _BlenderGpuRenderSlot():
                        preview_result = service.invoke("render_preview", {
                            "output_path": preview_name,
                            "frames": review_frames,
                            "overwrite": False,
                        })
                    outputs = list(preview_result.get("outputs") or [])
                    frame_paths: list[str] = []
                    for item in outputs:
                        path = os.path.realpath(str(item.get("output_path") or ""))
                        if (
                            os.path.dirname(path) != os.path.realpath(project_root)
                            or not os.path.isfile(path)
                        ):
                            raise HTTPException(
                                status_code=503,
                                detail="Blender returned an invalid Director review frame",
                            )
                        output_name = os.path.basename(path)
                        sample_policy = dict(policy)
                        sample_policy["private"] = True
                        _write_blender_preview_sidecar(
                            project_root, output_name,
                            workspace=workspace,
                            policy=sample_policy,
                            frames=review_frames,
                            lineage=lineage,
                        )
                        sample_names.append(output_name)
                        frame_paths.append(path)
                    if len(frame_paths) < 2:
                        raise HTTPException(
                            status_code=503,
                            detail="Director review requires at least two rendered frames",
                        )

                    frame_labels = ", ".join(
                        f"image {index + 1}=frame {frame} ({(frame - frame_start) / fps:.3f}s)"
                        for index, frame in enumerate(review_frames)
                    )
                    review_prompt = (
                        "Analyze all attached frames together as one temporal sample of "
                        "the same Blender animation. Judge scene correctness, readable "
                        "motion, spatial continuity, and progress against the request. "
                        f"Temporal mapping: {frame_labels}. "
                        f"Original request: {plan.get('director_prompt', '')}. "
                        f"User edit request: {edit_prompt or 'none'}. "
                        "Keep the semantic mapping data-only and aligned to the exact "
                        "normalized object names, primitives, and colors. "
                        "Return verdict=approved only if the animation is ready for a "
                        "full-frame-rate render. Otherwise return verdict=revise and a "
                        "complete replacement scene, animation, and 2-8 review_frames. "
                        f"Current normalized plan: {json.dumps({'scene': scene, 'animation': animation, 'semantic_mapping': semantic_mapping})}"
                    )
                    verdict_schema = {
                        "type": "object",
                        "additionalProperties": False,
                        "required": ["verdict", "analysis"],
                        "properties": {
                            "verdict": {"enum": ["approved", "revise"]},
                            "analysis": {"type": "string"},
                            "scene": {"type": "object"},
                            "animation": {"type": "object"},
                            "review_frames": {
                                "type": "array", "minItems": 2, "maxItems": 8,
                                "items": {"type": "integer"},
                            },
                            "semantic_mapping": {"type": "object"},
                        },
                    }
                    raw = _run_configured_llm_operation(
                        llm_service.generate,
                        prompt=review_prompt,
                        system_prompt=(
                            "You are Director's visual quality controller for Blender. "
                            "You receive multiple chronologically ordered frames in one "
                            "request. Return strict JSON and never approve from text alone."
                        ),
                        image_paths=frame_paths,
                        max_new_tokens=2600,
                        temperature=0.2,
                        top_p=0.9,
                        enable_thinking=False,
                        json_schema=verdict_schema,
                    )
                    verdict = _blender_plan_json(raw)
                    decision = str(verdict.get("verdict") or "").lower()
                    analysis = str(verdict.get("analysis") or "")[:4000]
                    reviews.append({
                        "attempt": attempt,
                        "verdict": decision,
                        "analysis": analysis,
                        "review_frames": list(review_frames),
                    })
                    if decision == "approved":
                        approved = True
                        break
                    if decision != "revise" or attempt >= max_attempts:
                        break
                    try:
                        next_scene = service._normalize_scene_create(
                            verdict.get("scene") or {}
                        )
                        next_animation = service._normalize_animation(
                            verdict.get("animation") or {}
                        )
                        next_frames = _normalize_blender_review_frames(
                            list(verdict.get("review_frames") or []),
                            int(next_animation["frame_start"]),
                            int(next_animation["frame_end"]),
                        )
                        raw_next_mapping = verdict.get("semantic_mapping")
                        if not isinstance(raw_next_mapping, dict):
                            current_names = {
                                str(item.get("name") or "")
                                for item in scene.get("objects") or []
                            }
                            next_names = {
                                str(item.get("name") or "")
                                for item in next_scene.get("objects") or []
                            }
                            mapping_fallback = semantic_mapping if current_names == next_names else None
                        else:
                            mapping_fallback = None
                        next_semantic_mapping = _normalize_blender_semantic_mapping(
                            raw_next_mapping,
                            next_scene,
                            director_prompt=str(plan.get("director_prompt") or ""),
                            fallback=mapping_fallback,
                        )
                    except (TypeError, ValueError) as error:
                        raise HTTPException(
                            status_code=422,
                            detail="The Director's Blender scene plan could not be applied. Review the plan and try again.",
                        ) from error
                    scene, animation, review_frames, semantic_mapping = (
                        next_scene, next_animation, next_frames, next_semantic_mapping
                    )
                    frame_start = int(animation["frame_start"])
                    frame_end = int(animation["frame_end"])
                    service.invoke("scene_create", scene)
                    service.invoke("animate_keyframes", animation)

                if not approved:
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            f"Director did not approve the Blender animation after "
                            f"{len(reviews)} review pass(es). Refine the prompt and retry."
                        ),
                    )

                video_name = f"blender_reference_{run_id[:12]}.mp4"
                with _BlenderGpuRenderSlot():
                    rendered = service.invoke("render_animation", {
                        "output_path": video_name,
                        "frame_start": frame_start,
                        "frame_end": frame_end,
                        "fps": fps,
                        "overwrite": False,
                    })
            video_path = os.path.realpath(str(rendered.get("output_path") or ""))
            if (
                os.path.dirname(video_path) != os.path.realpath(project_root)
                or not os.path.isfile(video_path)
            ):
                raise HTTPException(
                    status_code=503, detail="Blender returned an invalid full video",
                )
            _write_blender_video_sidecar(
                project_root, os.path.basename(video_path),
                workspace=workspace,
                policy=policy,
                lineage=lineage,
                frame_start=frame_start,
                frame_end=frame_end,
                fps=fps,
                review_attempts=len(reviews),
                director_model=director_model,
                control_mode=control_mode,
                semantic_mapping=semantic_mapping,
            )
            try:
                asset = _project_asset_store().create_asset(
                    workspace, "main",
                    name=reference_name,
                    asset_type="setting",
                    description=(
                        f"Director-reviewed Blender motion candidate; "
                        f"{frame_end - frame_start + 1} frames at {fps} fps"
                    ),
                    provenance="generated",
                    variants=[{
                        "variant_type": "blender_video",
                        "label": "Director-reviewed full-rate video",
                        "outputs": [{
                            "source_path": video_path,
                            "label": "Full animation reference",
                            "metadata": {
                                **dict(policy),
                                "semantic_mapping": semantic_mapping,
                                "conditioned_prompt": semantic_mapping["conditioned_prompt"],
                            },
                        }],
                        "provenance": "generated",
                        "status": "candidate",
                        "metadata": {
                            "tool": "blender_mcp",
                            "director_model": director_model,
                            "artifact_lineage": lineage,
                            "gallery_output_filename": os.path.basename(video_path),
                            "review_owner_session_hash": hashlib.sha256(
                                request.state.maestro_session_id.encode("utf-8")
                            ).hexdigest(),
                            "requested_private": bool(policy.get("private", False)),
                            "requested_explicit": bool(policy.get("explicit", False)),
                            "recommended_model_type": "ltx2_22B_1_1",
                            "recommended_video_prompt_type": control_mode,
                            "ic_lora_adapter": "LTX-2.3 Union Control ref0.5",
                            "reference_downscale_factor": 2,
                            "attention_strength": 1.0,
                            "full_fps_reference": True,
                            "stage2_controlled": False,
                            "semantic_mapping": semantic_mapping,
                            "conditioned_prompt": semantic_mapping["conditioned_prompt"],
                        },
                    }],
                    metadata={
                        "tool": "blender_mcp",
                        "director_reviewed": True,
                        "artifact_lineage": lineage,
                        "recommended_model_type": "ltx2_22B_1_1",
                        "recommended_video_prompt_type": control_mode,
                        "full_fps_reference": True,
                        "semantic_mapping": semantic_mapping,
                        "conditioned_prompt": semantic_mapping["conditioned_prompt"],
                    },
                )
            except Exception:
                # Do not orphan a review-only gallery candidate if its asset
                # provenance cannot be committed.
                for path in (
                    video_path,
                    os.path.join(
                        project_root,
                        os.path.splitext(os.path.basename(video_path))[0] + ".meta.json",
                    ),
                ):
                    try:
                        os.remove(path)
                    except OSError:
                        pass
                raise
            variant = asset["variants"][0]
            return {
                "status": "awaiting_user_review",
                "workspace": workspace,
                "video": {
                    "filename": os.path.basename(video_path),
                    "url": f"/api/v1/file/{quote(os.path.basename(video_path))}?workspace={quote(workspace)}",
                    "fps": fps,
                    "frame_start": frame_start,
                    "frame_end": frame_end,
                    "frame_count": frame_end - frame_start + 1,
                    "duration_seconds": (frame_end - frame_start + 1) / fps,
                    "recommended_model_type": "ltx2_22B_1_1",
                    "recommended_video_prompt_type": control_mode,
                    "stage2_controlled": False,
                },
                "asset_id": asset["id"],
                "variant_id": variant["id"],
                "director_model": director_model,
                "director_reviews": reviews,
                "semantic_mapping": semantic_mapping,
                "final_plan": {
                    **plan,
                    "scene": scene,
                    "animation": animation,
                    "semantic_mapping": semantic_mapping,
                    "review_frames": review_frames,
                    "fps": fps,
                },
            }
        except Exception:
            # Failed analyses never leave internal review samples behind.
            for sample_name in sample_names:
                for path in (
                    os.path.join(project_root, sample_name),
                    os.path.join(
                        project_root,
                        os.path.splitext(sample_name)[0] + ".meta.json",
                    ),
                ):
                    try:
                        os.remove(path)
                    except OSError:
                        pass
            raise

    try:
        return await asyncio.to_thread(execute_review_loop)
    except HTTPException:
        raise
    except Exception as error:
        raise _blender_error(error) from error


# ============================================================================
# API Routes: Storage (duplicate finder + usage analytics)
# ============================================================================

_STORAGE_WEIGHT_EXTS = (".safetensors", ".sft", ".gguf", ".pth", ".ckpt", ".pt", ".bin", ".onnx")
_STORAGE_MIN_DUP_BYTES = 10 * 1024 * 1024  # skip configs/tokenizers — reclaim noise


def _walk_sized(root: str) -> dict:
    """normcased relpath -> (abs_path, size) for weight files under root."""
    out: dict = {}
    root_abs = os.path.abspath(root)
    for dirpath, _dirnames, filenames in os.walk(root_abs):
        for f in filenames:
            if not f.lower().endswith(_STORAGE_WEIGHT_EXTS):
                continue
            full = os.path.join(dirpath, f)
            try:
                size = os.path.getsize(full)
            except OSError:
                continue
            out[os.path.normcase(os.path.relpath(full, root_abs))] = (full, size)
    return out


def _same_physical_file(a: str, b: str) -> bool:
    """True when two paths reference the same on-disk data: junctions and
    symlinks resolve via realpath; NTFS hardlinks (which realpath does NOT
    resolve) via matching (st_dev, st_ino)."""
    if os.path.normcase(os.path.realpath(a)) == os.path.normcase(os.path.realpath(b)):
        return True
    try:
        sa, sb = os.stat(a), os.stat(b)
        return sa.st_ino != 0 and (sa.st_dev, sa.st_ino) == (sb.st_dev, sb.st_ino)
    except OSError:
        return False


def _files_probably_identical(a: str, b: str, size: int) -> bool:
    """Sampled content comparison (1MB head/middle/tail) — same-size files
    can still be divergent weights (a retrained LoRA at the same rank is
    byte-size-identical), and reading multi-GB files fully is not viable
    per scan."""
    chunk = 1024 * 1024
    offsets = [0]
    if size > chunk * 3:
        offsets += [size // 2, max(0, size - chunk)]
    elif size > chunk:
        offsets.append(max(0, size - chunk))
    try:
        with open(a, "rb") as fa, open(b, "rb") as fb:
            for off in offsets:
                fa.seek(off)
                fb.seek(off)
                if fa.read(chunk) != fb.read(chunk):
                    return False
        return True
    except OSError:
        return False


def _storage_roots() -> dict:
    """Primary + linked roots for both file kinds, resolved once."""
    ckpt_roots = wgp.fl.get_checkpoints_paths()
    # The "." search root is the whole app folder — walking it would sweep
    # the entire repo; only the real primary (index 0) is the reclaim target.
    primary_ckpts = os.path.abspath(ckpt_roots[0]) if ckpt_roots else None
    linked_ckpts = [os.path.abspath(r) for r in ckpt_roots[1:] if wgp.fl.is_external_root(r)]
    lora_primary = _resolve_lora_root()
    return {
        "checkpoint": (primary_ckpts, linked_ckpts),
        "lora": (os.path.abspath(lora_primary) if lora_primary else None, _linked_lora_roots()),
    }


@api.get("/api/v1/storage/duplicates")
def storage_duplicates():
    """Primary-root files that also exist (same relative path AND size) in
    a linked install. Deleting the PRIMARY copy is pure reclaim — the
    files locator keeps resolving the linked copy afterwards. Same-path
    different-size pairs are conflicts, not duplicates: the primary copy
    currently shadows a divergent linked file and deleting it would
    silently change behavior."""
    duplicates = []
    conflicts = []
    shared_via_link = 0
    for kind, (primary_root, linked_roots) in _storage_roots().items():
        if not primary_root or not os.path.isdir(primary_root):
            continue
        primary_files = _walk_sized(primary_root)
        for linked_root in linked_roots:
            if not os.path.isdir(linked_root):
                continue
            linked_files = _walk_sized(linked_root)
            for rel, (ppath, psize) in primary_files.items():
                hit = linked_files.get(rel)
                if not hit:
                    continue
                lpath, lsize = hit
                if psize == lsize:
                    # Same physical data (junction, symlink, or hardlink)
                    # is zero reclaimable bytes — "deleting one copy"
                    # would delete the only copy.
                    if _same_physical_file(ppath, lpath):
                        shared_via_link += 1
                        continue
                # Both roots derive from <install>/app/<ckpts|loras>, so the
                # install name is two levels up from the ROOT (deriving it
                # from the file path mislabels subfoldered loras).
                row = {
                    "kind": kind, "filename": os.path.basename(ppath), "rel_path": rel,
                    "primary_path": ppath, "size_bytes": psize,
                    "linked_path": lpath, "linked_size_bytes": lsize,
                    "linked_install": os.path.basename(os.path.dirname(os.path.dirname(linked_root))),
                }
                if psize == lsize and psize >= _STORAGE_MIN_DUP_BYTES:
                    # Same size is not same content: a retrained LoRA at the
                    # same rank is byte-size-identical. Divergent pairs are
                    # conflicts (the primary is the one actually in use).
                    if _files_probably_identical(ppath, lpath, psize):
                        duplicates.append(row)
                    else:
                        conflicts.append(row)
                elif psize != lsize:
                    conflicts.append(row)
    # One primary file can match several linked installs — count it once,
    # keyed by PHYSICAL identity so a junctioned root can't double-list.
    seen = set()
    unique = []
    for d in duplicates:
        key = os.path.normcase(os.path.realpath(d["primary_path"]))
        if key not in seen:
            seen.add(key)
            unique.append(d)
    return {
        "duplicates": sorted(unique, key=lambda d: -d["size_bytes"]),
        "conflicts": conflicts,
        "shared_via_link": shared_via_link,
        "total_reclaimable_bytes": sum(d["size_bytes"] for d in unique),
    }


@api.post("/api/v1/storage/duplicates/reclaim")
async def storage_reclaim(request: Request):
    """Delete ONE primary-root duplicate. Revalidates from scratch: the
    path must live under a primary root and a same-relpath same-size
    linked copy must exist right now — a stale scan result can't delete
    anything that isn't still redundant."""
    body = await request.json()
    path = body.get("path", "")
    if not path or not os.path.isfile(path):
        raise HTTPException(status_code=404, detail="File not found.")
    target = os.path.abspath(path)
    if wgp.fl.is_protected_path(target):
        raise HTTPException(status_code=403, detail="That file is in a linked install (read-only).")
    # All comparisons happen in realpath space: a junctioned primary root
    # (e.g. ckpts linked into another install to share storage) makes
    # abspath and physical location disagree, and a "linked copy" reached
    # through the junction is the SAME file — deleting the primary would
    # delete the only copy.
    target_real = os.path.realpath(target)
    try:
        psize = os.path.getsize(target_real)
    except OSError:
        raise HTTPException(status_code=404, detail="File not found.")
    matched = False
    for kind, (primary_root, linked_roots) in _storage_roots().items():
        if not primary_root:
            continue
        proot_real = os.path.realpath(primary_root)
        if not os.path.normcase(target_real).startswith(os.path.normcase(proot_real + os.sep)):
            continue
        rel_key = os.path.relpath(target_real, proot_real)
        for linked_root in linked_roots:
            candidate = os.path.join(linked_root, rel_key)
            try:
                if not os.path.isfile(candidate) or os.path.getsize(candidate) != psize:
                    continue
                # Same physical data (junction/symlink/hardlink) is not a
                # copy, and same size is not same content — a retrained
                # LoRA at the same rank is byte-size-identical.
                if _same_physical_file(candidate, target_real):
                    continue
                if not _files_probably_identical(target_real, candidate, psize):
                    continue
                matched = candidate
                break
            except OSError:
                continue
        break
    if not matched:
        raise HTTPException(status_code=409, detail="No identical linked copy exists (anymore) — refusing to delete the only copy.")
    from services.win_safe_files import safe_delete
    result = safe_delete(target)
    if not result.get("deleted"):
        raise HTTPException(status_code=423, detail="The file is locked by another process. Try again in a moment.")
    # Audit line names the exact surviving copy — if it ever turns out to
    # be gone afterwards, this line is the forensic anchor.
    print(f"[Storage] Reclaimed duplicate: {target} ({psize} bytes; surviving copy: {matched})")
    if not os.path.isfile(matched):
        print(f"[Storage] CRITICAL: surviving copy vanished immediately after reclaim: {matched}")
    return {"status": "ok", "freed_bytes": psize, "deferred": bool(result.get("deferred")), "surviving_copy": matched}


@api.post("/api/v1/storage/duplicates/remove-linked")
async def storage_remove_linked(request: Request):
    """The inverse of reclaim: keep Maestro's copy, remove the LINKED
    install's duplicate — to the Recycle Bin, never a hard delete.

    Gated on the opt-in services.storage_allow_linked_removal flag:
    deleting from another install is the one sanctioned exception to the
    is_protected_path rule, and only with an identical different-physical
    copy verified in Maestro's primary root at this exact moment."""
    services = wgp.server_config.get("services", {})
    if not services.get("storage_allow_linked_removal", False):
        raise HTTPException(status_code=403, detail="Removing files from linked installs is disabled. Enable it in the Storage Manager first.")
    body = await request.json()
    path = body.get("path", "")
    if not path or not os.path.isfile(path):
        raise HTTPException(status_code=404, detail="File not found.")
    target = os.path.abspath(path)
    if not wgp.fl.is_protected_path(target):
        raise HTTPException(status_code=400, detail="That file is not in a linked install — use Reclaim for Maestro's own copies.")
    target_real = os.path.realpath(target)
    try:
        psize = os.path.getsize(target_real)
    except OSError:
        raise HTTPException(status_code=404, detail="File not found.")
    surviving = None
    for kind, (primary_root, linked_roots) in _storage_roots().items():
        if not primary_root:
            continue
        for linked_root in linked_roots:
            lroot_real = os.path.realpath(linked_root)
            if not os.path.normcase(target_real).startswith(os.path.normcase(lroot_real + os.sep)):
                continue
            rel_key = os.path.relpath(target_real, lroot_real)
            candidate = os.path.join(primary_root, rel_key)
            try:
                if not os.path.isfile(candidate) or os.path.getsize(candidate) != psize:
                    continue
                if _same_physical_file(candidate, target_real):
                    continue
                if not _files_probably_identical(target_real, candidate, psize):
                    continue
                surviving = os.path.abspath(candidate)
                break
            except OSError:
                continue
        if surviving:
            break
    if not surviving:
        raise HTTPException(status_code=409, detail="Maestro does not hold an identical copy of that file — refusing to remove the linked install's only version.")
    from services.win_safe_files import recycle_file
    if not recycle_file(target):
        raise HTTPException(status_code=423, detail="Could not move the file to the Recycle Bin (it may be locked, or too large for the Bin). Nothing was deleted.")
    print(f"[Storage] Removed linked duplicate to Recycle Bin: {target} ({psize} bytes; Maestro's copy: {surviving})")
    return {"status": "ok", "freed_bytes": psize, "recycled": True, "surviving_copy": surviving}


@api.get("/api/v1/storage/usage")
def storage_usage():
    """Usage analytics backfilled from generation sidecars: every job ever
    run left a .meta.json with model_type, activated_loras, and created_at.
    Joined with on-disk sizes so 'largest, least used' is one sort away."""
    base = wgp.server_config.get("save_path", "outputs")
    scan_dirs = [w["path"] for w in _list_workspaces()]
    model_usage: dict = {}
    lora_usage: dict = {}
    sidecars = 0
    for d in scan_dirs:
        try:
            entries = os.listdir(d)
        except OSError:
            continue
        for n in entries:
            if not n.endswith(".meta.json"):
                continue
            try:
                with open(os.path.join(d, n), "r", encoding="utf-8") as f:
                    meta = json.load(f)
            except Exception:
                continue
            sidecars += 1
            params = meta.get("params") or {}
            created = meta.get("created_at") or 0
            mt = params.get("model_type")
            if mt:
                agg = model_usage.setdefault(mt, {"count": 0, "last_used": 0})
                agg["count"] += 1
                agg["last_used"] = max(agg["last_used"], created)
            for lora in params.get("activated_loras") or []:
                if isinstance(lora, str) and lora:
                    agg = lora_usage.setdefault(lora, {"count": 0, "last_used": 0})
                    agg["count"] += 1
                    agg["last_used"] = max(agg["last_used"], created)

    models = []
    # Shared weights (pointer-resolved base transformers, common text
    # encoders) appear in MANY models' groups — per-model sizes overlap by
    # design, so the dashboard's total comes from this global dedupe, not
    # from summing rows.
    global_seen = set()
    models_total_bytes = 0
    for mt in wgp.displayed_model_types:
        if mt == "minimax_music3":
            continue
        md = wgp.get_model_def(mt)
        if md is None:
            continue
        total = 0
        primary_bytes = 0
        seen_paths = set()
        try:
            for group in _model_weight_groups(mt):
                for fname in _variant_group_filenames(group):
                    p = wgp.fl.locate_file(fname, error_if_none=False)
                    if not p:
                        continue
                    key = os.path.normcase(os.path.abspath(p))
                    if key in seen_paths:
                        continue
                    seen_paths.add(key)
                    try:
                        size = os.path.getsize(p)
                    except OSError:
                        continue
                    total += size
                    if key not in global_seen:
                        global_seen.add(key)
                        models_total_bytes += size
            # What the row's Delete actually frees: DELETE /models/{mt}
            # removes owned files only (a finetune's alias never deletes
            # the shared base) — mirror that here or the button lies.
            for group in _model_weight_groups(mt, owned_only=True):
                for fname in _variant_group_filenames(group):
                    p = wgp.fl.locate_file(fname, error_if_none=False)
                    if p and not wgp.fl.is_protected_path(p):
                        try:
                            primary_bytes += os.path.getsize(p)
                        except OSError:
                            pass
        except Exception:
            pass
        usage = model_usage.get(mt, {})
        # Rows without deletable bytes need to say WHY: a finetune whose
        # def aliases another model's weights frees nothing when deleted
        # (delete the base row instead), and weights living only in
        # linked installs are read-only here.
        _raw_urls = md.get("URLs")
        _alias_of = None
        if isinstance(_raw_urls, str):
            _alias_md = wgp.get_model_def(_raw_urls)
            _alias_of = (_alias_md or {}).get("name", _raw_urls)
        models.append({
            "model_type": mt, "name": md.get("name", mt),
            "size_bytes": total, "primary_bytes": primary_bytes,
            "alias_of": _alias_of,
            "use_count": usage.get("count", 0),
            "last_used": usage.get("last_used") or None,
        })

    loras = []
    lora_root = _resolve_lora_root()
    walk_roots = ([(lora_root, False)] if lora_root else []) + [(r, True) for r in _linked_lora_roots()]
    seen_keys = set()
    for root, linked in walk_roots:
        for dirpath, _dn, fns in os.walk(root):
            for f in fns:
                if not f.endswith((".safetensors", ".sft")):
                    continue
                rel_dir = os.path.relpath(dirpath, root)
                key = os.path.normcase(os.path.normpath(os.path.join(rel_dir, f)))
                if key in seen_keys:
                    continue
                seen_keys.add(key)
                try:
                    size = os.path.getsize(os.path.join(dirpath, f))
                except OSError:
                    size = 0
                usage = lora_usage.get(f, {})
                loras.append({
                    "filename": f, "directory": rel_dir, "linked": linked, "size_bytes": size,
                    "use_count": usage.get("count", 0),
                    "last_used": usage.get("last_used") or None,
                })

    workspaces = []
    for w in _list_workspaces():
        ws_bytes = 0
        try:
            with os.scandir(w["path"]) as it:
                for e in it:
                    if e.is_file() and not e.name.startswith("."):
                        try:
                            ws_bytes += e.stat().st_size
                        except OSError:
                            pass
        except OSError:
            pass
        workspaces.append({"name": w["name"], "file_count": w.get("file_count", 0), "size_bytes": ws_bytes})

    return {
        "models": sorted(models, key=lambda m: -m["size_bytes"]),
        "models_total_bytes": models_total_bytes,
        "loras": sorted(loras, key=lambda l: -l["size_bytes"]),
        "workspaces": workspaces,
        "scanned_sidecars": sidecars,
    }


# ============================================================================
# API Routes: LLM service
# ============================================================================

@api.get("/api/v1/llm/status")
def llm_status():
    """Get LLM service status."""
    from services import llm_service
    return _truthful_llm_status(llm_service)


def _truthful_llm_status(llm_service) -> dict:
    """Publish a local model as loaded only after health-ready commit.

    ``llama-server`` exists while it is still loading weights, but the runtime
    intentionally commits ``model_id`` and effective ``device`` only after its
    health endpoint reports ready.  Treat that identity-less subprocess state
    as loading so API/UI consumers cannot mistake it for usable inference.
    """
    status = dict(llm_service.get_status())
    runtime = status.get("runtime")
    if isinstance(runtime, dict):
        runtime = dict(runtime)
        if "speed" in runtime:
            runtime["speed"] = _safe_llm_speed(runtime.get("speed"))
        status["runtime"] = runtime
    transient_local_load = bool(
        status.get("provider", "local") == "local"
        and status.get("loaded")
        and (not status.get("model_id") or not status.get("device"))
    )
    if transient_local_load:
        status["loaded"] = False
        status["device"] = None
        status["vision_available"] = False
        status["loading"] = True
        status["loading_phase"] = status.get("loading_phase") or "loading model"
        if isinstance(runtime, dict) and "speed" in runtime:
            runtime["speed"] = _safe_llm_speed(None)
            runtime["speed"]["reason"] = "The selected model is still loading."
    return status


def _safe_llm_speed(speed) -> dict:
    """Normalize content-free runtime speed metadata for browser exposure."""
    unavailable = {
        "prompt_tokens_per_second": None,
        "generation_tokens_per_second": None,
        "source": "unavailable",
        "confidence": "unavailable",
        "reason": "No calibrated measurement is available yet.",
        "sample_count": 0,
        "backend": "unavailable",
    }
    if not isinstance(speed, dict):
        return unavailable
    result = dict(unavailable)
    for key in (
        "prompt_tokens_per_second", "generation_tokens_per_second",
    ):
        value = speed.get(key)
        if (
            isinstance(value, (int, float))
            and not isinstance(value, bool)
            and math.isfinite(value)
            and value > 0
        ):
            result[key] = float(value)
    if speed.get("source") in {
        "measured", "calibrated", "heuristic", "unavailable",
    }:
        result["source"] = speed["source"]
    if speed.get("confidence") in {
        "measured", "high", "medium", "low", "unavailable",
    }:
        result["confidence"] = speed["confidence"]
    reason = speed.get("reason")
    if isinstance(reason, str) and reason.strip():
        # Reasons describe only numeric/model-profile calibration. Bounded text
        # prevents a provider response from becoming a path or prompt oracle.
        result["reason"] = reason.strip()[:240]
    count = speed.get("sample_count")
    if isinstance(count, int) and not isinstance(count, bool) and count >= 0:
        result["sample_count"] = min(count, 1_000_000)
    backend = speed.get("backend")
    if backend in {"cuda", "cpu", "remote", "openai", "anthropic", "unavailable"}:
        result["backend"] = backend
    return result


@api.post("/api/v1/llm/load")
async def llm_load(request: Request):
    """Load the LLM model."""
    from services import llm_service
    from services.llm_operations import run_blocking_shielded
    body = {}
    if request.headers.get("content-type", "").startswith("application/json"):
        body = await request.json()

    _require_local_llm_control(request)

    services = wgp.server_config.get("services", {})
    provider = body.get("provider", services.get("llm_provider", "local"))
    selection = {
        "model_id": body.get(
            "model_id", services.get("llm_model_id", _DEFAULT_LLM_REPO),
        ),
        "device": body.get(
            "device", services.get("llm_device", _llm_default_device()),
        ),
        "provider": provider,
        "remote_url": body.get(
            "remote_url", services.get("llm_remote_url", ""),
        ),
        "api_key": _llm_provider_api_key(provider, services),
        "local_gguf_path": "",
        "gguf_file_override": "",
    }

    try:
        await run_blocking_shielded(
            _run_authorized_llm_with_selection, request, selection,
        )
        return {"status": "ok", **llm_service.get_status()}
    except Exception as error:
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail="LLM preparation failed; check the local Maestro logs",
        ) from error


@api.post("/api/v1/llm/unload")
def llm_unload(request: Request):
    """Unload the LLM model to free memory."""
    from services import llm_service
    _require_local_llm_control(request)
    with _gen_lock:
        # Classify after acquiring the generation gate.  A queued unload may
        # otherwise observe CPU, then unload a replacement CUDA runtime without
        # joining the process-global native GPU lane.
        status = llm_service.get_status()
        with _WgpNativeGpuExecutionSlot(
            _local_llm_uses_native_gpu(status),
        ):
            llm_service.unload_model()
    return {"status": "ok"}


def _llm_provider_api_key(provider: str, services: dict) -> str:
    if provider == "openai":
        return services.get("openai_api_key", "")
    if provider == "anthropic":
        return services.get("anthropic_api_key", "")
    return ""


def _llm_linked_model_roots() -> list[str]:
    """Return only owner-configured, read-only roots for GGUF discovery."""
    return list(_get_linked_model_folders())


_llm_chat_admission = threading.BoundedSemaphore(1)
_LLM_CHAT_MAX_IMAGES = 4
_LLM_ENHANCE_MAX_IMAGES = _LLM_CHAT_MAX_IMAGES
_LLM_CHAT_MAX_IMAGE_BYTES = 32 * 1024 * 1024
_LLM_ENHANCE_MAX_TOTAL_IMAGE_BYTES = 64 * 1024 * 1024
_LLM_CHAT_IMAGE_EXTENSIONS = {
    ".avif", ".bmp", ".gif", ".jpeg", ".jpg", ".png", ".webp",
}
_LLM_CHAT_UPLOAD_MARKER_SUFFIX = ".llm-chat-upload.json"
_LLM_CHAT_UPLOAD_TTL_SECONDS = 24 * 60 * 60
_LLM_CHAT_UPLOAD_SERVER_EPOCH = uuid.uuid4().hex
_llm_chat_upload_lock = threading.RLock()
_llm_project_instance_lock = threading.Lock()


class _LlmChatUploadClaimError(RuntimeError):
    """One-use Chat input could not be claimed by this request."""


def _llm_chat_upload_marker_path(upload_path: str) -> str:
    return f"{upload_path}{_LLM_CHAT_UPLOAD_MARKER_SUFFIX}"


def _read_llm_chat_upload_marker(upload_path: str) -> dict | None:
    try:
        with open(
            _llm_chat_upload_marker_path(upload_path),
            "r",
            encoding="utf-8",
        ) as handle:
            marker = json.load(handle)
    except (OSError, TypeError, ValueError):
        return None
    if not isinstance(marker, dict) or marker.get("version") not in {1, 2}:
        return None
    if marker.get("kind") != "llm_chat_upload":
        return None
    owner = marker.get("owner_session_id")
    workspace = marker.get("workspace")
    created_at = marker.get("created_at")
    if (
        not isinstance(owner, str)
        or len(owner) != 32
        or any(character not in "0123456789abcdef" for character in owner)
        or not isinstance(workspace, str)
        or not workspace
        or not isinstance(created_at, (int, float))
        or isinstance(created_at, bool)
        or not math.isfinite(float(created_at))
        or float(created_at) < 0
    ):
        return None
    if marker["version"] == 1:
        if "claim" in marker or "project_instance" in marker or "pending_request_id" in marker:
            return None
    if marker["version"] == 2:
        project_instance = marker.get("project_instance")
        pending_request_id = marker.get("pending_request_id")
        claim = marker.get("claim")
        if (
            not isinstance(project_instance, str)
            or re.fullmatch(r"[0-9a-f]{64}", project_instance) is None
            or re.fullmatch(
                r"[0-9a-f]{32}", str(pending_request_id or ""),
            ) is None
            or claim is not None and (
                not isinstance(claim, dict)
                or set(claim) != {
                    "request_id", "request_digest", "project_instance",
                    "server_epoch", "claimed_at",
                }
                or re.fullmatch(
                    r"[0-9a-f]{32}", str(claim.get("request_id") or ""),
                ) is None
                or claim.get("request_id") != pending_request_id
                or re.fullmatch(
                    r"[0-9a-f]{64}", str(claim.get("request_digest") or ""),
                ) is None
                or claim.get("project_instance") != project_instance
                or re.fullmatch(
                    r"[0-9a-f]{32}", str(claim.get("server_epoch") or ""),
                ) is None
                or not isinstance(claim.get("claimed_at"), (int, float))
                or isinstance(claim.get("claimed_at"), bool)
                or not math.isfinite(float(claim["claimed_at"]))
                or float(claim["claimed_at"]) < 0
            )
        ):
            return None
    return marker


def _write_llm_chat_upload_marker(marker_path: str, marker: dict) -> None:
    """Create or atomically replace one private marker under the caller lock."""
    temp_path = f"{marker_path}.{uuid.uuid4().hex[:8]}.tmp"
    descriptor = None
    try:
        descriptor = os.open(
            temp_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            0o600,
        )
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            descriptor = None
            json.dump(marker, handle, sort_keys=True, separators=(",", ":"))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, marker_path)
    finally:
        if descriptor is not None:
            os.close(descriptor)
        try:
            os.remove(temp_path)
        except OSError:
            pass


def _register_llm_chat_upload(
    request: Request,
    workspace: str,
    filename: str,
    request_id: str,
) -> None:
    """Mark one direct, private upload as single-use Chat input."""
    from services.win_safe_files import safe_direct_file_under

    root = os.path.join(os.getcwd(), "uploads")
    upload_path = safe_direct_file_under(root, filename)
    owner = str(getattr(request.state, "maestro_session_id", "") or "")
    if (
        upload_path is None
        or not os.path.isfile(upload_path)
        or not can_access_upload(upload_path, owner)
    ):
        raise HTTPException(status_code=404, detail="Chat image not found")
    marker = {
        "version": 2,
        "kind": "llm_chat_upload",
        "owner_session_id": owner,
        "workspace": workspace,
        "project_instance": _llm_project_instance_id(request, workspace),
        "pending_request_id": request_id,
        "created_at": time.time(),
        "claim": None,
    }
    marker_path = _llm_chat_upload_marker_path(upload_path)
    with _llm_chat_upload_lock:
        _write_llm_chat_upload_marker(marker_path, marker)


def _claim_llm_chat_uploads(
    request: Request,
    workspace: str,
    image_paths: list[str],
    *,
    request_id: str,
    request_digest: str,
    project_instance: str,
) -> None:
    """Atomically fence one-use uploads before publishing an operation."""
    from services.win_safe_files import safe_direct_file_under

    root = os.path.join(os.getcwd(), "uploads")
    owner = str(getattr(request.state, "maestro_session_id", "") or "")
    candidates: list[tuple[str, str, dict]] = []
    with _llm_chat_upload_lock:
        for raw_path in image_paths:
            upload_path = safe_direct_file_under(
                root, os.path.basename(str(raw_path or "")),
            )
            if (
                upload_path is None
                or not os.path.isabs(str(raw_path or ""))
                or os.path.normcase(os.path.abspath(str(raw_path)))
                != os.path.normcase(upload_path)
            ):
                continue
            if (
                not os.path.isfile(upload_path)
                or not can_access_upload(upload_path, owner)
            ):
                # A concurrent client cleanup won. Do not publish an operation
                # with a path that disappeared after request resolution.
                raise _LlmChatUploadClaimError
            marker = _read_llm_chat_upload_marker(upload_path)
            if marker is None:
                # Ordinary authorized uploads and project media are compatible,
                # but a present malformed one-use marker fails closed.
                if os.path.exists(_llm_chat_upload_marker_path(upload_path)):
                    raise _LlmChatUploadClaimError
                continue
            if (
                not hmac.compare_digest(marker["owner_session_id"], owner)
                or marker["workspace"] != workspace
            ):
                raise _LlmChatUploadClaimError
            # V1 markers have no immutable project identity and are retained
            # only for bounded cleanup compatibility. They can never be
            # promoted into a newly created same-name project.
            if marker["version"] != 2:
                raise _LlmChatUploadClaimError
            if (
                not hmac.compare_digest(
                    marker["project_instance"], project_instance,
                )
                or not hmac.compare_digest(
                    marker["pending_request_id"], request_id,
                )
            ):
                raise _LlmChatUploadClaimError
            claim = marker.get("claim")
            if claim is not None and claim["server_epoch"] == _LLM_CHAT_UPLOAD_SERVER_EPOCH:
                if not (
                    hmac.compare_digest(claim["request_id"], request_id)
                    and hmac.compare_digest(
                        claim["request_digest"], request_digest,
                    )
                    and hmac.compare_digest(
                        claim["project_instance"], project_instance,
                    )
                ):
                    raise _LlmChatUploadClaimError
                continue
            candidates.append((
                upload_path,
                _llm_chat_upload_marker_path(upload_path),
                marker,
            ))

        written: list[tuple[str, dict]] = []
        try:
            for _upload_path, marker_path, previous in candidates:
                claimed = {
                    **previous,
                    "version": 2,
                    "project_instance": project_instance,
                    "claim": {
                        "request_id": request_id,
                        "request_digest": request_digest,
                        "project_instance": project_instance,
                        "server_epoch": _LLM_CHAT_UPLOAD_SERVER_EPOCH,
                        "claimed_at": time.time(),
                    },
                }
                _write_llm_chat_upload_marker(marker_path, claimed)
                written.append((marker_path, previous))
        except Exception:
            for marker_path, previous in reversed(written):
                try:
                    _write_llm_chat_upload_marker(marker_path, previous)
                except Exception:
                    pass
            raise


def _cleanup_llm_chat_uploads(
    request: Request,
    workspace: str,
    image_paths: list[str],
    *,
    request_id: str | None = None,
    request_digest: str | None = None,
    project_instance: str | None = None,
) -> list[str]:
    """Delete only single-use Chat uploads owned by this project/session."""
    from services.output_access import upload_access_sidecar_path
    from services.win_safe_files import safe_direct_file_under

    root = os.path.join(os.getcwd(), "uploads")
    owner = str(getattr(request.state, "maestro_session_id", "") or "")
    deleted = []
    with _llm_chat_upload_lock:
        for raw_path in image_paths:
            filename = os.path.basename(str(raw_path or ""))
            upload_path = safe_direct_file_under(root, filename)
            if (
                upload_path is None
                or not os.path.isabs(str(raw_path or ""))
                or os.path.normcase(os.path.abspath(str(raw_path)))
                != os.path.normcase(upload_path)
            ):
                continue
            marker = _read_llm_chat_upload_marker(upload_path)
            if marker is None:
                continue
            if (
                not hmac.compare_digest(marker["owner_session_id"], owner)
                or marker["workspace"] != workspace
                or not can_access_upload(upload_path, owner)
            ):
                continue
            claim = marker.get("claim")
            if claim is not None:
                current_claim = (
                    claim["server_epoch"] == _LLM_CHAT_UPLOAD_SERVER_EPOCH
                )
                exact_server_cleanup = (
                    request_id is not None
                    and request_digest is not None
                    and project_instance is not None
                    and hmac.compare_digest(claim["request_id"], request_id)
                    and hmac.compare_digest(
                        claim["request_digest"], request_digest,
                    )
                    and hmac.compare_digest(
                        claim["project_instance"], project_instance,
                    )
                )
                if current_claim and not exact_server_cleanup:
                    continue
            try:
                os.remove(upload_path)
            except FileNotFoundError:
                pass
            except OSError:
                # Keep the authorization sidecar and marker so a later cleanup
                # or TTL prune can safely retry without creating an untracked
                # private file.
                continue
            for path in (
                upload_access_sidecar_path(upload_path),
                _llm_chat_upload_marker_path(upload_path),
            ):
                try:
                    os.remove(path)
                except OSError:
                    pass
            deleted.append(filename)
    return deleted


def _prune_stale_llm_chat_uploads() -> None:
    """Bound crash/disconnect leftovers without touching ordinary uploads."""
    from services.output_access import upload_access_sidecar_path
    from services.win_safe_files import safe_direct_file_under

    root = os.path.join(os.getcwd(), "uploads")
    try:
        names = os.listdir(root)
    except OSError:
        return
    cutoff = time.time() - _LLM_CHAT_UPLOAD_TTL_SECONDS
    with _llm_chat_upload_lock:
        for marker_name in names[:4096]:
            if not marker_name.endswith(_LLM_CHAT_UPLOAD_MARKER_SUFFIX):
                continue
            filename = marker_name[:-len(_LLM_CHAT_UPLOAD_MARKER_SUFFIX)]
            upload_path = safe_direct_file_under(root, filename)
            if upload_path is None:
                continue
            marker = _read_llm_chat_upload_marker(upload_path)
            if marker is None or marker["created_at"] >= cutoff:
                continue
            claim = marker.get("claim")
            if (
                claim is not None
                and claim["server_epoch"] == _LLM_CHAT_UPLOAD_SERVER_EPOCH
                and max(
                    float(marker["created_at"]),
                    float(claim["claimed_at"]),
                ) >= cutoff
            ):
                continue
            try:
                os.remove(upload_path)
            except FileNotFoundError:
                pass
            except OSError:
                continue
            for path in (
                upload_access_sidecar_path(upload_path),
                _llm_chat_upload_marker_path(upload_path),
            ):
                try:
                    os.remove(path)
                except OSError:
                    pass


def _llm_chat_image_signature(header: bytes) -> bool:
    """Recognize the bounded image formats accepted by Chat."""
    return bool(
        header.startswith(b"\x89PNG\r\n\x1a\n")
        or header.startswith(b"\xff\xd8\xff")
        or header.startswith((b"GIF87a", b"GIF89a", b"BM"))
        or (
            len(header) >= 12
            and header[:4] == b"RIFF"
            and header[8:12] == b"WEBP"
        )
        or (
            len(header) >= 12
            and header[4:8] == b"ftyp"
            and header[8:12] in {b"avif", b"avis"}
        )
    )


@api.post("/api/v1/llm/chat-upload")
async def llm_chat_upload(
    request: Request,
    workspace: str,
    request_id: str,
    file: UploadFile = File(...),
):
    """Upload one private Chat image without exposing its server path."""
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    _require_project_access(request, workspace)
    try:
        normalized_request_id = _normalize_llm_chat_request_id(request_id)
    except ValueError as error:
        raise HTTPException(
            status_code=400, detail="Invalid Chat request id",
        ) from error
    _prune_stale_llm_chat_uploads()
    content_type = str(file.content_type or "").casefold()
    if not content_type.startswith("image/"):
        raise HTTPException(status_code=400, detail="Chat attachments must be images")
    extension = os.path.splitext(str(file.filename or ""))[1].casefold()
    if extension not in _LLM_CHAT_IMAGE_EXTENSIONS:
        raise HTTPException(status_code=400, detail="Unsupported Chat image format")
    declared_size = getattr(file, "size", None)
    if (
        isinstance(declared_size, int)
        and declared_size > _LLM_CHAT_MAX_IMAGE_BYTES
    ):
        raise HTTPException(
            status_code=413,
            detail="Chat image is too large (max 32 MB)",
        )
    if declared_size is None:
        probe = await file.read(_LLM_CHAT_MAX_IMAGE_BYTES + 1)
        await file.seek(0)
        if len(probe) > _LLM_CHAT_MAX_IMAGE_BYTES:
            raise HTTPException(
                status_code=413,
                detail="Chat image is too large (max 32 MB)",
            )
        header = probe[:16]
    else:
        header = await file.read(16)
        await file.seek(0)
    if not _llm_chat_image_signature(header):
        raise HTTPException(
            status_code=400,
            detail="Chat attachment is not a valid image",
        )
    result = await upload_image(request, file, private=True)
    try:
        _register_llm_chat_upload(
            request,
            workspace,
            result["filename"],
            normalized_request_id,
        )
    except Exception:
        from services.output_access import upload_access_sidecar_path
        from services.win_safe_files import safe_direct_file_under
        candidate = safe_direct_file_under(
            os.path.join(os.getcwd(), "uploads"),
            result["filename"],
        )
        if candidate and can_access_upload(
            candidate,
            request.state.maestro_session_id,
        ):
            for path in (candidate, upload_access_sidecar_path(candidate)):
                try:
                    os.remove(path)
                except OSError:
                    pass
        raise
    return {
        "filename": result["filename"],
        "url": result["url"],
    }


@api.delete("/api/v1/llm/chat-upload/{filename}")
def delete_llm_chat_upload(
    request: Request,
    filename: str,
    workspace: str,
):
    """Cancel one not-yet-consumed Chat upload owned by this session."""
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    # The session-owned marker is the authority for cancellation. Requiring a
    # still-unlocked project here would strand a pre-admission upload precisely
    # when project authorization changed between upload and Chat submission.
    resolved = _resolve_authorized_request_media(request, filename, workspace)
    deleted = (
        _cleanup_llm_chat_uploads(request, workspace, [resolved])
        if resolved else []
    )
    if not deleted:
        raise HTTPException(status_code=404, detail="Chat image not found")
    return {"deleted": deleted[0]}


@api.delete("/api/v1/llm/chat-upload-request/{request_id}")
def reconcile_llm_chat_upload_request(
    request: Request,
    request_id: str,
    workspace: str,
    project_instance: str,
):
    """Resolve reload ambiguity without exposing or persisting upload names."""
    from services.output_access import upload_access_sidecar_path
    from services.win_safe_files import safe_direct_file_under

    _require_upload_content_access(request)
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    try:
        normalized_request_id = _normalize_llm_chat_request_id(request_id)
    except ValueError as error:
        raise HTTPException(status_code=404, detail="Chat request not found") from error
    if re.fullmatch(r"[0-9a-f]{64}", str(project_instance or "")) is None:
        raise HTTPException(status_code=404, detail="Chat request not found")
    owner = str(getattr(request.state, "maestro_session_id", "") or "")
    root = os.path.join(os.getcwd(), "uploads")
    try:
        names = os.listdir(root)
    except OSError:
        names = []
    matched = False
    claimed_records: list[tuple[str, str, str]] = []
    cleanup_failed = False
    deleted = 0
    with _llm_chat_upload_lock:
        for marker_name in names[:4096]:
            if not marker_name.endswith(_LLM_CHAT_UPLOAD_MARKER_SUFFIX):
                continue
            filename = marker_name[:-len(_LLM_CHAT_UPLOAD_MARKER_SUFFIX)]
            upload_path = safe_direct_file_under(root, filename)
            if upload_path is None:
                continue
            marker = _read_llm_chat_upload_marker(upload_path)
            if (
                marker is None
                or marker["version"] != 2
                or not hmac.compare_digest(marker["owner_session_id"], owner)
                or marker["workspace"] != workspace
                or not hmac.compare_digest(
                    marker["project_instance"], project_instance,
                )
                or not hmac.compare_digest(
                    marker["pending_request_id"], normalized_request_id,
                )
                or not can_access_upload(upload_path, owner)
            ):
                continue
            matched = True
            claim = marker.get("claim")
            if (
                claim is not None
                and claim["server_epoch"] == _LLM_CHAT_UPLOAD_SERVER_EPOCH
            ):
                claimed_records.append((
                    upload_path,
                    claim["request_digest"],
                    marker["project_instance"],
                ))
                continue
            try:
                os.remove(upload_path)
            except FileNotFoundError:
                pass
            except OSError:
                cleanup_failed = True
                continue
            for path in (
                upload_access_sidecar_path(upload_path),
                _llm_chat_upload_marker_path(upload_path),
            ):
                try:
                    os.remove(path)
                except OSError:
                    pass
            deleted += 1
    owner_key = hmac.new(
        _session_secret(),
        f"llm-operation-owner-v1\0{owner}".encode(),
        hashlib.sha256,
    ).hexdigest()
    from services.llm_operations import llm_chat_operation_manager

    def cleanup_absent_claims():
        removed_count = 0
        failed = False
        for upload_path, request_digest, _project in claimed_records:
            removed = _cleanup_llm_chat_uploads(
                request,
                workspace,
                [upload_path],
                request_id=normalized_request_id,
                request_digest=request_digest,
                project_instance=project_instance,
            )
            removed_count += len(removed)
            if not removed and os.path.exists(upload_path):
                failed = True
        return removed_count, failed

    operation, reconciled = (
        llm_chat_operation_manager.status_or_reconcile_absent(
            normalized_request_id,
            owner_key=owner_key,
            project_key=project_instance,
            reconcile_absent=cleanup_absent_claims,
            reconcile_terminal=cleanup_absent_claims,
        )
    )
    if reconciled is not None:
        removed_count, failed = reconciled
        deleted += removed_count
        cleanup_failed = cleanup_failed or failed
    if operation is not None:
        return {"state": "claimed", "deleted": deleted}
    if cleanup_failed:
        return {"state": "retry", "deleted": deleted}
    if matched:
        return {"state": "cleaned", "deleted": deleted}
    return {"state": "not_found", "deleted": 0}


def _llm_chat_request_is_external(request: Request) -> bool:
    """Treat Cloudflare and non-loopback LAN clients as remote for Chat."""
    if bool(getattr(request.state, "maestro_remote", False)):
        return True
    peer_host = str(getattr(getattr(request, "client", None), "host", "") or "")
    if peer_host:
        try:
            if not ipaddress.ip_address(peer_host.split("%", 1)[0]).is_loopback:
                return True
        except ValueError:
            if peer_host.casefold() != "localhost":
                return True
    return any(
        not _approved_local_origin(origin)
        for origin in _request_external_origins(request)
    )


def _promote_external_llm_request(request: Request) -> None:
    """Apply Chat's LAN/Cloudflare boundary before project authorization."""
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True


def _require_local_llm_control(request: Request) -> None:
    """Require local authority or a recently reauthenticated remote owner."""
    _promote_external_llm_request(request)
    remote = bool(getattr(request.state, "maestro_remote", False))
    has_capability = globals().get("_request_has_account_capability")
    has_reauth = globals().get("_request_has_recent_account_reauth")
    remote_owner = (
        remote
        and callable(has_capability)
        and callable(has_reauth)
        and has_capability(request, "owner.remote_parity")
        and has_reauth(request)
    )
    if remote and not remote_owner:
        raise HTTPException(
            status_code=403,
            detail="This machine-wide control is available locally only",
        )


@api.middleware("http")
async def _llm_operation_no_store(request: Request, call_next):
    """Keep transient LLM operation state/results out of intermediary caches."""
    response = await call_next(request)
    path = request.url.path
    if (
        path == "/api/v1/llm/prepare"
        or path.startswith("/api/v1/llm/prepare/")
        or path == "/api/v1/llm/chat"
        or path.startswith("/api/v1/llm/chat/")
        or path.startswith("/api/v1/llm/chat-upload")
        or path == "/api/v1/llm/enhance-prompt"
        or path.startswith("/api/v1/llm/operations/")
        or path == "/api/v1/llm/refusal-literals"
        or path == "/api/v1/director/v2/plan"
    ):
        response.headers["Cache-Control"] = "private, no-store"
        response.headers["Pragma"] = "no-cache"
    return response


@api.post("/api/v1/llm/refusal-literals")
async def add_llm_refusal_literal(request: Request):
    """Add one exact owner-confirmed response literal on the host only."""
    # Repeat both guards at the endpoint so alternate/test invocation cannot
    # parse a remote or cross-origin body even without the normal middleware.
    _require_local_llm_control(request)
    csrf_denial = _reject_cross_origin_mutation(request)
    if csrf_denial is not None:
        return csrf_denial
    try:
        body = await request.json()
    except Exception as error:
        raise HTTPException(
            status_code=400, detail="Invalid refusal literal request",
        ) from error
    if not isinstance(body, dict) or "literal" not in body:
        raise HTTPException(
            status_code=400, detail="Invalid refusal literal request",
        )

    from services.llm_refusal_corpus import (
        RefusalCorpusStorageError,
        RefusalCorpusValidationError,
        add_refusal_literal,
    )

    try:
        update = add_refusal_literal(body.get("literal"))
    except RefusalCorpusValidationError as error:
        raise HTTPException(
            status_code=400, detail="Invalid refusal literal",
        ) from error
    except RefusalCorpusStorageError as error:
        raise HTTPException(
            status_code=500, detail="Refusal literal could not be saved",
        ) from error
    return JSONResponse(
        {
            "added": update.added,
            "count": update.snapshot.count,
            "revision": update.snapshot.revision,
        },
        headers={
            "Cache-Control": "private, no-store",
            "Pragma": "no-cache",
        },
    )


def _llm_project_instance_id(request: Request, workspace: str) -> str:
    """Return an opaque identity that changes if a project is recreated."""
    # Operation recovery must never reserve or recreate a missing project as
    # a side effect of a typo, stale poll, or detached worker retry.
    _require_project_access(request, workspace, existing_only=True)
    workspace_dir = _existing_workspace_dir(workspace)
    marker_path = os.path.join(workspace_dir, ".llm-chat-instance")

    def read_marker() -> str:
        flags = (
            os.O_RDONLY
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NONBLOCK", 0)
        )
        descriptor = -1
        try:
            descriptor = os.open(marker_path, flags)
            before = os.fstat(descriptor)
            if (
                not stat.S_ISREG(before.st_mode)
                or before.st_nlink != 1
                or before.st_size != 32
            ):
                return ""
            raw_value = os.read(descriptor, 33)
            after = os.fstat(descriptor)
            current = os.stat(marker_path, follow_symlinks=False)
            identity = (before.st_dev, before.st_ino, before.st_size)
            if (
                identity != (after.st_dev, after.st_ino, after.st_size)
                or identity != (
                    current.st_dev, current.st_ino, current.st_size,
                )
                or not stat.S_ISREG(current.st_mode)
                or current.st_nlink != 1
            ):
                return ""
            value = raw_value.decode("ascii")
        except (OSError, UnicodeError):
            return ""
        finally:
            if descriptor >= 0:
                os.close(descriptor)
        return value if (
            len(value) == 32
            and all(character in "0123456789abcdef" for character in value)
        ) else ""

    with _llm_project_instance_lock:
        instance = read_marker()
        if not instance:
            instance = uuid.uuid4().hex
            flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            flags |= getattr(os, "O_NOFOLLOW", 0)
            try:
                descriptor = os.open(marker_path, flags, 0o600)
                with os.fdopen(descriptor, "w", encoding="ascii") as handle:
                    handle.write(instance)
                    handle.flush()
                    os.fsync(handle.fileno())
            except FileExistsError:
                instance = read_marker()
            except OSError as error:
                raise HTTPException(
                    status_code=500,
                    detail="Could not open the project conversation",
                ) from error
        if not instance:
            raise HTTPException(
                status_code=500,
                detail="Could not open the project conversation",
            )

    material = f"llm-chat-project-v1\0{workspace}\0{instance}".encode("utf-8")
    return hmac.new(_session_secret(), material, hashlib.sha256).hexdigest()


def _llm_model_catalog(request: Request, provider: str = "") -> list[dict]:
    """Build a path-free catalog appropriate to this request's authority."""
    from services import llm_service

    services = wgp.server_config.get("services", {})
    remote = _llm_chat_request_is_external(request)
    # A Cloudflare client may inspect only the fixed local catalog. It cannot
    # make Maestro query a configured external provider with machine secrets.
    selected_provider = (
        "local" if remote
        else provider or services.get("llm_provider", "local")
    )
    remote_url = "" if remote else services.get("llm_remote_url", "")
    api_key = (
        "" if remote
        else _llm_provider_api_key(selected_provider, services)
    )
    models = llm_service.get_available_models(
        provider=selected_provider,
        remote_url=remote_url,
        api_key=api_key,
    )
    linked_roots = _llm_linked_model_roots()
    models.extend(llm_service.discover_gguf_models(linked_roots))

    truthful_status = globals().get("_truthful_llm_status")
    status = (
        truthful_status(llm_service)
        if callable(truthful_status)
        else llm_service.get_status()
    )
    desired_device = services.get("llm_device", _llm_default_device())
    safe_fields = {
        "id", "label", "size_hint", "provider", "source", "installed",
        "downloaded", "description", "vision_capable",
        "projector_available", "native_vision", "backend",
        "effective_device",
    }
    safe_profile_fields = {
        "backend", "device", "gpu_layers", "threads", "context_size",
        "threads_batch", "batch_size", "ubatch_size", "flash_attention",
        "cache_type_k", "cache_type_v", "slots", "prompt_cache",
        "projector_offload",
    }
    seen = set()
    catalog = []
    for raw in models:
        model_id = raw.get("id")
        if not isinstance(model_id, str) or not model_id or model_id in seen:
            continue
        seen.add(model_id)
        # Provider catalogs and linked-folder discovery are never allowed to
        # turn the browser catalog into a filesystem oracle.
        item = {key: raw.get(key) for key in safe_fields if key in raw}
        raw_profile = raw.get("runtime_profile")
        if isinstance(raw_profile, dict):
            item["runtime_profile"] = {
                key: raw_profile.get(key)
                for key in safe_profile_fields
                if key in raw_profile
            }
        item["current"] = bool(
            status.get("loaded")
            and status.get("model_id") == model_id
            and status.get("provider") == item.get("provider", "local")
        )
        item["configured"] = bool(
            model_id == services.get(
                "llm_model_id", globals().get("_DEFAULT_LLM_REPO", ""),
            )
            and item.get("provider", "local")
            == services.get("llm_provider", "local")
        )
        item["loaded"] = item["current"]
        item["vision_available"] = (
            bool(status.get("vision_available")) if item["current"] else None
        )
        item.setdefault("downloaded", item.get("provider") != "local")
        item.setdefault(
            "backend",
            "llama.cpp" if item.get("provider", "local") == "local"
            else item.get("provider"),
        )
        item["effective_device"] = (
            status.get("device") if item["current"]
            else item.get("effective_device")
            or (
                desired_device
                if item.get("provider", "local") == "local"
                else item.get("provider")
            )
        )
        download = status.get("download")
        loading_id = (
            status.get("loading_model_id")
            or (download.get("model_id") if isinstance(download, dict) else None)
        )
        item["loading"] = bool(
            status.get("loading")
            and (loading_id == model_id or status.get("model_id") == model_id)
        )
        item["loading_phase"] = (
            status.get("loading_phase") if item["loading"] else None
        )
        if item["current"]:
            runtime = status.get("runtime")
            if isinstance(runtime, dict):
                item["backend"] = runtime.get("backend") or item["backend"]
                effective_profile = runtime.get("effective_profile")
                if isinstance(effective_profile, dict):
                    item["runtime_profile"] = {
                        key: effective_profile.get(key)
                        for key in safe_profile_fields
                        if key in effective_profile
                    }
                    item["effective_device"] = (
                        effective_profile.get("backend")
                        or runtime.get("backend")
                        or item["effective_device"]
                    )
        if item["loading"] and isinstance(download, dict):
            item["download"] = {
                "phase": status.get("loading_phase"),
                "downloaded_bytes": int(download.get("downloaded_bytes") or 0),
                "total_bytes": download.get("total_bytes"),
                "seconds_since_progress": download.get("seconds_since_progress"),
            }
        else:
            item["download"] = None
        speed = None
        if item["current"]:
            runtime = status.get("runtime")
            if isinstance(runtime, dict):
                speed = runtime.get("speed")
        if (
            speed is None
            and item.get("provider", "local") == "local"
            and hasattr(llm_service, "get_model_speed_estimate")
        ):
            local_gguf_path = ""
            if item.get("source") == "Linked model folder":
                try:
                    local_gguf_path = (
                        llm_service.resolve_discovered_gguf(
                            model_id, linked_roots,
                        ) or ""
                    )
                except Exception:
                    local_gguf_path = ""
            try:
                speed = llm_service.get_model_speed_estimate(
                    model_id,
                    local_gguf_path=local_gguf_path,
                    device=(
                        status.get("device") if item["current"]
                        else desired_device
                        if item.get("provider", "local") == "local"
                        else item.get("provider")
                    ) or "auto",
                    multimodal=bool(item.get("vision_capable")),
                )
            except Exception:
                speed = None
        if speed is None and item.get("provider", "local") != "local":
            speed = {
                "source": "unavailable",
                "confidence": "unavailable",
                "reason": "Throughput depends on the external provider.",
                "sample_count": 0,
                "backend": item.get("provider"),
            }
        safe_speed = globals().get("_safe_llm_speed")
        item["speed"] = safe_speed(speed) if callable(safe_speed) else None
        catalog.append(item)
    return catalog


@api.get("/api/v1/llm/models")
def list_llm_models(
    request: Request,
    provider: str = "",
    workspace: str = "",
):
    """Return the safe model catalog and server-owned prompting guides."""
    from services import llm_service
    project_instance = (
        _llm_project_instance_id(request, workspace) if workspace else None
    )
    result = {
        "models": _llm_model_catalog(request, provider),
        "guides": llm_service.get_chat_guides(),
    }
    if project_instance:
        result["project_instance"] = project_instance
    return result


def _resolve_llm_chat_model(request: Request, model_id: str) -> dict:
    """Resolve one authorized catalog/custom selection to runtime arguments."""
    from services import llm_service

    if not isinstance(model_id, str) or not model_id or model_id != model_id.strip():
        raise ValueError("model_id is required")
    services = wgp.server_config.get("services", {})
    remote = _llm_chat_request_is_external(request)
    roots = _llm_linked_model_roots()

    # Remote users get a strict server-owned allowlist: curated models plus
    # opaque IDs for files in linked roots. Hidden registry entries and raw
    # Hugging Face sources remain machine-owner capabilities.
    safe_models = llm_service.get_available_models(provider="local")
    safe_models.extend(llm_service.discover_gguf_models(roots))
    safe_by_id = {item["id"]: item for item in safe_models}
    if remote:
        selected = safe_by_id.get(model_id)
        if selected is None:
            raise ValueError("That LLM is not available for remote chat")
    else:
        configured_provider = services.get("llm_provider", "local")
        available = llm_service.get_available_models(
            provider=configured_provider,
            remote_url=services.get("llm_remote_url", ""),
            api_key=_llm_provider_api_key(configured_provider, services),
        )
        available.extend(llm_service.discover_gguf_models(roots))
        selected = next(
            (item for item in available if item.get("id") == model_id),
            None,
        )

    provider = selected.get("provider", "local") if selected else "local"
    runtime_model_id = model_id
    local_gguf_path = ""
    gguf_file_override = ""
    if model_id.startswith("gguf:"):
        local_gguf_path = llm_service.resolve_discovered_gguf(model_id, roots) or ""
        if not local_gguf_path:
            raise ValueError("That linked GGUF is no longer available")
    elif selected is None:
        runtime_model_id, gguf_file_override = (
            llm_service.normalize_hf_model_source(model_id)
        )

    return {
        "model_id": runtime_model_id,
        "response_model_id": model_id,
        "device": services.get("llm_device", _llm_default_device()),
        "provider": provider,
        "remote_url": (
            services.get("llm_remote_url", "")
            if provider in {"remote", "openai"} else ""
        ),
        "api_key": _llm_provider_api_key(provider, services),
        "local_gguf_path": local_gguf_path,
        "gguf_file_override": gguf_file_override or "",
        "vision_capable": (
            selected.get("vision_capable") if selected is not None else None
        ),
        # This is only a catalog capability hint. Runtime availability is
        # established after the exact model/projector identity is loaded.
        "vision_available": None,
    }


def _configured_llm_selection() -> dict:
    """Snapshot the exact server-configured LLM load arguments."""
    services = wgp.server_config.get("services", {})
    provider = str(services.get("llm_provider") or "local")
    return {
        "model_id": str(
            services.get("llm_model_id") or _DEFAULT_LLM_REPO
        ),
        "device": str(
            services.get("llm_device") or _llm_default_device()
        ),
        "provider": provider,
        "remote_url": str(services.get("llm_remote_url") or ""),
        "api_key": _llm_provider_api_key(provider, services),
        "local_gguf_path": "",
        "gguf_file_override": "",
    }


def _run_configured_llm_operation(operation, /, *args, **kwargs):
    """Run one configured LLM operation under its exact runtime/GPU lease."""
    return _run_llm_with_selection(
        _configured_llm_selection(), operation, *args, **kwargs,
    )


def _resolve_direct_llm_selection(request: Request) -> dict:
    """Resolve the server-owned selection for a direct LLM request.

    External callers may use only the curated local catalog. They can neither
    inherit a host-configured network provider nor make Maestro reveal or use
    its provider URL/key. If the configured model is not in that catalog, use
    the server's curated default rather than accepting caller-controlled input.
    """
    if not _llm_chat_request_is_external(request):
        return _configured_llm_selection()
    services = wgp.server_config.get("services", {})
    configured_model = str(
        services.get("llm_model_id") or _DEFAULT_LLM_REPO
    )
    try:
        selection = _resolve_llm_chat_model(request, configured_model)
    except ValueError:
        selection = _resolve_llm_chat_model(request, _DEFAULT_LLM_REPO)
    if selection.get("provider") != "local":
        raise ValueError("External LLM requests require a local model")
    selection["remote_url"] = ""
    selection["api_key"] = ""
    return selection


def _cpu_text_operation_eligible(
    selection: dict,
    *,
    operation_name: str,
    text_only: bool,
    job: dict | None,
) -> bool:
    """Classify only server-owned operation/capability facts."""
    if (
        operation_name not in _CPU_TEXT_OPERATIONS
        or text_only is not True
        or str(selection.get("provider") or "local").casefold() != "local"
        or selection.get("vision_capable") is not False
    ):
        return False
    if isinstance(job, dict):
        model_type = str(job.get("model_type") or "").casefold()
        generation_mode = str(job.get("generation_mode") or "").casefold()
        if model_type.startswith("minimax_h3"):
            return False
        if generation_mode not in {"", "image", "video", "avatar"}:
            return False
    return True


def _cpu_text_required_host_bytes(llm_service, selection: dict) -> int:
    """Return a conservative private load+KV/transient RAM requirement."""
    model_gb = 0.0
    known = False
    estimator = getattr(llm_service, "_catalog_model_size_gb", None)
    if callable(estimator):
        try:
            model_gb, known = estimator(
                str(selection.get("model_id") or ""),
                str(selection.get("local_gguf_path") or ""),
            )
        except (OSError, TypeError, ValueError):
            model_gb, known = 0.0, False
    if not known:
        path = str(selection.get("local_gguf_path") or "")
        try:
            if path and os.path.isfile(path):
                model_gb = os.path.getsize(path) / float(1 << 30)
                known = True
        except OSError:
            known = False
    # Unknown model size must fail CPU coexistence admission rather than guess
    # around a resident generation stack. The standard lane remains available.
    if not known or not math.isfinite(float(model_gb)) or model_gb <= 0:
        return 1 << 62
    return int(math.ceil((float(model_gb) * 1.30 + 4.0) * (1 << 30)))


def _cpu_text_host_snapshot(llm_service, selection: dict) -> HostAdmissionSnapshot:
    try:
        available, total = wgp._host_memory_snapshot()
    except Exception:
        available, total = 0, 0
    try:
        import psutil
        cpu_percent = float(psutil.cpu_percent(interval=None))
    except Exception:
        cpu_percent = 100.0
    try:
        defaults = llm_service.get_cpu_coexistence_defaults()
    except Exception:
        defaults = {}
    worker_threads = max(1, min(64, int(defaults.get("max_threads", 8) or 8)))
    return HostAdmissionSnapshot(
        available_bytes=max(0, int(available or 0)),
        total_bytes=max(0, int(total or 0)),
        required_bytes=_cpu_text_required_host_bytes(llm_service, selection),
        logical_threads=max(0, int(os.cpu_count() or 0)),
        worker_threads=worker_threads,
        cpu_percent=cpu_percent,
    )


def _cpu_text_generation_waiter_exists(job: dict | None = None) -> bool:
    """Preserve generation queue/residency priority over opportunistic LLM GPU."""
    return any(
        candidate is not job
        and candidate.get("status") == "queued"
        and not candidate.get("queue_held", False)
        and not is_cancel_requested(candidate)
        and candidate.get("resource_intent", RESOURCE_INTENT_GENERATION)
            == RESOURCE_INTENT_GENERATION
        for candidate in _jobs.values()
        if isinstance(candidate, dict)
    )


def _cpu_text_job_cancelled(job: dict | None) -> bool:
    return bool(isinstance(job, dict) and is_cancel_requested(job))


def _cpu_text_transition(
    job: dict | None,
    *,
    expected_attempt: int | None,
    state: str,
    execution: str,
    increment_attempt: bool = False,
    reset_progress: bool = False,
    **updates,
) -> int | None:
    if not isinstance(job, dict):
        return 1 if expected_attempt is None else expected_attempt
    updates.setdefault("_resource_preemption_eligible", False)
    return transition_resource_execution(
        job,
        expected_execution_attempt=expected_attempt,
        intent=RESOURCE_INTENT_TEXT,
        execution=execution,
        preemption_mode=(
            "discard_restart"
            if execution == RESOURCE_EXECUTION_CPU else "none"
        ),
        state=state,
        increment_attempt=increment_attempt,
        reset_progress=reset_progress,
        **updates,
    )


def _cpu_text_runtime_preemption_eligible(control: object, tokens) -> bool:
    """Accept only exact attempt-bound, decision-grade runtime evidence."""
    if not isinstance(control, dict) or tokens is None:
        return False
    remaining = control.get("remaining")
    if not isinstance(remaining, dict):
        return False
    runtime_generation = tokens.runtime_generation
    runtime_attempt_id = tokens.runtime_attempt_id
    estimate = control.get("remaining_estimate_seconds")
    return bool(
        control.get("abort_capable") is True
        and control.get("preemptible") is True
        and control.get("generation") == runtime_generation
        and control.get("attempt_id") == runtime_attempt_id
        and remaining.get("state") == "decision_grade"
        and remaining.get("decision_eligible") is True
        and remaining.get("runtime_generation") == runtime_generation
        and remaining.get("attempt_id") == runtime_attempt_id
        and isinstance(estimate, (int, float))
        and not isinstance(estimate, bool)
        and math.isfinite(float(estimate))
        and estimate >= 0
    )


def _cpu_text_revoke_preemption_if_published(
    job: dict | None,
    execution_attempt: int,
) -> None:
    """Withdraw restart copy as soon as decision evidence becomes unknown."""
    if not isinstance(job, dict) or job.get(
        "_resource_preemption_eligible",
    ) is not True:
        return
    _cpu_text_transition(
        job,
        expected_attempt=execution_attempt,
        state="running",
        execution=RESOURCE_EXECUTION_CPU,
        message="Running text preparation on the slower CPU lane",
    )


def _cpu_text_restore_after_abandoned_preemption(
    job: dict | None,
    execution_attempt: int,
) -> None:
    """Return an untransferred CPU attempt to nonpreemptible running state."""
    _cpu_text_transition(
        job,
        expected_attempt=execution_attempt,
        state="running",
        execution=RESOURCE_EXECUTION_CPU,
        message="Continuing the CPU text attempt",
    )


def _cpu_text_speed_estimate(
    llm_service,
    selection: dict,
    *,
    device: str,
) -> dict | None:
    try:
        estimate = llm_service.get_model_speed_estimate(
            str(selection.get("model_id") or ""),
            local_gguf_path=str(selection.get("local_gguf_path") or ""),
            gguf_file_override=str(selection.get("gguf_file_override") or ""),
            device=device,
            multimodal=False,
            use_current_measurement=False,
        )
    except Exception:
        return None
    if not isinstance(estimate, dict) or estimate.get("confidence") != "measured":
        return None
    rate = estimate.get("generation_tokens_per_second")
    if (
        not isinstance(rate, (int, float))
        or isinstance(rate, bool)
        or not math.isfinite(float(rate))
        or rate <= 0
    ):
        return None
    return estimate


def _cpu_text_break_even_estimate(
    llm_service,
    selection: dict,
    *,
    runtime_remaining_seconds: float | None,
) -> BreakEvenEstimate:
    if (
        not isinstance(runtime_remaining_seconds, (int, float))
        or isinstance(runtime_remaining_seconds, bool)
        or not math.isfinite(float(runtime_remaining_seconds))
        or runtime_remaining_seconds < 0
    ):
        return BreakEvenEstimate(None, None, None, None)
    cpu = _cpu_text_speed_estimate(llm_service, selection, device="cpu")
    gpu = _cpu_text_speed_estimate(llm_service, selection, device="cuda")
    if cpu is None or gpu is None:
        return BreakEvenEstimate(None, None, None, None)
    cpu_rate = float(cpu["generation_tokens_per_second"])
    gpu_rate = float(gpu["generation_tokens_per_second"])
    cpu_remaining = float(runtime_remaining_seconds)
    remaining_tokens = cpu_remaining * cpu_rate
    required = _cpu_text_required_host_bytes(llm_service, selection)
    if required >= (1 << 61):
        return BreakEvenEstimate(None, None, None, None)
    # Abort has a hard 5s terminate + 5s kill budget. Model movement uses a
    # conservative 1 GiB/s floor plus fixed startup/warmup, so a preemption
    # must win despite—not by ignoring—weight movement.
    model_gb = max(0.1, required / float(1 << 30) / 1.30)
    return BreakEvenEstimate(
        cpu_remaining_seconds=cpu_remaining,
        stop_release_seconds=10.0,
        gpu_load_seconds=10.0 + model_gb,
        gpu_remaining_seconds=remaining_tokens / gpu_rate,
    )


def _cpu_text_preemption_monitor(
    *,
    llm_service,
    selection: dict,
    job: dict | None,
    owner_key: str,
    lease,
    execution_attempt: int,
    stopped: threading.Event,
    outcome: dict,
    handoff_ready: threading.Event,
    handoff_acknowledged: threading.Event,
    handoff_abandoned: threading.Event,
    handoff_transferred: threading.Event,
    monitor_done: threading.Event,
) -> None:
    """Reserve the GPU first, then abort only an exact known-slower CPU attempt."""
    while not stopped.wait(0.5):
        if _cpu_text_job_cancelled(job):
            monitor_done.set()
            return
        tokens = _cpu_text_lane.runtime_tokens(owner_key)
        if tokens is None:
            _cpu_text_revoke_preemption_if_published(
                job, execution_attempt,
            )
            continue
        try:
            control = llm_service.get_local_runtime_control()
        except Exception:
            _cpu_text_revoke_preemption_if_published(
                job, execution_attempt,
            )
            continue
        if not isinstance(control, dict):
            _cpu_text_revoke_preemption_if_published(
                job, execution_attempt,
            )
            continue
        if (
            control.get("execution") != "cooperative_cpu"
            or not _cpu_text_runtime_preemption_eligible(control, tokens)
        ):
            _cpu_text_revoke_preemption_if_published(
                job, execution_attempt,
            )
            continue
        estimate = _cpu_text_break_even_estimate(
            llm_service,
            selection,
            runtime_remaining_seconds=control.get(
                "remaining_estimate_seconds",
            ),
        )
        if not _cpu_text_preemption_gate.permits(owner_key, estimate):
            continue
        if _cpu_text_generation_waiter_exists(job):
            continue
        if not _gen_lock.acquire(blocking=False):
            continue
        keep_reservation = False
        try:
            requested = _cpu_text_transition(
                job,
                expected_attempt=execution_attempt,
                state="preemption_requested",
                execution=RESOURCE_EXECUTION_CPU,
                message=(
                    "Restarting text preparation on acceleration because it "
                    "is predicted to finish sooner"
                ),
                _resource_preemption_eligible=True,
            )
            if requested is None:
                return
            if stopped.is_set():
                _cpu_text_transition(
                    job,
                    expected_attempt=execution_attempt,
                    state="running",
                    execution=RESOURCE_EXECUTION_CPU,
                    message="CPU text attempt completed before handoff",
                )
                return
            current_tokens = _cpu_text_lane.runtime_tokens(owner_key)
            if current_tokens != tokens:
                _cpu_text_restore_after_abandoned_preemption(
                    job, execution_attempt,
                )
                return
            try:
                fresh_control = llm_service.get_local_runtime_control()
            except Exception:
                fresh_control = None
            if (
                not isinstance(fresh_control, dict)
                or fresh_control.get("execution") != "cooperative_cpu"
                or not _cpu_text_runtime_preemption_eligible(
                    fresh_control, current_tokens,
                )
            ):
                _cpu_text_restore_after_abandoned_preemption(
                    job, execution_attempt,
                )
                return
            try:
                result = llm_service.abort_local_cpu_runtime(
                    tokens.runtime_generation,
                    tokens.runtime_attempt_id,
                    terminate_timeout=5.0,
                    kill_timeout=5.0,
                )
            except Exception:
                _cpu_text_transition(
                    job,
                    expected_attempt=execution_attempt,
                    state="running",
                    execution=RESOURCE_EXECUTION_CPU,
                    message="Continuing the CPU text attempt",
                )
                return
            if handoff_abandoned.is_set():
                _cpu_text_restore_after_abandoned_preemption(
                    job, execution_attempt,
                )
                return
            if not isinstance(result, dict) or result.get("resources_released") is not True:
                _cpu_text_transition(
                    job,
                    expected_attempt=execution_attempt,
                    state="running",
                    execution=RESOURCE_EXECUTION_CPU,
                    message="Continuing the CPU text attempt",
                )
                return
            releasing = _cpu_text_transition(
                job,
                expected_attempt=execution_attempt,
                state="resources_releasing",
                execution=RESOURCE_EXECUTION_CPU,
                message="CPU text resources released",
            )
            if releasing is None:
                return
            if handoff_abandoned.is_set():
                _cpu_text_restore_after_abandoned_preemption(
                    job, execution_attempt,
                )
                return
            handoff_ready.set()
            while not handoff_acknowledged.wait(0.05):
                if handoff_abandoned.is_set():
                    _cpu_text_restore_after_abandoned_preemption(
                        job, execution_attempt,
                    )
                    return
            if handoff_abandoned.is_set():
                _cpu_text_restore_after_abandoned_preemption(
                    job, execution_attempt,
                )
                return
            _cpu_text_preemption_gate.record(owner_key)
            outcome.update({"preempted": True, "gpu_reserved": True})
            keep_reservation = True
            handoff_transferred.set()
            return
        finally:
            if not keep_reservation:
                _gen_lock.release()
            monitor_done.set()
    monitor_done.set()


def _cpu_text_fenced_progress(
    callback,
    job: dict | None,
    execution_attempt: int,
):
    if not callable(callback) or not isinstance(job, dict):
        return callback

    def publish(event):
        from services import job_lifecycle as lifecycle
        # The attempt check and downstream progress mutation share the same
        # re-entrant lifecycle fence as restart/cancel. An attempt cannot
        # increment in the gap between validation and publication.
        with lifecycle._lifecycle_lock:
            if (
                not is_cancel_requested(job)
                and job.get("execution_attempt", 1) == execution_attempt
            ):
                return callback(event)
        return None

    return publish


def _run_cpu_text_llm_attempt(
    selection: dict,
    operation,
    args: tuple,
    kwargs: dict,
    *,
    job: dict | None,
    operation_name: str,
):
    """Run one sealed operation on standard/GPU or the sole CPU text lane."""
    from services import llm_service

    owner_key = (
        str(job.get("id") or "") if isinstance(job, dict)
        else f"ephemeral-{uuid.uuid4().hex}"
    )
    execution_attempt = (
        max(1, int(job.get("execution_attempt", 1) or 1))
        if isinstance(job, dict) else 1
    )
    _cpu_text_transition(
        job,
        expected_attempt=execution_attempt,
        state="queued",
        execution=RESOURCE_EXECUTION_STANDARD,
        message="Waiting for text execution resources",
    )

    cpu_lease = None
    gpu_reserved = False
    while not _cpu_text_job_cancelled(job):
        # A queued generation retains residency/fairness priority. If no such
        # work exists, atomically reserve the standard accelerator lane.
        if not _cpu_text_generation_waiter_exists(job) and _gen_lock.acquire(
            blocking=False,
        ):
            gpu_reserved = True
            break
        if _gen_lock.locked():
            cpu_lease, decision = _cpu_text_lane.acquire(
                owner_key,
                snapshot_supplier=lambda: _cpu_text_host_snapshot(
                    llm_service, selection,
                ),
                cancel_requested=lambda: _cpu_text_job_cancelled(job),
                poll_interval=0.1,
                timeout=0.35,
            )
            if cpu_lease is not None:
                # The generation holder may have exited while this caller was
                # waiting for the sole CPU lease. Prefer the accelerator when
                # it is now atomically reservable; never start a stale slow
                # attempt merely because the earlier observation was busy.
                if (
                    not _cpu_text_generation_waiter_exists(job)
                    and _gen_lock.acquire(blocking=False)
                ):
                    cpu_lease.release()
                    cpu_lease = None
                    gpu_reserved = True
                break
            if (
                decision.reason in {
                    "memory_pressure", "thread_pressure", "cpu_pressure",
                }
                and isinstance(job, dict)
                and job.get("resource_state") != "blocked"
            ):
                _cpu_text_transition(
                    job,
                    expected_attempt=execution_attempt,
                    state="blocked",
                    execution=RESOURCE_EXECUTION_STANDARD,
                    message=(
                        "Waiting for safe host resources for concurrent text "
                        "preparation"
                    ),
                )
        time.sleep(0.05)
    if _cpu_text_job_cancelled(job):
        if gpu_reserved:
            _gen_lock.release()
        _cpu_text_preemption_gate.clear(owner_key)
        raise llm_service.LocalRuntimeAbortedError(
            0, 0, resources_released=True,
        )

    load_args = {
        key: selection.get(key, "")
        for key in (
            "model_id", "device", "provider", "remote_url", "api_key",
            "local_gguf_path", "gguf_file_override",
        )
    }
    if cpu_lease is None:
        native_gpu_slot = _WgpNativeGpuExecutionSlot(
            _local_llm_uses_native_gpu(selection),
        )
        native_gpu_acquired = False
        try:
            native_gpu_acquired = native_gpu_slot.__enter__()
            resident_type = str(
                getattr(wgp, "transformer_type", "") or ""
            ).casefold()
            if resident_type.startswith("minimax_h3") and (
                getattr(wgp, "wan_model", None) is not None
                or getattr(wgp, "offloadobj", None) is not None
            ):
                print("[LLM] Releasing H3 before local language-model load")
                _release_wgp_model_with_native_gpu_exclusion()
            current = _cpu_text_transition(
                job,
                expected_attempt=execution_attempt,
                state="running",
                execution=RESOURCE_EXECUTION_STANDARD,
                message=f"Running {operation_name.replace('_', ' ')}",
            )
            if current is None:
                raise llm_service.LocalRuntimeAbortedError(
                    0, 0, resources_released=True,
                )
            attempt_kwargs = dict(kwargs)
            if "progress_callback" in attempt_kwargs:
                attempt_kwargs["progress_callback"] = _cpu_text_fenced_progress(
                    attempt_kwargs.get("progress_callback"), job, current,
                )
            with llm_service.loaded_model_lease(**load_args):
                return operation(*args, **attempt_kwargs)
        finally:
            if native_gpu_acquired:
                native_gpu_slot.__exit__(None, None, None)
            if gpu_reserved:
                _gen_lock.release()
            _cpu_text_preemption_gate.clear(owner_key)

    current = _cpu_text_transition(
        job,
        expected_attempt=execution_attempt,
        state="admitted",
        execution=RESOURCE_EXECUTION_CPU,
        message="Admitted to the slower CPU text lane",
    )
    if current is None:
        cpu_lease.release()
        raise llm_service.LocalRuntimeAbortedError(
            0, 0, resources_released=True,
        )
    outcome = {"preempted": False, "gpu_reserved": False}
    stopped = threading.Event()
    handoff_ready = threading.Event()
    handoff_acknowledged = threading.Event()
    handoff_abandoned = threading.Event()
    handoff_transferred = threading.Event()
    monitor_done = threading.Event()
    monitor = None
    result = None
    aborted_error = None
    try:
        current = _cpu_text_transition(
            job,
            expected_attempt=current,
            state="running",
            execution=RESOURCE_EXECUTION_CPU,
            message="Running text preparation on the slower CPU lane",
        )
        if current is None:
            raise llm_service.LocalRuntimeAbortedError(
                0, 0, resources_released=True,
            )
        attempt_kwargs = dict(kwargs)
        if "progress_callback" in attempt_kwargs:
            attempt_kwargs["progress_callback"] = _cpu_text_fenced_progress(
                attempt_kwargs.get("progress_callback"), job, current,
            )
        with llm_service.loaded_model_lease(
            **load_args, cpu_coexistence=True,
        ):
            control = llm_service.get_local_runtime_control()
            generation = int(control.get("generation") or 0)
            with llm_service.local_runtime_attempt(generation) as runtime_attempt:
                runtime_tokens = _cpu_text_lane.bind_runtime_tokens(
                    cpu_lease,
                    runtime_generation=generation,
                    runtime_attempt_id=runtime_attempt,
                )
                runtime_control = llm_service.get_local_runtime_control()
                decision_eligible = _cpu_text_runtime_preemption_eligible(
                    runtime_control, runtime_tokens,
                )
                current = _cpu_text_transition(
                    job,
                    expected_attempt=current,
                    state="running",
                    execution=RESOURCE_EXECUTION_CPU,
                    message=(
                        "Running text preparation on CPU; this attempt may "
                        "restart on acceleration if delivery becomes faster"
                        if decision_eligible
                        else "Running text preparation on the slower CPU lane"
                    ),
                    _resource_preemption_eligible=decision_eligible,
                )
                if current is None:
                    raise llm_service.LocalRuntimeAbortedError(
                        generation, runtime_attempt, resources_released=False,
                    )
                monitor = threading.Thread(
                    target=_cpu_text_preemption_monitor,
                    kwargs={
                        "llm_service": llm_service,
                        "selection": selection,
                        "job": job,
                        "owner_key": owner_key,
                        "lease": cpu_lease,
                        "execution_attempt": current,
                        "stopped": stopped,
                        "outcome": outcome,
                        "handoff_ready": handoff_ready,
                        "handoff_acknowledged": handoff_acknowledged,
                        "handoff_abandoned": handoff_abandoned,
                        "handoff_transferred": handoff_transferred,
                        "monitor_done": monitor_done,
                    },
                    daemon=True,
                    name=f"cpu-text-preemption-{owner_key}",
                )
                monitor.start()
                try:
                    result = operation(*args, **attempt_kwargs)
                except llm_service.LocalRuntimeAbortedError as error:
                    aborted_error = error
    finally:
        stopped.set()
        _cpu_text_lane.clear_runtime_tokens(cpu_lease)
        cpu_lease.release()
        if monitor is not None:
            deadline = time.monotonic() + 12.0
            while (
                not handoff_ready.is_set()
                and not monitor_done.is_set()
                and time.monotonic() < deadline
            ):
                monitor_done.wait(timeout=0.05)
            if handoff_ready.is_set() and not monitor_done.is_set():
                handoff_acknowledged.set()
                # After acknowledgment the monitor performs no blocking work;
                # wait for the explicit ownership-transfer confirmation.
                handoff_transferred.wait()
                monitor.join()
            else:
                handoff_abandoned.set()
                monitor.join(timeout=0.25)

    if not outcome.get("preempted"):
        if outcome.get("gpu_reserved"):
            _gen_lock.release()
        _cpu_text_preemption_gate.clear(owner_key)
        if aborted_error is not None:
            raise aborted_error
        return result

    # The previous result/error is intentionally discarded. The monitor holds
    # the exact GPU reservation until this thread has confirmed CPU lease exit.
    restarted_attempt = _cpu_text_transition(
        job,
        expected_attempt=current,
        state="restarting_on_accelerator",
        execution=RESOURCE_EXECUTION_STANDARD,
        increment_attempt=True,
        reset_progress=True,
        message="Restarting the sealed text operation on acceleration",
    )
    if restarted_attempt is None:
        _gen_lock.release()
        _cpu_text_preemption_gate.clear(owner_key)
        if aborted_error is not None:
            raise aborted_error
        raise llm_service.LocalRuntimeAbortedError(
            0, 0, resources_released=True,
        )
    try:
        running_attempt = _cpu_text_transition(
            job,
            expected_attempt=restarted_attempt,
            state="running",
            execution=RESOURCE_EXECUTION_STANDARD,
            message="Running restarted text preparation on acceleration",
        )
        if running_attempt is None:
            raise llm_service.LocalRuntimeAbortedError(
                0, 0, resources_released=True,
            )
        restart_kwargs = dict(kwargs)
        if "progress_callback" in restart_kwargs:
            restart_kwargs["progress_callback"] = _cpu_text_fenced_progress(
                restart_kwargs.get("progress_callback"), job, running_attempt,
            )
        with _WgpNativeGpuExecutionSlot(
            _local_llm_uses_native_gpu(selection),
        ), llm_service.loaded_model_lease(**load_args):
            return operation(*args, **restart_kwargs)
    finally:
        _gen_lock.release()
        _cpu_text_preemption_gate.clear(owner_key)


def _run_authorized_llm_with_selection(
    request: Request,
    selection: dict,
    operation=None,
    /,
    *args,
    **kwargs,
):
    """Revalidate locality before model load and immediately before content."""
    def require_allowed_selection() -> None:
        # Re-read origin authority on both sides of the model lease. A request
        # may be promoted to remote while a cold model is loading; the stale
        # pre-lease boolean must not let host credentials reach that origin.
        promote = globals().get("_promote_external_llm_request")
        if callable(promote):
            promote(request)
        external = _llm_chat_request_is_external(request)
        if external and (
            selection.get("provider") != "local"
            or selection.get("remote_url")
            or selection.get("api_key")
        ):
            raise PermissionError("External LLM selection is not local")

    require_allowed_selection()

    def run_after_load():
        require_allowed_selection()
        if operation is None:
            return None
        return operation(*args, **kwargs)

    generation_slot_owned = bool(getattr(
        request.state, "maestro_llm_generation_slot_owned", False,
    ))
    return _run_llm_with_selection(
        selection,
        run_after_load,
        _cpu_text_job=getattr(
            request.state, "maestro_cpu_text_job", None,
        ),
        _cpu_text_operation=("" if generation_slot_owned else str(getattr(
            request.state, "maestro_cpu_text_operation", "",
        ) or "")),
        _cpu_text_text_only=bool(getattr(
            request.state, "maestro_cpu_text_text_only", False,
        )),
        _coordinate_generation=not generation_slot_owned,
        _precoordinated_generation=generation_slot_owned,
    )


def _run_llm_with_selection(
    selection: dict,
    operation=None,
    /,
    *args,
    _coordinate_generation: bool = True,
    _precoordinated_generation: bool = False,
    _cpu_text_job: dict | None = None,
    _cpu_text_operation: str = "",
    _cpu_text_text_only: bool = False,
    **kwargs,
):
    """Hold one exact model identity across load and optional inference."""
    from services import llm_service

    cpu_classifier = globals().get("_cpu_text_operation_eligible")
    if callable(cpu_classifier) and cpu_classifier(
        selection,
        operation_name=_cpu_text_operation,
        text_only=_cpu_text_text_only,
        job=_cpu_text_job,
    ):
        if operation is None:
            operation = lambda: None
        return _run_cpu_text_llm_attempt(
            selection,
            operation,
            args,
            kwargs,
            job=_cpu_text_job,
            operation_name=_cpu_text_operation,
        )

    # A resident H3 stack and a local GGUF can together exhaust host RAM even
    # when neither is using much VRAM. Serialize with the generation owner and
    # retire H3 before the local model lease begins. Remote providers own no
    # local model memory and intentionally skip this path.
    if str(selection.get("provider") or "local").casefold() == "local" and (
        _coordinate_generation or _precoordinated_generation
    ):
        def run_local_operation():
            resident_type = str(
                getattr(wgp, "transformer_type", "") or ""
            ).casefold()
            if resident_type.startswith("minimax_h3") and (
                getattr(wgp, "wan_model", None) is not None
                or getattr(wgp, "offloadobj", None) is not None
            ):
                print("[LLM] Releasing H3 before local language-model load")
                _release_wgp_model_with_native_gpu_exclusion()
            load_args = {
                key: selection.get(key, "")
                for key in (
                    "model_id", "device", "provider", "remote_url", "api_key",
                    "local_gguf_path", "gguf_file_override",
                )
            }
            with llm_service.loaded_model_lease(**load_args):
                if operation is None:
                    return None
                return operation(*args, **kwargs)
        if _precoordinated_generation:
            with _WgpNativeGpuExecutionSlot(
                _local_llm_uses_native_gpu(selection),
            ):
                return run_local_operation()
        with _gen_lock, _WgpNativeGpuExecutionSlot(
            _local_llm_uses_native_gpu(selection),
        ):
            return run_local_operation()

    load_args = {
        key: selection.get(key, "")
        for key in (
            "model_id", "device", "provider", "remote_url", "api_key",
            "local_gguf_path", "gguf_file_override",
        )
    }
    with llm_service.loaded_model_lease(**load_args):
        if operation is None:
            return None
        return operation(*args, **kwargs)


_run_llm_with_selection._maestro_cpu_text_lane = True


def _prepare_llm_selection(selection: dict) -> None:
    _run_llm_with_selection(selection)


def _llm_operation_scope(
    request: Request,
    workspace: str,
) -> tuple[str, str]:
    """Return opaque session and project keys after project authorization."""
    project_key = _llm_project_instance_id(request, workspace)
    session_id = str(
        getattr(request.state, "maestro_session_id", "") or ""
    )
    owner_key = hmac.new(
        _session_secret(),
        f"llm-operation-owner-v1\0{session_id}".encode(),
        hashlib.sha256,
    ).hexdigest()
    return owner_key, project_key


def _prompt_enhancement_operation_scope(
    request: Request,
    workspace: str,
) -> tuple[str, str, str]:
    """Return separate opaque account, project, and session scope keys."""
    session_key, project_key = _llm_operation_scope(request, workspace)
    principal = getattr(request.state, "maestro_account_principal", None)
    account_id = str(
        principal.get("id")
        if isinstance(principal, dict)
        else ""
    ).strip()
    account_material = account_id or session_key
    account_key = hmac.new(
        _session_secret(),
        f"prompt-enhance-account-v1\0{account_material}".encode(),
        hashlib.sha256,
    ).hexdigest()
    return account_key, project_key, session_key


_LLM_ROUTE_OPERATION_KINDS = frozenset({"enhance", "director_preview"})


def _normalize_llm_route_request_id(value) -> str:
    """Normalize one caller-owned request UUID without accepting aliases."""
    if not isinstance(value, str):
        raise ValueError("request_id must be a UUID")
    try:
        return uuid.UUID(value).hex
    except (AttributeError, TypeError, ValueError) as error:
        raise ValueError("request_id must be a UUID") from error


def _llm_route_effective_input_digest(
    operation_kind: str,
    effective_input: Mapping[str, Any],
) -> str:
    """Bind an operation UUID to the exact authorized effective input."""
    try:
        material = json.dumps(
            {
                "operation_kind": operation_kind,
                "effective_input": effective_input,
            },
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    except (TypeError, ValueError) as error:
        raise ValueError("LLM operation input is not serializable") from error
    return hmac.new(
        _session_secret(), material, hashlib.sha256,
    ).hexdigest()


def _llm_route_operation_scope_or_404(
    request: Request,
    operation_kind: str,
    workspace: str,
) -> tuple[str, str, str]:
    """Authorize and scope one generic transient LLM route operation."""
    if operation_kind not in _LLM_ROUTE_OPERATION_KINDS:
        raise HTTPException(status_code=404, detail="LLM operation not found")
    _promote_external_llm_request(request)
    selected_workspace = _request_project_workspace(request, workspace)
    _require_project_access(
        request,
        selected_workspace,
        existing_only=True,
        permission="project.generate",
    )
    owner_key, project_key = _llm_operation_scope(
        request, selected_workspace,
    )
    return selected_workspace, owner_key, project_key


def _llm_route_public_status(
    operation_kind: str,
    status: Mapping[str, Any],
) -> dict[str, Any]:
    """Project operation-specific redacted failures onto generic telemetry."""
    public = dict(status)
    if operation_kind == "director_preview" and public.get("status") == "failed":
        public["error"] = {
            "code": "director_preview_failed",
            "message": "Director could not build this preview.",
            "retryable": True,
        }
    return public


@api.get("/api/v1/llm/operations/{operation_kind}/{request_id}")
def llm_route_operation_status(
    request: Request,
    operation_kind: str,
    request_id: str,
    workspace: str = "",
):
    """Return bounded telemetry for one exact owner/project operation."""
    selected, owner_key, project_key = _llm_route_operation_scope_or_404(
        request, operation_kind, workspace,
    )
    if operation_kind == "enhance":
        account_key, project_key, session_key = (
            _prompt_enhancement_operation_scope(request, selected)
        )
        status = _prompt_enhancement_operation_manager.status(
            request_id,
            account_key=account_key,
            project_instance_key=project_key,
            session_key=session_key,
        )
    else:
        from services.llm_operations import llm_route_operation_manager

        status = llm_route_operation_manager.status(
            request_id,
            owner_key=owner_key,
            project_instance_key=project_key,
            operation_kind=operation_kind,
        )
    if status is None:
        raise HTTPException(status_code=404, detail="LLM operation not found")
    return _llm_route_public_status(operation_kind, status)


@api.get("/api/v1/llm/operations/{operation_kind}/{request_id}/result")
def llm_route_operation_result(
    request: Request,
    operation_kind: str,
    request_id: str,
    workspace: str = "",
):
    """Return the private result only after exact-scope terminal recovery."""
    selected, owner_key, project_key = _llm_route_operation_scope_or_404(
        request, operation_kind, workspace,
    )
    if operation_kind == "enhance":
        account_key, project_key, session_key = (
            _prompt_enhancement_operation_scope(request, selected)
        )
        status = _prompt_enhancement_operation_manager.status(
            request_id,
            account_key=account_key,
            project_instance_key=project_key,
            session_key=session_key,
        )
    else:
        from services.llm_operations import llm_route_operation_manager

        status = llm_route_operation_manager.status(
            request_id,
            owner_key=owner_key,
            project_instance_key=project_key,
            operation_kind=operation_kind,
        )
    if status is None:
        raise HTTPException(status_code=404, detail="LLM operation not found")
    if status.get("status") != "completed":
        return JSONResponse(_llm_route_public_status(operation_kind, status), status_code=(
            202 if status.get("status") == "running" else 409
        ))
    if operation_kind == "enhance":
        result = _prompt_enhancement_operation_manager.result(
            request_id,
            account_key=account_key,
            project_instance_key=project_key,
            session_key=session_key,
        )
    else:
        result = llm_route_operation_manager.result(
            request_id,
            owner_key=owner_key,
            project_instance_key=project_key,
            operation_kind=operation_kind,
        )
    if result is None:
        raise HTTPException(status_code=404, detail="LLM operation not found")
    return result


@api.delete("/api/v1/llm/operations/{operation_kind}/{request_id}")
def cancel_llm_route_operation(
    request: Request,
    operation_kind: str,
    request_id: str,
    workspace: str = "",
):
    """Cancel one exact transient operation without touching other requests."""
    selected, owner_key, project_key = _llm_route_operation_scope_or_404(
        request, operation_kind, workspace,
    )
    if operation_kind == "enhance":
        account_key, project_key, session_key = (
            _prompt_enhancement_operation_scope(request, selected)
        )
        status = _prompt_enhancement_operation_manager.cancel(
            request_id,
            account_key=account_key,
            project_instance_key=project_key,
            session_key=session_key,
        )
    else:
        from services.llm_operations import llm_route_operation_manager

        status = llm_route_operation_manager.cancel(
            request_id,
            owner_key=owner_key,
            project_instance_key=project_key,
            operation_kind=operation_kind,
        )
    if status is None:
        raise HTTPException(status_code=404, detail="LLM operation not found")
    return _llm_route_public_status(operation_kind, status)


def _llm_selection_key(purpose: str, selection: dict) -> str:
    """Hash exact load inputs so the manager never retains credentials."""
    material = json.dumps(
        {
            "purpose": purpose,
            "selection": {
                key: str(selection.get(key, "") or "")
                for key in (
                    "model_id", "device", "provider", "remote_url", "api_key",
                    "local_gguf_path", "gguf_file_override",
                )
            },
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hmac.new(
        _session_secret(), material, hashlib.sha256,
    ).hexdigest()


def _resolve_llm_prepare_selection(
    request: Request,
    body: dict,
) -> tuple[str, dict]:
    purpose = body.get("purpose")
    if purpose not in {"chat", "enhance", "configured"}:
        raise ValueError("invalid purpose")
    allowed = {"workspace", "purpose"}
    if purpose == "chat":
        allowed.add("model_id")
        selection = _resolve_llm_chat_model(request, body.get("model_id"))
    elif purpose == "enhance":
        from services import llm_service

        allowed.update({"model_type", "vision_required"})
        vision_required = body.get("vision_required", False)
        if not isinstance(vision_required, bool):
            raise ValueError("invalid vision_required")
        model_type = body.get("model_type", "")
        if not isinstance(model_type, str):
            raise ValueError("invalid model_type")
        services = wgp.server_config.get("services", {})
        model_id, device, _raw_mode = _resolve_prompt_enhancer_selection(
            model_type,
            services,
            has_images=vision_required,
            model_registry=llm_service.MODEL_REGISTRY,
        )
        selection = {
            "model_id": model_id,
            "device": device,
            "provider": "local",
            "remote_url": "",
            "api_key": "",
            "local_gguf_path": "",
            "gguf_file_override": "",
        } if model_id else _resolve_direct_llm_selection(request)
    else:
        selection = _resolve_direct_llm_selection(request)
    if set(body) - allowed:
        raise ValueError("unexpected preparation field")
    return purpose, selection


@api.post("/api/v1/llm/prepare", status_code=202)
async def llm_prepare(request: Request):
    """Start/coalesce content-free, project-authorized model preparation."""
    from services.llm_operations import (
        LlmOperationCapacityError,
        llm_preparation_manager,
    )

    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(
            status_code=400, detail="Invalid LLM preparation request",
        )
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    workspace = _request_project_workspace(request, body.get("workspace"))
    _require_project_access(request, workspace)
    try:
        purpose, selection = await asyncio.to_thread(
            _resolve_llm_prepare_selection, request, body,
        )
    except (TypeError, ValueError) as error:
        raise HTTPException(
            status_code=400,
            detail="LLM preparation selection is not available",
        ) from error
    owner_key, project_key = _llm_operation_scope(request, workspace)
    selection_key = _llm_selection_key(purpose, selection)
    try:
        return await llm_preparation_manager.start(
            owner_key=owner_key,
            project_key=project_key,
            selection_key=selection_key,
            purpose=purpose,
            prepare=lambda: _prepare_llm_selection(selection),
        )
    except LlmOperationCapacityError as error:
        raise HTTPException(
            status_code=503, detail="LLM preparation is busy",
        ) from error


@api.get("/api/v1/llm/prepare/{operation_id}")
def llm_prepare_status(
    request: Request,
    operation_id: str,
    workspace: str = "",
):
    """Return bounded public state for one owned preparation operation."""
    from services.llm_operations import llm_preparation_manager

    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    selected_workspace = _request_project_workspace(request, workspace)
    _require_project_access(request, selected_workspace)
    owner_key, project_key = _llm_operation_scope(
        request, selected_workspace,
    )
    status = llm_preparation_manager.status(
        operation_id,
        owner_key=owner_key,
        project_key=project_key,
    )
    if status is None:
        raise HTTPException(
            status_code=404, detail="LLM preparation not found",
        )
    return status


def _resolve_llm_chat_images(
    request: Request,
    body: dict,
    workspace: str,
) -> list[str]:
    """Resolve a bounded set of session/project-authorized Chat images.

    Browser clients submit only upload references.  Local API compatibility
    also permits the existing authorized media forms, but every value passes
    through the same project/session resolver before a model can see it.
    """
    raw_images = body.get("image_paths", [])
    if raw_images in (None, []):
        return []
    if (
        not isinstance(raw_images, list)
        or not 1 <= len(raw_images) <= _LLM_CHAT_MAX_IMAGES
    ):
        raise HTTPException(
            status_code=400,
            detail=f"image_paths must contain at most {_LLM_CHAT_MAX_IMAGES} images",
        )
    resolved: list[str] = []
    for raw in raw_images:
        if not isinstance(raw, str) or not raw.strip():
            raise HTTPException(status_code=400, detail="Invalid Chat image reference")
        image_path = _resolve_authorized_request_media(request, raw, workspace)
        if image_path is None:
            # Keep ownership and existence failures indistinguishable.
            raise HTTPException(status_code=404, detail="Chat image not found")
        resolved.append(image_path)
    return resolved


async def _execute_llm_chat(
    request: Request,
    body: dict,
    image_paths: list[str],
    progress_callback=None,
    validated: dict | None = None,
    response_assist_snapshot=None,
) -> dict:
    """Execute one prevalidated, already-authorized Chat turn."""
    from services import llm_service

    from services.llm_operations import run_blocking_shielded

    if validated is None:
        try:
            validated = await run_blocking_shielded(
                _validate_llm_chat_request, request, body, image_paths,
            )
        except ValueError as error:
            raise HTTPException(status_code=400, detail=str(error)) from error
    if response_assist_snapshot is None:
        from services.llm_response_assist import response_assist_corpus_snapshot
        response_assist_snapshot = response_assist_corpus_snapshot()
    messages = validated["messages"]
    guide_ids = validated["guide_ids"]
    system_prompt = validated["system_prompt"]
    selection = validated["selection"]
    max_new_tokens = validated["max_new_tokens"]
    temperature = validated["temperature"]
    top_p = validated["top_p"]

    try:
        _emit_llm_progress(progress_callback, {
            "phase": "loading",
            "attempt": 1,
        })

        def run_chat():
            # Resolve both consent and provider locality after the exact model
            # lease is ready. A stale configured URL/key or a public provider
            # can never receive the prefill/detector mechanism.
            response_assist = _resolved_local_response_assist(
                body, selection, corpus_snapshot=response_assist_snapshot,
            )
            _emit_llm_progress(progress_callback, {
                "phase": "inference",
                "attempt": 1,
                "attempt_cap": 2 if (
                    response_assist
                    and response_assist.get("retry_on_refusal") is True
                ) else 1,
            })
            runtime_system_prompt = system_prompt
            if _explicit_llm_guidance_allowed(body):
                from services.director.nsfw_guidance import inject_content_guidance
                runtime_system_prompt = inject_content_guidance(
                    runtime_system_prompt, True, "enhance",
                )
            return llm_service.generate_chat(
                messages,
                model_id=selection["model_id"],
                device=selection["device"],
                provider=selection["provider"],
                remote_url=selection["remote_url"],
                api_key=selection["api_key"],
                local_gguf_path=selection["local_gguf_path"],
                gguf_file_override=selection["gguf_file_override"],
                system_prompt=runtime_system_prompt,
                max_new_tokens=max_new_tokens,
                temperature=temperature,
                top_p=top_p,
                enable_thinking=(
                    False
                    if response_assist
                    and response_assist.get("assistant_prefill")
                    else None
                ),
                image_paths=image_paths,
                response_assist=response_assist,
                progress_callback=progress_callback,
            )

        text = await run_blocking_shielded(
            _run_authorized_llm_with_selection,
            request,
            selection,
            run_chat,
        )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    except Exception as error:
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail="LLM chat failed; check the local Maestro logs",
        ) from error
    return {
        "text": text,
        "model_id": selection["response_model_id"],
        "guide_ids": guide_ids,
    }


def _emit_llm_progress(progress_callback, event: dict) -> None:
    """Send one operation-local snapshot without risking inference failure."""
    if not callable(progress_callback):
        return
    try:
        progress_callback(event)
    except Exception:
        pass


def _llm_chat_sampling_options(body: dict) -> tuple[float, float]:
    """Validate the public Chat sampling controls used by inference/digest."""
    temperature = body.get("temperature", 0.7)
    top_p = body.get("top_p", 0.9)
    if (
        isinstance(temperature, bool)
        or not isinstance(temperature, (int, float))
        or not math.isfinite(temperature)
        or not 0 <= temperature <= 2
    ):
        raise ValueError("temperature must be between 0 and 2")
    if (
        isinstance(top_p, bool)
        or not isinstance(top_p, (int, float))
        or not math.isfinite(top_p)
        or not 0 < top_p <= 1
    ):
        raise ValueError("top_p must be greater than 0 and at most 1")
    return float(temperature), float(top_p)


def _validate_llm_chat_request(
    request: Request,
    body: dict,
    image_paths: list[str],
) -> dict:
    """Resolve all deterministic Chat inputs before admitting an operation."""
    from services import llm_service

    messages = llm_service.validate_chat_messages(body.get("messages"))
    guide_ids, system_prompt = llm_service.load_chat_guides(
        body.get("guide_ids", []),
    )
    selection = _resolve_llm_chat_model(request, body.get("model_id"))
    if image_paths and selection.get("vision_capable") is False:
        raise ValueError("The selected LLM is text only and cannot accept images")
    max_new_tokens = body.get("max_new_tokens", 2048)
    if (
        isinstance(max_new_tokens, bool)
        or not isinstance(max_new_tokens, int)
        or not 1 <= max_new_tokens <= llm_service.CHAT_MAX_NEW_TOKENS
    ):
        raise ValueError(
            "max_new_tokens must be between 1 and "
            f"{llm_service.CHAT_MAX_NEW_TOKENS}"
        )
    temperature, top_p = _llm_chat_sampling_options(body)
    return {
        "messages": messages,
        "guide_ids": guide_ids,
        "system_prompt": system_prompt,
        "selection": selection,
        "max_new_tokens": max_new_tokens,
        "temperature": temperature,
        "top_p": top_p,
    }


def _resolved_local_response_assist(
    body: dict,
    selection: dict,
    *,
    corpus_snapshot=None,
) -> dict | None:
    """Gate prefill/detection on literal opt-in, current consent, and locality."""
    if (
        body.get("explicit_output") is not True
        or not _explicit_llm_guidance_allowed(body)
        or str(selection.get("provider") or "local").strip().lower() != "local"
        or bool(str(selection.get("remote_url") or "").strip())
        or bool(str(selection.get("api_key") or "").strip())
    ):
        return None
    from services.llm_response_assist import build_server_response_assist
    return build_server_response_assist(corpus_snapshot=corpus_snapshot)


def _normalize_llm_chat_request_id(value) -> str:
    if not isinstance(value, str):
        raise ValueError("request_id must be a UUID")
    try:
        parsed = uuid.UUID(value)
    except (AttributeError, TypeError, ValueError) as error:
        raise ValueError("request_id must be a UUID") from error
    return parsed.hex


def _llm_chat_request_digest(
    body: dict,
    *,
    workspace: str,
    image_paths: list[str],
    response_assist_snapshot=None,
) -> str:
    """Bind a recovery id to only fields that affect Chat inference."""
    from services.llm_response_assist import (
        SERVER_RESPONSE_ASSIST_IDENTITY,
        response_assist_corpus_snapshot,
    )

    if response_assist_snapshot is None:
        response_assist_snapshot = response_assist_corpus_snapshot()
    corpus_revision = getattr(response_assist_snapshot, "revision", 0)
    if isinstance(corpus_revision, bool) or not isinstance(corpus_revision, int):
        corpus_revision = 0

    effective_request = {
        "workspace": workspace,
        "model_id": body.get("model_id"),
        "messages": body.get("messages"),
        "guide_ids": body.get("guide_ids", []),
        "max_new_tokens": body.get("max_new_tokens", 2048),
        "temperature": body.get("temperature", 0.7),
        "top_p": body.get("top_p", 0.9),
        "explicit_output": body.get("explicit_output") is True,
        "response_assist": dict(SERVER_RESPONSE_ASSIST_IDENTITY),
        "refusal_corpus_revision": corpus_revision,
        "image_paths": list(image_paths),
    }
    try:
        material = json.dumps(
            effective_request,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    except (TypeError, ValueError) as error:
        raise ValueError("Chat request is not serializable") from error
    return hmac.new(
        _session_secret(), material, hashlib.sha256,
    ).hexdigest()


@api.post("/api/v1/llm/chat")
async def llm_chat(request: Request):
    """Run one bounded, project-authorized LLM Chat turn."""
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="JSON object body is required")
    workspace = body.get("workspace")
    if not isinstance(workspace, str) or not workspace.strip():
        raise HTTPException(status_code=400, detail="workspace is required")

    # PINOKIO_SHARE_LOCAL clients are external even though the broader legacy
    # middleware reserves `maestro_remote` for Cloudflare. Promote only this
    # request before the shared project guard/model resolver run.
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    # Authorization happens before guide/model resolution or any download.
    _require_project_access(
        request, workspace, permission="project.generate",
    )
    image_paths = (
        _resolve_llm_chat_images(request, body, workspace)
        if "image_paths" in body else []
    )
    cleanup_chat_uploads = globals().get("_cleanup_llm_chat_uploads")
    claim_chat_uploads = globals().get("_claim_llm_chat_uploads")
    claim_error_type = globals().get("_LlmChatUploadClaimError")
    if not isinstance(claim_error_type, type):
        class _MissingLlmChatUploadClaimError(Exception):
            pass
        claim_error_type = _MissingLlmChatUploadClaimError

    from services.llm_operations import (
        ChatAdmissionError,
        ChatRequestMismatchError,
        LlmOperationCapacityError,
        llm_chat_operation_manager,
    )

    raw_request_id = body.get("request_id")
    if raw_request_id is None:
        if callable(cleanup_chat_uploads):
            cleanup_chat_uploads(request, workspace, image_paths)
        raise HTTPException(
            status_code=400,
            detail="request_id is required for recoverable Chat",
        )
    try:
        request_id = _normalize_llm_chat_request_id(raw_request_id)
    except ValueError as error:
        if callable(cleanup_chat_uploads):
            cleanup_chat_uploads(request, workspace, image_paths)
        raise HTTPException(
            status_code=400, detail="Invalid Chat request id",
        ) from error
    try:
        from services.llm_operations import run_blocking_shielded
        validated = await run_blocking_shielded(
            _validate_llm_chat_request, request, body, image_paths,
        )
        from services.llm_response_assist import response_assist_corpus_snapshot
        response_assist_snapshot = response_assist_corpus_snapshot()
        request_digest = _llm_chat_request_digest(
            body,
            workspace=workspace,
            image_paths=image_paths,
            response_assist_snapshot=response_assist_snapshot,
        )
    except ValueError as error:
        if callable(cleanup_chat_uploads):
            cleanup_chat_uploads(request, workspace, image_paths)
        raise HTTPException(status_code=400, detail=str(error)) from error
    owner_key, project_key = _llm_operation_scope(request, workspace)

    def admit_async_chat() -> bool:
        if not _llm_chat_admission.acquire(blocking=False):
            return False
        try:
            if callable(claim_chat_uploads):
                claim_chat_uploads(
                    request,
                    workspace,
                    image_paths,
                    request_id=request_id,
                    request_digest=request_digest,
                    project_instance=project_key,
                )
        except Exception:
            _llm_chat_admission.release()
            raise
        return True

    def finish_async_chat() -> None:
        try:
            if callable(cleanup_chat_uploads):
                cleanup_chat_uploads(
                    request,
                    workspace,
                    image_paths,
                    request_id=request_id,
                    request_digest=request_digest,
                    project_instance=project_key,
                )
        finally:
            _llm_chat_admission.release()

    try:
        status = llm_chat_operation_manager.submit(
            request_id=request_id,
            owner_key=owner_key,
            project_key=project_key,
            request_digest=request_digest,
            execute=lambda progress_callback: _execute_llm_chat(
                request, body, image_paths, progress_callback, validated,
                response_assist_snapshot,
            ),
            admit=admit_async_chat,
            release=finish_async_chat,
        )
    except claim_error_type as error:
        raise HTTPException(
            status_code=409,
            detail="Chat image is already attached to another request",
        ) from error
    except ChatRequestMismatchError as error:
        # The original in-flight operation may still need these exact
        # single-use uploads. Its completion callback owns cleanup.
        raise HTTPException(
            status_code=409, detail="Chat request does not match",
        ) from error
    except ChatAdmissionError as error:
        if callable(cleanup_chat_uploads):
            cleanup_chat_uploads(request, workspace, image_paths)
        raise HTTPException(
            status_code=429,
            detail="Another LLM chat turn is already running; retry shortly",
        ) from error
    except LlmOperationCapacityError as error:
        if callable(cleanup_chat_uploads):
            cleanup_chat_uploads(request, workspace, image_paths)
        raise HTTPException(
            status_code=503, detail="LLM Chat recovery is busy",
        ) from error
    if status is None:
        if callable(cleanup_chat_uploads):
            cleanup_chat_uploads(request, workspace, image_paths)
        raise HTTPException(status_code=404, detail="Chat request not found")
    return JSONResponse(status, status_code=202)


@api.get("/api/v1/llm/chat/{request_id}")
def llm_chat_status(
    request: Request,
    request_id: str,
    workspace: str = "",
):
    """Recover one bounded, in-memory Chat result by opaque request id."""
    from services.llm_operations import llm_chat_operation_manager

    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    selected_workspace = _request_project_workspace(request, workspace)
    _require_project_access(request, selected_workspace)
    try:
        normalized_id = _normalize_llm_chat_request_id(request_id)
    except ValueError as error:
        raise HTTPException(
            status_code=404, detail="Chat request not found",
        ) from error
    owner_key, project_key = _llm_operation_scope(
        request, selected_workspace,
    )
    status = llm_chat_operation_manager.status(
        normalized_id,
        owner_key=owner_key,
        project_key=project_key,
    )
    if status is None:
        raise HTTPException(status_code=404, detail="Chat request not found")
    return status


