@api.post("/api/v1/llm/generate")
async def llm_generate(request: Request):
    """Generate text with the configured LLM for an authorized project."""
    from services import llm_service
    from services.llm_operations import run_blocking_shielded
    body = await request.json()
    _promote_external_llm_request(request)
    workspace = _request_project_workspace(request, body.get("workspace"))
    _require_project_access(
        request, workspace, permission="project.generate",
    )

    prompt = body.get("prompt", "")
    if not prompt:
        raise HTTPException(status_code=400, detail="prompt is required")

    try:
        selection = await run_blocking_shielded(
            _resolve_direct_llm_selection, request,
        )
        result = await run_blocking_shielded(
            _run_authorized_llm_with_selection,
            request,
            selection,
            _run_llm_route_operation,
            request,
            body,
            selection,
            llm_service.generate,
            prompt=prompt,
            system_prompt=body.get("system_prompt", ""),
            max_new_tokens=body.get("max_new_tokens", 256),
            temperature=body.get("temperature", 0.7),
            top_p=body.get("top_p", 0.9),
            seed=body.get("seed"),
        )
        return {"text": result}
    except Exception as error:
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail="LLM generation failed; check the local Maestro logs",
        ) from error


# --- Music: LLM song-writer (Music mode Simple) ---

# The song-writer system prompts live in editable guide files (loaded via
# services.guide_loader.load_guide at request time, cached after first read):
#   app/services/llm_guides/music/song_writer.md            (vocals)
#   app/services/llm_guides/music/song_writer_instrumental.md
# Edit those to tune the prompt without touching code. These short fallbacks are
# only used if a guide file is missing/unreadable.
_SONG_WRITER_FALLBACK = (
    "You are a songwriter for ACE-Step 1.5. From the user's brief, output EXACTLY "
    "two sections and nothing else:\n[STYLE]\nA dense prose paragraph describing "
    "genre, instruments, mood, production, and vocal type (no numeric BPM/key).\n"
    "[LYRICS]\nOriginal lyrics with [Verse]/[Chorus]/[Bridge] section tags on their "
    "own lines, ~6-10 syllables per line. Keep STYLE and LYRICS consistent."
)
_SONG_WRITER_FALLBACK_INSTRUMENTAL = (
    "You are a music producer for ACE-Step 1.5. Output EXACTLY two sections:\n"
    "[STYLE]\nA dense prose paragraph describing genre, instruments, mood, "
    "production, and energy — instrumental, no vocals, no numeric BPM/key.\n"
    "[LYRICS]\n[Instrumental]"
)


def _parse_song_output(raw, instrumental):
    """Split the song-writer LLM output into (style, lyrics)."""
    import re as _re
    text = str(raw or "").strip()
    style, lyrics = "", ""
    sm = _re.search(r"\[STYLE\](.*?)(?=\[LYRICS\]|\Z)", text, _re.IGNORECASE | _re.DOTALL)
    lm = _re.search(r"\[LYRICS\](.*)\Z", text, _re.IGNORECASE | _re.DOTALL)
    if sm:
        style = sm.group(1).strip()
    if lm:
        lyrics = lm.group(1).strip()
    if not style and not lyrics:
        # LLM ignored the format — keep the whole thing as lyrics.
        lyrics = text
    if instrumental:
        lyrics = "[Instrumental]"
    return style, lyrics


@api.post("/api/v1/llm/write-song")
async def llm_write_song(request: Request):
    """Music-mode Simple writer: from a free-text description, produce a Music
    Caption (style tags) + structured lyrics for ACE-Step. Returns
    {style, lyrics, raw}."""
    from services import llm_service
    from services.llm_operations import run_blocking_shielded
    body = await request.json()
    _promote_external_llm_request(request)
    description = (body.get("description") or "").strip()
    if not description:
        raise HTTPException(status_code=400, detail="description is required")
    instrumental = bool(body.get("instrumental"))

    # Optional reference image → the vision LLM lets the visuals inform the
    # STYLE (e.g. neon cityscape → synthwave). Degrades gracefully: if the
    # loaded LLM has no vision (mmproj), llm_service.generate ignores images.
    image_paths = body.get("image_paths") or []
    if not image_paths and body.get("reference_image_path"):
        image_paths = [body["reference_image_path"]]
    workspace = _request_project_workspace(request, body.get("workspace"))
    _require_project_access(
        request, workspace, permission="project.generate",
    )
    image_paths = [
        resolved for path in image_paths
        if (resolved := _resolve_authorized_request_media(
            request, path, workspace,
        ))
    ]

    from services.guide_loader import load_guide
    if instrumental:
        system_prompt = load_guide("music", "song_writer_instrumental") or _SONG_WRITER_FALLBACK_INSTRUMENTAL
    else:
        system_prompt = load_guide("music", "song_writer") or _SONG_WRITER_FALLBACK
    try:
        selection = await run_blocking_shielded(
            _resolve_direct_llm_selection, request,
        )
        raw = await run_blocking_shielded(
            _run_authorized_llm_with_selection,
            request,
            selection,
            _run_llm_route_operation,
            request,
            body,
            selection,
            llm_service.generate,
            prompt=description,
            system_prompt=system_prompt,
            max_new_tokens=body.get("max_new_tokens", 1024),
            temperature=body.get("temperature", 0.85),
            top_p=body.get("top_p", 0.9),
            seed=body.get("seed"),
            image_paths=image_paths or None,
        )
    except Exception as error:
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail="Song writing failed; check the local Maestro logs",
        ) from error
    style, lyrics = _parse_song_output(raw, instrumental)
    return {"style": style, "lyrics": lyrics, "raw": raw}


def _build_music_gen_params(model_type: str, lyrics: str, style: str, duration_seconds, seed) -> dict:
    """Build an ACE-Step generation params dict by seeding from the model's
    OWN default settings — the exact same source the Studio Music UI starts
    from (served via /api/v1/models/{model_type} → wgp.get_default_settings).
    This guarantees parity: every model-specific field the ACE-Step pipeline
    needs (LM sampling temperature/top_k/top_p, audio_scale, scheduler_type,
    shift, num_inference_steps, etc.) is present. A hand-built subset omitted
    the LM sampling fields, which made the XL "Strong Think" LM path fail with
    'NoneType object does not support item assignment'. We override only the
    song content, duration, and seed, then force audio-only generation."""
    try:
        params = dict(wgp.get_default_settings(model_type) or {})
    except Exception as e:
        print(f"[generate-music] get_default_settings failed for {model_type}: {e}")
        params = {}
    params["model_type"] = model_type
    params["prompt"] = lyrics or "[Instrumental]"
    params["alt_prompt"] = style or ""
    params.setdefault("negative_prompt", "")
    if duration_seconds:
        try:
            params["duration_seconds"] = float(duration_seconds)
        except (TypeError, ValueError):
            pass
    try:
        params["seed"] = int(seed)
    except (TypeError, ValueError):
        params["seed"] = -1
    # Force audio-only, single-prompt generation (no video output).
    params["video_length"] = 0
    params["image_mode"] = 0
    params["multi_prompts_gen_type"] = 2
    params["generation_mode"] = "audio"
    return params


@api.post("/api/v1/director/preparation")
async def director_preparation_start(request: Request):
    """Issue the durable request id before a long music/analysis chain."""
    body = await request.json()
    workspace = body.get("workspace") or _get_active_workspace()
    image_paths = body.get("image_paths") or []
    if not image_paths and body.get("reference_image_path"):
        image_paths = [body["reference_image_path"]]
    image_paths = [
        resolved for path in image_paths
        if (resolved := _resolve_authorized_request_media(
            request, path, workspace,
        ))
    ]
    project_dir = _require_project_access(
        request, workspace, permission="project.generate",
    )
    durable_request = dict(body)
    durable_request["workspace"] = workspace
    durable_request["image_paths"] = list(image_paths)
    durable_request.pop("reference_image_path", None)
    request_id, state = _register_director_preparation(
        request, durable_request, workspace, project_dir,
    )
    return {
        "director_request_id": request_id,
        "status": str(state.get("status") or "running"),
        "phase": str(state.get("phase") or "registered"),
        "next_action": "generate_music",
        "actions": ["generate_music"],
    }


@api.post("/api/v1/director/generate-music")
async def director_generate_music(request: Request):
    """Generate a music track for Director Music Video mode. Dual-mode:
      - If `style`/`lyrics` are supplied, render them directly.
      - Else if `description` is supplied, write the song first (optionally
        informed by a reference image via the vision LLM), then render.
    Blocks until the track is rendered (consistent with the awaited
    upload→analyze→plan-structure chain) and returns the ABSOLUTE
    {audio_path} so the frontend can feed it straight into /audio/analyze.
    Returns {audio_path, filename, style, lyrics}."""
    import asyncio

    from services.llm_operations import run_blocking_shielded

    body = await request.json()
    _promote_external_llm_request(request)
    description = (body.get("description") or "").strip()
    style = (body.get("style") or "").strip()
    lyrics = (body.get("lyrics") or "").strip()
    instrumental = bool(body.get("instrumental"))
    model_type = body.get("model_type") or "ace_step_v1_5_xl_sft_lm_4b"
    _require_remote_visible_models(request, [model_type])
    duration_seconds = body.get("duration_seconds")
    seed = body.get("seed")
    workspace = _request_project_workspace(request, body.get("workspace"))
    if not body.get("director_request_id") and wgp.get_model_def(model_type) is None:
        raise HTTPException(status_code=400, detail=f"Unknown model: {model_type}")

    image_paths = body.get("image_paths") or []
    if not image_paths and body.get("reference_image_path"):
        image_paths = [body["reference_image_path"]]
    image_paths = [
        resolved for path in image_paths
        if (resolved := _resolve_authorized_request_media(
            request, path, workspace,
        ))
    ]

    out_dir = _require_project_access(
        request, workspace, permission="project.generate",
    )
    durable_request = dict(body)
    durable_request["workspace"] = workspace
    durable_request["image_paths"] = list(image_paths)
    durable_request.pop("reference_image_path", None)
    request_id, preparation = _register_director_preparation(
        request, durable_request, workspace, out_dir,
    )
    saved_request = preparation.get("request")
    if isinstance(saved_request, dict):
        description = str(
            saved_request.get("description") or description
        ).strip()
        style = str(saved_request.get("style") or style).strip()
        lyrics = str(saved_request.get("lyrics") or lyrics).strip()
        instrumental = bool(
            saved_request.get("instrumental", instrumental)
        )
        model_type = str(saved_request.get("model_type") or model_type)
        duration_seconds = saved_request.get(
            "duration_seconds", duration_seconds,
        )
        seed = saved_request.get("seed", seed)
        saved_images = saved_request.get("image_paths")
        if isinstance(saved_images, list):
            image_paths = list(saved_images)
    _require_remote_visible_models(request, [model_type])
    if wgp.get_model_def(model_type) is None:
        raise HTTPException(status_code=400, detail=f"Unknown model: {model_type}")
    _checkpoint_director_preparation(
        request_id,
        out_dir,
        phase=(
            "song_writing"
            if description and (not style or not lyrics)
            else "music_queued"
        ),
    )

    if instrumental:
        lyrics = "[Instrumental]"

    # Write the song from the description when we don't already have content.
    if (not style or not lyrics) and description:
        from services import llm_service
        from services.guide_loader import load_guide
        if instrumental:
            system_prompt = load_guide("music", "song_writer_instrumental") or _SONG_WRITER_FALLBACK_INSTRUMENTAL
        else:
            system_prompt = load_guide("music", "song_writer") or _SONG_WRITER_FALLBACK
        try:
            selection = await run_blocking_shielded(
                _resolve_direct_llm_selection, request,
            )
            raw = await run_blocking_shielded(
                _run_authorized_llm_with_selection,
                request,
                selection,
                _run_llm_route_operation,
                request,
                body,
                selection,
                llm_service.generate,
                prompt=description,
                system_prompt=system_prompt,
                max_new_tokens=body.get("max_new_tokens", 1024),
                temperature=body.get("temperature", 0.85),
                top_p=body.get("top_p", 0.9),
                seed=body.get("seed"),
                image_paths=image_paths or None,
            )
        except Exception as error:
            traceback.print_exc()
            raise HTTPException(
                status_code=500,
                detail="Song writing failed; check the local Maestro logs",
            ) from error
        w_style, w_lyrics = _parse_song_output(raw, instrumental)
        style = style or w_style
        lyrics = lyrics or w_lyrics

    with _director_preparation_lock:
        current_preparation = dict(
            _director_preparation_states.get(request_id) or {}
        )
    current_request = dict(current_preparation.get("request") or durable_request)
    current_request.update({"style": style, "lyrics": lyrics})
    _checkpoint_director_preparation(
        request_id, out_dir,
        phase="music_queued",
        request=current_request,
    )

    if not lyrics:
        raise HTTPException(status_code=400, detail="Provide a description, or style + lyrics")

    gen_params = _build_music_gen_params(model_type, lyrics, style, duration_seconds, seed)
    music_policy = _http_output_policy_from_request(
        body,
        owner_session_id=request.state.maestro_session_id,
    )
    gen_params["_maestro_access_policy"] = music_policy
    gen_params["_maestro_session_id"] = request.state.maestro_session_id
    gen_params["_director_request_id"] = request_id
    gen_params["_director_recovery_parent_id"] = request_id
    gen_params["_director_recovery_unit"] = {
        "kind": "prepipeline_music",
        "variant": 0,
        "index": 0,
    }

    # Wire director_pipeline's shared refs (_jobs / _run_generation / _gen_lock)
    # before using _submit_and_wait — without this they're None and the first
    # line `_jobs[job_id] = job` raises "'NoneType' object does not support
    # item assignment". Every other _submit_and_wait caller calls this first.
    _init_pipeline()
    from services.director_pipeline import _submit_and_wait
    try:
        output_files = await asyncio.to_thread(
            _submit_and_wait,
            gen_params,
            timeout_s=1800,
            workspace=workspace,
            out_dir=out_dir,
        )
    except Exception as error:
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail="Music generation failed; check the local Maestro logs",
        ) from error
    if not output_files:
        raise HTTPException(status_code=500, detail="Music generation produced no output")

    filename = output_files[0]
    audio_path = os.path.join(out_dir, filename)
    music_evidence = None
    for candidate in list(_jobs.values()):
        candidate_params = candidate.get("params") or {}
        if (
            candidate.get("kind") != "director_child"
            or candidate_params.get("_director_request_id") != request_id
        ):
            continue
        verified = _director_recovery_verified_child(candidate, out_dir)
        if (
            isinstance(verified, dict)
            and filename in (verified.get("outputs") or [])
        ):
            music_evidence = verified
            break
    if music_evidence is None:
        raise HTTPException(
            status_code=500,
            detail="Music generation recovery evidence is incomplete",
        )
    _checkpoint_director_preparation(
        request_id, out_dir,
        phase="music_completed",
        music={"filename": filename, "evidence": music_evidence},
    )
    return {
        "director_request_id": request_id,
        "audio_path": filename if bool(getattr(request.state, "maestro_remote", False)) else audio_path,
        "filename": filename,
        "style": style,
        "lyrics": lyrics,
    }


def _resolve_prompt_enhancer_selection(
    model_type: str,
    services: dict,
    *,
    has_images: bool = False,
    model_registry: dict | None = None,
) -> tuple[str, str, bool]:
    """Return a task/capability-safe enhancer selection.

    Dedicated generation-model enhancers retain precedence when they support
    the request. An image-bearing request never reaches a text-only configured
    or dedicated override; it falls back to the generic Qwen Vision enhancer.
    """
    enhance_model = str(
        services.get("enhance_llm_model_id")
        or _DEFAULT_ENHANCE_LLM_REPO
    )
    enhance_device = str(services.get("enhance_llm_device") or "cuda")
    raw_enhancer_mode = False
    if model_type:
        try:
            model_definition = wgp.get_model_def(model_type)
            dedicated = (model_definition or {}).get("prompt_enhancer_model")
            if dedicated:
                enhance_model = str(dedicated)
                raw_enhancer_mode = True
        except Exception as error:
            print(f"[Enhance] Per-model enhancer lookup failed: {error}")

    if has_images:
        registry_entry = (model_registry or {}).get(enhance_model) or {}
        if not (
            registry_entry.get("mmproj_file")
            or registry_entry.get("native_vision") is True
        ):
            print(
                f"[Enhance] {enhance_model} has no registered vision "
                "projector; using the Qwen Vision enhancer"
            )
            enhance_model = _DEFAULT_ENHANCE_LLM_REPO
            raw_enhancer_mode = False
    return enhance_model, enhance_device, raw_enhancer_mode


def _resolve_prompt_enhancer_runtime_selection(
    request: Request,
    model_type: str,
    services: dict,
    *,
    has_images: bool,
) -> tuple[dict[str, Any], bool]:
    """Resolve the exact configured provider/catalog identity for Enhance."""
    from services import llm_service

    enhance_model, enhance_device, raw_enhancer_mode = (
        _resolve_prompt_enhancer_selection(
            model_type,
            services,
            has_images=has_images,
            model_registry=llm_service.MODEL_REGISTRY,
        )
    )
    configured_model = str(services.get("enhance_llm_model_id") or "")
    uses_configured_catalog = bool(
        configured_model
        and not raw_enhancer_mode
        and hmac.compare_digest(enhance_model, configured_model)
    )
    if uses_configured_catalog:
        configured_provider = str(
            services.get("llm_provider") or "local"
        ).strip().lower()
        catalog = _llm_model_catalog(request, configured_provider)
        catalog_entry = next(
            (
                item for item in catalog
                if isinstance(item, dict)
                and item.get("id") == enhance_model
            ),
            None,
        )
        if catalog_entry is None:
            raise HTTPException(
                status_code=409,
                detail="Configured Prompt Enhance model is unavailable",
            )
        selection = _resolve_llm_chat_model(request, enhance_model)
        expected_provider = str(
            catalog_entry.get("provider")
            or (
                "local"
                if _llm_chat_request_is_external(request)
                else configured_provider
            )
            or "local"
        ).strip().lower()
        if not hmac.compare_digest(
            str(selection.get("provider") or "local").strip().lower(),
            expected_provider,
        ):
            raise HTTPException(
                status_code=409,
                detail="Configured Prompt Enhance model is unavailable",
            )
        if expected_provider == "local":
            selection["device"] = enhance_device
    else:
        selection = {
            "model_id": enhance_model,
            "device": enhance_device,
            "provider": "local",
            "remote_url": "",
            "api_key": "",
            "local_gguf_path": "",
            "gguf_file_override": "",
        }
    return selection, raw_enhancer_mode


def _resolve_vision_llm_selection() -> dict:
    """Resolve the local Qwen/compatible enhancer lane for image work."""
    from services import llm_service

    services = wgp.server_config.get("services", {})
    model_id, device, _raw_mode = _resolve_prompt_enhancer_selection(
        "",
        services,
        has_images=True,
        model_registry=llm_service.MODEL_REGISTRY,
    )
    return {
        "model_id": model_id,
        "device": device,
        "provider": "local",
        "remote_url": "",
        "api_key": "",
        "local_gguf_path": "",
        "gguf_file_override": "",
    }


def _llm_route_progress_callback(request: Request):
    """Return only a server-owned, request-scoped telemetry writer."""
    callback = getattr(request.state, "maestro_llm_progress_callback", None)
    return callback if callable(callback) else None


def _run_llm_route_operation(
    request: Request,
    body: dict,
    selection: dict,
    operation,
    /,
    *args,
    explicit_guidance_keyword: str = "",
    **kwargs,
):
    """Inject only server-owned options after the exact-model lease is held."""
    if explicit_guidance_keyword:
        kwargs[explicit_guidance_keyword] = _explicit_llm_guidance_allowed(body)
    kwargs.setdefault(
        "response_assist",
        _resolved_local_response_assist(body, selection),
    )
    kwargs.setdefault(
        "progress_callback",
        _llm_route_progress_callback(request),
    )
    return operation(*args, **kwargs)


def _with_llm_route_progress(
    operation,
    progress_callback,
    response_assist=None,
    cancel_handle=None,
):
    """Bind request options without reading the singleton stream buffer."""
    if not callable(progress_callback) and not response_assist and cancel_handle is None:
        return operation

    def run(*args, **kwargs):
        if callable(progress_callback):
            kwargs.setdefault("progress_callback", progress_callback)
        if response_assist:
            kwargs.setdefault("response_assist", response_assist)
        if cancel_handle is not None:
            kwargs.setdefault("cancel_handle", cancel_handle)
        return operation(*args, **kwargs)

    return run


def _resolve_prompt_enhancement_images(
    request: Request,
    body: Mapping[str, Any],
    workspace: str,
) -> list[str]:
    """Resolve every supplied Enhance image or fail with one opaque result."""
    requested = body.get("image_paths")
    if requested in (None, []):
        single = body.get("image_path")
        requested = [single] if single else []
    if (
        not isinstance(requested, list)
        or len(requested) > _LLM_ENHANCE_MAX_IMAGES
    ):
        raise HTTPException(status_code=400, detail="Invalid Enhance image list")
    resolved_paths: list[str] = []
    for value in requested:
        if not isinstance(value, str) or not value.strip():
            raise HTTPException(status_code=404, detail="Enhance image not found")
        resolved = _resolve_authorized_request_media(
            request, value, workspace,
        )
        if resolved is None:
            raise HTTPException(status_code=404, detail="Enhance image not found")
        resolved_paths.append(resolved)
    return resolved_paths


def _seal_prompt_enhancement_images(
    image_paths: list[str],
    cancel_handle=None,
    *,
    max_file_bytes: int = _LLM_CHAT_MAX_IMAGE_BYTES,
    max_total_bytes: int = _LLM_ENHANCE_MAX_TOTAL_IMAGE_BYTES,
    media_label: str = "Enhance image",
) -> list[dict[str, Any]]:
    """Bind authorized image paths to exact regular-file bytes."""
    admitted: list[tuple[str, tuple[int, int, int, int, int]]] = []
    total_size = 0
    try:
        for image_path in image_paths:
            if cancel_handle is not None:
                cancel_handle.checkpoint()
            current = os.stat(image_path, follow_symlinks=False)
            if not stat.S_ISREG(current.st_mode) or current.st_nlink != 1:
                raise OSError("unsafe Enhance image")
            if current.st_size > max_file_bytes:
                raise HTTPException(
                    status_code=413,
                    detail=(
                        "Enhance image is too large (max 32 MB)"
                        if media_label == "Enhance image"
                        and max_file_bytes == _LLM_CHAT_MAX_IMAGE_BYTES
                        else f"{media_label} is too large"
                    ),
                )
            total_size += current.st_size
            if total_size > max_total_bytes:
                raise HTTPException(
                    status_code=413,
                    detail=(
                        "Enhance images are too large (max 64 MB total)"
                        if media_label == "Enhance image"
                        and max_total_bytes == _LLM_ENHANCE_MAX_TOTAL_IMAGE_BYTES
                        else f"{media_label} selection is too large"
                    ),
                )
            admitted.append((image_path, (
                current.st_dev,
                current.st_ino,
                current.st_size,
                current.st_mtime_ns,
                current.st_ctime_ns,
            )))
    except HTTPException:
        raise
    except (OSError, TypeError, ValueError):
        raise HTTPException(
            status_code=404, detail=f"{media_label} not found",
        ) from None

    seals: list[dict[str, Any]] = []
    for image_path, admitted_identity in admitted:
        descriptor = -1
        try:
            if cancel_handle is not None:
                cancel_handle.checkpoint()
            descriptor = os.open(
                image_path,
                os.O_RDONLY
                | getattr(os, "O_NOFOLLOW", 0)
                | getattr(os, "O_NONBLOCK", 0),
            )
            before = os.fstat(descriptor)
            if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
                raise OSError("unsafe Enhance image")
            identity = (
                before.st_dev,
                before.st_ino,
                before.st_size,
                before.st_mtime_ns,
                before.st_ctime_ns,
            )
            if identity != admitted_identity:
                raise OSError("Enhance image changed before sealing")
            digest = hashlib.sha256()
            remaining_bytes = before.st_size
            while remaining_bytes:
                if cancel_handle is not None:
                    cancel_handle.checkpoint()
                chunk = os.read(
                    descriptor, min(1024 * 1024, remaining_bytes),
                )
                if not chunk:
                    raise OSError("Enhance image ended while sealing")
                digest.update(chunk)
                remaining_bytes -= len(chunk)
            if os.read(descriptor, 1):
                raise OSError("Enhance image grew while sealing")
            after = os.fstat(descriptor)
            current = os.stat(image_path, follow_symlinks=False)
            if identity != (
                after.st_dev,
                after.st_ino,
                after.st_size,
                after.st_mtime_ns,
                after.st_ctime_ns,
            ) or identity != (
                current.st_dev,
                current.st_ino,
                current.st_size,
                current.st_mtime_ns,
                current.st_ctime_ns,
            ) or not stat.S_ISREG(current.st_mode) or current.st_nlink != 1:
                raise OSError("Enhance image changed while sealing")
            seals.append({
                "path": image_path,
                "device": before.st_dev,
                "inode": before.st_ino,
                "size": before.st_size,
                "mtime_ns": before.st_mtime_ns,
                "ctime_ns": before.st_ctime_ns,
                "sha256": digest.hexdigest(),
            })
        except (OSError, TypeError, ValueError):
            raise HTTPException(
                status_code=404, detail=f"{media_label} not found",
            ) from None
        finally:
            if descriptor >= 0:
                os.close(descriptor)
    return seals


def _revalidate_prompt_enhancement_images(
    image_paths: list[str],
    expected_seals: list[dict[str, Any]],
    cancel_handle=None,
    *,
    max_file_bytes: int = _LLM_CHAT_MAX_IMAGE_BYTES,
    max_total_bytes: int = _LLM_ENHANCE_MAX_TOTAL_IMAGE_BYTES,
    media_label: str = "Enhance image",
) -> None:
    """Fail closed if a worker no longer sees the admitted image bytes."""
    current = _seal_prompt_enhancement_images(
        image_paths,
        cancel_handle,
        max_file_bytes=max_file_bytes,
        max_total_bytes=max_total_bytes,
        media_label=media_label,
    )
    if len(current) != len(expected_seals):
        raise HTTPException(status_code=404, detail=f"{media_label} not found")
    fields = (
        "path", "device", "inode", "size", "mtime_ns", "ctime_ns", "sha256",
    )
    for observed, expected in zip(current, expected_seals):
        if not isinstance(expected, dict) or any(
            observed.get(field) != expected.get(field) for field in fields
        ):
            raise HTTPException(status_code=404, detail=f"{media_label} not found")


def _remove_prompt_enhancement_snapshots(snapshot_paths: list[str]) -> None:
    """Delete private snapshots, clearing Windows read-only state at teardown."""
    for snapshot_path in snapshot_paths:
        if not snapshot_path:
            continue
        if os.name == "nt":
            try:
                os.chmod(snapshot_path, stat.S_IREAD | stat.S_IWRITE)
            except FileNotFoundError:
                continue
        try:
            os.unlink(snapshot_path)
        except FileNotFoundError:
            continue
        except PermissionError:
            # Python on Windows maps chmod(0400) to the read-only file flag.
            # Clear it only during teardown, then retry the exact unlink.
            os.chmod(snapshot_path, stat.S_IREAD | stat.S_IWRITE)
            os.unlink(snapshot_path)


def _materialize_prompt_enhancement_images(
    expected_seals: list[dict[str, Any]],
    cancel_handle=None,
    *,
    max_file_bytes: int = _LLM_CHAT_MAX_IMAGE_BYTES,
    max_total_bytes: int = _LLM_ENHANCE_MAX_TOTAL_IMAGE_BYTES,
    media_label: str = "Enhance image",
    snapshot_prefix: str = "maestro-enhance-",
) -> list[str]:
    """Copy exact admitted bytes to private worker-owned immutable paths."""
    import tempfile

    materialized: list[str] = []
    try:
        total_size = 0
        for expected in expected_seals:
            expected_size = expected.get("size")
            if type(expected_size) is not int or expected_size < 0:
                raise OSError("invalid Enhance image seal")
            if expected_size > max_file_bytes:
                raise HTTPException(
                    status_code=413,
                    detail=(
                        "Enhance image is too large (max 32 MB)"
                        if media_label == "Enhance image"
                        and max_file_bytes == _LLM_CHAT_MAX_IMAGE_BYTES
                        else f"{media_label} is too large"
                    ),
                )
            total_size += expected_size
            if total_size > max_total_bytes:
                raise HTTPException(
                    status_code=413,
                    detail=(
                        "Enhance images are too large (max 64 MB total)"
                        if media_label == "Enhance image"
                        and max_total_bytes == _LLM_ENHANCE_MAX_TOTAL_IMAGE_BYTES
                        else f"{media_label} selection is too large"
                    ),
                )
        for expected in expected_seals:
            if cancel_handle is not None:
                cancel_handle.checkpoint()
            source_path = str(expected.get("path") or "")
            source_descriptor = -1
            snapshot_descriptor = -1
            snapshot_path = ""
            try:
                source_descriptor = os.open(
                    source_path,
                    os.O_RDONLY
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_NONBLOCK", 0),
                )
                before = os.fstat(source_descriptor)
                expected_identity = (
                    expected.get("device"),
                    expected.get("inode"),
                    expected.get("size"),
                    expected.get("mtime_ns"),
                    expected.get("ctime_ns"),
                )
                observed_identity = (
                    before.st_dev,
                    before.st_ino,
                    before.st_size,
                    before.st_mtime_ns,
                    before.st_ctime_ns,
                )
                if (
                    observed_identity != expected_identity
                    or not stat.S_ISREG(before.st_mode)
                    or before.st_nlink != 1
                ):
                    raise OSError("Enhance image identity changed")
                suffix = os.path.splitext(source_path)[1].lower()
                snapshot_descriptor, snapshot_path = tempfile.mkstemp(
                    prefix=snapshot_prefix,
                    suffix=suffix,
                )
                digest = hashlib.sha256()
                remaining_bytes = before.st_size
                while remaining_bytes:
                    if cancel_handle is not None:
                        cancel_handle.checkpoint()
                    chunk = os.read(
                        source_descriptor,
                        min(1024 * 1024, remaining_bytes),
                    )
                    if not chunk:
                        raise OSError("Enhance image ended during snapshot")
                    digest.update(chunk)
                    remaining_bytes -= len(chunk)
                    remaining = memoryview(chunk)
                    while remaining:
                        written = os.write(snapshot_descriptor, remaining)
                        if written <= 0:
                            raise OSError("Enhance image snapshot write failed")
                        remaining = remaining[written:]
                if os.read(source_descriptor, 1):
                    raise OSError("Enhance image grew during snapshot")
                os.fsync(snapshot_descriptor)
                after = os.fstat(source_descriptor)
                current = os.stat(source_path, follow_symlinks=False)
                snapshot = os.fstat(snapshot_descriptor)
                os.lseek(snapshot_descriptor, 0, os.SEEK_SET)
                snapshot_digest = hashlib.sha256()
                while True:
                    if cancel_handle is not None:
                        cancel_handle.checkpoint()
                    chunk = os.read(snapshot_descriptor, 1024 * 1024)
                    if not chunk:
                        break
                    snapshot_digest.update(chunk)
                if (
                    observed_identity != (
                        after.st_dev,
                        after.st_ino,
                        after.st_size,
                        after.st_mtime_ns,
                        after.st_ctime_ns,
                    )
                    or observed_identity != (
                        current.st_dev,
                        current.st_ino,
                        current.st_size,
                        current.st_mtime_ns,
                        current.st_ctime_ns,
                    )
                    or digest.hexdigest() != expected.get("sha256")
                    or snapshot.st_size != expected.get("size")
                    or snapshot_digest.hexdigest() != expected.get("sha256")
                ):
                    raise OSError("Enhance image bytes changed")
                restrict_descriptor = getattr(os, "fchmod", None)
                if callable(restrict_descriptor):
                    restrict_descriptor(snapshot_descriptor, 0o400)
                else:
                    os.chmod(snapshot_path, 0o400)
                materialized.append(snapshot_path)
                snapshot_path = ""
            finally:
                if source_descriptor >= 0:
                    os.close(source_descriptor)
                if snapshot_descriptor >= 0:
                    os.close(snapshot_descriptor)
                if snapshot_path:
                    _remove_prompt_enhancement_snapshots([snapshot_path])
    except HTTPException:
        _remove_prompt_enhancement_snapshots(materialized)
        raise
    except (OSError, TypeError, ValueError):
        _remove_prompt_enhancement_snapshots(materialized)
        raise HTTPException(
            status_code=404, detail=f"{media_label} not found",
        ) from None
    except Exception:
        _remove_prompt_enhancement_snapshots(materialized)
        raise
    return materialized


def _prompt_enhancement_runtime_snapshot(
    request: Request,
    body: Mapping[str, Any],
    *,
    has_images: bool,
) -> dict[str, Any]:
    """Freeze server-owned Enhance routing before an async 202 is admitted."""
    from services import llm_service
    from services.llm_response_assist import response_assist_corpus_snapshot

    services = dict(wgp.server_config.get("services", {}) or {})
    model_type = str(body.get("model_type", "") or "")
    selection, raw_enhancer_mode = (
        _resolve_prompt_enhancer_runtime_selection(
            request,
            model_type,
            services,
            has_images=has_images,
        )
    )
    try:
        selection["vision_capable"] = bool(
            llm_service.get_model_capabilities(
                str(selection.get("model_id") or ""),
                local_gguf_path=str(
                    selection.get("local_gguf_path") or ""
                ),
                gguf_file_override=str(
                    selection.get("gguf_file_override") or ""
                ),
            ).get("vision_capable", True)
        )
    except Exception:
        selection["vision_capable"] = None
    return {
        "enhancer_enabled": int(
            wgp.server_config.get("enhancer_enabled", 0) or 0
        ),
        "explicit_provider": str(
            services.get("llm_provider") or "local"
        ).strip().lower(),
        "raw_enhancer_mode": raw_enhancer_mode,
        "selection": selection,
        "response_assist_snapshot": response_assist_corpus_snapshot(),
    }


class _ScopedPromptEnhancementRequest:
    """Detached request authority for one manager-owned Enhance worker."""

    @staticmethod
    def snapshot_authority(request: Request) -> dict[str, Any]:
        """Extract only bounded authority/origin facts needed by the worker."""
        source_headers = getattr(request, "headers", {}) or {}
        principal = getattr(
            request.state, "maestro_account_principal", None,
        )
        cpu_text_operation = str(getattr(
            request.state, "maestro_cpu_text_operation", "",
        ) or "")
        if cpu_text_operation not in _CPU_TEXT_OPERATIONS:
            cpu_text_operation = ""
        return {
            "headers": {
                name: str(source_headers.get(name) or "")
                for name in ("x-forwarded-proto", "x-forwarded-host")
                if source_headers.get(name)
            },
            "base_url": str(getattr(request, "base_url", "") or ""),
            "peer_host": str(
                getattr(getattr(request, "client", None), "host", "") or ""
            ),
            "session_id": str(getattr(
                request.state, "maestro_session_id", "",
            ) or ""),
            "remote": bool(getattr(
                request.state, "maestro_remote", False,
            )),
            "principal_id": (
                str(principal.get("id") or "")
                if isinstance(principal, dict) else ""
            ),
            "account_error": str(getattr(
                request.state, "maestro_account_error", "",
            ) or ""),
            "generation_preparation": bool(getattr(
                request.state, "maestro_generation_preparation", False,
            )),
            "cpu_text_operation": cpu_text_operation,
            "cpu_text_text_only": bool(getattr(
                request.state, "maestro_cpu_text_text_only", False,
            )),
        }

    def __init__(
        self,
        authority: Mapping[str, Any],
        body: dict,
        *,
        progress_callback,
        cancel_handle,
        project_instance_key: str,
        runtime_snapshot: dict,
        image_seals: list[dict[str, Any]],
        materialized_image_paths: list[str],
        canonical_job: dict | None = None,
        generation_slot_owned: bool = False,
    ) -> None:
        from types import SimpleNamespace

        self.headers = dict(authority.get("headers") or {})
        self.base_url = str(authority.get("base_url") or "")
        peer_host = str(authority.get("peer_host") or "")
        self.client = SimpleNamespace(host=peer_host) if peer_host else None
        self.method = "POST"
        self.url = SimpleNamespace(path="/api/v1/llm/enhance-prompt")
        principal_id = str(authority.get("principal_id") or "")
        bounded_principal = (
            {"id": principal_id}
            if principal_id
            else None
        )
        state = {
            "maestro_session_id": str(authority.get("session_id") or ""),
            "maestro_remote": bool(authority.get("remote", False)),
            "maestro_account_principal": bounded_principal,
            "maestro_account_error": str(authority.get("account_error") or ""),
            "maestro_llm_progress_callback": progress_callback,
            "maestro_llm_cancel_handle": cancel_handle,
            "maestro_llm_expected_project_instance": project_instance_key,
            "maestro_llm_enhance_runtime_snapshot": runtime_snapshot,
            "maestro_llm_enhance_image_seals": copy.deepcopy(image_seals),
            "maestro_llm_enhance_materialized_images": list(
                materialized_image_paths,
            ),
            "maestro_generation_preparation": bool(
                authority.get("generation_preparation", False)
            ),
            "maestro_cpu_text_operation": str(
                authority.get("cpu_text_operation") or ""
            ),
            "maestro_cpu_text_text_only": bool(
                authority.get("cpu_text_text_only", False)
            ),
            "maestro_cpu_text_job": canonical_job,
            "maestro_llm_generation_slot_owned": bool(
                generation_slot_owned
            ),
        }
        self.state = SimpleNamespace(**state)
        self._body = copy.deepcopy(body)

    async def json(self) -> dict:
        return copy.deepcopy(self._body)


def _prompt_enhancement_effective_digest(
    body: Mapping[str, Any],
    *,
    workspace: str,
    authorized_image_paths: list[str],
    image_seals: list[dict[str, Any]],
    runtime_snapshot: Mapping[str, Any],
) -> str:
    """Hash only exact effective inputs; never retain raw material in state."""
    response_assist_snapshot = runtime_snapshot.get("response_assist_snapshot")
    corpus_revision = getattr(response_assist_snapshot, "revision", 0)
    if isinstance(corpus_revision, bool) or not isinstance(corpus_revision, int):
        corpus_revision = 0
    payload = {
        key: value for key, value in body.items() if key != "request_id"
    }
    payload["workspace"] = workspace
    payload["image_paths"] = list(authorized_image_paths)
    payload.pop("image_path", None)
    selection = dict(runtime_snapshot.get("selection") or {})
    return _llm_route_effective_input_digest("enhance", {
        "request": payload,
        "image_content": [
            {
                "path": seal.get("path"),
                "size": seal.get("size"),
                "sha256": seal.get("sha256"),
            }
            for seal in image_seals
        ],
        "enhancer_enabled": runtime_snapshot.get("enhancer_enabled"),
        "explicit_provider": runtime_snapshot.get("explicit_provider"),
        "raw_enhancer_mode": runtime_snapshot.get("raw_enhancer_mode") is True,
        "selection_key": _llm_selection_key("enhance", selection),
        "response_assist_revision": corpus_revision,
    })


def _validate_standalone_enhanced_prompt_cardinality(
    body: Mapping[str, Any], model_type: str, result: Any,
) -> Any:
    """Require locked-timeline parity or exact standalone cardinality."""
    enhanced_text = (
        result.get("enhanced")
        if isinstance(result, Mapping) else result
    )
    if body.get("preserve_global_timeline") is True:
        source_timeline = str(body.get("prompt") or "")
        enhanced_timeline = str(enhanced_text or "")
        if not wgp.prompt_parser.has_global_timeline(source_timeline):
            return result
        _source_global, source_events = (
            wgp.prompt_parser.parse_global_timeline_prompt(source_timeline)
        )
        _enhanced_global, enhanced_events = (
            wgp.prompt_parser.parse_global_timeline_prompt(enhanced_timeline)
        )

        def timing_structure(events):
            return [
                (
                    str(event.get("kind") or ""),
                    float(event.get("start", 0.0)),
                    float(event.get("end", 0.0)),
                )
                for event in events
            ]

        if (
            source_events
            and timing_structure(enhanced_events)
                != timing_structure(source_events)
        ):
            raise ValueError(
                "Prompt enhancement changed a locked global timestamp; "
                "the original Studio timeline was preserved"
            )
        return result
    try:
        window_count = int(body.get("window_count") or 0)
    except (TypeError, ValueError):
        window_count = 0
    if (
        window_count <= 1
        or str(model_type or "").lower().startswith("minimax_h3")
        or str(body.get("mode") or "video") not in {"video", "avatar"}
    ):
        return result
    # A valid timeline is one structured type-2 prompt, not N type-1
    # paragraphs. Match integrated preparation's parser transition before
    # applying the paragraph-cardinality contract.
    if wgp.prompt_parser.has_global_timeline(str(enhanced_text or "")):
        return result
    wgp._validate_enhanced_prompt_cardinality(
        enhanced_text,
        {
            "version": _ENHANCED_PROMPT_CARDINALITY_VERSION,
            "projected_windows": window_count,
        },
        window_count,
    )
    return result


@api.post("/api/v1/llm/enhance-prompt")
async def llm_enhance_prompt(request: Request):
    """Enhance a generation prompt. Routes to Wan2GP enhancer or local LLM based on config."""
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="JSON object body is required")
    from services.llm_operations import run_blocking_shielded
    from services.llm_cancellation import LlmRequestCancelled
    _promote_external_llm_request(request)

    prompt = body.get("prompt", "")
    if not prompt:
        raise HTTPException(status_code=400, detail="prompt is required")

    workspace = _request_project_workspace(request, body.get("workspace"))
    if callable(globals().get("_existing_workspace_dir")):
        _require_project_access(
            request,
            workspace,
            existing_only=True,
            permission="project.generate",
        )
    else:
        # Isolated legacy callers compile only this route and supply their
        # established authorization stub. The loaded application always takes
        # the existing-only branch above.
        _require_project_access(
            request, workspace, permission="project.generate",
        )
    image_resolver = globals().get("_resolve_prompt_enhancement_images")
    if callable(image_resolver):
        authorized_image_paths = image_resolver(request, body, workspace)
    else:
        # Compatibility for isolated legacy callers that compile this route
        # without module helpers. Production always uses the bounded resolver.
        requested_images = body.get("image_paths")
        if requested_images in (None, []):
            image_path = body.get("image_path")
            requested_images = [image_path] if image_path else []
        if not isinstance(requested_images, list) or len(requested_images) > 4:
            raise HTTPException(status_code=400, detail="Invalid Enhance image list")
        authorized_image_paths = []
        for image_path in requested_images:
            resolved = _resolve_authorized_request_media(
                request, image_path, workspace,
            )
            if resolved is None:
                raise HTTPException(
                    status_code=404, detail="Enhance image not found",
                )
            authorized_image_paths.append(resolved)

    cancel_handle = getattr(
        request.state, "maestro_llm_cancel_handle", None,
    )
    if cancel_handle is not None:
        cancel_handle.checkpoint()
    progress_resolver = globals().get("_llm_route_progress_callback")
    progress_callback = (
        progress_resolver(request) if callable(progress_resolver) else None
    )
    progress_emitter = globals().get("_emit_llm_progress")

    def report_progress(event: dict) -> None:
        if callable(progress_emitter):
            progress_emitter(progress_callback, event)

    raw_request_id = body.get("request_id")
    expected_image_seals = getattr(
        request.state, "maestro_llm_enhance_image_seals", None,
    )
    if expected_image_seals is not None:
        await run_blocking_shielded(
            _revalidate_prompt_enhancement_images,
            authorized_image_paths,
            expected_image_seals,
            cancel_handle,
        )
    materialized_image_paths = getattr(
        request.state, "maestro_llm_enhance_materialized_images", None,
    )
    if materialized_image_paths is not None:
        if (
            not isinstance(materialized_image_paths, list)
            or len(materialized_image_paths) != len(authorized_image_paths)
            or not all(
                isinstance(path, str) and path
                for path in materialized_image_paths
            )
        ):
            raise LlmRequestCancelled("LLM request images changed")
        authorized_image_paths = list(materialized_image_paths)

    # Internal callers without a recoverable request UUID retain their
    # synchronous response contract, but image bytes still cross the same
    # capped seal/private-snapshot boundary as manager-owned operations.
    if (
        raw_request_id is None
        and authorized_image_paths
        and expected_image_seals is None
        and materialized_image_paths is None
    ):
        image_seals = await run_blocking_shielded(
            _seal_prompt_enhancement_images,
            authorized_image_paths,
            cancel_handle,
        )
        runtime_snapshot = _prompt_enhancement_runtime_snapshot(
            request, body, has_images=True,
        )
        _owner_key, project_instance_key = _llm_operation_scope(
            request, workspace,
        )
        materialized_images = await run_blocking_shielded(
            _materialize_prompt_enhancement_images,
            image_seals,
            cancel_handle,
        )
        try:
            detached_request = _ScopedPromptEnhancementRequest(
                _ScopedPromptEnhancementRequest.snapshot_authority(request),
                body,
                progress_callback=progress_callback,
                cancel_handle=cancel_handle,
                project_instance_key=project_instance_key,
                runtime_snapshot=runtime_snapshot,
                image_seals=image_seals,
                materialized_image_paths=materialized_images,
            )
            return await llm_enhance_prompt(detached_request)
        finally:
            _remove_prompt_enhancement_snapshots(materialized_images)

    expected_project_instance = str(getattr(
        request.state, "maestro_llm_expected_project_instance", "",
    ) or "")
    if expected_project_instance:
        _worker_owner, current_project_instance = _llm_operation_scope(
            request, workspace,
        )
        if not hmac.compare_digest(
            expected_project_instance, current_project_instance,
        ):
            raise LlmRequestCancelled("LLM request project changed")

    if raw_request_id is not None:
        from services.llm_operations import (
            LlmRouteAdmissionError,
        )

        try:
            request_id = _normalize_llm_route_request_id(raw_request_id)
            expected_project_instance = body.get("project_instance")
            if (
                not isinstance(expected_project_instance, str)
                or len(expected_project_instance) != 64
                or expected_project_instance != expected_project_instance.lower()
                or bytes.fromhex(expected_project_instance).hex()
                    != expected_project_instance
            ):
                raise ValueError("project_instance must be canonical")
            account_key, project_instance_key, session_key = (
                _prompt_enhancement_operation_scope(
                    request, workspace,
                )
            )
            if not hmac.compare_digest(
                expected_project_instance, project_instance_key,
            ):
                raise HTTPException(
                    status_code=409,
                    detail="Prompt Enhance request does not match",
                )
            image_seals = await run_blocking_shielded(
                _seal_prompt_enhancement_images,
                authorized_image_paths,
                cancel_handle,
            )
            runtime_snapshot = _prompt_enhancement_runtime_snapshot(
                request, body, has_images=bool(authorized_image_paths),
            )
            effective_input_digest = _prompt_enhancement_effective_digest(
                body,
                workspace=workspace,
                authorized_image_paths=authorized_image_paths,
                image_seals=image_seals,
                runtime_snapshot=runtime_snapshot,
            )
        except ValueError as error:
            raise HTTPException(
                status_code=400,
                detail="Invalid Prompt Enhance operation request",
            ) from error
        worker_body = {
            key: copy.deepcopy(value)
            for key, value in body.items()
            if key not in {"request_id", "project_instance"}
        }
        detached_authority = (
            _ScopedPromptEnhancementRequest.snapshot_authority(request)
        )

        async def execute(
            progress_callback,
            operation_cancellation,
            execution_context=None,
        ):
            materialized_images = await run_blocking_shielded(
                _materialize_prompt_enhancement_images,
                image_seals,
                operation_cancellation,
            )
            try:
                detached_request = _ScopedPromptEnhancementRequest(
                    detached_authority,
                    worker_body,
                    progress_callback=progress_callback,
                    cancel_handle=operation_cancellation,
                    project_instance_key=project_instance_key,
                    runtime_snapshot=runtime_snapshot,
                    image_seals=image_seals,
                    materialized_image_paths=materialized_images,
                    canonical_job=(
                        execution_context.get("job")
                        if isinstance(execution_context, Mapping) else None
                    ),
                    generation_slot_owned=bool(
                        isinstance(execution_context, Mapping)
                        and execution_context.get("generation_slot_owned")
                    ),
                )
                return await llm_enhance_prompt(detached_request)
            finally:
                _remove_prompt_enhancement_snapshots(materialized_images)

        try:
            status = _prompt_enhancement_operation_manager.submit(
                request_id=request_id,
                account_key=account_key,
                project_instance_key=project_instance_key,
                session_key=session_key,
                request_digest=effective_input_digest,
                execute=execute,
                job_context={
                    "workspace": workspace,
                    "out_dir": (
                        globals()["_existing_workspace_dir"](workspace)
                        if callable(globals().get("_existing_workspace_dir"))
                        else workspace
                    ),
                    "session_id": str(getattr(
                        request.state, "maestro_session_id", "",
                    ) or ""),
                    "source_remote": bool(getattr(
                        request.state, "maestro_remote", False,
                    )),
                    "generation_mode": str(body.get("mode") or ""),
                    "private": bool(body.get("private_output", False)),
                    "explicit": bool(body.get("explicit_output", False)),
                    "body": worker_body,
                },
            )
        except PromptEnhancementRecoveryConflictError as error:
            raise HTTPException(
                status_code=409, detail="Prompt Enhance request does not match",
            ) from error
        except LlmRouteAdmissionError as error:
            raise HTTPException(
                status_code=429,
                detail="Prompt Enhance is busy; retry shortly",
            ) from error
        except PromptEnhancementRecoveryCapacityError as error:
            raise HTTPException(
                status_code=503,
                detail="Prompt Enhance recovery is busy",
            ) from error
        except PromptEnhancementRecoveryError as error:
            raise HTTPException(
                status_code=503,
                detail="Prompt Enhance recovery is unavailable",
            ) from error
        if status is None:
            raise HTTPException(status_code=404, detail="LLM operation not found")
        return JSONResponse(status, status_code=202)

    model_type = str(body.get("model_type", "") or "")
    generation_mode = str(body.get("mode", "video") or "video")
    needs_h3_context_ir = (
        model_type.lower().startswith("minimax_h3")
        and generation_mode in ("video", "avatar")
    )
    runtime_snapshot = getattr(
        request.state, "maestro_llm_enhance_runtime_snapshot", None,
    )
    enhancer_enabled = int(
        runtime_snapshot.get("enhancer_enabled", 0)
        if isinstance(runtime_snapshot, dict)
        else wgp.server_config.get("enhancer_enabled", 0) or 0
    )
    explicit_guidance = _explicit_llm_guidance_allowed(body)
    explicit_provider = ""
    durable_generation_preparation = bool(
        getattr(request.state, "maestro_generation_preparation", False)
    )
    try:
        standalone_window_count = int(body.get("window_count") or 0)
    except (TypeError, ValueError):
        standalone_window_count = 0
    requires_standalone_cardinality = (
        not durable_generation_preparation
        and not needs_h3_context_ir
        and generation_mode in {"video", "avatar"}
        and body.get("preserve_global_timeline") is not True
        and standalone_window_count > 1
    )
    requires_standalone_postcondition = (
        not durable_generation_preparation
        and (
            requires_standalone_cardinality
            or body.get("preserve_global_timeline") is True
        )
    )
    h3_style_workflow_present = bool(
        durable_generation_preparation
        and body.get("h3_style_workflow_present") is True
    )
    if explicit_guidance:
        explicit_provider = str(
            runtime_snapshot.get("explicit_provider")
            if isinstance(runtime_snapshot, dict)
            else wgp.server_config.get("services", {}).get("llm_provider")
            or "local"
        ).strip().lower()

    # The generic Wan2GP cinematic enhancer cannot produce MiniMax H3's
    # required Context-IR fields, speaker IDs, or <d> dialogue tags. Route H3
    # through Maestro's model-specific guide even when the legacy enhancer is
    # enabled; all other model families retain the configured behavior.
    if (
        enhancer_enabled > 0
        and not needs_h3_context_ir
        and not explicit_guidance
        and not durable_generation_preparation
    ):
        try:
            report_progress({
                "phase": "loading",
                "stage": "wangp",
                "pass": 1,
                "pass_limit": 2,
            })
            # Support both single image_path and array image_paths
            wangp_result = await _enhance_with_wangp(
                prompt,
                generation_mode,
                enhancer_enabled,
                image_paths=authorized_image_paths,
                cancel_handle=cancel_handle,
            )
            if requires_standalone_postcondition:
                return _validate_standalone_enhanced_prompt_cardinality(
                    body, model_type, wangp_result,
                )
            return wangp_result
        except LlmRequestCancelled:
            # An explicit cancel is terminal. It must never begin the LLM
            # fallback merely because WanGP surfaced the cancellation.
            raise
        except Exception as e:
            print(f"[Enhance] Wan2GP enhancer failed, falling back to LLM: {e}")
            report_progress({
                "phase": "retrying",
                "stage": "llm_fallback",
                "pass": 2,
                "pass_limit": 2,
            })
            # Fall through to LLM
    elif enhancer_enabled > 0 and needs_h3_context_ir:
        print("[Enhance] MiniMax H3 requires structured Context-IR; using Maestro's model-specific LLM guide")
    elif enhancer_enabled > 0 and explicit_guidance:
        print(
            "[Enhance] Explicit request requires server-owned authoring "
            "guidance; bypassing the generic Wan2GP enhancer"
        )
    elif enhancer_enabled > 0 and durable_generation_preparation:
        print(
            "[Enhance] Durable generation preparation uses the serialized "
            "local LLM lane"
        )
    if (
        enhancer_enabled <= 0
        or needs_h3_context_ir
        or explicit_guidance
        or durable_generation_preparation
    ):
        report_progress({
            "phase": "loading",
            "stage": "llm",
            "pass": 1,
            "pass_limit": 1,
        })

    # Use our local LLM service
    from services import llm_service

    services = wgp.server_config.get("services", {})

    # Per-model dedicated prompt enhancer: when the active gen model declares
    # `prompt_enhancer_model` (e.g. Sulphur ships its own uncensored enhancer
    # LLM), it takes precedence and runs in raw-passthrough mode — the user's
    # prompt (+ optional image) is sent with NO guide/system prompt because the
    # model is trained to enhance directly. Ordinary calls stay raw; the LLM
    # service supplies server-owned guidance only when explicit_guidance is
    # true, so selecting an nsfw_only model alone cannot activate it.
    if isinstance(runtime_snapshot, dict):
        selection = copy.deepcopy(runtime_snapshot.get("selection") or {})
        enhance_model = str(selection.get("model_id") or "")
        enhance_device = str(selection.get("device") or "cuda")
        raw_enhancer_mode = bool(
            runtime_snapshot.get("raw_enhancer_mode") is True
        )
    else:
        runtime_resolver = globals().get(
            "_resolve_prompt_enhancer_runtime_selection",
        )
        if callable(runtime_resolver):
            selection, raw_enhancer_mode = runtime_resolver(
                request,
                model_type,
                services,
                has_images=bool(authorized_image_paths),
            )
        else:
            # Retain isolated legacy caller compatibility; the loaded module
            # always uses the strict catalog/provider resolver above.
            enhance_model, enhance_device, raw_enhancer_mode = (
                _resolve_prompt_enhancer_selection(
                    model_type,
                    services,
                    has_images=bool(authorized_image_paths),
                    model_registry=llm_service.MODEL_REGISTRY,
                )
            )
            selection = {
                "model_id": enhance_model,
                "device": enhance_device,
                "provider": "local",
                "remote_url": "",
                "api_key": "",
                "local_gguf_path": "",
                "gguf_file_override": "",
            }
        enhance_model = str(selection.get("model_id") or "")
        enhance_device = str(selection.get("device") or "cuda")
        try:
            selection["vision_capable"] = bool(
                llm_service.get_model_capabilities(
                    str(selection.get("model_id") or ""),
                    local_gguf_path=str(
                        selection.get("local_gguf_path") or ""
                    ),
                    gguf_file_override=str(
                        selection.get("gguf_file_override") or ""
                    ),
                ).get("vision_capable", True)
            )
        except Exception:
            # Capability is a server stamp, not a caller hint. Unknown must
            # remain serialized instead of risking multimodal RAM.
            selection["vision_capable"] = None
    if raw_enhancer_mode:
        print(
            f"[Enhance] Per-model enhancer for {model_type}: "
            f"{enhance_model} (raw passthrough)"
        )
    if not getattr(request.state, "maestro_cpu_text_operation", None):
        request.state.maestro_cpu_text_operation = "prompt_enhancement"
    request.state.maestro_cpu_text_text_only = bool(
        not authorized_image_paths and not needs_h3_context_ir
    )

    # Collect image paths for vision-enabled LLM
    llm_image_paths = authorized_image_paths

    # Load LoRA info for activated LoRAs — extract ONLY trigger words and key tips
    lora_hint_text = ""
    activated_loras = body.get("activated_loras") or []
    print(
        "[Enhance] LoRA context: "
        f"count={len(activated_loras)}, model_selected={bool(model_type)}"
    )
    if activated_loras and model_type:
        try:
            lora_dir = wgp.get_lora_dir(model_type)
            # Only inject trigger words from the CivitAI sidecar's
            # trainedWords field. Do NOT extract triggers from guide prose —
            # guide descriptions like "include the trigger phrase 'Unchained'"
            # are instructions for the user, not actual trained tokens, and
            # injecting them causes the LLM to insert them as broken tags.
            trigger_lines = []
            for lora_name in activated_loras:
                sidecar_path = os.path.join(lora_dir, os.path.splitext(lora_name)[0] + ".civitai.json")
                trigger_words = []
                if os.path.isfile(sidecar_path):
                    try:
                        with open(sidecar_path, "r", encoding="utf-8") as sf:
                            sidecar = json.loads(sf.read())
                        trigger_words = sidecar.get("trainedWords", []) or []
                    except Exception:
                        pass

                if trigger_words:
                    trigger_lines.append(f"- {', '.join(trigger_words[:5])}")

            if trigger_lines:
                any_leet = any(any(c.isdigit() for c in ln) for ln in trigger_lines)
                leet_block = (
                    " Some trigger words are coded tokens with letters replaced by "
                    "numbers (e.g. 'o'→'0', 'i'→'1', 's'→'5', 'e'→'3', 'a'→'4'). "
                    "If you see one with digits, copy it EXACTLY as written — do "
                    "not decode it into plain English."
                ) if any_leet else ""
                lora_hint_text = (
                    "\n\n[LORA TRIGGER WORDS — these are exact tokens the model was "
                    "trained on. Pick the ONE most relevant trigger and include it "
                    "somewhere in the prompt IF AND ONLY IF it forms a natural, "
                    "grammatical part of a sentence. If you cannot weave it in "
                    "naturally, OMIT IT ENTIRELY.\n\n"
                    "FORBIDDEN INSERTION PATTERNS (any of these ruins the prompt):\n"
                    "- At the start as a standalone tag:  'Unchained, the doctor...'\n"
                    "- As a comma-offset appositive:      'the doctor, Unchained, in white...'\n"
                    "- As a parenthetical:                'the doctor (Unchained) in white...'\n"
                    "- As a standalone label anywhere:    '...in the exam room. Unchained. She...'\n"
                    "- Attached to an unrelated character: 'the doctor, Mystic XXX, leans...'\n\n"
                    "ACCEPTABLE INSERTIONS only if grammatically natural:\n"
                    "- Body/appearance descriptor trigger ('detailed muscle definition'): "
                    "scoped to the right character inside a sentence — "
                    "'the man with detailed muscle definition lifts the crate...'\n"
                    "- Style tag trigger ('Mystic XXX', 'Unchained'): use only when the "
                    "trigger names a genre or action the scene actually depicts. If it "
                    "does not fit grammatically, OMIT IT. Do not force it in.\n\n"
                    "Do NOT invent variants. Do NOT include a trigger that does not "
                    "match the scene." + leet_block + "]\n"
                ) + "\n".join(trigger_lines)
                print(
                    f"[Enhance] Loaded {len(trigger_lines)} private LoRA "
                    "trigger block(s)"
                )
            else:
                print(f"[Enhance] No LoRA triggers extractable from {len(activated_loras)} LoRA(s)")
        except Exception as e:
            print(f"[Enhance] LoRA hint loading failed: {e}")

    try:
        def run_enhancement():
            if cancel_handle is not None:
                cancel_handle.checkpoint()
            # Revalidate after the exact model lease finishes cold loading and
            # immediately before content reaches the provider.
            if explicit_guidance:
                current_provider = str(
                    wgp.server_config.get("services", {}).get("llm_provider")
                    or "local"
                ).strip().lower()
                if (
                    not _explicit_llm_guidance_allowed(body)
                    or current_provider != explicit_provider
                ):
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "LLM provider settings changed while the explicit "
                            "prompt enhancer was preparing. Retry after settings "
                            "stabilize."
                        ),
                    )
            if isinstance(runtime_snapshot, dict):
                response_assist = _resolved_local_response_assist(
                    body,
                    selection,
                    corpus_snapshot=runtime_snapshot.get(
                        "response_assist_snapshot",
                    ),
                )
            else:
                response_assist = _resolved_local_response_assist(
                    body, selection,
                )
            return llm_service.enhance_prompt(
                prompt=prompt,
                lora_system_hint=lora_hint_text,
                mode=body.get("mode", "video"),
                max_new_tokens=body.get("max_new_tokens", 512),
                temperature=body.get("temperature", 0.6),
                nsfw=explicit_guidance,
                model_type=model_type,
                image_paths=llm_image_paths if llm_image_paths else None,
                duration_seconds=body.get("duration_seconds"),
                window_count=body.get("window_count"),
                window_size_seconds=body.get("window_size_seconds"),
                preserve_global_timeline=bool(body.get("preserve_global_timeline")),
                visual_style=body.get("visual_style"),
                h3_style_workflow_present=h3_style_workflow_present,
                tts_enhance_mode=body.get("tts_enhance_mode"),
                tts_voice_count=body.get("tts_voice_count", 2),
                raw_enhancer_mode=raw_enhancer_mode,
                response_assist=response_assist,
                progress_callback=progress_callback,
                cancel_handle=cancel_handle,
            )

        # Pass LoRA hints as system-level context so the LLM treats them as instructions,
        # not content to parrot. The hints go via lora_system_hint into the system prompt.
        result = await run_blocking_shielded(
            _run_authorized_llm_with_selection,
            request,
            selection,
            run_enhancement,
        )
        if requires_standalone_postcondition:
            try:
                result = _validate_standalone_enhanced_prompt_cardinality(
                    body, model_type, result,
                )
            except ValueError:
                raise HTTPException(
                    status_code=422,
                    detail="Prompt enhancement did not match the requested structure",
                ) from None
        return {"original": prompt, "enhanced": result}
    except LlmRequestCancelled:
        raise
    except HTTPException:
        raise
    except Exception as error:
        print(
            "[Enhance] Prompt enhancement failed "
            f"({type(error).__name__})"
        )
        raise HTTPException(
            status_code=500,
            detail="Prompt enhancement failed; check the local Maestro logs",
        ) from error


async def _enhance_with_wangp(
    prompt: str,
    mode: str,
    enhancer_enabled: int,
    image_paths: list = None,
    cancel_handle=None,
):
    """Run the Wan2GP prompt enhancer using wgp's built-in offload system."""
    from services.llm_operations import run_blocking_shielded
    return await run_blocking_shielded(
        _enhance_with_wangp_sync,
        prompt,
        mode,
        enhancer_enabled,
        image_paths,
        cancel_handle,
    )


def _enhance_with_wangp_sync(
    prompt: str,
    mode: str,
    enhancer_enabled: int,
    image_paths: list = None,
    cancel_handle=None,
):
    """Blocking Wan2GP enhancer implementation, isolated from the API loop."""
    import secrets
    from PIL import Image
    from shared.prompt_enhancer.prompt_enhance_utils import generate_cinematic_prompt
    from mmgp import offload

    acquired = False
    acquired_native_gpu = False
    acquired_prompt_enhancer = False
    loaded_images = []
    try:
        while not acquired:
            if cancel_handle is not None:
                cancel_handle.checkpoint()
            acquired = _gen_lock.acquire(timeout=0.05)
        if cancel_handle is not None:
            cancel_handle.checkpoint()

        wgp.acquire_native_gpu_execution_lock(
            cancel_handle.checkpoint if cancel_handle is not None else None
        )
        acquired_native_gpu = True

        wgp.acquire_prompt_enhancer_lock(
            cancel_handle.checkpoint if cancel_handle is not None else None
        )
        acquired_prompt_enhancer = True

        # Setup and inference mutate process-global WanGP/offload state. The
        # generation lock excludes ordinary generation; wgp's enhancer lock
        # also excludes Classic's native Enhance button.
        if wgp.enhancer_offloadobj is None:
            print(f"[Enhance] Loading Wan2GP enhancer (mode {enhancer_enabled}) with GPU offload...")
            pipe = {}
            kwargs = {}
            wgp.download_models()
            if cancel_handle is not None:
                cancel_handle.checkpoint()
            wgp.setup_prompt_enhancer(pipe, kwargs)
            profile = wgp.compute_profile(-1, "video")
            mmgp_profile = wgp.init_pipe(pipe, kwargs, profile)
            wgp.enhancer_offloadobj = offload.profile(
                pipe, profile_no=mmgp_profile, **kwargs,
            )

        if wgp.prompt_enhancer_llm_model is None:
            raise RuntimeError("Prompt enhancer model failed to load")

        is_video = mode in ("video", "avatar")
        temperature = wgp.server_config.get("prompt_enhancer_temperature", 0.6)
        top_p = wgp.server_config.get("prompt_enhancer_top_p", 0.9)
        seed = secrets.randbits(32) if wgp.server_config.get("prompt_enhancer_randomize_seed", True) else 0

        prompt_images = None
        if image_paths:
            for img_path in image_paths:
                if cancel_handle is not None:
                    cancel_handle.checkpoint()
                if not img_path or not os.path.isfile(img_path):
                    raise RuntimeError(
                        "An authorized enhancement image is unavailable"
                    )
                loaded_image = None
                try:
                    loaded_image = Image.open(img_path)
                    loaded_image.load()
                except Exception:
                    if loaded_image is not None:
                        try:
                            loaded_image.close()
                        except Exception:
                            pass
                    raise RuntimeError(
                        "An authorized enhancement image could not be decoded"
                    ) from None
                loaded_images.append(loaded_image)
                print(f"[Enhance] Including image: {os.path.basename(img_path)}")
            prompt_images = loaded_images

        post_image_caption_hook = None
        if prompt_images and wgp.enhancer_offloadobj is not None:
            if hasattr(wgp.prompt_enhancer_image_caption_model, "vision_tower_model") and hasattr(wgp.prompt_enhancer_llm_model, "generate_messages"):
                post_image_caption_hook = wgp.enhancer_offloadobj.unload_all

        if cancel_handle is not None:
            cancel_handle.checkpoint()
        result = generate_cinematic_prompt(
            wgp.prompt_enhancer_image_caption_model,
            wgp.prompt_enhancer_image_caption_processor,
            wgp.prompt_enhancer_llm_model,
            wgp.prompt_enhancer_llm_tokenizer,
            [prompt],
            prompt_images,
            video_prompt=is_video,
            text_prompt=False,
            max_new_tokens=512,
            do_sample=True,
            temperature=temperature,
            top_p=top_p,
            seed=seed,
            post_image_caption_hook=post_image_caption_hook,
        )
        if cancel_handle is not None:
            cancel_handle.checkpoint()

        enhanced = result[0] if isinstance(result, list) and result else (result or prompt)
        print(f"[Enhance] Wan2GP enhanced: {len(enhanced)} chars")
        return {"original": prompt, "enhanced": enhanced}
    finally:
        for image in loaded_images:
            try:
                image.close()
            except Exception:
                pass
        if acquired_prompt_enhancer:
            try:
                if wgp.enhancer_offloadobj is not None:
                    wgp.enhancer_offloadobj.unload_all()
            except Exception as error:
                print(
                    "[Enhance] Wan2GP cleanup failed "
                    f"({type(error).__name__})"
                )
            finally:
                wgp.prompt_enhancer_lock.release()
        if acquired_native_gpu:
            wgp.native_gpu_execution_lock.release()
        if acquired:
            _gen_lock.release()


@api.post("/api/v1/llm/describe-image")
async def llm_describe_image(request: Request):
    """Describe an uploaded image using the LLM."""
    from services import llm_service
    from services.llm_operations import run_blocking_shielded
    body = await request.json()
    _promote_external_llm_request(request)

    image_path = body.get("image_path", "")
    if not image_path:
        raise HTTPException(status_code=400, detail="image_path is required")
    workspace = _request_project_workspace(request, body.get("workspace"))
    _require_project_access(
        request, workspace, permission="project.generate",
    )
    image_path = _resolve_authorized_request_media(
        request,
        image_path,
        workspace,
    )
    if not image_path:
        raise HTTPException(status_code=404, detail="Image not found")

    try:
        selection = await run_blocking_shielded(
            _resolve_vision_llm_selection,
        )

        def run_description():
            return llm_service.describe_image(
                image_path=image_path,
                image_paths=[image_path],
                prompt=body.get("prompt", "Describe this image in detail."),
                max_new_tokens=body.get("max_new_tokens", 256),
                response_assist=_resolved_local_response_assist(
                    body, selection,
                ),
                progress_callback=_llm_route_progress_callback(request),
            )

        result = await run_blocking_shielded(
            _run_authorized_llm_with_selection,
            request,
            selection,
            run_description,
        )
        return {"description": result}
    except Exception as error:
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail="Image description failed; check the local Maestro logs",
        ) from error


# ============================================================================
# API Routes: Audio Analysis
# ============================================================================

def _probe_audio_duration(filepath: str) -> float | None:
    """Return only the duration scalar; never expose container metadata."""
    try:
        import soundfile as sf

        info = sf.info(filepath)
        if info.samplerate and info.frames:
            return round(float(info.frames) / float(info.samplerate), 3)
    except Exception:
        pass
    return None


@api.post("/api/v1/upload-audio")
async def upload_audio(
    request: Request,
    file: UploadFile = File(...),
    private: bool = True,
):
    """Upload an audio file (wav, mp3, flac, ogg, m4a) OR a video file
    (mp4, mov, mkv, webm, avi, m4v) for audio extraction. Video files
    are transparently demuxed to a 16-bit PCM WAV containing only the
    audio track; the source video is deleted afterwards. The response
    shape is identical regardless of input format — callers always
    receive a WAV path."""
    _require_upload_content_access(request)
    from services.audio_upload_validation import (
        AudioUploadStorageError,
        WavUploadValidationError,
        record_pending_audio_cleanup,
        retry_pending_audio_cleanup,
        validate_wav_upload,
        write_regular_upload,
    )
    from services.output_access import upload_access_sidecar_path
    from services.win_safe_files import safe_delete

    AUDIO_EXTENSIONS = {".wav", ".mp3", ".flac", ".ogg", ".m4a", ".aac"}
    VIDEO_EXTENSIONS = {".mp4", ".mov", ".mkv", ".webm", ".avi", ".m4v"}
    ALLOWED_EXTENSIONS = AUDIO_EXTENSIONS | VIDEO_EXTENSIONS

    def cleanup_upload_artifacts(stamp_private_upload, *paths):
        pending = []
        for path in paths:
            if not path:
                continue
            for candidate in (upload_access_sidecar_path(path), path):
                result = safe_delete(candidate, retries=1)
                if (
                    not result.get("deleted")
                    and result.get("reason") != "not_found"
                ):
                    pending.append(candidate)
        if not pending:
            return True
        # A persistently locked media file remains fail-closed and private
        # while its content-free cleanup marker survives process restart.
        for path in paths:
            if not path or not os.path.isfile(path):
                continue
            try:
                stamp_private_upload(
                    path,
                    request.state.maestro_session_id,
                    private=True,
                )
                sidecar = upload_access_sidecar_path(path)
                if os.path.isfile(sidecar):
                    pending.append(sidecar)
            except Exception:
                pass
        try:
            record_pending_audio_cleanup(upload_dir, tuple(set(pending)))
        except AudioUploadStorageError:
            return False
        return False

    ext = os.path.splitext(file.filename or "audio.wav")[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Unsupported format: {ext}. Allowed audio: "
                f"{', '.join(sorted(AUDIO_EXTENSIONS))}. "
                f"Allowed video (audio will be extracted): "
                f"{', '.join(sorted(VIDEO_EXTENSIONS))}."
            ),
        )

    # Pre-check via Content-Length to reject obviously-too-large uploads
    # before we read them into memory. The post-read length check below
    # is the authoritative one since Content-Length can be spoofed.
    cl = request.headers.get("content-length")
    if cl and cl.isdigit() and int(cl) > MAX_AUDIO_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="File too large (max 500 MB)")

    content = await file.read(MAX_AUDIO_UPLOAD_BYTES + 1)
    if len(content) > MAX_AUDIO_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="File too large (max 500 MB)")

    # A .wav extension is only a claim.  Parse the bounded RIFF container
    # before creating a directory, path, file, access sidecar, job, or model.
    # The validator is content-neutral: it inspects structural audio metadata
    # only, and an empty/missing MIME declaration does not affect admission.
    validated_wav = None
    if ext == ".wav":
        try:
            validated_wav = validate_wav_upload(
                content,
                max_bytes=MAX_AUDIO_UPLOAD_BYTES,
            )
        except WavUploadValidationError as error:
            raise HTTPException(
                status_code=400,
                detail=error.public_message,
            ) from None

    upload_dir = os.path.join(os.getcwd(), "uploads", "audio")
    retry_pending_audio_cleanup(upload_dir, safe_delete)
    unique_name = f"{uuid.uuid4().hex[:8]}{ext}"
    try:
        filepath = write_regular_upload(upload_dir, unique_name, content)
    except AudioUploadStorageError:
        raise HTTPException(
            status_code=500,
            detail="Audio upload could not be stored.",
        ) from None

    # libsndfile (soundfile) supports wav/flac/ogg natively but NOT the
    # compressed formats users commonly have (mp3, m4a, aac). Downstream code
    # like wgp.slice_audio_window calls sf.SoundFile() directly which raises
    # LibsndfileError: Format not recognised. Transcode those to 16-bit PCM
    # wav here so the rest of the pipeline stays format-agnostic. Video
    # files take the same path with audio-only extraction (no -vn flag
    # needed because the .wav output container can't hold video — ffmpeg
    # naturally drops the video stream — but we pass `vn=None` to be
    # explicit and avoid bitstream-copy attempts on rare containers).
    is_video = ext in VIDEO_EXTENSIONS
    needs_transcode = ext in (".mp3", ".m4a", ".aac") or is_video
    if needs_transcode:
        wav_name = f"{uuid.uuid4().hex[:8]}.wav"
        wav_path = None
        source_original = filepath
        transcode_ok = False
        try:
            import ffmpeg as _ffmpeg
            # Reserve the final basename exclusively before handing it to
            # ffmpeg.  Its overwrite flag can now replace only this request's
            # empty placeholder, never another session's upload.
            wav_path = write_regular_upload(upload_dir, wav_name, b"")
            output_kwargs = {"acodec": "pcm_s16le"}
            if is_video:
                # `-vn`: explicitly drop video stream. The .wav container
                # doesn't support video so ffmpeg would drop it anyway,
                # but being explicit avoids edge cases where the encoder
                # tries to copy an unsupported video bitstream.
                output_kwargs["vn"] = None
            (
                _ffmpeg
                .input(filepath)
                .output(wav_path, **output_kwargs)
                .overwrite_output()
                .run(quiet=True)
            )
            source_delete = safe_delete(source_original)
            if not source_delete.get("deleted") and source_delete.get(
                "reason"
            ) != "not_found":
                raise OSError("uploaded source could not be retired")
            transcode_ok = True
            filepath = wav_path
            unique_name = wav_name
            if is_video:
                print(
                    "[upload-audio] Extracted an audio track from the "
                    "uploaded video; the source video was deleted."
                )
        except _ffmpeg.Error:
            raise HTTPException(
                status_code=400,
                detail="Uploaded media could not be decoded as audio.",
            ) from None
        except Exception:
            raise HTTPException(
                status_code=500,
                detail="Audio upload could not be processed.",
            ) from None
        finally:
            # If transcode/extract bombed (either branch above raised),
            # clean up the partial wav AND the original upload so orphans
            # don't pile up in uploads/audio/ on repeated failures.
            if not transcode_ok:
                cleanup_upload_artifacts(
                    write_upload_access_sidecar,
                    wav_path,
                    source_original,
                )

    # Uploaded audio is source/input media, not a publishable output. Keep it
    # private for local and remote callers even if an older client explicitly
    # supplies private=false; generated outputs have their own policy path.
    private = True
    try:
        access = write_upload_access_sidecar(
            filepath,
            request.state.maestro_session_id,
            private=private,
        )
        output_policy = public_output_policy(access)
    except Exception:
        cleanup_upload_artifacts(write_upload_access_sidecar, filepath)
        raise HTTPException(
            status_code=500,
            detail="Audio upload could not be published.",
        ) from None
    return {
        "filename": unique_name,
        "path": (
            unique_name
            if bool(getattr(request.state, "maestro_remote", False))
            else filepath
        ),
        "url": f"/api/v1/uploads/audio/{unique_name}",
        "duration_seconds": (
            validated_wav.duration_seconds
            if validated_wav is not None
            else _probe_audio_duration(filepath)
        ),
        **output_policy,
    }


@api.get("/api/v1/uploads/audio/{filename}")
def serve_audio_upload(request: Request, filename: str):
    """Serve an uploaded audio file."""
    from services.win_safe_files import (
        safe_direct_file_under,
        share_delete_file_response,
    )
    base = os.path.join(os.getcwd(), "uploads", "audio")
    filepath = safe_direct_file_under(base, filename)
    if filepath is None or not os.path.isfile(filepath):
        raise HTTPException(status_code=404, detail="File not found")
    resolved = _resolve_authorized_request_media(request, filepath)
    if resolved != filepath:
        raise HTTPException(status_code=404, detail="File not found")
    return share_delete_file_response(resolved)


@api.post("/api/v1/audio/mix")
async def mix_audio(request: Request):
    """Mix multiple audio tracks into one file using ffmpeg.

    Body: {
        tracks: [{ path: str, start_time: float, volume: float }, ...],
        workspace: str | null
    }
    First track is the base (full duration). Subsequent tracks are overlaid at their start_time.
    Volume is 0.0-1.0.
    """
    import subprocess

    body = await request.json()
    tracks = body.get("tracks", [])
    if len(tracks) < 2:
        raise HTTPException(status_code=400, detail="At least 2 tracks required (base + overlay)")

    workspace = body.get("workspace") or _get_active_workspace()
    out_dir = _require_project_access(
        request, workspace, permission="project.generate",
    )
    source_policies = []
    for i, t in enumerate(tracks):
        path = t.get("path", "")
        resolved = _resolve_authorized_request_media(request, path, workspace)
        if not resolved:
            raise HTTPException(
                status_code=404,
                detail=f"Track {i+1}: file not found",
            )
        t["path"] = resolved
        if os.path.normcase(os.path.realpath(os.path.dirname(resolved))) == os.path.normcase(
            os.path.realpath(out_dir)
        ):
            source_policies.append(
                load_media_sidecars(out_dir, {os.path.basename(resolved)}).get(
                    os.path.basename(resolved),
                ) or {}
            )
        else:
            source_policies.append(read_upload_access_sidecar(resolved) or {})

    # Build ffmpeg filter_complex for mixing
    # Input 0 = base track, inputs 1..N = overlay tracks
    inputs = []
    filter_parts = []

    for i, t in enumerate(tracks):
        inputs.extend(["-i", t["path"]])

    # Process each track: apply volume and delay (except base track which starts at 0)
    mix_labels = []
    for i, t in enumerate(tracks):
        vol = max(0.0, min(1.0, float(t.get("volume", 1.0))))
        start_ms = int(float(t.get("start_time", 0)) * 1000)

        filters = []
        if start_ms > 0:
            filters.append(f"adelay={start_ms}|{start_ms}")
        if vol != 1.0:
            filters.append(f"volume={vol:.3f}")

        if filters:
            label = f"t{i}"
            filter_parts.append(f"[{i}]{','.join(filters)}[{label}]")
            mix_labels.append(f"[{label}]")
        else:
            mix_labels.append(f"[{i}]")

    # Combine all tracks with amix
    n = len(tracks)
    mix_input = "".join(mix_labels)
    filter_parts.append(f"{mix_input}amix=inputs={n}:duration=longest:normalize=0")

    filter_complex = ";".join(filter_parts)

    # Output to workspace
    os.makedirs(out_dir, exist_ok=True)
    out_filename = f"mix_{uuid.uuid4().hex[:6]}.wav"
    out_path = os.path.join(out_dir, out_filename)

    cmd = [
        "ffmpeg", "-y",
        *inputs,
        "-filter_complex", filter_complex,
        "-ac", "1",  # mono output (LTX audio guide works best with mono)
        out_path,
    ]

    print(f"[Audio Mix] Mixing {n} tracks → {out_path}")
    print(f"[Audio Mix] Filter: {filter_complex}")

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
        if result.returncode != 0:
            print(f"[Audio Mix] ffmpeg error: {result.stderr[-500:]}")
            raise HTTPException(status_code=500, detail=f"ffmpeg failed: {result.stderr[-200:]}")
    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=500, detail="Audio mix timed out")

    if not os.path.isfile(out_path):
        raise HTTPException(status_code=500, detail="Mix output file not created")

    policy = {
        "private": any(bool(item.get("private", False)) for item in source_policies),
        "explicit": any(bool(item.get("explicit", False)) for item in source_policies),
        "owner_session_id": request.state.maestro_session_id,
    }
    sidecar = {
        "params": {
            "source_files": [os.path.basename(t["path"]) for t in tracks],
            "track_count": len(tracks),
        },
        "artifact_class": "final",
        "generation_mode": "audio",
        "created_at": time.time(),
    }
    stamp_sidecar_policy(sidecar, policy, workspace=workspace)
    sidecar_path = os.path.splitext(out_path)[0] + ".meta.json"
    sidecar_temp = f"{sidecar_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(sidecar_temp, "w", encoding="utf-8") as handle:
            json.dump(sidecar, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(sidecar_temp, sidecar_path)
    except Exception as error:
        for stale in (sidecar_temp, out_path):
            try:
                os.remove(stale)
            except OSError:
                pass
        raise HTTPException(
            status_code=500, detail="Could not protect mixed audio output",
        ) from error

    print(f"[Audio Mix] Done: {out_filename}")

    return {
        "filename": out_filename,
        "path": out_path,
    }


_audio_analysis_gate = threading.Lock()
_audio_analysis_state_lock = threading.RLock()
_audio_analysis_active: dict | None = None


def _audio_analysis_workspace(request: Request, explicit: str = "") -> str:
    """Resolve the project scope without exposing machine-global selection."""
    requested = str(explicit or "").strip()
    if bool(getattr(request.state, "maestro_remote", False)):
        with _remote_active_projects_lock:
            active = _remote_active_projects.get(
                request.state.maestro_session_id, "",
            )
        if not active:
            raise HTTPException(
                status_code=423,
                detail="Select and unlock a project before analyzing audio",
            )
        if requested and requested != active:
            raise HTTPException(status_code=404, detail="Analysis not found")
        return active
    return requested or _get_active_workspace()


def _audio_analysis_owner_key(request: Request, workspace: str) -> str:
    material = (
        f"audio-analysis\0{workspace}\0"
        f"{request.state.maestro_session_id}"
    ).encode("utf-8")
    return hmac.new(_session_secret(), material, hashlib.sha256).hexdigest()


@api.post("/api/v1/audio/analyze")
async def analyze_audio(request: Request):
    """Analyze an audio file: beat detection, sections, optional transcription."""
    from services import audio_analysis
    body = await request.json()

    audio_path = body.get("audio_path", "")
    if not audio_path:
        raise HTTPException(status_code=400, detail="audio_path is required")
    workspace = _audio_analysis_workspace(
        request, str(body.get("workspace") or ""),
    )
    audio_path = _resolve_authorized_request_media(
        request,
        audio_path,
        workspace,
    )
    if not audio_path:
        raise HTTPException(status_code=404, detail="Audio file not found")
    director_request_id = str(body.get("director_request_id") or "")
    director_project_dir = ""
    if director_request_id:
        preparation = _require_director_preparation(
            request, director_request_id, workspace,
        )
        expected_music = preparation.get("music")
        expected_filename = (
            str(expected_music.get("filename") or "")
            if isinstance(expected_music, dict) else ""
        )
        if not expected_filename or expected_filename != os.path.basename(audio_path):
            raise HTTPException(status_code=404, detail="Director request not found")
        director_project_dir = _require_project_access(request, workspace)
        if _director_recovery_validate_child(
            director_project_dir,
            expected_music.get("evidence"),
        ) is None:
            raise HTTPException(status_code=404, detail="Director request not found")
        _checkpoint_director_preparation(
            director_request_id,
            director_project_dir,
            phase="analyzing_audio",
        )

    if not _audio_analysis_gate.acquire(blocking=False):
        raise HTTPException(
            status_code=409,
            detail="Another audio analysis is already in progress",
        )
    # Do not let the next owner briefly inherit a prior operation's global
    # progress text before the worker publishes its first phase.
    reset_progress = getattr(audio_analysis, "_set_progress", None)
    if callable(reset_progress):
        try:
            reset_progress("", "")
        except Exception:
            pass
    analysis_id = uuid.uuid4().hex
    owner_key = _audio_analysis_owner_key(request, workspace)
    global _audio_analysis_active
    with _audio_analysis_state_lock:
        _audio_analysis_active = {
            "analysis_id": analysis_id,
            "owner_key": owner_key,
            "workspace": workspace,
        }
    worker_started = threading.Event()
    lease_lock = threading.Lock()
    lease_released = False

    def release_analysis_lease():
        """Clear this operation exactly once, including pre-start failure."""
        nonlocal lease_released
        global _audio_analysis_active
        with lease_lock:
            if lease_released:
                return
            lease_released = True
        with _audio_analysis_state_lock:
            if (
                isinstance(_audio_analysis_active, dict)
                and hmac.compare_digest(
                    str(_audio_analysis_active.get("analysis_id") or ""),
                    analysis_id,
                )
            ):
                _audio_analysis_active = None
        _audio_analysis_gate.release()

    def run_analysis():
        """The worker owns cleanup so client cancellation cannot release the
        single-analysis gate while native/model work is still running."""
        worker_started.set()
        torch_module = globals().get("torch")
        uses_native_gpu = bool(
            torch_module is not None
            and torch_module.cuda.is_available()
        )
        generation_slot_acquired = False
        native_gpu_slot = (
            _WgpNativeGpuExecutionSlot()
            if uses_native_gpu else None
        )
        native_gpu_acquired = False
        try:
            if uses_native_gpu:
                _gen_lock.acquire()
                generation_slot_acquired = True
                native_gpu_acquired = native_gpu_slot.__enter__()
                if getattr(wgp, "wan_model", None) is not None:
                    print(
                        "[AudioAnalysis] Releasing generation model VRAM "
                        "before analysis"
                    )
                    _release_wgp_model_with_native_gpu_exclusion()
                else:
                    import gc
                    gc.collect()
                    torch_module.cuda.empty_cache()
            return audio_analysis.analyze(
                audio_path=audio_path,
                transcribe=body.get("transcribe", False),
                extract_vocals_for_transcription=body.get("extract_vocals", True),
                # Known written lyrics (generated tracks) → Whisper initial_prompt
                lyrics_hint=body.get("lyrics_hint") or None,
            )
        finally:
            if native_gpu_acquired:
                native_gpu_slot.__exit__(None, None, None)
            if generation_slot_acquired:
                _gen_lock.release()
            release_analysis_lease()

    try:
        # Keep FastAPI's event loop available for the scoped progress poller.
        # The synchronous audio stack may run for minutes and download models.
        worker_task = asyncio.create_task(asyncio.to_thread(run_analysis))

        def finalize_worker_task(done_task):
            # Executor shutdown/submission failure can complete the future
            # without ever entering run_analysis. Request cancellation is
            # shielded, so a queued worker otherwise retains the lease until
            # it really finishes.
            if not worker_started.is_set():
                release_analysis_lease()
            try:
                done_task.exception()
            except BaseException:
                pass

        worker_task.add_done_callback(finalize_worker_task)
        result = await asyncio.shield(worker_task)
        if director_request_id:
            _checkpoint_director_preparation(
                director_request_id,
                director_project_dir,
                phase="analysis_completed",
                analysis=result,
            )
        public_result = dict(result)
        public_result["analysis_id"] = analysis_id
        if director_request_id:
            public_result["director_request_id"] = director_request_id
        return public_result
    except ImportError as e:
        raise HTTPException(status_code=501, detail=str(e))
    except Exception as e:
        if director_request_id and director_project_dir:
            try:
                _checkpoint_director_preparation(
                    director_request_id,
                    director_project_dir,
                    phase="analysis_interrupted",
                )
            except Exception:
                pass
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


@api.get("/api/v1/audio/analyze/status")
def audio_analyze_status(
    request: Request,
    analysis_id: str = "",
    workspace: str = "",
):
    """Read the current audio-analyze phase for live UI progress.

    Polled by the frontend during the synchronous /audio/analyze call
    so the user sees meaningful sub-status ("Preparing transcription
    model on this host (downloads ~300MB if needed before loading)..."
    vs "Transcribing audio...")
    instead of a single "Analyzing audio..." message for the entire
    1-5 minute wait.

    The server issues an opaque ``analysis_id`` and binds it to the browser
    session plus selected project. Legacy no-id polling remains safe because
    it can see only that same owner/project's active operation. Unknown and
    foreign IDs are indistinguishable 404s; no global progress is returned.
    """
    selected_workspace = _audio_analysis_workspace(request, workspace)
    owner_key = _audio_analysis_owner_key(request, selected_workspace)
    with _audio_analysis_state_lock:
        active = dict(_audio_analysis_active or {})
    if not active:
        if analysis_id:
            raise HTTPException(status_code=404, detail="Analysis not found")
        return {"step": "", "detail": ""}
    if (
        active.get("workspace") != selected_workspace
        or not hmac.compare_digest(
            str(active.get("owner_key") or ""), owner_key,
        )
        or (
            analysis_id
            and not hmac.compare_digest(
                str(active.get("analysis_id") or ""), analysis_id,
            )
        )
    ):
        raise HTTPException(status_code=404, detail="Analysis not found")
    from services.audio_analysis import get_progress
    progress = get_progress()
    return {
        "analysis_id": active["analysis_id"],
        "step": str(progress.get("step") or ""),
        "detail": str(progress.get("detail") or ""),
    }


