@api.post("/api/v1/audio/plan-structure")
async def plan_audio_structure(request: Request):
    """Plan variable-duration clip structure aligned to beats and sections."""
    from services import audio_analysis
    body = await request.json()

    director_request_id = str(body.get("director_request_id") or "")
    director_project_dir = ""
    analysis = body.get("analysis")
    if director_request_id:
        selected_workspace = str(body.get("workspace") or "")
        preparation = _require_director_preparation(
            request, director_request_id, selected_workspace,
        )
        analysis = preparation.get("analysis")
        director_project_dir = _require_project_access(
            request,
            str(preparation.get("workspace") or "default"),
            permission="project.generate",
        )
    if not analysis:
        raise HTTPException(status_code=400, detail="analysis is required")

    # Resolve frame parameters from the DIRECTOR's video model when given —
    # the frontend's modelOptions belong to the Studio-selected model (often
    # ACE-Step right after generating the track), whose missing fps fell back
    # to 16 and silently shrank every planned clip's duration_frames by
    # 16/25 once rendered at LTX-2's 25 fps.
    fps = body.get("fps", 16)
    frames_steps = body.get("frames_steps", 4)
    frames_minimum = body.get("frames_minimum", 5)
    video_model = body.get("video_model")
    if video_model:
        try:
            md = wgp.get_model_def(video_model) or {}
            if md.get("fps"):
                fps = md["fps"]
            _minf, _fs, _lat = wgp.get_model_min_frames_and_step(video_model)
            frames_minimum, frames_steps = _minf, _fs
        except Exception:
            pass

    try:
        clips = audio_analysis.plan_clip_structure(
            analysis=analysis,
            energy_bias=body.get("energy_bias", 0),
            fps=fps,
            frames_steps=frames_steps,
            frames_minimum=frames_minimum,
            total_duration=body.get("total_duration"),
        )
        if director_request_id:
            _checkpoint_director_preparation(
                director_request_id,
                director_project_dir,
                phase="structure_completed",
                status="completed",
                structure={"clips": clips},
            )
        return {
            "clips": clips,
            **(
                {"director_request_id": director_request_id}
                if director_request_id else {}
            ),
        }
    except Exception as error:
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail="Audio structure planning failed; check the local Maestro logs",
        ) from error


@api.post("/api/v1/director/classify-sections")
async def director_classify_sections(request: Request):
    """Use LLM to reclassify section labels based on lyrics content."""
    from services import audio_analysis, llm_service
    from services.llm_operations import run_blocking_shielded

    body = await request.json()
    _promote_external_llm_request(request)
    if bool(getattr(request.state, "maestro_remote", False)):
        body["workspace"] = _request_project_workspace(
            request, body.get("workspace"),
        )

    director_request_id = str(body.get("director_request_id") or "")
    director_project_dir = ""
    analysis = body.get("analysis")
    if director_request_id:
        selected_workspace = str(body.get("workspace") or "")
        preparation = _require_director_preparation(
            request, director_request_id, selected_workspace,
        )
        analysis = preparation.get("analysis")
        director_project_dir = _require_project_access(
            request,
            str(preparation.get("workspace") or "default"),
            permission="project.generate",
        )
    else:
        workspace = _request_project_workspace(request, body.get("workspace"))
        director_project_dir = _require_project_access(
            request, workspace, permission="project.generate",
        )
    if not analysis:
        raise HTTPException(status_code=400, detail="analysis is required")

    sections = analysis.get("sections", [])
    lyrics = analysis.get("lyrics")
    duration = analysis.get("duration", 0)

    # If no lyrics or no sections, return unchanged
    if not lyrics or not sections:
        response = {"sections": sections, "method": "heuristic"}
        if director_request_id:
            _checkpoint_director_preparation(
                director_request_id,
                director_project_dir,
                phase="classification_completed",
                classification=response,
            )
            response["director_request_id"] = director_request_id
        return response

    try:
        selection = await run_blocking_shielded(
            _resolve_direct_llm_selection, request,
        )
        result = await run_blocking_shielded(
            _run_authorized_llm_with_selection,
            request,
            selection,
            _run_llm_route_operation,
            request,
            body,
            selection,
            llm_service.classify_song_sections,
            sections=sections,
            lyrics=lyrics,
            duration=duration,
        )
        song_structure = result.get("song_structure", [])

        if song_structure:
            # Replace audio sections entirely with LLM structure
            # (uses LLM boundaries/labels, interpolates energy from audio)
            updated = audio_analysis.replace_sections_with_structure(
                analysis, song_structure
            )
        else:
            # Fallback: just relabel existing sections
            labels = result["labels"]
            updated = audio_analysis.classify_sections_with_lyrics(analysis, labels)

        response = {
            "sections": updated["sections"],
            "song_structure": song_structure,
            "method": "llm",
        }
        if director_request_id:
            _checkpoint_director_preparation(
                director_request_id,
                director_project_dir,
                phase="classification_completed",
                classification=response,
                analysis=updated,
            )
            response["director_request_id"] = director_request_id
        return response
    except Exception as e:
        print(f"[Director] LLM section classification failed, using heuristic: {e}")
        response = {
            "sections": sections,
            "song_structure": [],
            "method": "heuristic",
        }
        if director_request_id:
            _checkpoint_director_preparation(
                director_request_id,
                director_project_dir,
                phase="classification_completed",
                classification=response,
            )
            response["director_request_id"] = director_request_id
        return response


