# ── Director Pipeline Endpoints ─────────────────────────────────────────

@api.get("/api/v1/director/preparation/{request_id}")
def director_preparation_status(
    request: Request,
    request_id: str,
    workspace: str = "",
):
    """Return opaque restart state for one owner/project preparation chain."""
    state = _require_director_preparation(
        request, request_id, workspace, allow_blocked=True,
    )
    phase = str(state.get("phase") or "registered")
    status = str(state.get("status") or "running")
    interrupted = phase.endswith("_interrupted") or phase in {
        "registered", "song_writing", "music_queued", "analyzing_audio",
    }
    next_action = (
        "generate_music"
        if phase in {"registered", "song_writing", "music_queued"}
        else "analyze_audio"
        if phase in {
            "music_completed", "analyzing_audio", "analysis_interrupted",
        }
        else "classify_or_structure"
        if phase in {"analysis_completed", "classification_completed"}
        else None
    )
    return {
        "director_request_id": request_id,
        "status": status,
        "phase": phase,
        "interrupted": interrupted,
        "next_action": next_action,
        "actions": [next_action] if next_action else [],
    }

def _pipeline_owner(params: dict | None) -> str | None:
    if not isinstance(params, dict):
        return None
    owner = params.get("_maestro_session_id")
    if isinstance(owner, str) and owner:
        return owner
    policy = params.get("_maestro_access_policy")
    if isinstance(policy, dict):
        owner = policy.get("owner_session_id")
        return owner if isinstance(owner, str) and owner else None
    return None


def _require_director_recovery_parent_access(
    request: Request,
    pid: str,
    workspace: str,
    project_dir: str,
    *,
    revalidate_inputs: bool,
    allow_blocked: bool = False,
) -> bool | dict:
    """Authorize a journal-known parent without permitting legacy fallback."""
    parent = _director_recovery_parents.get(pid)
    rejected = _director_recovery_rejected_parents.get(pid)
    if not isinstance(parent, dict) and not isinstance(rejected, dict):
        return True
    owner_digest = str(
        (parent or {}).get("_recovery_owner_digest")
        or (rejected or {}).get("owner_principal")
        or ""
    )
    project_digest = str(
        (parent or {}).get("_recovery_project_digest")
        or (rejected or {}).get("project_instance")
        or ""
    )
    try:
        request_owner = owner_principal_digest(
            _session_secret(), request.state.maestro_session_id,
        )
        current_project = _queue_recovery_project_identity(
            workspace, project_dir,
        )
    except (ValueError, QueueRecoveryAdapterError):
        raise HTTPException(status_code=404, detail="Pipeline not found")
    if (
        not owner_digest
        or not project_digest
        or not hmac.compare_digest(owner_digest, request_owner)
        or not hmac.compare_digest(project_digest, current_project)
    ):
        raise HTTPException(status_code=404, detail="Pipeline not found")
    if not isinstance(parent, dict):
        if allow_blocked:
            return False
        raise HTTPException(
            status_code=409,
            detail="Director recovery is blocked and requires manual repair.",
        )
    if not revalidate_inputs:
        return True
    try:
        from services.director_pipeline import pipeline_state_filename
        state_filename = pipeline_state_filename(pid)
        cursor = parent.get("recovery_cursor")
        cursor = cursor if isinstance(cursor, dict) else {}
        if cursor.get("delete_pending") and not os.path.isfile(
            os.path.join(project_dir, state_filename)
        ):
            _director_recovery_remove_parent(pid, project_dir)
            raise HTTPException(status_code=404, detail="Pipeline not found")
        sealed_state, sealed_descriptor, used_pending = (
            _load_director_recovery_cursor_state(
                project_dir, state_filename, cursor,
            )
        )
        if (
            sealed_state is None
            or sealed_state.get("pipeline_id") != pid
        ):
            raise QueueRecoveryRuntimeError(
                "Director recovery state identity changed."
            )
        manifest = load_request_manifest(
            project_dir,
            parent.get("_recovery_manifest_pointer") or {},
            expected_job_id=str(parent.get("id") or ""),
        )
        manifest_params = manifest.get("params") or {}
        if (
            manifest_params.get("pipeline_id") != pid
            or manifest_params.get("state_filename")
                != state_filename
        ):
            raise QueueRecoveryRuntimeError(
                "Director recovery state pointer is invalid."
            )
        validate_manifest_inputs(
            manifest,
            lambda descriptor: _queue_recovery_manifest_validator(
                dict(descriptor),
                owner_digest=owner_digest,
                workspace=workspace,
                project_dir=project_dir,
            ),
        )
        if used_pending:
            _director_recovery_checkpoint_parent(
                pid, sealed_state, dict(sealed_descriptor or {}),
            )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        if allow_blocked:
            return False
        raise HTTPException(
            status_code=409,
            detail=(
                "Director recovery is blocked because its saved request or "
                "inputs changed."
            ),
        )
    return sealed_state


def _require_live_pipeline(request: Request, pid: str) -> dict:
    from services.director_pipeline import get_pipeline
    pipeline = get_pipeline(pid)
    if not pipeline:
        raise HTTPException(status_code=404, detail="Pipeline not found")
    workspace = pipeline.get("workspace") or "default"
    out_dir = _require_project_access(request, workspace)
    owner = _pipeline_owner(pipeline.get("params"))
    if owner and owner != request.state.maestro_session_id:
        raise HTTPException(status_code=404, detail="Pipeline not found")
    recovered_owner = str(pipeline.get("_recovery_owner_digest") or "")
    if recovered_owner:
        try:
            request_owner = owner_principal_digest(
                _session_secret(), request.state.maestro_session_id,
            )
        except ValueError:
            raise HTTPException(status_code=404, detail="Pipeline not found")
        if not hmac.compare_digest(recovered_owner, request_owner):
            raise HTTPException(status_code=404, detail="Pipeline not found")
    recovered_project = str(pipeline.get("_recovery_project_digest") or "")
    if recovered_project:
        try:
            current_project = _queue_recovery_project_identity(workspace, out_dir)
        except (ValueError, QueueRecoveryAdapterError):
            raise HTTPException(status_code=404, detail="Pipeline not found")
        if not hmac.compare_digest(recovered_project, current_project):
            raise HTTPException(status_code=404, detail="Pipeline not found")
    recovery_valid = _require_director_recovery_parent_access(
        request,
        pid,
        workspace,
        out_dir,
        revalidate_inputs=True,
        allow_blocked=True,
    )
    if (
        not recovery_valid
        and str(pipeline.get("status") or "")
            not in {"completed", "failed", "cancelled"}
    ):
        from services.director_pipeline import block_pipeline_recovery
        pipeline = block_pipeline_recovery(
            pid,
            "Recovery inputs changed; manual repair is required.",
        ) or pipeline
    return pipeline


def _verified_blocked_director_state(
    pid: str,
    project_dir: str,
) -> dict | None:
    """Reload journal-sealed state when only input revalidation failed."""
    from services.director_pipeline import pipeline_state_filename
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        return None
    cursor = parent.get("recovery_cursor")
    cursor = cursor if isinstance(cursor, dict) else {}
    try:
        state, _descriptor, _used_pending = (
            _load_director_recovery_cursor_state(
                project_dir, pipeline_state_filename(pid), cursor,
            )
        )
    except (OSError, TypeError, ValueError, QueueRecoveryRuntimeError):
        return None
    return state if isinstance(state, dict) else None


def _require_saved_pipeline(
    request: Request,
    pid: str,
    workspace: str,
) -> tuple[dict, str]:
    """Authorize one direct-child saved pipeline in an explicit project."""
    from services.director_pipeline import pipeline_state_filename
    from services.win_safe_files import safe_direct_file_under
    out_dir = _require_project_access(request, workspace)
    try:
        filename = pipeline_state_filename(pid)
    except ValueError:
        raise HTTPException(status_code=404, detail="Pipeline not found")
    recovery_state = _require_director_recovery_parent_access(
        request,
        pid,
        workspace,
        out_dir,
        revalidate_inputs=True,
        allow_blocked=True,
    )
    if isinstance(recovery_state, dict):
        state = recovery_state
    else:
        if recovery_state is False:
            from services.director_pipeline import block_pipeline_recovery
            state = _verified_blocked_director_state(pid, out_dir)
            if state is None:
                raise HTTPException(
                    status_code=409,
                    detail="Director recovery is blocked and requires manual repair.",
                )
            block_pipeline_recovery(
                pid,
                "Recovery inputs changed; manual repair is required.",
            )
        else:
            state_path = safe_direct_file_under(out_dir, filename)
            if not state_path or not os.path.isfile(state_path):
                raise HTTPException(status_code=404, detail="Pipeline not found")
            try:
                with open(state_path, "r", encoding="utf-8") as handle:
                    state = json.load(handle)
            except (OSError, ValueError, TypeError):
                raise HTTPException(status_code=404, detail="Pipeline not found")
    if not isinstance(state, dict) or state.get("pipeline_id") != pid:
        raise HTTPException(status_code=404, detail="Pipeline not found")
    owner = _pipeline_owner(state.get("_params_snapshot"))
    if owner and owner != request.state.maestro_session_id:
        raise HTTPException(status_code=404, detail="Pipeline not found")
    return state, out_dir


def _public_pipeline_state(state: dict) -> dict:
    import copy
    from services.director.nsfw_guidance import EXPLICIT_GUIDANCE_SNAPSHOT_KEY
    public = copy.deepcopy(state)
    # Historical raw planner logs predate request-scoped streaming. Keep the
    # file untouched for provenance, but never publish its prompt, thinking,
    # or response content. New Director checkpoints write this field as null.
    public["llm_log"] = None
    snapshot = public.get("_params_snapshot")
    if isinstance(snapshot, dict):
        snapshot = dict(snapshot)
        snapshot.pop("_maestro_session_id", None)
        snapshot.pop("_maestro_access_policy", None)
        for internal_key in _CREDIT_INTERNAL_PARAMS:
            snapshot.pop(internal_key, None)
        _strip_director_image_role_internals(snapshot)
        snapshot.pop(EXPLICIT_GUIDANCE_SNAPSHOT_KEY, None)
        public["_params_snapshot"] = snapshot
    return _redact_local_paths(_sanitize_director_public_failures(public))


_DIRECTOR_PUBLIC_FAILURE_MESSAGES = {
    "director_pipeline_failed": "Director generation stopped after an internal error.",
    "director_worker_start_failed": "Director could not start its worker.",
    "cuda_oom": "Director generation stopped after a GPU memory error.",
}
_DIRECTOR_PUBLIC_REPAIR_FAILURE_MESSAGES = {
    "director_repair_failed": "Director repair stopped after an internal error.",
    "cuda_oom": "Director repair stopped after a GPU memory error.",
}


def _safe_director_failure_details(value, code: str) -> dict:
    """Normalize a saved/live failure envelope without retaining content."""
    normalized = None
    if isinstance(value, dict):
        try:
            from services.oom_detect import normalize_failure_details
            candidate = normalize_failure_details(value)
            if candidate.get("code") == code:
                normalized = candidate
        except Exception:
            normalized = None
    if normalized is None:
        normalized = {
            "code": code,
            "stage": "generation",
            "detail": "Generation failed.",
            "exception_type": "Exception",
            "is_oom": code == "cuda_oom",
        }
    return normalized


def _sanitize_director_public_failures(state: dict) -> dict:
    """Replace current and legacy Director exception text with stable fields."""
    if str(state.get("status") or "") == "failed":
        code = str(state.get("error_code") or "")
        if code not in _DIRECTOR_PUBLIC_FAILURE_MESSAGES:
            code = "director_pipeline_failed"
        details = _safe_director_failure_details(
            state.get("failure_details"), code,
        )
        state["error_code"] = code
        state["error"] = _DIRECTOR_PUBLIC_FAILURE_MESSAGES[code]
        state["failure_details"] = details
        try:
            from services.oom_detect import oom_info_from_failure_details
            coefficient = float(
                getattr(wgp, "server_config", {}).get(
                    "vram_safety_coefficient", 0.80,
                )
            )
            state["oom_info"] = oom_info_from_failure_details(
                details, coefficient,
            )
        except Exception:
            state["oom_info"] = None

    repair = state.get("repair")
    if isinstance(repair, dict) and repair.get("status") == "failed":
        repair_code = str(repair.get("error_code") or "")
        if repair_code not in _DIRECTOR_PUBLIC_REPAIR_FAILURE_MESSAGES:
            repair_code = "director_repair_failed"
        repair["error_code"] = repair_code
        repair["error"] = _DIRECTOR_PUBLIC_REPAIR_FAILURE_MESSAGES[repair_code]
        repair["message"] = _DIRECTOR_PUBLIC_REPAIR_FAILURE_MESSAGES[repair_code]
        repair["failure_details"] = _safe_director_failure_details(
            repair.get("failure_details"), repair_code,
        )
    return state


def _director_action_failure_response() -> JSONResponse:
    """Return one stable remote-safe envelope for unexpected saved actions."""
    traceback.print_exc()
    return JSONResponse(
        {
            "code": "director_action_failed",
            "error": "Director could not complete this action.",
        },
        status_code=500,
    )


_DIRECTOR_RECOVERY_STATES = frozenset({
    "blocked_input_changed", "blocked_remote_reauth", "interrupted",
    "paused", "retrying", "terminal",
})
_DIRECTOR_RECOVERY_REASONS = {
    "blocked_input_changed": (
        "input_missing_or_changed",
        "A required Director input is missing or changed",
    ),
    "blocked_remote_reauth": (
        "owner_reauthentication_required",
        "Unlock this project to resume Director",
    ),
}


def _public_director_recovery_metadata(pipeline: dict) -> dict:
    """Bound live Director recovery state to safe, actionable fields."""
    state = str(pipeline.get("recovery_state") or "")
    if state not in _DIRECTOR_RECOVERY_STATES:
        state = ""
    status = str(pipeline.get("status") or "")
    blocked = status == "blocked" and state.startswith("blocked_")
    reason, reason_text = _DIRECTOR_RECOVERY_REASONS.get(
        state, (None, None),
    )
    raw_actions = pipeline.get("recovery_actions")
    raw_actions = raw_actions if isinstance(raw_actions, list) else []
    actions = []
    if (
        blocked
        and state == "blocked_remote_reauth"
        and "resume" in raw_actions
    ):
        actions = ["resume"]
    elif status == "paused" and state == "paused" and "continue" in raw_actions:
        actions = ["continue"]
    return {
        "recovery_state": state or None,
        "recovery_blocked": blocked,
        "recovery_reason": reason,
        "recovery_reason_text": reason_text,
        "recovery_actions": actions,
    }


def _saved_pipeline_live_recovery_overlay(pid: str) -> dict:
    """Overlay only bounded live recovery facts on authorized saved state."""
    from services.director_pipeline import get_pipeline
    live = get_pipeline(pid)
    if not isinstance(live, dict) or live.get("id") != pid:
        return {}
    metadata = _public_director_recovery_metadata(live)
    if not metadata["recovery_state"]:
        return {}
    return {
        "status": str(live.get("status") or ""),
        "phase": str(live.get("phase") or ""),
        **metadata,
    }


def _revalidate_saved_director_runtime(request: Request, state: dict) -> dict:
    """Re-run model and role-LoRA admission before saved work can restart."""
    snapshot = state.get("_params_snapshot")
    if not isinstance(snapshot, dict):
        raise HTTPException(
            status_code=409,
            detail="Director recovery request is unavailable",
        )
    snapshot = dict(snapshot)
    _resolve_director_image_role_request(request, snapshot)
    state["_params_snapshot"] = snapshot
    for key in (
        "image_creator_model", "image_editor_model",
        "image_creator_loras", "image_editor_loras",
    ):
        if key in snapshot:
            state[key] = snapshot[key]
    return state


_DIRECTOR_READINESS_REASONS = frozenset({
    "model_unavailable", "director_incompatible", "model_disabled",
    "model_terms_required", "manual_verification_required",
    "model_not_downloaded",
})
_DIRECTOR_READINESS_ACTIONS = frozenset({
    "select_model", "enable_model", "accept_terms",
    "verify_manual_checkpoint", "download_model",
})


def _director_image_candidate_readiness(
    model_type: str,
    role: str,
) -> dict:
    """Project bounded, content-free readiness for one image role candidate."""
    from services.director_model_compat import assess_director_model
    from services.model_terms import (
        model_availability_policy,
        model_terms_manifest_valid,
        model_terms_statuses,
    )

    reasons = []
    actions = []
    model_def = wgp.get_model_def(model_type)
    compatible = False
    if not isinstance(model_def, dict) or not model_terms_manifest_valid(
        model_type, wgp.models_def,
    ):
        reasons.append("model_unavailable")
        actions.append("select_model")
        downloaded = False
        enabled = False
    else:
        try:
            assessment = assess_director_model(
                model_type,
                model_def,
                family=wgp.get_model_family(model_type, for_ui=True),
                architecture=wgp.get_base_model_type(model_type),
            )
            compatible = bool(assessment["image"][role]["compatible"])
        except Exception:
            compatible = False
        if not compatible:
            reasons.append("director_incompatible")
            actions.append("select_model")
        enabled = _director_image_model_enabled(model_type)
        if not enabled:
            reasons.append("model_disabled")
            actions.append("enable_model")
        services = getattr(wgp, "server_config", {}).get("services", {})
        term_statuses = model_terms_statuses(
            services, model_type, wgp.models_def,
        )
        terms_accepted = all(
            item.get("accepted") is True for item in term_statuses
        )
        if not terms_accepted:
            reasons.append("model_terms_required")
            actions.append("accept_terms")
        manual_required = getattr(
            wgp, "manual_checkpoint_integrity_required", None,
        )
        manual_ready = getattr(
            wgp, "manual_checkpoint_integrity_ready", None,
        )
        verification_required = bool(
            callable(manual_required)
            and manual_required(model_type, model_def, wgp.models_def)
        )
        verified = bool(
            not verification_required
            or (
                callable(manual_ready)
                and manual_ready(model_type, model_def, wgp.models_def)
            )
        )
        if not verified:
            reasons.append("manual_verification_required")
            actions.append("verify_manual_checkpoint")
        downloaded = bool(_check_model_downloaded(model_type))
        if not downloaded:
            reasons.append("model_not_downloaded")
            availability = model_availability_policy(
                model_type, wgp.models_def,
            )
            if availability["downloadable"] is True:
                actions.append("download_model")
            elif "verify_manual_checkpoint" not in actions:
                actions.append("verify_manual_checkpoint")
    return {
        "model_type": model_type,
        "compatible": compatible,
        "ready": not reasons,
        "reasons": list(dict.fromkeys(reasons)),
        "actions": list(dict.fromkeys(actions)),
        "enabled": enabled,
        "downloaded": downloaded,
    }


@api.get("/api/v1/director/capabilities")
def director_capabilities(
    request: Request,
    explicit_output: bool = False,
):
    """Return v1 role defaults and content-free candidate readiness."""
    creator = _director_explicit_creator_resolution(
        unrestricted=explicit_output is True,
    )
    remote_visible = _remote_visible_model_ids(request)
    ordered_ids = list(dict.fromkeys([
        creator["resolved_model"],
        *_DIRECTOR_EXPLICIT_CREATOR_MODELS,
        _DIRECTOR_SAFE_IMAGE_MODEL,
        _DIRECTOR_DEFAULT_EDITOR_MODEL,
        *list(getattr(wgp, "displayed_model_types", ()) or ()),
    ]))[:500]
    if remote_visible is not None:
        ordered_ids = [
            model_type for model_type in ordered_ids
            if model_type in remote_visible
        ]

    def role_payload(role: str, resolved_model: str, source: str) -> dict:
        candidates = [
            _director_image_candidate_readiness(model_type, role)
            for model_type in ordered_ids
            if isinstance(wgp.get_model_def(model_type), dict)
            and bool(wgp.get_model_def(model_type).get("image_outputs"))
        ]
        return {
            "resolved_model": (
                resolved_model
                if remote_visible is None or resolved_model in remote_visible
                else None
            ),
            "selection_source": source,
            "candidates": candidates,
            "lora_catalog_endpoint": "/api/v1/loras/{model_type}/details",
        }

    return {
        "schema_version": 1,
        "readiness_reason_values": sorted(_DIRECTOR_READINESS_REASONS),
        "readiness_action_values": sorted(_DIRECTOR_READINESS_ACTIONS),
        "image_roles": {
            "creator": role_payload(
                "creator",
                creator["resolved_model"],
                creator["selection_source"],
            ),
            "editor": role_payload(
                "editor",
                _DIRECTOR_DEFAULT_EDITOR_MODEL,
                "fixed_default",
            ),
        },
    }


def _director_preflight_admission_body(body) -> tuple[dict, dict]:
    """Validate the exact content-free wire and adapt continuity field names."""
    from services.director_model_compat import DIRECTOR_PIPELINE_TYPES

    required = {
        "explicit_output",
        "pipeline_type",
        "video_model",
        "image_creator_model",
        "continuity_editor_model",
        "director_resolution_preset",
        "director_aspect_ratio",
        "reference_presence",
    }
    optional = {"image_creator_loras", "continuity_editor_loras"}
    if not isinstance(body, dict) or set(body) - required - optional:
        raise HTTPException(
            status_code=400,
            detail="Invalid Director preflight request",
        )
    if not required.issubset(body) or not isinstance(body["explicit_output"], bool):
        raise HTTPException(
            status_code=400,
            detail="Invalid Director preflight request",
        )

    def model_id(value, *, nullable: bool = False):
        if nullable and value is None:
            return None
        if (
            not isinstance(value, str)
            or not 1 <= len(value) <= 200
            or value != value.strip()
        ):
            raise HTTPException(
                status_code=400,
                detail="Invalid Director preflight request",
            )
        return value

    references = body.get("reference_presence")
    reference_keys = {"starting_image", "character", "location"}
    if (
        not isinstance(references, dict)
        or set(references) != reference_keys
        or any(not isinstance(references[key], bool) for key in reference_keys)
    ):
        raise HTTPException(
            status_code=400,
            detail="Invalid Director preflight request",
        )
    pipeline_type = model_id(body["pipeline_type"])
    if pipeline_type not in DIRECTOR_PIPELINE_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid Director preflight request",
        )
    admission = {
        "explicit_output": body["explicit_output"],
        "pipeline_type": pipeline_type,
        "video_model": model_id(body["video_model"]),
        "image_creator_model": model_id(
            body["image_creator_model"], nullable=True,
        ),
        "image_editor_model": model_id(body["continuity_editor_model"]),
        "director_resolution_preset": model_id(
            body["director_resolution_preset"],
        ),
        "director_aspect_ratio": model_id(body["director_aspect_ratio"]),
    }
    if "image_creator_loras" in body:
        admission["image_creator_loras"] = body["image_creator_loras"]
    if "continuity_editor_loras" in body:
        admission["image_editor_loras"] = body["continuity_editor_loras"]
    return admission, dict(references)


def _director_model_resolution(
    model_type: str,
    preset: str,
    aspect_ratio: str,
) -> str:
    """Resolve one Director canvas only through the selected model contract."""
    model_def = wgp.get_model_def(model_type)
    if not isinstance(model_def, dict):
        raise HTTPException(status_code=404, detail="Model not found")
    contract = _model_resolution_contract(model_def)
    presets = contract["resolution_presets"]
    if preset not in contract["resolution_preset_order"]:
        raise HTTPException(
            status_code=400,
            detail="Invalid Director resolution selection",
        )
    values = presets[preset]["values"]
    if (
        aspect_ratio == "auto"
        and contract["supports_auto_aspect"] is not True
    ) or aspect_ratio not in values:
        raise HTTPException(
            status_code=400,
            detail="Invalid Director resolution selection",
        )
    return values[aspect_ratio]


def _director_validate_resolution_request(
    body: dict,
    *,
    require_selection: bool,
    require_resolved_values: bool,
) -> dict | None:
    """Validate the same Director selection at preflight and start.

    Old recovered/start payloads may carry only a concrete native resolution.
    They remain accepted when the model still declares that canvas, but never
    acquire a guessed preset/aspect tuple.
    """
    preset = body.get("director_resolution_preset")
    aspect_ratio = body.get("director_aspect_ratio")
    video_model = body.get("video_model")
    if not isinstance(video_model, str) or not video_model:
        if require_selection:
            raise HTTPException(
                status_code=400,
                detail="Invalid Director resolution selection",
            )
        return None

    if preset is None and aspect_ratio is None and not require_selection:
        video_params = body.get("video_params")
        legacy_resolution = (
            video_params.get("resolution")
            if isinstance(video_params, dict)
            else None
        )
        if legacy_resolution is None:
            return None
        model_def = wgp.get_model_def(video_model)
        if not isinstance(model_def, dict):
            raise HTTPException(status_code=404, detail="Model not found")
        contract = _model_resolution_contract(model_def)
        supported = {
            value
            for definition in contract["resolution_presets"].values()
            for value in definition["values"].values()
        }
        for item in model_def.get("resolutions") or ():
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                supported.add(str(item[1]))
        if not isinstance(legacy_resolution, str) or legacy_resolution not in supported:
            raise HTTPException(
                status_code=400,
                detail="Invalid Director resolution selection",
            )
        return {
            "preset": None,
            "aspect_ratio": None,
            "video_resolution": legacy_resolution,
            "image_resolution": None,
            "legacy": True,
        }

    if not isinstance(preset, str) or not isinstance(aspect_ratio, str):
        raise HTTPException(
            status_code=400,
            detail="Invalid Director resolution selection",
        )
    video_resolution = _director_model_resolution(
        video_model, preset, aspect_ratio,
    )
    image_model = body.get("image_creator_model")
    creator_resolution = (
        _director_model_resolution(image_model, preset, aspect_ratio)
        if isinstance(image_model, str) and image_model
        else None
    )
    editor_model = body.get("image_editor_model")
    editor_resolution = (
        _director_model_resolution(editor_model, preset, aspect_ratio)
        if isinstance(editor_model, str) and editor_model
        else None
    )
    if (
        creator_resolution is not None
        and editor_resolution is not None
        and creator_resolution != editor_resolution
    ):
        raise HTTPException(
            status_code=400,
            detail="Selected Director image roles require different resolutions",
        )
    image_resolution = creator_resolution or editor_resolution

    if require_resolved_values:
        video_params = body.get("video_params")
        image_params = body.get("image_params")
        if (
            not isinstance(video_params, dict)
            or video_params.get("resolution") != video_resolution
            or (
                image_resolution is not None
                and (
                    not isinstance(image_params, dict)
                    or image_params.get("resolution") != image_resolution
                )
            )
        ):
            raise HTTPException(
                status_code=400,
                detail="Invalid Director resolution selection",
            )
    return {
        "preset": preset,
        "aspect_ratio": aspect_ratio,
        "video_resolution": video_resolution,
        "image_resolution": image_resolution,
        "legacy": False,
    }


@api.post("/api/v1/director/preflight")
async def director_preflight(request: Request):
    """Check exact Director model admission without touching jobs or media."""
    try:
        admission, references = _director_preflight_admission_body(
            await request.json(),
        )
        _resolve_director_image_role_request(
            request,
            admission,
            component_errors=True,
        )
        resolution = _director_validate_resolution_request(
            admission,
            require_selection=True,
            require_resolved_values=False,
        )
    except HTTPException as error:
        response = _director_component_error_response(error)
        if response is not None:
            return response
        raise

    components = [
        {"component": "video_model", "status": "ready"},
        {"component": "image_creator_model", "status": "ready"},
        {"component": "continuity_editor_model", "status": "ready"},
        {
            "component": "image_creator_lora",
            "status": (
                "ready" if admission.get("image_creator_loras")
                else "not_required"
            ),
        },
        {
            "component": "continuity_editor_lora",
            "status": (
                "ready" if admission.get("image_editor_loras")
                else "not_required"
            ),
        },
    ]
    components.extend({
        "component": component,
        "status": "ready" if references[presence] else "not_required",
    } for presence, component in (
        ("starting_image", "starting_image"),
        ("character", "character_reference"),
        ("location", "location_reference"),
    ))
    return {
        "status": "ready",
        "resolved": {
            "pipeline_type": admission["pipeline_type"],
            "video_model": admission["video_model"],
            "image_creator_model": admission["image_creator_model"],
            "continuity_editor_model": admission["image_editor_model"],
            "director_resolution_preset": resolution["preset"],
            "director_aspect_ratio": resolution["aspect_ratio"],
            "video_resolution": resolution["video_resolution"],
            "image_resolution": resolution["image_resolution"],
        },
        "components": components,
    }

