@api.post("/api/v1/director/pipelines/{pid}/rejoin")
async def rejoin_pipeline_clips(request: Request, pid: str, workspace: str = ""):
    """Re-join all clips from a saved pipeline using current best versions."""
    selected_workspace = _request_project_workspace(request, workspace)
    _init_pipeline()
    from services.director_pipeline import PipelineBusyError, rejoin_clips
    state, base = _require_saved_pipeline(request, pid, selected_workspace)
    _begin_workspace_operation(selected_workspace)
    try:
        result = await asyncio.to_thread(rejoin_clips, base, pid)
        filename = str(result.get("filename") or "")
        joined_path = os.path.join(base, filename)
        if not filename or not os.path.isfile(joined_path):
            raise RuntimeError("Director rejoin returned no output")
        snapshot = state.get("_params_snapshot") if isinstance(state, dict) else {}
        snapshot = snapshot if isinstance(snapshot, dict) else {}
        policy = snapshot.get("_maestro_access_policy")
        if not isinstance(policy, dict):
            policy = {
                "private": bool(snapshot.get("private_output", False)),
                "explicit": bool(snapshot.get("explicit_output", False)),
                "owner_session_id": (
                    request.state.maestro_session_id
                    if snapshot.get("private_output") else None
                ),
            }
        meta_path = os.path.splitext(joined_path)[0] + ".meta.json"
        sidecar = {}
        if os.path.isfile(meta_path):
            try:
                with open(meta_path, "r", encoding="utf-8") as handle:
                    existing_sidecar = json.load(handle)
                if isinstance(existing_sidecar, dict):
                    sidecar.update(existing_sidecar)
            except (OSError, ValueError, TypeError):
                pass
        sidecar.update({
            "params": {"_director_pipeline_id": pid},
            "director_pipeline_id": pid,
            "artifact_class": "final",
            "generation_mode": "video",
            "output_filename": filename,
            "created_at": time.time(),
        })
        stamp_sidecar_policy(sidecar, policy, workspace=selected_workspace)
        temp_path = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
        try:
            with open(temp_path, "w", encoding="utf-8") as handle:
                json.dump(sidecar, handle, indent=2)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp_path, meta_path)
        except Exception:
            for path in (temp_path, joined_path):
                try:
                    os.remove(path)
                except OSError:
                    pass
            raise
        return result
    except PipelineBusyError as e:
        return JSONResponse({"error": str(e)}, status_code=409)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception:
        return _director_action_failure_response()
    finally:
        _end_workspace_operation(selected_workspace)


@api.delete("/api/v1/director/pipelines/{pid}")
def delete_pipeline_endpoint(request: Request, pid: str, workspace: str = ""):
    """Delete a saved pipeline and all media it produced (any workspace)."""
    selected_workspace = _request_project_workspace(request, workspace)
    _init_pipeline()
    from services.director_pipeline import delete_pipeline
    _state, base = _require_saved_pipeline(request, pid, selected_workspace)
    _begin_workspace_operation(selected_workspace)
    try:
        result = delete_pipeline(base, pid)
    finally:
        _end_workspace_operation(selected_workspace)
    if not result.get("ok"):
        if result.get("error") == "running":
            raise HTTPException(status_code=409, detail="This pipeline is still running. Stop it first, then delete.")
        if result.get("error") == "state_file_locked":
            raise HTTPException(
                status_code=409,
                detail="Pipeline media was cleaned, but its state file is locked. Close any process using it and retry deletion.",
            )
        if result.get("error") == "media_locked":
            raise HTTPException(
                status_code=409,
                detail="Some pipeline media is still in use. Close its preview or any process using it, then retry deletion.",
            )
        raise HTTPException(status_code=404, detail=f"Pipeline not found: {pid}")
    print(f"[Pipeline] Deleted {pid}: {result['media_deleted']} media files removed "
          f"({result['media_deferred']} deferred) from {result['dir']}")
    return {
        "ok": True,
        "media_total": int(result.get("media_total") or 0),
        "media_deleted": int(result.get("media_deleted") or 0),
        "media_deferred": int(result.get("media_deferred") or 0),
        "error_count": len(result.get("errors") or []),
        "errors": (
            ["media_cleanup_incomplete"] if result.get("errors") else []
        ),
    }


